[" Here's a high-level design for a C library named `netif_lib` that manages a dynamic list of network interface configurations:

1. Define custom data structure for network interface configuration (nic_cfg):

```c
typedef struct {
    char iface[IF_NAMESIZE];  // Interface name
    uint32_t bandwidth;        // Bandwidth in bits per second
    uint32_t latency_tolerance; // Latency tolerance in microseconds
    uint8_t qos_level;          // Quality of Service level
} nic_cfg;
```

2. Create a dynamic list using doubly-linked list (doubly_list):

```c
typedef struct _node {
    nic_cfg data;
    struct _node *next, *prev;
} node;

typedef struct {
    node *head, *tail;
    size_t len; // Number of elements in the list
} doubly_list;
```

3. Implement initializer and destructor functions for `doubly_list`:

```c
void dl_init(doubly_list *dl) {
    dl->head = dl->tail = NULL;
    dl->len = 0;
}

void dl_destroy(doubly_list *dl) {
    node *cur, *next;

    cur = dl->head;
    while (cur != NULL) {
        next = cur->next;
        free(cur);
        cur = next;
    }

    dl_init(dl);
}
```

4. Implement functions for adding, removing and searching elements in the dynamic list:

```c
node* dl_add(doubly_list *dl, const nic_cfg *nic) {
    node *new_node = malloc(sizeof(node));
    if (new_node == NULL) return NULL;

    new_node->data = *nic;
    new_node->next = dl->head;
    new_node->prev = NULL;

    if (dl->len > 0) {
        dl->head->prev = new_node;
        dl->head = new_node;
    } else {
        dl->tail = new_node;
    }

    dl->len++;
    return new_node;
}

node* dl_remove(doubly_list *dl, node *node_to_remove) {
    if (node_to_remove == NULL || node_to_remove->next == NULL) return NULL;

    node *prev = node_to_remove->prev;
    if (prev != NULL) prev->next = node_to_remove->next;
    else dl->head = node_to_remove->next;

    node_to_remove->next->prev = prev;
    free(node_to_remove);
    dl->len--;
    return node_to_remove;
}

node* dl_search(const doubly_list *dl, const char *iface) {
    node *cur = dl->head;
    while (cur != NULL) {
        if (strcmp(cur->data.iface, iface) == 0) return cur;
        cur = cur->next;
    }
    return NULL;
}
```

