#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define BUFFER_SIZE 4096
#define LINE_ENDINGS "\n\r"

typedef struct {
    char *buffer;
    size_t pos;
    size_t cap;
} Buffer;

void log_message(enum LogLevel level, const char *msg) {
    // Implement logging here using a non-blocking API and error handling.
}

int line_count = 0;
int nonempty_line_count = 0;
Buffer input_buffer;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_cond = PTHREAD_COND_INITIALIZER;
FILE *output_file = NULL;

int opt_case_insensitive = 0;
int opt_only_nonempty = 0;
char *opt_output_file = NULL;

void* process_input(void *arg) {
    char buffer[BUFFER_SIZE];
    size_t bytes_read;

    while ((bytes_read = getline(&buffer, sizeof(buffer), stdin)) != -1) {
        pthread_mutex_lock(&buffer_mutex);
        if (input_buffer.pos + bytes_read >= input_buffer.cap) {
            // Resize buffer when it's full.
            input_buffer.cap *= 2;
            void *tmp = realloc(input_buffer.buffer, input_buffer.cap * sizeof(char));
            if (!tmp) {
                log_message(ERROR, "Failed to resize input buffer.");
                pthread_mutex_unlock(&buffer_mutex);
                return NULL;
            }
            input_buffer.buffer = tmp;
        }
        memcpy(input_buffer.buffer + input_buffer.pos, buffer, bytes_read);
        input_buffer.pos += bytes_read;
        pthread_cond_signal(&buffer_cond);
        pthread_mutex_unlock(&buffer_mutex);
    }

    return NULL;
}

void process_lines() {
    char *line = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!line) {
        log_message(ERROR, "Failed to allocate memory for line processing.");
        return;
    }

    size_t bytes_read = BUFFER_SIZE;

    while (bytes_read > 0) {
        pthread_mutex_lock(&buffer_mutex);
        if (input_buffer.pos == 0) {
            pthread_cond_wait(&buffer_cond, &buffer_mutex);
            if (input_buffer.pos == 0) {
                break; // No more input data
            }
        }
        memcpy(line, input_buffer.buffer, input_buffer.pos);
        input_buffer.pos = 0;
        pthread_mutex_unlock(&buffer_mutex);

        char *current_line = line;
        while ((*current_line != '\0') && (strchr(LINE_ENDINGS, *current_line))) {
            size_t len = current_line - line;

            if (!opt_case_insensitive) {
                // Case-sensitive comparison for line ending.
                if (len >= 1 && (tolower(*(line + len - 1)) == tolower(LINE_ENDINGS[0]) || tolower(*(line + len - 1)) == tolower(LINE_ENDINGS[1]))) {
                    if (!opt_only_nonempty) {
                        line_count++;
                    }
                    if (*(current_line - 1) != '\r') {
                        nonempty_line_count++;
                    }
                }
            } else {
                // Case-insensitive comparison for line ending.
                if (len >= 1 && ((*(line + len - 1) == LINE_ENDINGS[0] || *(line + len - 1) == LINE_ENDINGS[1]) ||
                    (*(line + len - 1) == toupper(LINE_ENDINGS[0]) || *(line + len - 1) == toupper(LINE_ENDINGS[1])))) {
                    if (!opt_only_nonempty) {
                        line_count++;
                    }
                    if (*(current_line - 1) != '\r') {
                        nonempty_line_count++;
                    }
                }
            }

            current_line += len + 1;
            bytes_read -= (len + 1);
            memmove(line, current_line, bytes_read);
        }

        if (output_file) {
            size_t write_size = current_line - line;
            if (fwrite(line, write_size, 1, output_file) != 1) {
                log_message(ERROR, "Failed to write data to output file.");
            }
        }
    }

    munmap(line, BUFFER_SIZE);
}

int main(int argc, char *argv[]) {
    // Implement getopt-like parsing here for command-line options.
    // ...

    pthread_t input_thread;
    if (pthread_create(&input_thread, NULL, process_input, NULL) != 0) {
        log_message(ERROR, "Failed to create input processing thread.");
        return EXIT_FAILURE;
    }

    process_lines();

    if (output_file) {
        if (fclose(output_file) != 0) {
            log_message(ERROR, "Failed to close output file.");
        }
    }

    pthread_join(input_thread, NULL);

    // Write results to an output file if specified.
    if (output_file) {
        FILE *result_file = fopen("results.txt", "w");
        if (!result_file) {
            log_message(ERROR, "Failed to open result file.");
            return EXIT_FAILURE;
        }
        fprintf(result_file, "- Lines: %d\n", line_count);
        fprintf(result_file, "- Non-empty lines: %d\n", nonempty_line_count);
        fclose(result_file);
    }

    return EXIT_SUCCESS;
}
