#include <openssl/ssl.h>
#include <openssl/err.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char *cipher_list;
    const char *key_mgmt;
    const char *fallback_list;
} Config;

SSL_CTX* init_ssl_context(const char *config_file) {
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();
    EVP_rlock();
    const SSL_METHOD *method = TLS_server_method();

    int rc;
    FILE *config = fopen(config_file, "r");
    if (!config) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    Config cfg;
    char line[256];
    while (fgets(line, sizeof(line), config)) {
        char *token = strtok(line, "=");
        if (!token) continue;

        if (strcmp(token, "cipher_list") == 0) {
            token = strtok(NULL, "\n");
            cfg.cipher_list = token ? strdup(token) : NULL;
        } else if (strcmp(token, "key_mgmt") == 0) {
            token = strtok(NULL, "\n");
            cfg.key_mgmt = token ? strdup(token) : NULL;
        } else if (strcmp(token, "fallback_list") == 0) {
            token = strtok(NULL, "\n");
            cfg.fallback_list = token ? strdup(token) : NULL;
        }
    }

    fclose(config);
    EVP_run_rlock();

    SSL_CTX *ctx = SSL_CTX_new(method);
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    const char *cipher_list = cfg.cipher_list ?: OpenSSL_strdup("DEFAULT");
    SSL_CTX_set_ciphers(ctx, cipher_list);

    const char *key_mgmt = cfg.key_mgmt;
    if (key_mgmt) SSL_CTX_set_tlsext_servername(ctx, key_mgmt);

    const char *fallback_list = cfg.fallback_list ?: OpenSSL_strdup("DEFAULT");
    SSL_CTX_set_options(ctx, SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_2_CLIENT_METHOD);
    SSL_CTX_set_cipher_list(ctx, fallback_list);

    return ctx;
}
```

