#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

typedef struct Semaphore {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int count;
    char name[64];
} Semaphore;

Semaphore* semaphore_create(const char* name, int initial_count) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    memset(sem, 0, sizeof(Semaphore));
    strcpy(sem->name, name);
    sem->count = initial_count;
    pthread_mutex_init(&sem->lock, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

void semaphore_destroy(Semaphore* sem) {
    if (sem != NULL) {
        pthread_mutex_destroy(&sem->lock);
        pthread_cond_destroy(&sem->cond);
        free(sem);
    }
}

int semaphore_wait(Semaphore* sem, long timeout_microseconds) {
    struct timespec abs_timeout;
    int rc = 0;

    clock_gettime(CLOCK_REALTIME, &abs_timeout);
    abs_timeout.tv_sec += timeout_microseconds / 1000000;
    abs_timeout.tv_nsec += (timeout_microseconds % 1000000) * 1000;
    if (abs_timeout.tv_nsec >= 1000000000) {
        abs_timeout.tv_sec++;
        abs_timeout.tv_nsec -= 1000000000;
    }

    pthread_mutex_lock(&sem->lock);

    while (sem->count <= 0 && rc == 0) {
        if (timeout_microseconds > 0 && clock_gettime(CLOCK_REALTIME, &abs_timeout) < abs_timeout) {
            rc = pthread_cond_timedwait(&sem->cond, &sem->lock, &abs_timeout);
        } else {
            rc = pthread_cond_wait(&sem->cond, &sem->lock);
        }

        if (rc == 0 && sem->count > 0) {
            sem->count--;
        }
    }

    pthread_mutex_unlock(&sem->lock);

    return rc;
}

void semaphore_signal(Semaphore* sem) {
    pthread_mutex_lock(&sem->lock);

    if (sem->count < INT32_MAX) {
        sem->count++;
    }

    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->lock);
}

void log_error(const char* message, Semaphore* sem) {
    if (sem != NULL && strcmp(sem->name, "") != 0) {
        fprintf(stderr, "[%s] Error: %s\n", sem->name, message);
    } else {
        fprintf(stderr, "Error: %s\n", message);
    }
}
```

This code defines a `Semaphore` structure and functions for creating, destroying, waiting on, signaling, and logging errors related to semaphores. The library ensures thread safety using mutexes and condition variables provided by the POSIX threads API (pthread). The wait function allows for optional timeouts in microseconds.

It is essential to note that this code only provides a minimal implementation of a semaphore management library, and further optimizations may be necessary depending on the specific requirements of your application environment. For instance, error handling can be improved by logging more detailed information or integrating with an existing logging framework. Additionally, consider implementing thread pooling or other concurrency techniques to optimize performance when dealing with a large number of concurrent users and operations.

To use this library, include the provided header file in your application source code and instantiate semaphores as needed throughout your program. Make sure to call `semaphore_destroy()` when each semaphore is no longer required to avoid memory leaks.']

