use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::BufReader;
use std::path::PathBuf;
use log::*;
use simple_logger;

const CONFIG_CACHE: &str = ".config_cache";

#[derive(Serialize, Deserialize, Debug)]
struct EnvironmentConfig {
    // Define your configuration schema here
}

fn load_config<T>(env: &str) -> Result<T, Box<dyn std::error::Error> where T: serde::DeserializeOwned + Default {
    let cache_file = PathBuf::from(CONFIG_CACHE).join(env);
    if cache_file.exists() {
        let mut data = HashMap::new();
        let file = File::open(&cache_file)?;
        let reader = BufReader::new(file);
        serde_json::from_reader(reader).unwrap().into_iter().for_each(|entry| {
            data.insert(entry.0, entry.1);
        });
        if let Ok(config) = serde_json::from_str::<EnvironmentConfig>(&env_logger::from_env().filter("configuration").unwrap()) {
            config.into_iter().for_each(|(key, value)| data.insert(key, value));
        }
        Ok(serde_json::to_vec_pretty(&data).unwrap())
    } else {
        let env_config = serde_json::from_str::<EnvironmentConfig>(&env_logger::from_env().filter("configuration").unwrap())?;
        let mut data = HashMap::new();
        env_config.into_iter().for_each(|(key, value)| data.insert(key, value));
        for file in get_config_files(env) {
            if let Ok(additional_config) = serde_json::from_str::<HashMap<String, serde_json::Value>>(&File::read_to_string(&file).unwrap()) {
                additional_config.into_iter().for_each(|(key, value)| data.insert(key, value));
            }
        }
        let serialized = serde_json::to_vec_pretty(&data)?;
        std::fs::write(cache_file, &serialized)?;
        Ok(serde_json::from_slice::<HashMap<String, serde_json::Value>>(&serialized)?)
    }
}

fn get_config_files(env: &str) -> Vec<PathBuf> {
    let mut config_files = vec![];
    for (i, file) in [format!("{}.dev.json", env), format!("{}.test.json", env), format!("{}.prod.json", env)]
        .into_iter()
        .filter(|file| PathBuf::from(file).exists())
        .enumerate() {
        config_files.push(PathBuf::from(file.1));
    }
    config_files
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    simple_logger::init_with_filter("configuration").unwrap();

    let env = env::var("ENVIRONMENT")?;
    let config = load_config(&env)?;
    // Process the loaded configuration here
    info!("Loaded configuration for environment: {}", &env);
    Ok(())
}
```

