// Function to initialize the Configuration object upon first use.
void init() {
    config = Logging::Configuration("config.xml");
    // Load all loggers defined in the configuration file
    for (auto loggerType : config.configTree.get_child("Loggers").get_children()) {
        auto minLevel = static_cast<Logging::Level>(loggerType.get<int>("MinLevel"));
        loggers.push_back(config.createLogger(loggerType.name(), minLevel));
    }
}

// Function to get the Logger instance based on its type and minimum level.
Logging::Logger* getLogger(const std::string& loggerType, Logging::Level minLevel) {
    pthread_mutex_lock(&loggersMutex);
    for (auto logger : loggers) {
        if (logger->getType() == loggerType && logger->getMinLevel() >= minLevel) {
            pthread_mutex_unlock(&loggersMutex);
            return logger;
        }
    }
    pthread_mutex_unlock(&loggersMutex);
    // Return null or throw exception if no suitable Logger is found.
}
```

