    private readonly string _connectionString;

    public BulkInsertService(ILogger<BulkInsertService> logger, string connectionString)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<bool> ExecuteBulkInsertAsync(string tableName, List<Record> records)
    {
        var success = true;
        var errorMessage = string.Empty;
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var transaction = new System.Data.SqlClient.SqlTransaction(connection, IsolationLevel.Serializable))
            {
                try
                {
                    var command = new SqlCommand($"BULK INSERT {tableName} FROM OPENROWSET(BULK '{string.Join("", records.Select(r => $"{r.Property1}, {r.Property2}\n"))}", CharSet: "UTF-8")", connection, transaction);
                    command.CommandTimeout = 300; // Set a reasonable timeout (in seconds)
                    await command.ExecuteNonQueryAsync();
                    transaction.Commit();
                }
                catch (Exception ex)
                {
                    success = false;
                    errorMessage = $"Failed to execute bulk insert for table '{tableName}'. Error: {ex.Message}";
                    _logger.LogError(errorMessage);
                    transaction.Rollback();
                }
            }
        }

        if (!success)
        {
            _logger.LogWarning($"Bulk insert failed for table '{tableName}', retrying after a delay due to potential network latency or failure: {errorMessage}");
            // Implement a retry mechanism with an exponential backoff strategy (e.g. wait 1s, 2s, 4s, etc.)
        }

        return success;
    }
}
