    }

    public function GetUserData($id) {
        $stmt = $this->db->prepare('SELECT * FROM users WHERE id=:id');
        $stmt->execute([':id' => $id]);
        return $stmt->fetch(PDO::FETCH_ASSOC);
    }

    public function SaveUserData($data) {
        // Ensure thread safety using locking mechanism or transactions
        // ...

        $sql = 'INSERT INTO users (name, email, password) VALUES (:name, :email, :password) ON DUPLICATE KEY UPDATE name=:name, email=:email, password=:password';
        $stmt = $this->db->prepare($sql);
        $stmt->execute($data);
    }

    public function DeleteUserData($id) {
        // Ensure user account exists and thread safety using locking mechanism or transactions
        // ...

        $stmt = $this->db->prepare('DELETE FROM users WHERE id=:id');
        $stmt->execute([':id' => $id]);
    }

    public function HandleRequest($request) {
        $data = $this->Validate($request);

        if (empty($data)) {
            http_response_code(400); // Bad Request
            echo json_encode(['message' => 'error', 'details' => 'Invalid data']);
            exit;
        }

        switch ($data['sub_action']) {
            case 'create':
            case 'update':
                if (isset($data['id'])) {
                    http_response_code(400); // Bad Request
                    echo json_encode(['message' => 'error', 'details' => 'Id should not be provided for create/update operation']);
                    exit;
                }
                $emailExists = $this->GetUserData('email', $data['email']);
                if ($emailExists) {
                    http_response_code(409); // Conflict
                    echo json_encode(['message' => 'error', 'details' => 'Email already exists']);
                    exit;
                }
                $this->SaveUserData($data);
                http_response_code(201); // Created
                echo json_encode(['message' => 'success', 'data' => $data]);
                break;
            case 'delete':
                if (!isset($data['id'])) {
                    http_response_code(400); // Bad Request
                    echo json_encode(['message' => 'error', 'details' => 'Id is required for delete operation']);
                    exit;
                }
                $userData = $this->GetUserData($data['id']);
                if (!$userData) {
                    http_response_code(404); // Not Found
                    echo json_encode(['message' => 'error', 'details' => 'User not found']);
                    exit;
                }
                $this->DeleteUserData($data['id']);
                http_response_code(200); // OK
                echo json_encode(['message' => 'success']);
                break;
            case 'retrieve':
                if (!isset($data['id'])) {
                    http_response_code(400); // Bad Request
                    echo json_encode(['message' => 'error', 'details' => 'Id is required for retrieve operation']);
                    exit;
                }
                $userData = $this->GetUserData($data['id']);
                if (!$userData) {
                    http_response_code(404); // Not Found
                    echo json_encode(['message' => 'error', 'details' => 'User not found']);
                    exit;
                }
                http_response_code(200); // OK
                echo json_encode(['message' => 'success', 'data' => $userData]);
                break;
            default:
                http_response_code(400); // Bad Request
                echo json_encode(['message' => 'error', 'details' => 'Invalid sub_action']);
        }
    }
}

