import com.example.MoSTState;

public class StateManager {
    private static final String CACHE_ROOT = "path/to/cache";
    private static final String THEME_DIR = "path/to/themes";

    public MoSTState loadStateOrRecycleTheme(String stateFilePath, String themeCacheFilePath) throws IOException {
        Path stateFile = Files.exists(Path.of(stateFilePath)) ? Path.of(stateFilePath) : Path.of("default-state.bin");
        try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(stateFile))) {
            return (MoSTState) ois.readObject();
        } catch (ClassNotFoundException e) {
            System.err.println("Error reading state: " + e.getMessage());
            return null;
        }
    }

    public void recycleTheme(Image themeBitmap) {
        if (themeBitmap != null) {
            ((BufferedImage) themeBitmap).getRGB(0, 0, 1, 1, null, 0, 1); // peek at pixels to trigger garbage collection
            themeBitmap.flush();
            themeBitmap = null;
        }
    }

    public Image loadTheme(String themeCacheFilePath) {
        Path cacheFile = Paths.get(CACHE_ROOT).resolve(Paths.get(themeCacheFilePath));
        if (!Files.exists(cacheFile)) {
            throw new FileNotFoundException("Theme cache file not found: " + themeCacheFilePath);
        }
        try {
            return ImageIO.read(new File(cacheFile.toString()));
        } catch (IOException e) {
            System.err.println("Error loading theme: " + e.getMessage());
            return null;
        }
    }

    public void ensureThemeDirectory() {
        if (!Files.exists(Paths.get(THEME_DIR))) {
            try {
                Files.createDirectories(Paths.get(THEME_DIR));
            } catch (IOException e) {
                System.err.println("Error initializing theme directory: " + e.getMessage());
            }
        }
    }
}
