const fs = require('fs-extra');
const path = require('path');
const async = require('async');

class FileReader {
  constructor(config) {
    this.baseDir = config.baseDir || process.cwd();
    this.extensions = (Array.isArray(config.extensions)) ? config.extensions : [config.extensions];
  }

  readDirectory(dir, cb) {
    fs.readdir(dir, (err, files) => {
      if (err) return cb(err);
      const tasks = files.map((file) => {
        const fullPath = path.join(dir, file);
        return fs.stat(fullPath, (err, stat) => {
          if (err || !stat.isFile()) return;
          const ext = path.extname(fullPath);
          if (!this.extensions.includes(ext)) return;
          cb(null, { file: fullPath, timestamp: stat.mtimeMs });
        });
      });
      async.series(tasks, (err, results) => cb(err, results));
    });
  }

  readFiles(dir, cb) {
    if (!fs.existsSync(dir)) return cb(new Error(`Directory does not exist: ${dir}`));
    this.readDirectory(dir, cb);
  }
}

module.exports = FileReader;
```

You can use this module in your application like this:

```javascript
const FileReader = require('./FileReader');
const reader = new FileReader({ extensions: ['png', 'jpg'] });
reader.readFiles(__dirname, (err, files) => {
  if (err) console.error(err);
  else files.forEach(({ file, timestamp }) => console.log(`${file} was last modified at ${timestamp}`));
});
```"]

