  if (currentTaskCount < config.maxConcurrentTasks) {
    try {
      const message = await sqs.receiveMessage({ QueueUrl: config.queueUrl, MaxNumberOfMessages: 1 }).promise();
      if (message.Body && !message.ReceiptHandle) {
