class DataBuffer {
  constructor(capacity) {
    this.buffer = [];
    this.capacity = capacity;
    this.hashMap = new Map();
  }

  addDataChunk(chunk, timestamp) {
    const hash = this._hashFunction(chunk);

    if (this.hashMap.has(hash)) return;

    this.hashMap.set(hash, true);

    // Remove older items when capacity is reached
    if (this.buffer.length >= this.capacity) {
      const [oldestChunk] = this.buffer.splice(0, 1);
      this.hashMap.delete(this._hashFunction(oldestChunk));
    }

    // Add the data chunk to the buffer with its timestamp
    this.buffer.push({ data: chunk, timestamp });
  }

  getCurrentData() {
    return this.buffer[this.buffer.length - 1]?.data;
  }

  _hashFunction(value) {
    // Implement your chosen hash function here
  }
}

