function generateSecureCredentials($characterSet, $length, $useSpecialChars) {
    $charset = str_split(str_replace(' ', '', $characterSet));
    $specialChars = ['!', '@', '#', '$', '%', '&', '*', '(', ')', '-', '_', '+', '=', '{', '[', '}', ']', '|', '\\', ':', '"', "'", ',', '<', '.>', '?'];
    $charset = array_merge($charset, $specialChars);

    $password = '';
    $hashedPassword = password_hash('your-actual-password-here', PASSWORD_DEFAULT); // Replace "your-actual-password-here" with a secure password.

    if ($useSpecialChars) {
        $password .= $charset[array_rand($charset)];
    }

    for ($i = 1; $i < $length; $i++) {
        $password .= $charset[array_rand($charset)];
    }

    return [$password, $hashedPassword];
}
