const fs = require('fs');

function readFileContents(filePath) {
    try {
        const encoding = 'utf8'; // Change this to adjust the encoding as needed
        let fileContent;

        // Handle potential race conditions and resource exhaustion
        const statSync = fs.statSync(filePath);
        if (statSync.isFile() && statSync.size <= 1000000) { // Adjust the size threshold as needed
            fileContent = fs.readFileSync(filePath, encoding);
        } else {
            throw new Error(`File "${filePath}" exceeds the specified size limit or does not exist.`);
        }

        return fileContent;
    } catch (error) {
        console.error(`Error reading file "${filePath}": ${error.message}`);
        throw error;
    }
}
