import json
import os
import sys
import threading
import logging
from collections import OrderedDict
from weakrefweakproxy import WeakRefProxy
from urllib.request import urlopen
from cachetools import TTLCache
import tempfile

class ConfigSetting:
    def __init__(self, key, value):
        self.key = key
        self.value = value

class ConfigException(Exception):
    pass

class ConfigValidator:
    def validate(self, setting):
        raise NotImplementedError("Must be implemented by subclasses.")

class SimpleConfigValidator(ConfigValidator):
    def validate(self, setting):
        # Basic validation for simple settings (e.g., strings, integers)
        if not isinstance(setting.value, str) and not isinstance(setting.value, int):
            raise ConfigException(f"Invalid value type for setting '{setting.key}': {type(setting.value)}")

class ExternalValidator(ConfigValidator):
    def __init__(self, url):
        self.url = url

    def validate(self, setting):
        try:
            response = urlopen(self.url)
            rules = json.load(response)
            # Custom validation logic using external rules
            if not self._validate_with_rules(setting, rules):
                raise ConfigException(f"Invalid setting '{setting.key}'")
        except Exception as e:
            logging.error(f"Failed to validate setting '{setting.key}': {e}")
            raise

    @staticmethod
    def _validate_with_rules(setting, rules):
        # Custom validation logic using external rules
        pass

class ConfigLoader:
    def __init__(self, config_file, validator=SimpleConfigValidator(), log_file="config.log"):
        self.validator = validator
        self.cache = TTLCache(maxsize=1000, ttl=60)  # Cache frequently accessed settings
        self.settings = OrderedDict()
        self._load_config(config_file)
        self.lock = threading.Lock()
        self.log = logging.getLogger(__name__)
        self.log.setLevel(logging.INFO)
        handler = logging.FileHandler(log_file, mode='w')
        handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s: %(message)s"))
        self.log.addHandler(handler)

    def _load_config(self, config_file):
        with open(config_file) as f:
            for line in f:
                try:
                    key, value = line.strip().split(":", maxsplit=1)
                    self.settings[key] = ConfigSetting(key, eval(value))
                    if key not in self.cache:
                        self.cache[key] = WeakRefProxy(self.settings[key])
                except Exception as e:
                    self.log.error(f"Failed to parse setting '{line}': {e}")
            self.sort_settings()

    def sort_settings(self):
        self.settings = sorted(list(self.settings.items()), key=lambda x: x[0])

    def get(self, key, default=None):
        with self.lock:
            if key in self.cache:
                return self.cache[key].value
            elif key in self.settings:
                self.validator.validate(self.settings[key])
                self.cache[key] = self.settings[key]
                return self.cache[key].value
        return default

    def get_sequence_number(self):
        sequence_number_key = "_seq_num"
        if sequence_number_key in self.get:
            seq_num = self.get(sequence_number_key)
            return int(seq_num.split(".")[-1])
        else:
            return 0

    def update(self, new_config):
        with tempfile.TemporaryFile() as tmp_file:
            for key, value in new_config.items():
                self.validator.validate(ConfigSetting(key, value))
                tmp_file.write(f"{key}: {value}\n")
            tmp_file.seek(0)
            with open("tmp_config.txt", "r") as f:
                self._load_config("tmp_config.txt")
        self.cache.clear()
        self.sort_settings()

def main():
