#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int id;
    struct State *next;
} State;

typedef struct FSA {
    // FSA specific members...
    pthread_mutex_t list_mutex;
    State *state_list;
    size_t max_size;
    size_t current_size;
    size_t last_index;
} FSA;

State* manage_state_list(int *states, int num_states, FSA *fsa) {
    if (fsa->max_size <= num_states) {
        return NULL;
    }

    pthread_mutex_lock(&fsa->list_mutex);

    // Allocate memory for a new state and add it to the list
    State *new_state = malloc(sizeof(State));
    if (!new_state) {
        pthread_mutex_unlock(&fsa->list_mutex);
        return NULL;
    }

    new_state->id = states[num_states - 1];
    new_state->next = fsa->state_list;
    fsa->state_list = new_state;

    // Increment the current size and update the last index if necessary
    fsa->current_size++;
    if (fsa->last_index < num_states - 1) {
        fsa->last_index = num_states - 1;
    }

    // Truncate the list if it exceeds the maximum allowed size
    while (fsa->current_size > fsa->max_size) {
        free(fsa->state_list);
        fsa->state_list = fsa->state_list->next;
        fsa->current_size--;
    }

    pthread_mutex_unlock(&fsa->list_mutex);

    // Update the 'next' pointer of the last state in the FSA
    if (fsa->state_list) {
        fsa->state_list->next = new_state;
    }

    return fsa->state_list;
}
```

