using UnityEngine;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;
    private Dictionary<string, object> externalDataCache;
    private readonly System.Object lockObject = new System.Object();

    public RandomValueGenerator(int min, int max, Dictionary<string, object> dataCache)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        minValue = min;
        maxValue = max;
        externalDataCache = dataCache;
    }

    public float GenerateRandomFloat()
    {
        lock (lockObject)
        {
            // Check cache for previously generated values to minimize external calls
            if (externalDataCache.ContainsKey($"float_{minValue}_{maxValue}"))
            {
                return (float)externalDataCache[$"float_{minValue}_{maxValue}"];
            }

            float result = UnityEngine.Random.Range((float)minValue, (float)maxValue + 1);
            externalDataCache[$"float_{minValue}_{maxValue}"] = result;
            return result;
        }
    }

    public int GenerateRandomInt()
    {
        lock (lockObject)
        {
            // Check cache for previously generated values to minimize external calls
            if (externalDataCache.ContainsKey($"int_{minValue}_{maxValue}"))
            {
                return (int)externalDataCache[$"int_{minValue}_{maxValue}"];
            }

            int result = UnityEngine.Random.Range(minValue, maxValue + 1);
            externalDataCache[$"int_{minValue}_{maxValue}"] = result;
            return result;
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
