class AggregationUtils {
  constructor(config = {}) {
    this.operation = config.operation || 'sum'; // sum, product, average, etc.
    this.strategy = config.strategy || 'sync'; // sync or async
    this.source = config.source;
  }

  async fetchData() {
    try {
      return await this.source();
    } catch (error) {
      console.error('Error while fetching data:', error);
      throw new Error('Failed to fetch data');
    }
  }

  aggregateSync(numbers) {
    if (!Array.isArray(numbers)) {
      throw new TypeError('Input must be an array');
    }

    if (numbers.length === 0) {
      return Promise.resolve(0);
    }

    let result = this[this.operation](numbers[0]);

    for (let i = 1; i < numbers.length; i++) {
      result = this[this.operation](result, numbers[i]);
    }

    return Promise.resolve(result);
  }

  async aggregateAsync(numbers) {
    if (!Array.isArray(numbers)) {
      throw new TypeError('Input must be an array');
    }

    const initialData = await this.fetchData();
    const result = await this.aggregateSync([...initialData, ...numbers]);

    return result;
  }
}

// Usage examples:
const aggUtils = new AggregationUtils({ operation: 'product', source: async () => [1, 2, 3] });

aggUtils.aggregateSync([4, 5, 6]).then(result => console.log(result)); // Output: 120
aggUtils.aggregateAsync([7, 8, 9]).then(result => console.log(result)); // Output: 360
```"]

