char* optimizeString(char *str, int maxLen, bool strict) {
    int len = strlen(str);
    if (len <= maxLen) return str;

    int i = len - 1;
    while ((strict && i > maxLen) || (!strict && i > maxLen - (int)strlen(&str[i]) + 1)) {
        i--;
    }
    str[i+1] = '\0';
