function enhancedDOMTraversal(root, cssSelector, classes, minDepth, callback) {
    const queue = [[root, 1]];
    const visited = new Set();
    const results = [];

    while (queue.length > 0) {
        let [node, depth] = queue.shift();
        if (depth < minDepth) continue;
        if (!visited.has(node)) {
            visited.add(node);
            if (cssSelector && !node.matches(cssSelector)) continue;
            if (classes && !classes.includes(node.className)) continue;
            if (callback(node)) results.push(node);
        }
        for (let child of node.children) {
            queue.push([child, depth + 1]);
        }
    }
    return results;
}
