    uint32_t sample_per_pixel;
    uint32_t number_of_extra_samples;
    unsigned char hash[MD5_DIGEST_LENGTH];
} ImageInfo;

ImageInfo* processImageAndComputeHash(const char* image_path, const char* string) {
    TIFF *image = TIFFOpen(image_path, "r");
    if (!image) {
        perror("Error opening the image file.");
        return NULL;
    }

    uint16_t photometric;
    int bitspersample = 0;
    tdata_t *buffer;

    TIFFGetField(image, TIFFTAG_PHOTOMETRIC, &photometric);

    switch (photometric) {
        case PHOTOMETRIC_MINISBLACK:
        case PHOTOMETRIC_MINISWHITE:
            bitspersample = 1;
            break;
        case PHOTOMETRIC_RGB:
            bitspersample = 8 * 3;
            break;
        // Add more cases as needed for other photometric interpretations
        default:
            fprintf(stderr, "Unsupported photometric interpretation.\n");
            TIFFClose(image);
            return NULL;
    }

    uint16_t samplesperpixel = 0;
    int planarconfig;
    if (TIFFGetFieldDefaulted(image, TIFFTAG_SAMPLESPERPIXEL, &samplesperpixel) == 0) {
        samplesperpixel = 1;
    }

    if (TIFFGetFieldDefaulted(image, TIFFTAG_PLANARCONFIG, &planarconfig) == 0) {
        planarconfig = PLANARCONFIG_CONTIG;
    }

    buffer = _TIFFmalloc(TIFFScanlineSize(image));

    ImageInfo *info = malloc(sizeof(ImageInfo));
    if (!info) {
        perror("Error allocating memory for the ImageInfo struct.");
        TIFFClose(image);
        return NULL;
    }

    info->bits_per_sample = bitspersample;
    info->sample_per_pixel = samplesperpixel;
    info->number_of_extra_samples = 0;

    uint32_t line;
    for (line = 0; line < TIFFScanlineCount(image); ++line) {
        if (TIFFReadScanline(image, buffer, line) != sizeof(buffer)) {
            perror("Error reading the image file.");
            free(info);
            TIFFClose(image);
            return NULL;
        }
    }

    info->hash = MD5((unsigned char*)string, strlen(string), info->hash);

    TIFFClose(image);
    free(_TIFFmalloc(buffer));

    return info;
}
