    if (baseNameLength == strlen(inputFilename)) { // no extension
        baseNameLength++;
    }

    const int extensionLenMax = 4;
    char extension[extensionLenMax + 1];
    sprintf(extension, ".%0*d", extensionLenMax - (baseNameLength - 1), baseNameLength);

    size_t dirPathLength = strspn(inputFilename, "/");

    size_t filenameLength = baseNameLength + strlen(extension) + dirPathLength;
    if (filenameLength >= 100) { // collision resolution
        time_t now = time(NULL);
        struct tm tm = *localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);
        counter++;

        int suffixIndex = 1; // start counting from the last part of the filename
        while (filenameLength + strlen(timestamp) + counter > 100) {
            if (suffixIndex >= 3) break; // we've reached the limit for extensions
            suffixIndex++;
            extension[extensionLenMax - suffixIndex] = (char)(counter % 10 + '0');
        }
    }

    char newFilename[sizeof(newFilename)];
    strncpy(newFilename, inputFilename, dirPathLength + baseNameLength); // copy the path and basename
    strcat(newFilename, extension);

    return newFilename;
}
