#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <err.h>
#include <string.h>
#include <execv.h>
#include <readline/history.h>
#include <readline/readline.h>

#define MAX_CMD_LEN 4096
#define MAX_ARG_COUNT 128

int exec_command(const char *cmd) {
    pid_t child_pid;
    int pipefd[2];
    char **argv;
    char *arglist[MAX_ARG_COUNT];
    char *token, *saveptr;
    int argc = 0, status;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 0;
    }

    /* Tokenize command */
    token = strtok_r(cmd, " ", &saveptr);
    while (token != NULL) {
        arglist[argc++] = token;
        token = strtok_r(NULL, " ", &saveptr);
    }
    arglist[argc] = NULL;

    /* Dynamically allocate and fill argv */
    argv = malloc((argc + 1) * sizeof(char*));
    for (int i = 0; i < argc; ++i) {
        argv[i] = arglist[i];
    }
    argv[argc] = NULL;

    /* Execute the command in the background */
    child_pid = fork();
    if (child_pid == -1) {
        perror("fork");
        free(argv);
        return 0;
    } else if (child_pid == 0) {
        /* Child process */
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        execv(cmd, argv);
        perror("execv");
        _exit(1);
    } else {
        /* Parent process */
        close(pipefd[1]);
        waitpid(child_pid, &status, WUNTRACED | WCONTINUED);

        /* Prevent child process from becoming a zombie */
        if (!WIFEXITED(status) && !WIFSIGNALED(status)) {
            kill(child_pid, SIGTERM);
            waitpid(child_pid, &status, 0);
        }
    }

    free(argv);

    /* Handle signal cleanup */
    signal(SIGCHLD, SIG_DFL);

    return WIFEXITED(status) ? WEXITSTATUS(status) : 0;
}
```

