import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.io.*;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

public class CommandExecutor {
    private static final Logger logger = LogManager.getLogger(CommandExecutor.class);
    private int retriesLeft;

    public void executeCommand(String command) throws Exception {
        if (retriesLeft <= 0) {
            throw new RuntimeException("No more retries allowed.");
        }

        Process process = null;
        try {
            // Attempt to execute the command
            process = Runtime.getRuntime().exec(command);

            // Read input and error streams
            InputStream is = process.getInputStream();
            InputStream es = process.getErrorStream();

            // Create threads for reading and logging the output/error stream
            new Thread(() -> readAndLogStream(is)).start();
            new Thread(() -> readAndLogStream(es)).start();

            // Wait for the process to complete or a timeout (30 seconds)
            Future<Integer> future = CompletableFuture.supplyAsync(() -> {
                try {
                    process.waitFor(30, TimeUnit.SECONDS);
                } catch (InterruptedException e) {
                    logger.error("Process interrupted.", e);
                }
                return process.exitValue();
            }).exceptionally(e -> {
                if (e instanceof ExecutionException && e.getCause() instanceof TimeoutException) {
                    // If timeout, log and decrease retries left before throwing exception
                    logger.error("Process timed out. Decreasing retries.");
                    decrementRetries();
                } else {
                    throw e;
                }
                return -1;
            });

            int exitValue = future.get();

            // Handle exit value (e.g., success or failure)
            if (exitValue == 0) {
                logger.info("Command executed successfully.");
            } else {
                logger.error("Command execution failed with exit code: " + exitValue);
            }
        } catch (IOException | InterruptedException e) {
            // Handle transient network issues or resource limitations by decreasing retries left and re-attempting the command execution
            if (!isNetworkError(e) && !isResourceLimitationError(e)) {
                logger.warn("Transient error occurred while executing command. Decreasing retries.");
                decrementRetries();
                executeCommand(command);
            } else {
                throw e;
            }
        } finally {
            if (process != null) {
                process.destroy();
            }
        }
    }

    private void decrementRetries() {
        retriesLeft--;
    }

    private boolean isNetworkError(Throwable e) {
        // Implement your logic to determine if the error is a network-related issue
        return false; // Replace with your own logic
    }

    private boolean isResourceLimitationError(Throwable e) {
        // Implement your logic to determine if the error is due to resource limitations
        return false; // Replace with your own logic
    }

    private void readAndLogStream(InputStream stream) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logger.info("Command output: " + line);
            }
        } catch (IOException e) {
            logger.error("Error reading command output.", e);
        }
    }

    private void deleteFileIfExists(String filePath) {
        if (new File(filePath).exists()) {
            new File(filePath).delete();
            logger.info("Deleted file: " + filePath);
        } else {
            logger.warn("Trying to delete non-existent file: " + filePath);
        }
    }
}
