#include <jansson/jansson.h>
#include <stdbool.h>
#include <pthread.h>
#include <string.h>
#include <sys/types.h>
#include <regex.h>
#include <pwd.h>

struct User {
    char *id;
    char *username;
    char *email;
    char *profile_picture_url;
};

bool isValidEmail(const char* email) {
    regex_t regex;
    regcomp(&regex, "\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}\\b", REG_EXTENDED);
    bool match = regexec(&regex, email, 0, NULL, 0) == 0;
    regfree(&regex);
    return match;
}

bool isPositiveInteger(const char* str) {
    long num;
    errno = 0;
    num = strtol(str, NULL, 10);
    return (num > 0 && errno == 0);
}

int hashUsername(char *username, int table_size) {
    unsigned long hash = 5381;
    int i;

    for (i = 0; username[i]; i++) {
        hash = ((hash << 5) + hash) + username[i]; /* hash * 33 + c */
    }

    return hash % table_size;
}

bool checkUsernameUniqueness(char **usernames, int len, char *username, int *index) {
    for (int i = 0; i < len; ++i) {
        if (!strcmp(usernames[i], username)) {
            *index = i;
            return false;
        }
    }

    *index = -1;
    return true;
}

bool processUserProfile(const char* json_str, User **user) {
    json_t *root, *id, *username, *email, *profile_picture_url;
    const char *error_ptr = NULL;
    size_t error_length = 0;
    int index;

    root = json_loads(json_str, 0, &error_ptr, &error_length);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error_ptr);
        return false;
    }

    id = json_object_get(root, "id");
    username = json_object_get(root, "username");
    email = json_object_get(root, "email");
    profile_picture_url = json_object_get(root, "profile_picture_url");

    if (!json_is_integer(id) || !json_is_string(username) || !json_is_string(email)) {
        json_decref(root);
        return false;
    }

    *user = malloc(sizeof(User));
    (*user)->id = strdup(json_string_value(id));
    (*user)->username = strdup(json_string_value(username));
    (*user)->email = strdup(json_string_value(email));
    if (profile_picture_url)
        (*user)->profile_picture_url = strdup(json_string_value(profile_picture_url));

    if (!isPositiveInteger((*user)->id) || !isValidEmail((*user)->email)) {
        json_decref(root);
        return false;
    }

    // Assuming a simple hash table for username uniqueness check
    static User users[1024];
    int user_table_size = sizeof(users) / sizeof(User);
    int index;

    if (!checkUsernameUniqueness((char **)users, user_table_size, (*user)->username, &index)) {
        json_decref(root);
        return false;
    }

    // Store the unique username in the table and return true
    users[index] = *user;
    json_decref(root);
    return true;
}
