using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public class DecodeBase64Message
{
    private readonly string _key;
    private readonly string _ivListUrl;

    public DecodeBase64Message(string key, string ivListUrl)
    {
        _key = key;
        _ivListUrl = ivListUrl;
    }

    public string DecryptAndValidate(string logEntry)
    {
        if (!IsBase64Encoded(logEntry))
            return "Error: Not Base64 encoded";

        try
        {
            var messageBytes = Convert.FromBase64String(logEntry);
            var message = Encoding.UTF8.GetString(messageBytes);

            using (var tripleDes = TripleDES.Create())
            {
                tripleDes.Key = Encoding.ASCII.GetBytes(_key);

                var ivList = FetchIVs();

                foreach (var iv in ivList)
                {
                    try
                    {
                        tripleDes.IV = Encoding.ASCII.GetBytes(iv);
                        var decryptedMessage = DecryptWithTripleDES(message, tripleDes);

                        if (ValidateHMACHash(decryptedMessage))
                            return decryptedMessage;
                    }
                    catch (Exception)
                    {
                        // Log error and skip to next IV
                    }
                }
            }

            // Return placeholder value indicating failure
            return "Error: Decryption failed";
        }
        catch (Exception e)
        {
            // Log error and return placeholder value indicating failure
            return $"Error: {e.Message}";
        }
    }

    private bool IsBase64Encoded(string input) => Convert.FromBase64String(input) != null;

    private string[] FetchIVs()
    {
        // Implement a mechanism to fetch IV list from external configuration management service
        // Here's an example using HttpClient and Json.NET library for simplicity
        var client = new WebClient();
        var jsonResponse = client.DownloadString(_ivListUrl);
        return JsonConvert.DeserializeObject<string[]>(jsonResponse);
    }

    private string DecryptWithTripleDES(string message, TripleDESCryptoServiceProvider tripleDes)
    {
        // Implement decryption with the given Triple DES algorithm
        using (var msEncrypt = new MemoryStream(Encoding.UTF8.GetBytes(message)))
        using (var msDecrypt = new MemoryStream())
        {
            var cs = tripleDes.CreateDecryptor();
            msEncrypt.CopyTo(msDecrypt, cs);
            return Encoding.UTF8.GetString(msDecrypt.ToArray());
        }
    }

    private bool ValidateHMACHash(string decryptedMessage)
    {
        // Implement HMAC hash validation using a provided key and the given decrypted message
        // Here's an example using SHA256 algorithm for simplicity
        var hmacKey = Encoding.ASCII.GetBytes(_key);
        var hmacHash = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(decryptedMessage));

