using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class MD5Hasher
{
    private readonly ConcurrentQueue<string> _queue = new ConcurrentQueue<string>();
    private readonly BlockingCollection<Task> _tasks = new BlockingCollection<Task>();
    private readonly int _maxDegreeOfParallelism;

    public MD5Hasher(int maxDegreeOfParallelism)
    {
        _maxDegreeOfParallelism = maxDegreeOfParallelism;
    }

    public void Add(string data)
    {
        if (string.IsNullOrEmpty(data))
            return;

        try
        {
            _queue.Enqueue(data);
        }
        catch (Exception ex)
        {
            // Log the error for further analysis
            Console.WriteLine($"Error enqueuing data: {ex.Message}");
        }
    }

    public void ProcessQueue()
    {
        var taskCompletionSource = Task.Run(() =>
        {
            while (true)
            {
                if (_queue.IsEmpty)
                    yield return Task.CompletedTask;

                string data;
                if (_queue.TryDequeue(out data))
                {
                    try
                    {
                        var md5 = ComputeMD5Hash(data);
                        // Persist metadata and hash to external storage
                        // ...
                        Console.WriteLine($"Hashed: {data} -> {md5}");
                    }
                    catch (Exception ex)
                    {
                        // Log the error for further analysis
                        Console.WriteLine($"Error hashing data: {ex.Message}");
                    }
                }
            }
        });

        _tasks.Add(taskCompletionSource);
        Task.WhenAll(_tasks.GetConsumingEnumerable(), task => task).Wait();
    }

    private string ComputeMD5Hash(string data)
    {
        using (var md5 = MD5.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(data);
            return BitConverter.ToString(md5.ComputeHash(bytes)).Replace("-", "");
        }
    }
}
```

