        private readonly byte[] _key;
        private readonly byte[] _iv;

        public AesGcmEncryptionService(byte[] key, byte[] iv)
        {
            _key = key;
            _iv = iv;
            _aes = new Aes256GCM(_key);
        }

        public async Task<EncryptedMessage> EncryptAsync(string plainText)
        {
            // Generate a new IV for each message
            var ivBytes = RandomNumberGenerator.GetBytes(12);
            _iv = ivBytes;

            var encryptor = _aes.CreateEncryptor(_key, _iv);
            using (var memoryStream = new MemoryStream())
            {
                using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
                {
                    using (var writer = new StreamWriter(cryptoStream))
                    {
                        await writer.WriteAsync(plainText);
                    }

                    cryptoStream.FlushFinalBlock();
                }

                var cipherTextBytes = memoryStream.ToArray();
                var tagBytes = _aes.TagLength;
                var tag = _aes.CreateTag(cipherTextBytes);

                return new EncryptedMessage
                {
                    CipherText = cipherTextBytes,
                    Tag = tag,
                    Iv = _iv,
                    Timestamp = DateTimeOffset.Now,
                };
            }
        }

        public async Task<string> DecryptAsync(EncryptedMessage encryptedMessage)
        {
            var cipherTextBytes = encryptedMessage.CipherText;
            var tagBytes = encryptedMessage.Tag;
            var ivBytes = encryptedMessage.Iv;

            try
            {
                using (var decryptor = _aes.CreateDecryptor(_key, ivBytes))
                {
                    using (var memoryStream = new MemoryStream(cipherTextBytes))
                    {
                        var tagVerificationResult = _aes.VerifyTag(memoryStream, tagBytes);

                        if (!tagVerificationResult)
                            throw new Exception("Invalid tag or tampered message");

                        using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                        {
                            using (var reader = new StreamReader(cryptoStream))
                            {
                                var plainText = await reader.ReadToEndAsync();
                                return plainText;
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                // Log the error with relevant details such as timestamp, error code, recovery action, etc.
                // Implement a retry mechanism to recover from decryption failures
                throw;
            }
        }

        public void Dispose()
        {
            _aes?.Dispose();
        }
    }
}
