const { ChildProcess, exec, execSync } = require('child_process');
const { promisify } = require('util');
const throttle = require('lodash/throttle');
const trace = require('tracer'); // Assuming you have a distributed tracing library called tracer.

const execPromise = promisify(exec);

function executeCommand(command, args, options) {
  const commandProcess = ChildProcess.spawn(command, args, {
    cwd: options.cwd,
    env: process.env,
    stdio: 'inherit', // Stream output to the frontend in real-time
    ...options,
  });

  trace.info(`Executing command: ${command} with arguments: ${args}`);

  // Throttling for rate limiting during peak usage periods
  const executeCommandThrottled = throttle(async function (command, args) {
    try {
      await execPromise(command, args, options);
    } catch (error) {
      trace.error(`Error executing command: ${command} with arguments: ${args}:`, error);
    }
  }, 500); // Adjust the interval according to your requirements

  executeCommandThrottled(command, args);
}

module.exports = { executeCommand };
```

