    lock = threading.Lock()
    factories: Dict[str, Dict[str, Callable[[Any], Type["DataProcessor"]]]] = {}

    @staticmethod
    def register_factory(id: str, factory: Dict[str, Callable[[Any], Type["DataProcessor"]]]):
        with DataProcessorRegistry.lock:
            DataProcessorRegistry.factories.setdefault(id, {})
            for sub_id, factory_func in factory.items():
                DataProcessorRegistry.factories[id][sub_id] = factory_func

