typedef struct Record {
    int value;
    long offset;
    int key;
} Record;

pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_records = 0;
static size_t max_records = 0;
static Record* records = NULL;
static void* data_source = NULL;

void update_data_source(void) {
    // Implement the logic for updating the offset and key arrays
    // from an external data source, ensuring graceful degradation in case of network issues or data source unavailability
}

Record* create_record_array(size_t num_records, size_t value_range) {
    Record* array = malloc(num_records * sizeof(Record));
    if (!array) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        array[i].value = rand() % value_range;
        // Use posix_memalign to align memory on a cache line boundary for better performance
        if (posix_memalign(&array[i].offset, sizeof(long), num_records * sizeof(long)) != 0) {
            free(array);
            return NULL;
        }
        if (posix_memalign(&array[i].key, sizeof(int), num_keys * sizeof(int)) != 0) {
            free(array->offset);
            free(array);
            return NULL;
        }
    }
    return array;
}

Record* add_record(size_t value, size_t* offset, size_t* key) {
    pthread_mutex_lock(&records_lock);

    if (total_records + 1 > max_records) {
        printf("Memory usage exceeded the threshold\n");
        pthread_mutex_unlock(&records_lock);
        return NULL;
    }

    Record* new_record = realloc(records, sizeof(Record) * (total_records + 1));
    if (!new_record) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&records_lock);
        return NULL;
    }

    new_record[total_records].value = value;
    *offset = total_records;
    *key = total_records;

    total_records++;
    records = new_record;
    pthread_mutex_unlock(&records_lock);

    return &new_record[total_records - 1];
}

void cleanup() {
    free(records->value);
    free(records->offset);
    free(records);
    data_source = NULL;
}
```

The `create_record_array` function creates an array of `Record` structures and initializes their values within a specified range. It uses posix_memalign to optimize memory alignment for better performance.

