["```cpp
#include <iostream>
#include <mutex>
#include <thread>
#include <vector>
#include <boost/circular_buffer.hpp>
#include <mt19937ar>
#include <random>

class RandomSemaphore {
public:
    explicit RandomSemaphore(unsigned int initialValue) : semaphore(initialValue), rng() {
        std::mt19937_64 engine;
        engine.seed(static_cast<std::uint64_t>(std::random_device{}()));
        rng.reset(new std::mt19937_64[numThreads]);
        for (size_t i = 0; i < numThreads; ++i) {
            new (rng[i]) std::mt19937_64(engine);
        }
    }

    unsigned int acquire() {
        std::unique_lock<std::mutex> lock(stateMutex);
        semaphore.wait();
        lock.unlock();

        auto now = boost::circular_buffer<unsigned long long>(64, lockStateCB);
        unsigned int idx = static_cast<unsigned int>(now.size() - 1);
        std::uniform_int_distribution<> dist(0, UINT64_MAX);
        auto rngIdx = static_cast<size_t>(dist(*rng[myThreadId % numThreads]) % numThreads);
        now.push_back(std::chrono::steady_clock::now().time_since_epoch().count());
        idx = (idx + rngIdx) % now.size();

        unsigned long long state = now[idx];
        auto gen64 = [&]() { return dist(*rng[myThreadId % numThreads])(state); };
        std::uniform_int_distribution<> dist32(0, UINT32_MAX);
        unsigned int randomNumber = static_cast<unsigned int>(dist32(gen64) & (UINT32_MAX >> 1)) | (static_cast<unsigned int>(dist32(gen64) << 1));
        semaphore.post(1);
        lock.lock();
        state += 1;
        lock.unlock();

        return randomNumber;
    }

private:
    std::mutex stateMutex;
    std::semaphore semaphore;
    std::vector<std::unique_ptr<std::mt19937_64>> rng;
    unsigned int myThreadId = std::hash<std::thread::id>{}(std::this_thread::get_id());
    static constexpr size_t numThreads = std::max(std::thread::hardware_concurrency(), 1);

    void lockStateCB(boost::circular_buffer<unsigned long long>& cb) {
        std::unique_lock<std::mutex> lock(cb.get_mutex());
    }
};
```

The class `RandomSemaphore` implements a thread-safe random number generator using the Mersenne Twister algorithm. The class manages a semaphore for fair access to the random number generation functionality, ensuring that each thread waits its turn while respecting the semaphore's initial value. It uses Boost circular buffer to store the state of the RNG and minimizes lock contention by using a single mutex for state persistence and locking only when necessary. The class is scalable, optimized for multi-threaded environments, and minimizes memory usage by sharing the random number generator's state between threads."]

