import java.io.*;
import java.math.BigInteger;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import com.google.common.cache.*;

public class FileHashManager {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final LoadingCache<String, BigInteger> cache = CacheBuilder.newBuilder()
                                            .maximumSize(1000) // Adjust based on cache size requirements
                                            .expireAfterAccess(1, TimeUnit.HOURS)
                                            .build(new CacheLoader<String, BigInteger>() {
        @Override
        public BigInteger load(String key) throws Exception {
            return computeHash(key);
        }
    });

    private static BigInteger computeHash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (FileInputStream inputStream = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return digest.digest();
    }

    public String getHashedFileList(List<String> filePaths) throws ExecutionException, InterruptedException {
        List<Callable<BigInteger>> tasks = new ArrayList<>();

        for (String filePath : filePaths) {
            if (!Files.exists(Paths.get(filePath)) || !Files.isRegularFile(Paths.get(filePath))) {
                System.out.println("Error: " + filePath + " is not a regular file.");
                continue;
            }
            tasks.add(() -> computeHash(filePath));
        }

        List<Future<BigInteger>> futures = executor.invokeAll(tasks);
        StringBuilder output = new StringBuilder();
        for (Future<BigInteger> future : futures) {
            BigInteger hash = cache.getIfPresent(future.get().toString());
            if (hash != null) {
                output.append(hash.toString());
            } else {
                output.append(future.get().toString());
                cache.put(future.get().toString(), future.get());
            }
        }
        return output.toString();
    }
}
```

