    strncpy(file, ext_start == filename ? "" : ext_start, len - (ext_start != filename)); // Extract file name and extension
    strcat(dir, num_digits > 0 ? fmt("%03d.txt", rand() % 1000) : ".txt"); // Append new extension or empty string if original has no extension
