void read_and_populate(NFAPI_CRC_INDICATION_PDU_T** data, size_t* num_elements) {
    size_t i = 0;
    *num_elements = 0;

    // Allocate memory for the number of elements read
    *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*num_elements));
    if (!*data) {
        perror("Error allocating memory");
        return;
    }

    while (1) {
        // Read RX_UE_INFORMATION_TAG and store in the current structure
        scanf("%u", &((*data)[i].RX_UE_INFORMATION_TAG));

        // Check if input is valid or EOF was reached
        int c;
        while ((c = getchar()) != '\n' && c != EOF) {}
        if (feof(stdin)) break;
        else if (ferror(stdin)) {
