        // Read RNTI and store in the current structure
        scanf("%hu", &((*data)[i].RNTI);

        // Check if input is valid or EOF was reached
        while ((c = getchar()) != '\n' && c != EOF) {}
        if (feof(stdin)) break;
        else if (ferror(stdin)) {
