struct Record {
    std::atomic<int> value;
};

class TestHarness {
public:
    void runTests(unsigned int numThreads, unsigned int numRecords) {
        // Initialize records with random values
        for (unsigned int i = 0; i < numRecords; ++i) {
            records_[i].value.store(rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE);
        }

        std::vector<std::thread> threads;
        std::mutex mtx;
        for (unsigned int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this, &mtx]() {
                auto startTime = std::chrono::high_resolution_clock::now();
                for (unsigned int j = 0; j < numRecords; ++j) {
                    // Simulate some random workload here
                    std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 100));
                    auto offset = rand() % numRecords;

                    // Update value atomically to ensure thread safety
                    int newValue = records_[offset].value.load();
                    int oldValue;
                    while (!records_[offset].value.compare_exchange_weak(oldValue, newValue + 1)) {
                        std::this_thread::yield();
                    }
                }
                auto endTime = std::chrono::high_resolution_clock::now();
                auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();

                // Log the runtime metrics here
                log_(duration);
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    void log_(unsigned long duration) {
        std::cout << "Test completed in " << duration << "ms" << std::endl;
    }

    std::unordered_map<long, Record> records_;
};
