struct semaphore {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int count;
};

int mem_limit = 100000000; // Adjustable memory limit (bytes)
long *offsets = NULL;
int *keys = NULL;
record *records = NULL;
struct semaphore sem;

void init_semaphore(int initial_value) {
    pthread_mutex_init(&sem.lock, NULL);
    pthread_cond_init(&sem.cond, NULL);
    sem.count = initial_value;
}

void delete_semaphore() {
    pthread_mutex_destroy(&sem.lock);
    pthread_cond_destroy(&sem.cond);
}

int random_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void *create_data_structures(void *arg) {
    long num_records = *(long *) arg;
    long memory_used = 0;

    offsets = mmap(NULL, num_records * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (offsets == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    memory_used += num_records * sizeof(long);

    keys = malloc(num_records * sizeof(int));
    if (!keys) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    memory_used += num_records * sizeof(int);

    records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    memory_used += num_records * sizeof(record);

    if (memory_used > mem_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&sem.lock);
    sem.count = num_records;
    pthread_mutex_unlock(&sem.lock);

    return NULL;
}

int find_largest_integer() {
    int largest = INT_MIN;
    for (size_t i = 0; i < keys && keys[i] < LONG_MAX / sizeof(record); ++i) {
        if (records[keys[i]].value > largest) {
            largest = records[keys[i]].value;
        }
    }
    return largest;
}

int main() {
    init_semaphore(1);
    pthread_t thread;
    long num_records = 1000000; // Adjustable number of records

    pthread_create(&thread, NULL, create_data_structures, &num_records);
    pthread_join(thread, NULL);
    delete_semaphore();

    // Initialize input buffer and read integers from standard input
    int input;
    for (size_t i = 0; i < num_records; ++i) {
        scanf("%d", &input);
        keys[i] = i;

        pthread_mutex_lock(&sem.lock);
        while (sem.count == 0) {
            pthread_cond_wait(&sem.cond, &sem.lock);
        }
        offsets[records[--sem.count].offset] = i;
        records[sem.count].value = input;
        records[sem.count].offset = i;
        pthread_mutex_unlock(&sem.lock);
    }

    printf("Largest integer: %d\n", find_largest_integer());

    // Deallocate memory and close resources
    munmap(offsets, num_records * sizeof(long));
    free(keys);
    free(records);

    return 0;
}
```

