#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/time.h>

typedef struct Record {
    int value;
} Record;

struct MemoryManager {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t used;
    size_t limit_kb;
};

void *mmap_region(size_t length, size_t alignment) {
    void *ptr = mmap(NULL, length + (alignment - 1), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return (void *)(((size_t)ptr + alignment - 1) & ~(alignment - 1));
}

struct MemoryManager *create_memory_manager(size_t initial_capacity, size_t limit_kb) {
    struct MemoryManager *mm = mmap_region(sizeof(*mm), sizeof(void*));
    mm->offsets = (long *)((char*)mm + sizeof(*mm));
    mm->keys = (int *)((char*)mm->offsets + initial_capacity * sizeof(long));
    mm->records = (Record **)((char*)mm->keys + initial_capacity * sizeof(long));
    mm->capacity = initial_capacity;
    mm->used = 0;
    mm->limit_kb = limit_kb;
    return mm;
}

void resize_memory_manager(struct MemoryManager *mm) {
    size_t new_capacity = mm->capacity * 2;
    void *temp = mmap_region(new_capacity * sizeof(long) + new_capacity * sizeof(Record*), sizeof(void*));
    memcpy((char*)temp + sizeof(*temp), (char*)mm->offsets, mm->used * sizeof(long));
    memcpy((char*)temp + mm->used * sizeof(long), (char*)mm->records, mm->used * sizeof(Record*));
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    mm->offsets = (long *)((char*)temp + sizeof(*temp));
    mm->keys = (int *)((char*)mm->offsets + new_capacity * sizeof(long));
    mm->records = (Record **)((char*)mm->keys + new_capacity * sizeof(long));
    mm->capacity = new_capacity;
}

struct MemoryManager *init_memory_manager(size_t initial_capacity, size_t limit_kb) {
    struct MemoryManager *mm = create_memory_manager(initial_capacity, limit_kb);
    if (mm->used + sizeof(long) + sizeof(Record*) > mm->limit_kb * 1024)
        resize_memory_manager(mm);
    return mm;
}

int main() {
