#include <pthread.h>

/* Define maximum filename length, adjust for your specific system */
#define MAX_FILENAME_LENGTH 255

typedef struct {
    char **extensions;
    size_t num_extensions;
    pthread_mutex_t mutex;
} Config;

Config *load_config(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) return NULL;

    Config *config = malloc(sizeof(Config));
    config->num_extensions = 0;
    config->mutex = PTHREAD_MUTEX_INITIALIZER;

    char line[MAX_FILENAME_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        if (strchr(line, '\n')) *strchr(line, '\n') = 0;
        size_t len = strlen(trim(line));
        if (!len) continue;
        config->extensions = realloc(config->extensions, sizeof(char *) * ++config->num_extensions);
        config->extensions[config->num_extensions - 1] = strdup(line);
    }

    fclose(file);
    return config;
}

char *trim(char *str) {
    char *end;

    /* Trim leading space */
    while (isspace(*str)) str++;

    if (*str == 0) return str;

    /* Find the end of the string to trim whitespace from */
    end = str + strlen(str) - 1;
    while (end > str && isspace(*end)) end--;

    /* Truncate the string and null-terminate */
    *(end + 1) = 0;
    return str;
}

/* Determine if a given filename ends with an extension */
bool has_extension(const char *filename, const char *extension) {
    size_t filename_len = strlen(filename);
    size_t extension_len = strlen(extension);
    return (filename_len >= extension_len && strcmp(filename + filename_len - extension_len, extension));
}

/* Analyze character distribution entropy of a given string */
float analyze_entropy(const char *str) {
    size_t len = strlen(str);
    if (!len) return 0.0;

    int counts[256] = {0};
    for (size_t i = 0; i < len; ++i)
        counts[(unsigned char)str[i]]++;

    float total = len * log(2.0);
    for (size_t i = 0; i < 256; ++i) {
        if (!counts[i]) continue;
        total -= counts[i] * log(counts[i]);
    }

    return total / len;
}

/* Determine the new file extension length based on entropy */
size_t determine_extension_length(float entropy) {
    const float min_entropy = 0.5;
    const size_t max_extension_length = 8;
    return (entropy - min_entropy) * (max_extension_length - 1) + 1;
}

/* Rename a file, returning true if successful */
bool rename_file(const char *old_path, const char *new_path) {
    int oldfd = open(old_path, O_RDONLY);
    if (oldfd == -1) return false;

    struct stat st;
    fstat(oldfd, &st);
    close(oldfd);

    char *new_filename = malloc(st.st_size + 1);
    memset(new_filename, 0, st.st_size + 1);
    if (readlinkat(AT_FDCWD, old_path, new_filename, st.st_size) != -1) {
        /* Extract filename and extension */
        char *dot = strrchr(new_filename, '.');
        size_t filename_len = dot ? (dot - new_filename) : st.st_size;
        char *extension_len = dot ? (dot + 1) : NULL;

        /* Determine extension from last three characters of original filename */
        if (!extension_len || strlen(extension_len) < 3) {
            free(new_filename);
            return false;
        }

        /* Load known extensions and determine new file type */
        Config *config = load_config("/path/to/config.txt");
        if (!config) {
            free(new_filename);
            return false;
        }

        pthread_mutex_lock(&config->mutex);
        for (size_t i = 0; i < config->num_extensions; ++i) {
            if (has_extension(extension_len, config->extensions[i])) {
                char *new_ext = strdup(config->extensions[i]);
                size_t ext_len = strlen(new_ext);
                /* Adjust new extension length based on entropy analysis */
                new_ext[determine_extension_length(analyze_entropy(new_filename)) - 1] = 0;
                strncat(new_filename, new_ext, MAX_FILENAME_LENGTH - filename_len);
                break;
            }
        }
        pthread_mutex_unlock(&config->mutex);
        free(config);

        if (!*new_filename) {
            free(new_filename);
            return false;
        }
    }

    /* Create the new filename and extension, removing any special characters */
    iconv_t cd = icontv_open("UTF-8", "ASCII//TRANSLIT");
    char *new_basename = icontv(cd, new_filename, st.st_size + 1, &st.st_size);
    icontv_close(cd);
    free(new_filename);

    mkdir("/tmp/renamed", S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);
    char tmp_path[MAX_FILENAME_LENGTH];
    snprintf(tmp_path, sizeof(tmp_path), "/tmp/renamed/%s", new_basename);

    /* Move the file temporarily to a safe location */
    if (rename(old_path, tmp_path) == -1 || mkdir("/tmp/processed", S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH) == -1 ||
        link(tmp_path, new_path) == -1 || rmdir("/tmp/renamed") == -1 || rmdir("/tmp/processed") == -1) {
        free(new_basename);
        return false;
    }

    free(new_basename);
    return true;
}
