typedef struct {
    double value;
    char key;
} data_point;

#define MAX_KEYS 100
char keys[MAX_KEYS];
size_t num_keys = 0;

// Memory limit (in bytes)
unsigned long mem_limit = 1000000; // Adjust as needed
unsigned long total_allocated = 0;

void log_memory() {
    printf("Total allocated: %lu bytes\n", total_allocated);
}

int allocate_and_initialize(data_point **array, size_t *size) {
    if (total_allocated + sizeof(*array) + (*size) * sizeof(**array) > mem_limit) {
        printf("Memory limit exceeded\n");
        return -1;
    }

    *array = malloc((*size) * sizeof(**array));
    if (!*array) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        return -1;
    }

    total_allocated += (*size) * sizeof(**array);
    log_memory();
    return 0;
}

void free_data_points(data_point **array, size_t size) {
    if (!array) return;
    free(*array);
    total_allocated -= size * sizeof(**array);
    log_memory();
}

int add_data_point(data_point **array, size_t *size, char key) {
    if (num_keys >= MAX_KEYS || key < 0 || key >= num_keys) return -1; // Invalid index

    data_point *new_data = &((*array)[(*size)++]);
    new_data->key = key;
    new_data->value = (double)(rand() % INT_MAX) / RAND_MAX * 2.0 - 1.0; // Random value between -1 and 1

    total_allocated += sizeof(**array);
    log_memory();
    return 0;
}

void print_largest_number(data_point *array, size_t size) {
    double largest = -INFINITY;
    for (size_t i = 0; i < size; ++i) {
        if (array[i].value > largest)
            largest = array[i].value;
    }
    printf("Largest number: %.2f\n", largest);
}

int serialize(const data_point *array, size_t size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    fwrite(&size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < size; ++i) {
        fwrite(&array[i].value, sizeof(double), 1, file);
        fwrite(&array[i].key, sizeof(char), 1, file);
    }
    fclose(file);
    return 0;
}

int deserialize(data_point **array, size_t *size, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return -1;
    }

    size_t temp_size;
    fread(&temp_size, sizeof(size_t), 1, file);
    *array = malloc(temp_size * sizeof(**array));
    if (!*array) {
        fprintf(stderr, "Failed to allocate memory for deserialized array\n");
        fclose(file);
        return -1;
    }
    *size = temp_size;

    for (size_t i = 0; i < *size; ++i) {
        fread(&((*array)[i].value), sizeof(double), 1, file);
        fread(&((*array)[i].key), sizeof(char), 1, file);
    }
    fclose(file);

    // Ensure keys are valid indices and update num_keys if necessary
    for (size_t i = 0; i < *size; ++i) {
        if (num_keys <= (*array)[i].key || (*array)[i].key < 0) return -1;
        if ((*array)[i].key >= num_keys) num_keys = (*array)[i].key + 1;
    }
    return 0;
}
```

