struct NetworkInterfaceConfig {
    int bandwidth;
    float latency_tolerance;
    int qos;
};

class NetworkManager {
private:
    std::list<std::unique_ptr<NetworkInterfaceConfig>> configs_;
    std::mutex mtx_;
    std::atomic<int> resize_threshold_;
    std::function<void(const NetworkInterfaceConfig&)> external_monitoring_service_;

public:
    NetworkManager(int resize_threshold, std::function<void(const NetworkInterfaceConfig&)> external_monitoring_service)
        : resize_threshold_(resize_threshold),
          external_monitoring_service_(external_monitoring_service) {}

    void add_config(NetworkInterfaceConfig config) {
        // Dynamic resizing based on network load metrics
        if (configs_.size() >= resize_threshold_) {
            std::unique_ptr<NetworkInterfaceConfig> to_remove = configs_.front();
            configs_.pop_front();
            delete to_remove;
        }

        // Add the new configuration
        configs_.emplace_back(std::make_unique<NetworkInterfaceConfig>(config));

        // Call external monitoring service with the added configuration
        external_monitoring_service_(config);
    }

    void update_config(int index, NetworkInterfaceConfig config) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (index >= 0 && index < configs_.size()) {
            configs_[index]->bandwidth = config.bandwidth;
            configs_[index]->latency_tolerance = config.latency_tolerance;
            configs_[index]->qos = config.qos;
        }
    }

    // Provide API for administrators to configure and monitor the network
    // interface configurations remotely
};
