#include <boost/graph/adjacency_list.hpp> // Third-party library for graph database

typedef boost::property<boost::vertex_index_t, int> VertexIndex;
typedef boost::property<boost::edge_index_t, int> EdgeIndex;
typedef boost::adjacency_list<boost::vecS, boost::vecS, boost::undirectedS, VertexIndex, EdgeIndex> Graph;

void initializeGraph(Graph& graph, size_t numVertices, size_t numEdges, boost::unordered_map<int, long>& keys, boost::unordered_map<long, int>& offsets, boost::unordered_map<int, int>& records) {
    // Initialize arrays for keys, offsets, and records
    keys.reserve(numVertices);
    offsets.reserve(numVertices);
    records.reserve(numVertices);

    // Set seed for random number generation
    srand(time(NULL));

    // Initialize arrays with default values
    long* offsetArr = (long*) malloc(sizeof(long) * (numVertices + 1));
    int* keyArr = (int*) malloc(sizeof(int) * numVertices);
    int* recordArr = (int*) malloc(sizeof(int) * numVertices);

    // Initialize offset array with initial value of zero and increment by the number of vertices for each vertex
    offsetArr[0] = 0;
    for (size_t i = 1; i <= numVertices; ++i) {
        offsetArr[i] = offsetArr[i - 1] + 1;
    }

    // Initialize keys and records arrays with randomly generated values within specified ranges
    for (size_t i = 0; i < numVertices; ++i) {
        keyArr[i] = rand() % (numVertices * 2);
        records[offsetArr[i]] = rand() % 100;
    }

    // Add vertices and edges to the graph database
    for (size_t i = 0; i < numEdges; ++i) {
        int u = rand() % numVertices;
        int v = (u + 1) % numVertices;
        graph.add_edge(u, v);

        // Set properties for the vertex and edge using keys and records arrays
        keys[rand() % numVertices] = offsetArr[u];
        offsets[offsetArr[u]] = u;
        recordArr[u] = records[keys[u]];
    }

    free(offsetArr);
    free(keyArr);
    free(recordArr);
}
