#define MAX_RECORDS 1000
#define MIN_INT 0
#define MAX_INT 100

struct record {
    time_t timestamp;
    int status;
    int value;
};

int execute_command(const char* command) {
    pid_t pid;
    FILE *fp;
    int exit_status;
    char **arguments;
    char working_dir[1024];

    // Get the current working directory
    getcwd(working_dir, sizeof(working_dir));

    // Allocate memory for command arguments and fill with required values
    arguments = (char**)malloc((sizeof(char*) + strlen(command) + 1) * 2);
    if (!arguments) {
        perror("Memory allocation failure");
        return -1;
    }

    // Set the command and arguments in the array
    snprintf(arguments[0], sizeof(arguments[0]), "-c");
    snprintf(arguments[1], sizeof(arguments[1]), command);
    arguments[2] = NULL;

    if (access(working_dir, WRTABLE) != -1) { // If the working directory is writable, remove any existing target file
        char target_file[1024];
        snprintf(target_file, sizeof(target_file), "%s/%s", working_dir, command);
        if (remove(target_file) != 0) {
            perror("Failed to remove target file");
            return -1;
        }
    }

    pid = fork();
    if (pid < 0) { // Error occurred while forking
        perror("Fork failed");
        return -1;
    } else if (pid == 0) { // Child process
        // Redirect the standard error to the parent's standard error, close the child's stderr
        dup2(STDOUT_FILENO, STDERR_FILENO);
        close(STDERR_FILENO);
        // Execute the command
        execvp(arguments[0], &arguments[0]);
        perror("Command execution failure");
        exit(1);
    } else { // Parent process
        waitpid(pid, &exit_status, 0);
    }

    free(arguments);
    return WEXITSTATUS(exit_status);
}

void init_arrays(long** offsets, int** keys, struct record** records, size_t num_records) {
    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)calloc(num_records, sizeof(int));
    *records = (struct record*)calloc(num_records, sizeof(struct record));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].timestamp = time(NULL);
        records[i].status = 0;
        // Generate random integer values within the specified range
        records[i].value = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s num_records command\n", argv[0]);
        return 1;
    }

    size_t num_records = atoi(argv[1]);
    char* command = argv[2];

    long* offsets;
    int* keys;
    struct record* records;

    init_arrays(&offsets, &keys, &records, num_records);

    int exit_code = execute_command(command);

    free(offsets);
    free(keys);
