int compare_keys(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

void* read_csv_and_populate(void *arg) {
    FILE *file = (FILE *) arg;
    char buffer[1024];
    record *records = NULL;
    int *keys = NULL, num_keys = 0, max_keys = 0;
    long *offsets = NULL, num_offsets = 0, max_offsets = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        char *token = strtok(buffer, "\t");
        if (!token) continue;

        int key = atoi(token);
        if (max_keys < num_keys + 1) max_keys = num_keys + 1;
        if (find(keys, num_keys, key) != num_keys) { // Binary search for duplicate keys
            keys = realloc(keys, sizeof(int) * (max_keys));
            records = realloc(records, sizeof(record) * (num_keys + 1));
            keys[num_keys] = key;
        }

        if (token = strtok(NULL, "\t")) {
            long offset = atol(token);
            if (max_offsets < num_offsets + 1) max_offsets = num_offsets + 1;
            if (!records[num_keys].transaction_id) { // Use existing ID if present, otherwise generate a new one
                int existing_id = atoi(token);
                records[num_keys].transaction_id = (existing_id > 0) ? existing_id : rand() % INT_MAX;
            }
            offsets = realloc(offsets, sizeof(long) * (max_offsets));
            offsets[num_offsets++] = offset;
        }
    }

    qsort(keys, num_keys, sizeof(int), compare_keys);
    return NULL;
}

void populate_data_structures(char *filename) {
    pthread_t threads[BUFFERS];
