2. Database Update Function (`update_profile.c`)

```c
#include <sqlite3.h>

typedef struct dao {
    sqlite3 *db;
    sqlite3_stmt *stmt;
} dao;

void init_dao(const char *filename, const char *update_sql, dao *da) {
    int rc = sqlite3_open(filename, &da->db);
    if (rc) error("Can't open database: %s\n", sqlite3_errmsg(da->db));

    rc = sqlite3_prepare_v2(da->db, update_sql, -1, &da->stmt, NULL);
    if (rc != SQLITE_OK) error("SQL error: %s\n", sqlite3_errmsg(da->db));
}

void update_profile(dao *da, int id, const char *name, const char *email) {
    if (!name || !email) error("Missing required fields.");

    sqlite3_reset(da->stmt); // Reset the statement to prepare for a new execution
    sqlite3_bind_int(da->stmt, 1, id);
    sqlite3_bind_text(da->stmt, 2, name, strlen(name), SQLITE_TRANSIENT);
    sqlite3_bind_text(da->stmt, 3, email, strlen(email), SQLITE_TRANSIENT);

    int rc = sqlite3_step(da->stmt);
    if (rc != SQLITE_DONE) error("SQL error: %s\n", sqlite3_errmsg(da->db));
}

void commit(dao *da) {
    int rc = sqlite3_exec(da->db, "COMMIT;", NULL, NULL, NULL);
    if (rc != SQLITE_OK) error("SQL error: %s\n", sqlite3_errmsg(da->db));
}

void finalize_dao(dao *da) {
    sqlite3_finalize(da->stmt);
    sqlite3_close(da->db);
}
