#include <pthread.h>
#include <zlib/zlib.h>

typedef struct {
    uLongf total_in; // total amount read from source (not stored)
    uLongf total_out; // total amount written to destination (not stored)
    int err; // return value for zcompress or deflate
    unsigned long compression_level;
    enum mode { DEFLATE, CFB } mode;
    z_stream strm;
} zlib_stream;

zlib_stream* init_zlib_stream(enum mode mode) {
    zlib_stream *strm = (zlib_stream*)malloc(sizeof(zlib_stream));
    memset(strm, 0, sizeof(zlib_stream));
    strm->mode = mode;
    if (deflateInit(&(strm->strm), COMPRESSIONLEVEL_BEST_SPEED) != ZOK) {
        fprintf(stderr, "deflateInit failed\n");
        exit(1);
    }
    return strm;
}

void destroy_zlib_stream(zlib_stream* strm) {
    deflateEnd(&(strm->strm));
    free(strm);
}

int compress_data(zlib_stream *strm, unsigned char *src, unsigned long src_len) {
    if (src_len > strm->total_in + CHUNK) {
        strm->total_in += CHUNK;
        src += CHUNK;
        src_len -= CHUNK;
    } else {
        strm->total_in = src_len;
        src = NULL;
        src_len = 0;
    }

    uLongf flush = (strm->mode == DEFLATE) ? Z_SYNC_FLUSH : Z_FULL_FLUSH;
    int ret = deflate(&(strm->strm), flush);
    if (ret != ZOK) {
        fprintf(stderr, "deflate failed\n");
        return -1;
    }
    strm->total_out += strm->strm.total_out;

    if (strm->err == Z_STREAM_END || (src_len == 0 && !strm->mode)) {
        destroy_zlib_stream(strm);
        return 1; // compression finished, return 1 to indicate completion
    }

    return 0; // continue compressing data
}

int decompress_data(zlib_stream *strm, unsigned char *dst, unsigned long dst_len) {
    if (dst_len > strm->total_out + CHUNK) {
        strm->total_out += CHUNK;
        dst += CHUNK;
        dst_len -= CHUNK;
    } else {
        strm->total_out = dst_len;
        dst = NULL;
        dst_len = 0;
    }

    int ret = inflate(&(strm->strm, Z_SYNC_FLUSH);
    if (ret != ZOK) {
        fprintf(stderr, "inflate failed\n");
        return -1;
    }
    strm->total_out += strm->strm.total_out;

    if (strm->err == Z_STREAM_END || !strm->mode) {
        destroy_zlib_stream(strm);
        return 1; // decompression finished, return 1 to indicate completion
    }

    return 0; // continue decompressing data
}
