#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <time.h>
#include <unistd.h>

#define MAX_PATH 256
#define MAX_LOG_SIZE (1024 * 1024) // 1MB
#define FILE_TYPE "txt" // Change this to desired file type
#define LOG_EXTENSION ".log"

typedef struct _LogFile {
    char path[MAX_PATH];
    size_t size;
    time_t last_modified;
} LogFile;

void log_write(const char *message) {
    char log_path[MAX_PATH];
    char timestr[20];
    struct tm *tm = localtime(&time(NULL));
    strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", tm);

    snprintf(log_path, MAX_PATH, "%s/%s_%s%s", getenv("HOME"), "myapp", timestr, LOG_EXTENSION);

    LogFile log;
    strcpy(log.path, log_path);
    FILE *fp = fopen(log.path, "a+");

    if (fp == NULL) return; // Return if file can't be opened

    if (log.size + strlen(message) + 1 > MAX_LOG_SIZE) {
        fseek(fp, 0, SEEK_SET); // Seek to the beginning of the file
        log.size = 0;
        rewind(fp);
    }

    fprintf(fp, "%s\n", message);
    log.size += strlen(message) + 1;
    fclose(fp);
}

void process_files(const char **filenames, size_t num_files) {
    if (!filenames || num_files == 0) return; // Return if no filenames or invalid input

    for (size_t i = 0; i < num_files; ++i) {
        char *filename = strdup(filenames[i]);
        if (!filename) continue; // Continue if memory allocation fails

        size_t last_index = strlen(filename) - 1;
        size_t digits = 0;

        // Check for valid characters and extract number of digits to append
        while (last_index > 0 && isdigit(filename[last_index])) {
            ++digits;
            --last_index;
        }

        char *ext = filename + last_index;
        size_t extension_len = strlen(ext);

        // Handle filenames without an extension gracefully
        if (extension_len == 0) {
            ext = FILE_TYPE;
            extension_len = strlen(ext);
        }

        char *new_filename = malloc(MAX_PATH);
        if (!new_filename) continue; // Continue if memory allocation fails

        snprintf(new_filename, MAX_PATH, "%.*s%d%s", (int)(last_index + 1), filename, digits, ext);

        // Ensure new filename does not exceed 255 characters
        if (strlen(new_filename) > 255) {
            free(new_filename);
            continue; // Continue if the limit is exceeded
        }

        struct stat st;
        char fullpath[MAX_PATH];
        snprintf(fullpath, MAX_PATH, "%s/%s", getcwd(NULL, MAX_PATH), new_filename);

        if (stat(new_filename, &st) != 0 || S_ISDIR(st.st_mode)) {
            // If the file already exists or is a directory, append numbers sequentially to find an available name
            snprintf(new_filename, MAX_PATH, "%.*s%d%s", (int)(last_index + 1), filename, digits, ext);
            int number = 2;

            while (stat(new_filename, &st) == 0 || S_ISDIR(st.st_mode)) {
                snprintf(new_filename, MAX_PATH, "%.*s%d%s", (int)(last_index + 1), filename, number++, ext);
            }
        }

        log_write(__func__ " processed: old=%s, new=%s\n", filename, new_filename);
        free(filename);
    }
}

int main() {
    // Replace this with your code to dynamically populate the filenames array
    const char *filenames[] = {"test1.txt", "test2.pdf", "/path/to/subdir/file.ext", "/path/to/non_existent_file"};

    process_files(filenames, sizeof(filenames) / sizeof(char*));
    return 0;
}
