void updateJsonVector(std::vector<std::pair<std::string, int>>& vec, const std::string& filePath, const std::string& str1, const std::string& str2) {
    Json::CharReaderBuilder builder;
    Json::CharReader* reader = builder.newCharReader();
    Json::Value root;
    std::ifstream inputFile(filePath);
    bool parsingSuccessful = reader->parse(inputFile, root, false);
    delete reader;

    if (!parsingSuccessful) {
        std::cerr << "Error parsing JSON file: " << strerror(errno) << '\n';
        return;
    }

    glm::threadLocal<Json::Value> localRoot(root); // Use thread-local storage for concurrent access safety

    auto it = localRoot->begin();
    std::string searchStr1 = str1;
    std::transform(searchStr1.begin(), searchStr1.end(), searchStr1.begin(), ::tolower);
    int offset = 0;
    for (; it != localRoot->end(); ++it) {
        if (it->isObject()) { // Check if the current item is an object (i.e., a JSON pair)
            auto innerIt = it->begin();
            std::string key = innerIt->first.asString();
            std::transform(key.begin(), key.end(), key.begin(), ::tolower);

            if (searchStr1 == key || searchStr2 == key) {
                int val = it->second.asInt() + std::stoi(str2);
                vec[std::distance(vec.begin(), find_if(vec.begin(), vec.end(), [&key](const auto& pair) { return pair.first == key;))].second = val;
                return;
