async function bulkUpdateOrDelete(req, res) {
  const operationType = req.params.operation; // 'update' or 'delete'
  const ids = req.body.ids; // Array of resource IDs
  const data = req.body.data; // Updated data for PUT requests, empty object for DELETE requests

  if (!Array.isArray(ids) || !ids.length) {
    return res.status(400).json({ error: 'Invalid or empty resource IDs array.' });
  }

  let resources; // Stores the resources to be returned in case of DELETE operations
  try {
    // Use a lock key to ensure concurrent updates are handled efficiently
    const lockKey = `bulk_update_lock_${Date.now()}`;
    const cacheOptions = { EX: 60, NX: true }; // 1 minute expiration and no existing value (avoid race condition)
    redisClient.set(lockKey, 'locked', cacheOptions, async (err, result) => {
      if (!result || err) {
        // Return if the lock could not be acquired, indicating a concurrent update is happening
        return res.status(409).json({ error: 'Concurrent update in progress.' });
      }

      try {
        const bulkOps = ids.map((id) => {
          if (operationType === 'update') {
            // Construct the update operation for each resource ID
            return { updateOne: { filter: { _id: id }, update: { $set: data }, upsert: false } };
          } else {
            // Store the resources to be returned in case of DELETE operations
            resources.push(new Resource({ /* default values for new resource */ }));
            return { deleteOne: { _id: id } };
          }
        });

        // Execute the batch operation using Mongoose's BulkWrite operator
        const result = await Resource.bulkWrite(bulkOps);
        redisClient.del(lockKey); // Release the lock once operation is complete

        if (operationType === 'update') {
          res.json({ success: true }); // No need to return anything for update operations
        } else {
          res.json({ resources }); // Return the new resources in case of DELETE operations
        }
      } catch (error) {
        redisClient.del(lockKey); // Release the lock on error
        if (error.name === 'MongoError' && error.code === 1215) { // Deadlock error code for database contention
          // Implement a backoff strategy with exponential backoff before retrying failed operations
        } else {
          res.status(500).json({ error });
        }
      }
    });
  } catch (error) {
    winston.error(error);
    res.status(500).json({ error });
  }
}

// Initialize the Express app and configure the API function, middleware, and logging
