using static System.Environment;

public class Program
{
    private const string BasePath = "BaseDirectory";
    private const string CharSet = "abcdefghijklmnopqrstuvwxyz1234567890";
    private const int RandomStringLength = 10;
    private const int XPathDepthLimit = 100;

    public static XmlNode SelectXmlElement(string xpath)
    {
        string xmlFilePath = GetXmlFilePath();

        if (File.Exists(xmlFilePath))
            return XDocument.Load(xmlFilePath).Root.XPathSelectElement(xpath);
        else
            return null;
    }

    private static string GetXmlFilePath()
    {
        string workingDirectory = NewDirectoryName();
        Environment.SetEnvironmentVariable(BasePath, Path.Combine(CurrentDirectory, workingDirectory));
        var xmlFile = Path.Combine(workingDirectory, "myXmlFile.xml");
        return xmlFile;
    }

    private static string NewDirectoryName()
    {
        string directoryName;
        int uniqueId = 0;
        do
        {
            directoryName = GenerateRandomString(RandomStringLength, CharSet);
            uniqueId++;
        } while (Directory.Exists(Path.Combine(CurrentDirectory, directoryName)));

        return directoryName;
    }

    private static string GenerateRandomString(int length, string charSet) =>
        new string(Enumerable.Repeat(charSet, length)
            .Select(s => s[new Random().Next(s.Length)]).ToArray());

    public static byte[] CalculateChecksum(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }
}
