const blueslip = require('blueslip');
const { performance } = require('perf_hooks');
const chalk = require('chalk');

async function runModuleTests(moduleLabel, testFunction, testCases, maxConcurrency, externalDataSource) {
  const testSuite = [];

  // Organize tests based on priority levels and create a parallelizable array
  const sortedTestCases = testCases.sort((a, b) => a.priority - b.priority);
  const batches = chunk(sortedTestCases, maxConcurrency);

  let testBatchIndex = 0;

  // Create a wrapper for each test case and register it to the blueslip mocking library
  function createTestWrapper(testCase) {
    return async function() {
      try {
        const startTime = performance.now();
        if (!testCase.skip) {
          await blueslip.reset(); // Reset blueslip before each test to isolate dependencies
          const result = await testFunction(externalDataSource, testCase.config); // Execute the test function with provided data source and configuration
          const executionTime = performance.now() - startTime;
          logTestResult(moduleLabel, testCase.name, result, executionTime); // Log the test result
        }
      } catch (error) {
        console.error(`Error executing test "${testCase.name}":`, error);
      }
    };
  }

  // Load and execute tests in parallel batches
  async function loadAndExecuteTests() {
    while (testBatchIndex < batches.length) {
      const batch = await Promise.all(batches[testBatchIndex].map(createTestWrapper));
      testSuite.push(...batch);
      testBatchIndex++;
    }

    // Execute tests concurrently with a for-await loop and Promises.all
    const testResults = await Promise.all(testSuite);
  }

  async function start() {
    try {
      await loadModule(moduleLabel); // Load the specified module before running tests
      await loadAndExecuteTests();
    } catch (error) {
      console.error(`Error loading or executing tests for "${moduleLabel}":`, error);
    }
  }

  start();

  // Helper function to log test metrics as objects with specific properties
  function logTestResult(module, testName, result, executionTime) {
    console.log(chalk.cyan(`[${module}]: ${testName}`), result ? chalk.green('passed') : chalk.red('failed'), `(${executionTime}ms)`);
  }

  // Helper function to chunk an array into groups of a specific size
  function chunk(arr, size) {
    const result = [];
    for (let i = 0; i < arr.length; i += size) {
      result.push(arr.slice(i, i + size));
    }
    return result;
  }
}
