[" Here's a basic implementation of the requested task using Node.js with a combination of async/await for parallel processing and a doubly-linked list for transaction ID management. This example uses `axios` for making HTTP requests, `lru-cache` for caching transaction statuses, and `linked-list` for the doubly-linked list.

```javascript
const axios = require('axios');
const LinkedList = require('linked-list');
const Cache = require('lru-cache');

class Transaction {
  constructor(id) {
    this.id = id;
    this.status = null;
  }
}

// Doubly-Linked List
let transactionList = new LinkedList();

// LRU Cache for transaction statuses
const cache = new Cache({ max: 1000 });

async function processTransactions(transactionIds, concurrencyLimit) {
  const promises = [];

  // Get processed transactions from the cache first
  const cachedTransactions = cache.getSync(transactionIds);

  if (cachedTransactions) {
    for (const id of transactionIds) {
      if (!cachedTransactions[id] || cachedTransactions[id].status === 'failed') {
        continue;
      }
      // Mark the processed transactions as already processed in the list
      const transaction = transactionList.find((node) => node.value.id === id);
      transaction.value.status = cachedTransactions[id].status;
    }
  }

  for (let i = 0; i < transactionIds.length; i++) {
    if (!transactionList.contains(new Transaction(transactionIds[i]))) {
      const transaction = new Transaction(transactionIds[i]);
      transactionList.append(transaction);
    }
  }

  let processedCount = 0;
  let activeTransactions = 0;

  while (processedCount < transactionIds.length && activeTransactions < concurrencyLimit) {
    for (let i = 0; i < transactionIds.length; i++) {
      const transaction = transactionList.find((node) => !node.next && node.value.status === null);

      if (!transaction) continue;

      activeTransactions++;

      processTransaction(transaction.value)
        .then(() => {
          processedCount++;
          activeTransactions--;

          // Remove the processed transaction from the list and cache the status
          const index = transactionList.indexOf(transaction);
          transactionList.removeAt(index);
          cache.set(transaction.id, {status: 'success'});
        })
        .catch((error) => {
          console.warn(`Error processing transaction ${transaction.id}:`, error);
          transaction.value.status = 'failed';
          activeTransactions--;
        });
    }
  }
}

async function processTransaction(transaction) {
  try {
    const response = await axios.post('API_ENDPOINT', data);

    if (response.data.status === 'success') {
      transaction.status = 'success';
    } else {
      transaction.status = 'failed';
    }

    console.log(`Transaction ${transaction.id}:`, response.data);
  } catch (error) {
    if (error.response && error.response.status === 429) {
      // Retry with exponential backoff
      await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt + 1) * 1000));
      transaction.retries++;
      if (transaction.retries < 3) {
        return processTransaction(transaction);
      } else {
        transaction.status = 'failed';
      }
    } else {
      transaction.status = 'failed';
    }
    console.warn(`Error processing transaction ${transaction.id}:`, error);
  }
}
```"]

[' ```java
import java.io.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.ConcurrentModificationException;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.LinkedBlockingDeque;
import org.apache.activemq.ActiveMQConnectionFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class StreamingDataService {
    private static final Logger LOGGER = LoggerFactory.getLogger(StreamingDataService.class);
    private Queue<String> buffer = new LinkedList<>();
    private BlockingQueue<Runnable> tasks = new LinkedBlockingDeque<>(10);
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private ActiveMQConnectionFactory factory;

    public void init(String brokerURL, int bufferSize) {
        this.buffer = new LinkedList<String>(BufferUtil.createCopyOnWriteArrayList(bufferSize));
        this.factory = new ActiveMQConnectionFactory(brokerURL);
    }

    public void addDataFeed(String feedUrl) {
        Runnable runnable = () -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(new URL(feedUrl).openStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    buffer.add(line);
                    tasks.add(() -> sendUpdates());
                }
            } catch (Exception e) {
                LOGGER.error("Error reading data feed", e);
            }
        };
        tasks.add(runnable);
        scheduler.execute(runnable);
    }

    public void addLocalFile(String filePath) throws FileNotFoundException {
        Runnable runnable = () -> {
            try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    buffer.add(line);
                    tasks.add(() -> sendUpdates());
                }
            } catch (Exception e) {
                LOGGER.error("Error reading local file", e);
            }
        };
        tasks.add(runnable);
        scheduler.execute(runnable);
    }

    public void sendUpdates() {
        try {
            validateData();
            sendToBroker();
        } catch (Exception e) {
            LOGGER.error("Error sending updates", e);
        }
    }

    private void validateData() throws Exception {
        // Integrate with external API for data validation
    }

    private void sendToBroker() throws InterruptedException, ExecutionException {
        MqConnection mq = new MqConnection(factory.createConnection());
        try {
            mq.start();
            for (String message : buffer) {
                mq.sendMessage(message);
            }
        } finally {
            mq.stop();
        }
    }

    private static class MqConnection {
        private Session session;
        private Destination destination;

        public void start() throws Exception {
            Connection connection = factory.createConnection();
            connection.start();
            session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
            destination = session.createQueue("streamingData");
        }

        public void stop() throws Exception {
            if (session != null) {
                session.close();
            }
            if (factory != null) {
                factory.close();
            }
        }

        public void sendMessage(String message) throws Exception {
            Producer producer = session.createProducer(destination);
            Message msg = session.createTextMessage(message);
            producer.send(msg);
        }
    }

    public String md5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            BigInteger bigInt = new BigInteger(1, digest);
            String hashtext = bigInt.toString(16);
            while (hashtext.length() < 32) {
                hashtext = "0" + hashtext;
            }
            return hashtext;
        } catch (Exception e) {
            LOGGER.error("Error calculating MD5 hash", e);
            throw new RuntimeException(e);
        }
    }
}
