// Function to analyze the characters in the original filename and determine the new extension based on its length.
char* getExtension(const char *filename) {
    size_t len = strlen(filename);
    size_t ext_len = (len <= 8) ? len : 8;
    char *extension = malloc(ext_len + 1);
    int i;
    for (i = len - ext_len + 1; i < len && i < INT_MAX; ++i) {
        extension[i - len + ext_len] = tolower(filename[i]);
    }
    extension[ext_len] = '\0';
    return extension;
}

// Function to load metadata from the configuration file.
