// Function to allocate memory for and initialize arrays.
void initArrays(metadata **metadatas, size_t *keyCount, size_t *offsetCount, size_t numKeys, size_t numOffsets) {
    *metadatas = (metadata*) mmap(NULL, sizeof(metadata) * numMetadata, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (*metadatas == MAP_FAILED) {
        perror("mmap() failed");
        exit(EXIT_FAILURE);
    }

    *keyCount = (size_t*) calloc(numKeys, sizeof(size_t));
    if (!*keyCount) {
        perror("calloc() failed for keys");
        munmap(*metadatas, sizeof(metadata) * numMetadata);
        exit(EXIT_FAILURE);
    }

    *offsetCount = (size_t*) calloc(numOffsets, sizeof(size_t));
    if (!*offsetCount) {
        perror("calloc() failed for offsets");
        free(*keyCount);
        munmap(*metadatas, sizeof(metadata) * numMetadata);
        exit(EXIT_FAILURE);
    }
}

// Function to allocate memory for and initialize an array of records.
record* initRecords(size_t numRecords, metadata** metadatas, size_t keyCount, size_t offsetCount) {
    record *records = (record*) malloc(numRecords * sizeof(record));
    if (!records) {
        perror("malloc() failed for records");
        free(*keyCount);
        free(*offsetCount);
        munmap(*metadatas, sizeof(metadata) * (*metadatas - MAP_FAILED)->size);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&records_mutex);
        // Initialize the record with a random value within the specified range.
        records[i].value = (*metadatas)[*keyCount[i % keyCount]].offset + rand() % (*offsetCount[i % offsetCount]);
        pthread_mutex_unlock(&records_mutex);
    }

    return records;
}

// Function to clean up allocated memory.
void cleanup(metadata** metadatas, size_t *keyCount, size_t *offsetCount, record* records) {
