const MAX_STREAMS = 100;
const BUFFER_CAPACITY = 1e6; // 1MB
const CHUNK_MAX_SIZE = 64 * 1024; // 64KB

class Merger {
  constructor() {
    this.streams = new Map();
    this.buffer = [];
    this.hashes = new Set();
  }

  addStream(stream, hashFn) {
    if (this.streams.size === MAX_STREAMS) return;

    const streamId = stream._id || Math.random().toString();
    const bufferChunk = { streamId, data: new Uint8Array(CHUNK_MAX_SIZE) };

    this.streams.set(streamId, { stream, bufferChunk });

    stream.on('data', (chunk) => {
      if (chunk.length > CHUNK_MAX_SIZE) return;

      const hash = hashFn(chunk);
      if (this.hashes.has(hash)) return;

      this.hashes.add(hash);
      this.bufferChunkBuffer(chunk, bufferChunk);
    });

    stream.on('end', () => {
      const { bufferChunk } = this.streams.get(streamId);
      if (bufferChunk && !bufferChunk.used) this.buffer.push(bufferChunk);
      this.streams.delete(streamId);
    });
  }

  bufferChunkBuffer(chunk, bufferChunk) {
    if (this.buffer.length + chunk.length > BUFFER_CAPACITY) {
      // Backpressure mechanism: throttle incoming streams when the buffer exceeds 1MB.
      bufferChunk.used = true;
      return;
    }

    // Merge chunk data into the bufferChunk, handle concurrency with a lock.
    const lock = new Set();
    function merge() {
      if (!lock.has(bufferChunk)) {
        lock.add(bufferChunk);
        const start = performance.now();
        const copy = [...chunk];

        // Copy the chunk data into the bufferChunk, ensuring no original stream data is modified.
        for (let i = 0; i < Math.min(copy.length, CHUNK_MAX_SIZE - bufferChunk.data.byteLength); i++) {
          bufferChunk.data.set(bufferChunk.data.slice(i), copy.slice(i, i + 1));
        }

        // Logging for debugging purposes (timestamps and stream identifiers)
        if (process.env.DEBUG) console.log(`[${performance.now()}] [${bufferChunk.streamId}] Merged chunk (${chunk.length} bytes) into buffer`);

        lock.delete(bufferChunk);
      }
    }

    // Ensure data integrity and consistency in the presence of network latency and packet loss.
    merge();
  }
}
```
