// Traversal.js - Efficient & flexible DOM traversal library

class DomTraversal {
  constructor(config) {
    this.cache = new Map();
    this.selectorCache = new WeakMap();
    this.asyncLib = config.asyncLib || async;
    this.log = config.log || console.log;
    this.errorHandler = config.errorHandler || (err => this.log(err));
  }

  // Recursive traversal of complex DOM trees based on given parameters
  traverse(node, filter) {
    if (!node) return [];

    let visitedNodes = new Set();

    function traverseRecursive(currentNode) {
      if (visitedNodes.has(currentNode)) return;
      visitedNodes.add(currentNode);

      const matchesFilter = filter(currentNode);
      if (matchesFilter) return currentNode;

      const children = Array.from(currentNode.children);
      let result = children.reduce((acc, child) => acc.concat(traverseRecursive(child)), []);

      // Cache accessed nodes and their selectors for optimized performance
      this.cache.set(currentNode, { node: currentNode, selector: getSelectorString(currentNode) });
      if (this.selectorCache.has(getSelectorString(currentNode))) {
        const cachedNodes = this.selectorCache.get(getSelectorString(currentNode));
        result = result.concat(cachedNodes);
      }

      return result;
    }

    return traverseRecursive(node);
  }

  // Asynchronously fetch nodes based on provided selector, ensuring compatibility with third-party libraries
  fetchNodesAsync(selector, cb) {
    this.asyncLib.resolve(document.querySelectorAll(selector))
      .then(nodes => {
        nodes.forEach(node => this.cache.set(node, { node, selector: selector }));
        this.selectorCache.set(selector, Array.from(this.cache.values()));
        return cb(null, nodes);
      })
      .catch(err => this.errorHandler(err));
  }

  // Locking mechanism for concurrent access from multiple threads
  lock() {
    if (!this._lock) this._lock = new Set();
    this._lock.add(Thread.current);
  }

  unlock() {
    this._lock.delete(Thread.current);
  }
}

// Helper function for getting CSS selector string from a node
function getSelectorString(node) {
  if (!node || !node.tagName) return null;
  const parent = node.parentElement;
  let currentNode = node;
  let result = [];

  while (currentNode && currentNode !== document) {
    result.unshift(currentNode.tagName.toLowerCase());
    if (currentNode === document) break;
    currentNode = currentNode.parentElement;
  }

  if (result.length) {
    const index = result.findIndex(node => node === 'html');
    if (index !== -1) result.splice(index, 1);
    let selector = result.join(' > ');
    if (currentNode && currentNode.id) selector += `#${currentNode.id}`;
    else if (currentNode && currentNode.classList) selector += `.${[...currentNode.classList].join('.')}`;
    return selector;
  }
}
