typedef struct {
    long offset;
    int key;
} Record;

Record* initialize_pipeline(size_t max_records, size_t max_offsets, size_t key_range, size_t max_key_sum) {
    // Allocate and align memory for offsets array
    size_t offset_size = (max_records * sizeof(long)) & ~(63);
    void* offsets_ptr = mmap(NULL, offset_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (offsets_ptr == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    // Cast to pointer of desired type and adjust the size accordingly
    long* offsets = (long*)((uint64_t)offsets_ptr & ~63);

    // Initialize keys array with unique values
    int* keys = malloc(max_records * sizeof(int));
    if (!keys) {
        perror("malloc failed");
        munmap(offsets_ptr, offset_size);
        return NULL;
    }

    // Generate and validate unique keys within specified range
    for (size_t i = 0; i < max_records; ++i) {
        int key;
        do {
            key = rand() % key_range;
        } while (i < max_records && keys[i] == key);

        keys[i] = key;
    }

    // Allocate and align memory for Record array
    size_t records_size = (max_records * sizeof(Record)) & ~63;
    void* records_ptr = mmap(NULL, records_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records_ptr == MAP_FAILED) {
        perror("mmap failed");
        free(keys);
        munmap(offsets_ptr, offset_size);
        return NULL;
    }

    Record* records = (Record*)((uint64_t)records_ptr & ~63);

    // Initialize Records array with valid keys and offsets
    for (size_t i = 0; i < max_records; ++i) {
        long offset = offsets[i];
        int key = keys[i];

        if ((offset + key) > max_key_sum) {
            perror("Key and offset exceed the maximum sum.");
            free(keys);
            munmap(offsets_ptr, offset_size);
            munmap(records_ptr, records_size);
            return NULL;
        }

        records[i].offset = offset;
        records[i].key = key;
    }

    return records;
}
