#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

const size_t kMaxMemoryUsage = 1024 * 1024; // Max memory usage: 1 MB
const size_t kBlockSize = sizeof(long) + sizeof(int) + sizeof(Record);
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_once_t g_once = PTHREAD_ONCE_INIT;
static Record *g_memoryPool = NULL;
static size_t g_memoryPoolSize = 0, g_memoryPoolCapacity = 0;
static unsigned long g_recordResizeCount = 0;

typedef struct {
    char active;
    int value;
} Record;

void initMemoryPool() {
    if (g_memoryPool) return;
    pthread_mutex_lock(&g_mutex);
    if (!g_memoryPool) {
        g_memoryPool = calloc(g_memoryPoolCapacity, kBlockSize);
        g_memoryPoolSize = g_memoryPoolCapacity;
    }
    pthread_mutex_unlock(&g_mutex);
}

void *getMemoryBlock() {
    void *block;
    initMemoryPool();
    pthread_mutex_lock(&g_mutex);
    if (g_memoryPoolSize > 0) {
        block = g_memoryPool;
        g_memoryPool += kBlockSize;
        --g_memoryPoolSize;
    } else {
        block = malloc(kBlockSize);
    }
    pthread_mutex_unlock(&g_mutex);
    return block;
}

void putMemoryBlock(void *block) {
    if (!block) return;
    initMemoryPool();
    pthread_mutex_lock(&g_mutex);
    if (g_memoryPoolSize < g_memoryPoolCapacity) {
        memcpy(g_memoryPool, block, kBlockSize);
        g_memoryPool += kBlockSize;
        ++g_memoryPoolSize;
    } else {
        free(block);
    }
    pthread_mutex_unlock(&g_mutex);
}

long *allocLongArray(size_t size) {
    long *array = malloc(size * sizeof(long));
    if (!array || (void*)(array + size) - (void*)array > kMaxMemoryUsage) {
        free(array);
        fprintf(stderr, "Error: Allocation exceeded maximum memory usage.\n");
        return NULL;
    }
    memset(array, 0, size * sizeof(long));
    return array;
}

int *allocIntArray(size_t size) {
    int *array = malloc(size * sizeof(int));
    if (!array || (void*)(array + size) - (void*)array > kMaxMemoryUsage) {
        free(array);
        fprintf(stderr, "Error: Allocation exceeded maximum memory usage.\n");
        return NULL;
    }
    memset(array, 0, size * sizeof(int));
    return array;
}

Record **allocRecordArray(size_t size) {
    Record **array = getMemoryBlock();
    if (!array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = getMemoryBlock();
        if (!array[i]) {
            free(array);
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return NULL;
        }
    }
    if (size * kBlockSize > g_memoryPoolCapacity) {
        extendMemoryPool((size_t)(size * 1.25));
    }
    return array;
}

void extendMemoryPool(size_t newCapacity) {
    void *newPool = realloc(g_memoryPool, newCapacity * kBlockSize);
    if (!newPool) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }
    g_memoryPool = newPool;
    g_memoryPoolCapacity = newCapacity;
    ++g_recordResizeCount;
}

Record **createDataStructures(size_t *inputSizes) {
    if (inputSizes[0] <= 0 || inputSizes[1] <= 0) {
        fprintf(stderr, "Error: Input array sizes must be positive.\n");
        return NULL;
    }
    long *longArray = allocLongArray(inputSizes[0]);
    int *intArray = allocIntArray(inputSizes[1]);
    Record **recordArray = allocRecordArray(inputSizes[1]);
    if (!longArray || !intArray || !recordArray) {
        free(longArray);
        free(intArray);
        free(recordArray);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < inputSizes[1]; ++i) {
        recordArray[i]->active = 1;
        recordArray[i]->value = rand() % 1001;
    }

    return recordArray;
}

int main() {
    size_t longSize, intSize;
    printf("Enter array sizes (long and int respectively): ");
    scanf("%zu%zu", &longSize, &intSize);

    Record **dataStructures = createDataStructures(&longSize, &intSize);
    if (!dataStructures) return EXIT_FAILURE;

    // Use the dynamically allocated arrays...

    free(longArray);
    free(intArray);
    free(recordArray);

    return EXIT_SUCCESS;
}
```

This code includes a custom allocator, lazy resizing of the `Record` array, and memory pooling to reduce overhead from frequent memory allocations. The function also handles error cases gracefully by printing an error message and returning early without allocating unnecessary memory. Additionally, it is designed for thread safety with the use of a mutex lock to synchronize access to the shared memory pool.']

