import org.jsoup.*;
import org.jsoup.nodes.*;
import java.net.*;
import java.util.*;
import java.time.*;
import java.util.concurrent.*;
import static java.lang.String.format;

public class WebScraper {
    private static final int MAX_ATTEMPTS = 5;
    private static final Duration BACKOFF_FACTOR = Duration.ofMillis(200);
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);

    public Map<String, List<Element>> scrapeUrls(List<String> urls, String selector) throws URISyntaxException {
        Map<String, List<Element>> result = new HashMap<>();
        for (String url : urls) {
            URI uri = new URI(url);
            String domain = uri.getHost();
            result.computeIfAbsent(domain, k -> new ArrayList<>());

            AtomicInteger attempt = new AtomicInteger(0);
            CompletableFuture<Void> future = CompletableFuture.supplyAsync(() -> {
                try (Connection.Response response = Jsoup.connect(url).timeout(5_000).ignoreContentType(true).execute()) {
                    if (response.statusCode() != HttpStatus.OK) return null;
                    Element rootElement = Jsoup.parseBodyFragment(response.body());
                    long startTime = System.nanoTime();
                    List<Element> elements = rootElement.select(selector);
                    long duration = TimeUnit.MILLISECONDS.convert(System.nanoTime() - startTime, TimeUnit.NANOSECONDS);
                    result.get(domain).addAll(elements);
                    System.out.println(format("Processed URL: %s in %d ms", url, duration));
                    return null;
                } catch (Exception e) {
                    if (attempt.incrementAndGet() <= MAX_ATTEMPTS) {
                        executor.submit(() -> scrapeUrls(url, selector).join());
                        try {
                            Thread.sleep((long) Math.pow(2, attempt.get()));
                        } catch (InterruptedException ignored) {}
                    } else {
                        System.out.println(format("Failed to process URL: %s", url));
                    }
                }
                return null;
            });
            future.exceptionally(e -> {
                System.err.println(format("Error while processing URL: %s - %s", url, e.getMessage()));
                return null;
            }).whenComplete((v, e) -> {
                if (e != null) result.remove(domain);
            });
        }
        executor.shutdown();
        while (!executor.isTerminated()) {}
        return result;
    }
}
```
