    @PostConstruct
    public void init() {
        offset = 0;
        key = -1;
        record = new Record();
    }

    public int executeCommand(String command) throws IOException, InterruptedException, ExecutionException {
        CustomProcessBuilder pb = new CustomProcessBuilder(command);
        try {
            File targetFile = new File(pb.getCommandLine().getArguments()[0]);
            if (targetFile.exists()) {
                targetFile.delete();
            }
        } catch (Exception e) {
            log.error("Error while preparing command execution", e);
            return -1;
        }

        Process process = pb.start();

        int exitCode = 0;
        try {
            process.waitFor(30, TimeUnit.SECONDS);
            exitCode = process.exitValue();
        } catch (Exception e) {
            log.error("Error while waiting for command execution", e);
            if (!process.destroy()) {
                log.warn("Failed to destroy process");
            }
            return -1;
        }

        return exitCode;
    }

    public static class Record {
        int value = Integer.MIN_VALUE;
        Instant timestamp = Instant.now();
        boolean status = false;
    }
