class AsyncPNGFileLoader(private val parser: PNGFileParser) : ObservableTransformer<File, Bitmap> {
    override fun call(observable: Observable<File>): Observable<Bitmap> {
        return observable.flatMap { file ->
            Observable.just(file).concatWith(Observable.error(IOException("I/O error")))
                .flatMap { FileUtils.toInputStream(it) }
                .flatMap { parser.parse(it) }
                .onErrorResumeNext { throwable ->
                    Observable.just(file).concatWith(Observable.error(throwable))
                        .flatMap { FileUtils.toInputStreamSync(it) }
                        .map { parser.parse(it) }
                }
        }
    }
}
