fn find_largest_rnti() -> u16 {
    let mut buffer = Vec::new();
    let mut max_value = 0;
    loop {
        let mut input = String::new();
        if std::io::stdin().read_line(&mut input).is_err() {
            break;
        }

        let num = match input.trim().parse::<u16>() {
            Ok(n) => n,
            Err(_) => continue,
        };

        if max_value < num {
