fn compile_and_measure() -> i32 {
    let mut rss_limit = libc::rlimit{rlim_cur: std::isize::MAX, rlim_max: std::isize::MAX};
    unsafe { getrlimit(RLIMIT_RSS, &mut rss_limit) };
    const MAX_RSS: u64 = 50 * (1024 * 1024); // Set the maximum RSS to 50MB
    rss_limit.rlim_cur = MAX_RSS as libc::rlim_t;
    unsafe { setrlimit(RLIMIT_RSS, &rss_limit) };

    let start = Instant::now();
    let mut args = Args::new();
    let _exit_code = catch_with_exit_code(|session| {
        let mut session = BuildSession::from_args(args, session).unwrap();
        let compilation_time = start.elapsed().as_secs_f64();
        let resident_set_size = check_rss_usage();
