#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    char str[100];
    double dbl;
    pthread_mutex_t mutex;
};

struct HashTable {
    size_t capacity;
    size_t load_factor_threshold;
    struct Record** data;
    size_t num_elements;
};

void hash_table_init(struct HashTable* table, size_t capacity, size_t load_factor_threshold) {
    table->capacity = capacity;
    table->load_factor_threshold = load_factor_threshold;
    table->data = calloc(capacity, sizeof(void*));
    table->num_elements = 0;
}

size_t hash_function(int key, size_t capacity) {
    return key % capacity;
}

void resize_hash_table(struct HashTable* table) {
    if (static_cast<double>(table->num_elements) / table->capacity >= table->load_factor_threshold) {
        size_t new_capacity = table->capacity * 2;
        void** new_data = calloc(new_capacity, sizeof(void*));
        for (size_t i = 0; i < table->capacity; ++i) {
            void* current = table->data[i];
            if (current != nullptr) {
                size_t index = hash_function(*(static_cast<int*>(current)), new_capacity);
                new_data[index] = current;
            }
        }
        free(table->data);
        table->data = new_data;
        table->capacity = new_capacity;
    }
}

void insert_record(struct HashTable* table, struct Record* record) {
    size_t index = hash_function(record->value, table->capacity);
    resize_hash_table(table);
    table->data[index] = record;
    ++table->num_elements;
}

struct Record* find_record(const struct HashTable* table, int key) {
    size_t index = hash_function(key, table->capacity);
    for (size_t i = index; i < table->capacity; ++i) {
        if (table->data[i] != nullptr && *(static_cast<int*>(table->data[i])) == key) {
            return table->data[i];
        }
    }
    for (size_t i = 0; i < index; ++i) {
        if (table->data[i] != nullptr && *(static_cast<int*>(table->data[i])) == key) {
            return table->data[i];
        }
    }
    return nullptr;
}

void* allocate_record() {
    struct Record* record = static_cast<struct Record*>(malloc(sizeof(struct Record)));
    if (record != nullptr) {
        pthread_mutex_init(&record->mutex, nullptr);
    }
    return record;
}

void free_record(void* record) {
    if (record != nullptr) {
        pthread_mutex_destroy(&static_cast<struct Record*>(record)->mutex);
        free(record);
    }
}

void create_data_structures(struct HashTable* table, size_t offsets_size, size_t keys_size, size_t records_pool_size) {
    table->offsets = calloc(offsets_size, sizeof(long));
    table->keys = calloc(keys_size, sizeof(int));
    table->records_pool = calloc(records_pool_size, sizeof(void*));
    pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize mutex for records pool access
    void** records_pool_ptr = table->records_pool;
    for (size_t i = 0; i < records_pool_size; ++i) {
        pthread_mutex_init(&(*records_pool_ptr++)->mutex, &pool_mutex);
    }
}

void generate_random_data(struct HashTable* table) {
    srand(time(nullptr));
    for (size_t i = 0; i < table->num_elements; ++i) {
        struct Record* record = allocate_record();
        if (record != nullptr) {
            record->value = rand() % 1000;
            snprintf(record->str, sizeof(record->str), "%d", record->value);
            record->dbl = static_cast<double>(rand()) / RAND_MAX;
            insert_record(table, record);
        }
    }
}
