void logError(const char* message) {
    std::cerr << "Error: " << message << std::endl;
}

int generateAndExecute(const std::string& filename, const std::string& configFile, unsigned long seed) {
    // Determine new file extension based on the original filename
    std::string extension = filename.substr(filename.find_last_of('.'));
    size_t digits = extension.size();
    extension.erase(extension.begin(), extension.end() - digits);
    if (digits > 8) {
        extension.resize(8);
    }

    // Load metadata from the configuration file
    std::ifstream configStream(configFile);
    if (!configStream.is_open()) {
        logError("Failed to open configuration file.");
        return -1;
    }

    std::map<std::string, std::string> typesExtensions;
    std::map<std::string, std::pair<int, int>> supportedRanges;
    std::string line;

    while (std::getline(configStream, line)) {
        std::istringstream iss(line);
        if (!(iss >> std::ws) || !(iss >> typesExtensions[iss.str()])) {
            continue;
        }
        if (!(iss >> std::ws) || !(iss >> supportedRanges[typesExtensions[iss.str()]].first)) {
            continue;
        }
        if (!(iss >> std::ws) || !(iss >> supportedRanges[typesExtensions[iss.str()]].second)) {
            break;
        }
    }
    configStream.close();

    // Allocate memory for offsets and keys arrays
    size_t keysCount = supportedRanges.size();
    std::vector<long> offsets(keysCount);
    std::vector<int> keys(keysCount);

    // Initialize arrays with metadata from the configuration file
    unsigned long currentOffset = 0;
    for (auto& entry : supportedRanges) {
        offsets[entry.first] = currentOffset;
        keys[currentOffset++] = entry.second.first;
    }

    // Allocate memory for and initialize the records array
    size_t recordCount = keysCount * 1024; // Adjust as needed to balance speed and resource usage
    std::vector<Record> records(recordCount);
    std::default_random_engine generator(seed);

    for (auto& record : records) {
        record.key = keys[currentOffset++];
        record.timestamp = time(nullptr);
        record.status = true;
        record.key = generator() % (supportedRanges[typesExtensions[filename.substr(0, filename.find_last_of('.'))].second.second - supportedRanges[typesExtensions[filename.substr(0, filename.find_last_of('.'))].second.first + 1) + 1) + supportedRanges[typesExtensions[filename.substr(0, filename.find_last_of('.'))].second.first;
    }

    // Error handling for file operations and memory allocations
    std::string command;
    std::vector<char*> args;

    try {
        command = "command-to-execute"; // Replace with the actual external command
        args.push_back((char*)command.c_str());

        // Delete existing target file if it exists
        std::string targetFile = filename + extension;
        remove(targetFile.c_str());

        // Allocate memory for command arguments
        char** finalArgs = new char*[args.size() + 1];
        for (size_t i = 0; i < args.size(); ++i) {
            finalArgs[i] = const_cast<char*>(args[i].c_str());
        }
        finalArgs[args.size()] = nullptr;

        // Execute the external command with retry logic and timeouts
        std::unique_ptr<pid_t, decltype(&::pid_t::kill)> pid(::fork());
        if (pid == nullptr) {
            logError("Fork failed.");
            return -1;
        }
        if (pid > 0) { // Parent process
            int status;
            if (waitpid(pid.get(), &status, 0) <= 0) {
                logError("Waitpid failed.");
                return -1;
            }
            delete[] finalArgs;
            return WEXITSTATUS(status);
        } else { // Child process
            ::execvp(finalArgs[0], finalArgs);
            if (errno != ENOENT) {
                logError("Execvp failed.");
            }
            _exit(-1); // Exit with an error code in the child process
        }
    } catch (const std::exception& e) {
        logError(e.what());
        return -1;
    }
}
