State* create_state_list(int *states, size_t num_states, FSA *fsa, int last_state, size_t max_size, pthread_mutex_t *mutex) {
    State **head = (State**)malloc(sizeof(State*)), **tail = head;
    if (!head || !tail) return NULL;

    for (size_t i = 0; i < num_states; ++i) {
        State *new_state = (State*)malloc(sizeof(State));
        if (!new_state) goto failure;
        new_state->id = states[i];
        new_state->timestamp = time(NULL);
        new_state->next = NULL;

        pthread_mutex_lock(mutex);
        *tail = new_state;
        if (!*head) {
            *head = new_state;
        } else {
            *tail = (*tail)->next = new_state;
        }
        pthread_mutex_unlock(mutex);
    }

    *head = (*head == last_state ? *head : (*head)->next);
    if (num_states >= max_size) {
        pthread_mutex_lock(mutex);
        State *current = *head;
        while ((*head = current->next) != NULL) {
            free(current);
            current = *head;
        }
        pthread_mutex_unlock(mutex);
    }

    // Implement compression algorithm here (optional)

    return *head;

failure:
