template<typename K, typename V>
class HashTable {
private:
    static constexpr float default_load_factor = 0.75f;
    static constexpr size_t default_max_size = 1'000'000u;
    static constexpr size_t default_entry_capacity = 32;

    float load_factor_threshold;
    size_t max_size;
    size_t entry_capacity;
    std::vector<std::unique_ptr<std::list<std::pair<K, V>>>> data;
    std::atomic_uint current_size{ 0 };

public:
    HashTable(float load_factor_threshold = default_load_factor, size_t max_size = default_max_size, size_t entry_capacity = default_entry_capacity)
        : load_factor_threshold(load_factor_threshold), max_size(std::min(max_size, std::numeric_limits<size_t>::max())), entry_capacity(std::min(entry_capacity, std::numeric_limits<size_t>::max())) {
        if constexpr (std::is_integral_v<K> && !std::is_unsigned_v<K>) {
            throw std::invalid_argument("Key type must be an unsigned integral type.");
        }

        if (load_factor_threshold <= 0 || load_factor_threshold > 1) {
            throw std::invalid_argument("Load factor threshold must be between 0 and 1.");
        }

        if (entry_capacity <= 1) {
            throw std::invalid_argument("Entry capacity must be greater than 1.");
        }

        data.resize(std::max(static_cast<size_t>(std::hash<K>{}(0) % max_size), 1u));
    }

    HashTable(const HashTable&) = delete;
    HashTable& operator=(const HashTable&) = delete;

    HashTable(HashTable&& other) noexcept {
        swap(*this, other);
    }

    HashTable& operator=(HashTable&& other) noexcept {
        swap(*this, other);
        return *this;
    }

    ~HashTable() {
        for (auto& bucket : data) {
            bucket.reset();
        }
    }

    V* insert(const K& key, const V& value) {
        if (current_size + 1 >= max_size * load_factor_threshold) {
            resize();
        }

        size_t hash = std::hash<K>{}(key) % data.size();

        auto it = data[hash].begin();
        for (; it != data[hash].end() && it->first != key; ++it) {}

        if (it == data[hash].end()) {
            data[hash].emplace_back(key, value);
            ++current_size;
            return &data[hash].back().second;
        }

        return &it->second;
    }

private:
    static void swap(HashTable& lhs, HashTable& rhs) noexcept {
        using std::swap;

        swap(lhs.load_factor_threshold, rhs.load_factor_threshold);
        swap(lhs.max_size, rhs.max_size);
        swap(lhs.entry_capacity, rhs.entry_capacity);
        swap(lhs.data, rhs.data);
        swap(lhs.current_size, rhs.current_size);
    }

    void resize() {
        // Implement an efficient collision resolution strategy and memory reallocation mechanism here.
    }
};
