struct Character {
    int health, mana, fatigue;
};

std::chrono::steady_clock::time_point lastAttackTime;
std::unordered_map<int, std::function<void(Character&)>> attacks = {
    {1, [](Character& c){ if (c.mana >= MANA_COST && c.fatigue >= FATIGUE_COST) { c.health += ATTACK_DAMAGE; c.mana -= MANA_COST; c.fatigue += FATIGUE_COST; } }},
    // Other attack functions go here...
};

void selectAttack() {
    auto currentTime = std::chrono::steady_clock::now();
    auto elapsedTime = currentTime - lastAttackTime;
    int cooldown = MIN_COOLDOWN + (std::random_device{}())() % ((MAX_COOLDOWN - MIN_COOLDOWN) + 1);
    if (elapsedTime < std::chrono::seconds(cooldown)) return;
    lastAttackTime = currentTime;
    auto chosenAttack = (std::uniform_int_distribution<int>(1, attacks.size()))(std::random_device{});
    attacks[chosenAttack](*currentCharacter);
    std::cout << "Selected attack: " << chosenAttack << std::endl;
}

void manageGameState(Character& currentCharacter) {
