    Character currentCharacter{MAX_HEALTH, MAX_MANA, MAX_FATIGUE};
    while (true) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Adjust sleep duration to manage game loop performance.
        selectAttack();
        manageGameState(currentCharacter);
    }
}
