#include <regex.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct email {
    char *email;
};

int validate_email(const char *email) {
    regex_t reg;
    int res = -1;
    regcomp(&reg, "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$", 0);
    if (regmatch(email, &reg) != NREG) res = 1;
    regfree(&reg);
    return res;
}

struct email* parseAndValidateEmails(const char *input, size_t max_emails) {
    size_t num_valid = 0, i = 0, j = 0;
    struct email *results = malloc((max_emails + 1)*sizeof(struct email));

    for (i = 0; input[i] != '\0'; ++i) {
        if (input[i] == ',') {
            if (!validate_email(&input[j])) continue;
            results[num_valid].email = strndup(&input[j], i - j);
            num_valid++;
            j = i + 1;
            if (num_valid == max_emails) break;
        }
    }

    // If there's a valid email left, add it to the array
    if (!validate_email(&input[j])) return NULL;
    results[num_valid].email = strndup(&input[j], i - j);
    num_valid++;

    // Free unnecessary memory and reallocate
    struct email *new_results = malloc(num_valid*sizeof(struct email));
    for (i = 0; i < num_valid; ++i) new_results[i] = results[i];
    free(results);
    return new_results;
}
```

