struct Message {
    std::string payload;
    boost::posix_time::ptime timestamp;
};

class MemoryPool {
public:
    virtual void* allocate(size_t size) = 0;
    virtual void deallocate(void* ptr) = 0;
};

class SharedQueue {
private:
    std::deque<Message> messages;
    std::mutex mutex;
    MemoryPool& memoryPool;

public:
    explicit SharedQueue(MemoryPool& memoryPool) : memoryPool(memoryPool) {}

    void append(const Message& message) {
        auto ptr = memoryPool.allocate(sizeof(Message));
        std::memcpy(ptr, &message, sizeof(Message));
        std::unique_lock<std::mutex> lock(mutex);
        messages.push_back(*static_cast<Message*>(ptr));
    }

    Message take() {
        std::unique_lock<std::mutex> lock(mutex);
        Message message = std::move(messages.front());
        messages.pop_front();
        memoryPool.deallocate(static_cast<void*>(reinterpret_cast<char*>(&message) - static_cast<char*>(&Message{})));
        return message;
    }
};

