['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/sha.h>
#include <math.h>

typedef struct {
    int bits_per_sample;
    int sample_per_pixel;
    int compression_type;
    int orientation;
    int num_extra_samples;
    int width;
    int height;
    float resolution;
    int color_space;
    unsigned char *md5_hash; // Dynamically allocated memory for hash
} ImageInfo;

int processImageAndHashData(const char *tiff_path, const char *input_string,
                            size_t max_memory_usage, double max_processing_time,
                            double min_accuracy) {
    TIFF *tif = TIFFOpen(tiff_path, "r");
    if (!tif) {
        return -1; // Error: invalid file path
    }

    ImageInfo info;
    tiffgetfield(tif, IFDT_BitsPerSample, &info.bits_per_sample);
    tiffgetfield(tif, IFDT_SampleFormat, &info.sample_per_pixel);
    tiffgetfield(tif, IFDT_Compression, &info.compression_type);
    tiffgetfield(tif, IFD_Orientation, &info.orientation);
    tiffgetfield(tif, IFDT_ExtraSamples, &info.num_extra_samples);

    if (info.bits_per_sample < 1 || info.bits_per_sample > 16) {
        info.bits_per_sample = -1; // Error: unsupported bits per sample
    }

    if (info.sample_per_pixel < 1 || info.sample_per_pixel > 4) {
        info.sample_per_pixel = -1; // Error: unsupported samples per pixel
    }

    if (info.compression_type >= NUMCOMPRESS) {
        info.compression_type = -1; // Error: unsupported compression type
    }

    tiffgetimage(tif, &info.width, &info.height);
    tiffgetfield(tif, IFD_ResolutionUnit, &info.resolution);
    if (info.resolution != RESOLUTION_INCH) {
        info.resolution = -1; // Error: unsupported resolution unit
    }
    tiffgetfield(tif, IFD_XResolution, &info.resolution);
    tiffgetfield(tif, IFD_YResolution, &info.resolution + 2);

    info.color_space = tiffgetfield(tif, IFDT_PhotometricInterpretation);

    if (TIFFGetField(tif, TIFFTAG_IMAGEDESCRIPTION) != NULL &&
        strlen((char *)TIFFGetField(tif, TIFFTAG_IMAGEDESCRIPTION)) > max_memory_usage) {
        info.md5_hash = malloc(SHA256_DIGEST_LENGTH); // Allocate additional memory for hash computation
    } else {
        info.md5_hash = malloc(strlen((char *)TIFFGetField(tif, TIFFTAG_IMAGEDESCRIPTION)) + SHA256_DIGEST_LENGTH);
        strcpy(info.md5_hash, (char *)TIFFGetField(tif, TIFFTAG_IMAGEDESCRIPTION)); // Copy image description into hash memory
    }

    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, input_string, strlen(input_string));
    SHA256_Final(info.md5_hash + strlen((char *)TIFFGetField(tif, TIFFTAG_IMAGEDESCRIPTION)), &ctx);

    double start = double_time(); // Start time measurement

    if (TIFFReadEncodedTile(tif, 0, 0) == -1 ||
        tiffgetfield(tif, IFD_ExtraSamples, &info.num_extra_samples) < 0) {
        info.width = -1; // Error: image extraction failure
    } else {
        if (fabs((double)TIFFScanlineSize(tif) / TIFFTileRowSize(tif) - (double)info.bits_per_sample * info.sample_per_pixel / 8) > min_accuracy ||
            max_processing_time < double_time() - start) {
            info.width = -2; // Error: processing time or accuracy limit exceeded
        } else {
            info.width = TIFFTileRowSize(tif);
        }
    }

    TIFClose(tif);

    if (info.width == -1) {
        return -3; // Error: image extraction failure
    }

    return 0;
}
```']

