['```c
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>

#define AES_KEY_SIZE 32 /* AES-256 key size */
#define SALT_LENGTH 8   /* PBKDF2 salt length */
#define NUM_ITERATIONS 100000 /* Balance between security and performance */

void aes_init(const char *passphrase, unsigned char **key, unsigned char **iv) {
    const EVP_CIPHER_CTX *cipher = EVP_aes_256_cbc();
    unsigned char salt[SALT_LENGTH];
    unsigned char hashed_key[AES_KEY_SIZE];

    if (getenv("AES_PASSPHRASE")) {
        strncpy(passphrase, getenv("AES_PASSPHRASE"), strlen(getenv("AES_PASSPHRASE")));
    } else {
        fprintf(stderr, "Error: AES_PASSPHRASE environment variable not found.\n");
        exit(1);
    }

    if (!passphrase || !strlen(passphrase)) {
        fprintf(stderr, "Error: Invalid or empty passphrase.\n");
        exit(1);
    }

    /* Generate random salt */
    if (RAND_bytes(salt, SALT_LENGTH) <= 0) {
        perror("Error generating random salt");
        exit(1);
    }

    PKCS5_PBKDF2_HMAC(*EVP_sha256(), passphrase, strlen(passphrase), salt, SALT_LENGTH, NUM_ITERATIONS, hashed_key, AES_KEY_SIZE);

    *key = malloc(AES_KEY_SIZE);
    if (!*key) {
        perror("Error allocating memory for key");
        exit(1);
    }
    memcpy(*key, hashed_key, AES_KEY_SIZE);

    /* Zero-initialize IV (Initialization Vector) */
    *iv = malloc(AES_IV_LENGTH);
    if (!*iv) {
        perror("Error allocating memory for IV");
        exit(1);
    }
    memset(*iv, 0, AES_IV_LENGTH);

    EVP_CIPHER_CTX_init(cipher);
    EVP_CIPHER_CTX_set_key(cipher, *key);
    EVP_CIPHER_CTX_set_iv(cipher, *iv);
}
```

Assumptions and design decisions:
- The function takes a user-provided passphrase as input and dynamically allocates memory for the derived key.
- To maintain compatibility with various OpenSSL versions, we are using EVP APIs (EVP_aes_256_cbc() and EVP_sha256()).
- We're utilizing PBKDF2 (PKCS5_PBKDF2_HMAC()) for key derivation, with a salt of 8 bytes and 100,000 iterations to find a balance between security and performance. The number of iterations can be adjusted according to the expected load on the system.
- We're using RAND_bytes() to generate a random salt for key derivation; however, it's important to note that this function may not always return bytes from a cryptographically secure source. In practice, you should ensure that your OpenSSL library is seeded appropriately before calling this function.
- Error handling is implemented for potential issues with OpenSSL operations (perror) and key derivation failures (fprintf). Additionally, the function checks for invalid input (null passphrase or empty string).
- The function is designed to read passphrases securely from environment variables; however, it's essential to ensure that these variables are only accessible by authorized users.']

