typedef struct {
    char *password;
    void *connection;
    void (*callback)(const char*);
    const void *config; // Configuration settings structure
} MessageContext;

int process_message(MessageContext *ctx) {
    if (!ctx || !ctx->password || strlen(ctx->password) < MIN_PASSWORD_LENGTH) {
        return ERROR_INVALID_PASSWORD;
    }

    if (!ctx->connection || strcmp(((Connection*) ctx->connection)->title, "invalid_title") || !((Connection*) ctx->connection)->is_active || !within_timeout()) {
        return ERROR_INVALID_CONNECTION;
    }

    if (!ctx->callback || !valid_callback(ctx->callback)) {
        return ERROR_INVALID_CALLBACK;
    }

    if (!ctx->config || !(isValidEncryptionConfig(ctx->config))) {
        return ERROR_INVALID_CONFIG;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    char *decrypted_message = NULL;
    int retries = MAX_RETRIES;
    while (retries > 0) {
        decrypted_message = decrypt_message(ctx->password, ctx->config, base64_decode(ctx->message));
        if (decrypted_message) break;
        --retries;
        log_attempt(); // Log each attempt for debugging purposes
    }

    if (!decrypted_message) {
        free(ctx->password);
        free(ctx->connection);
        free(ctx->config);
        return ERROR_DECRYPTION_FAILURE;
    }

    pthread_mutex_lock(&mutex);
    ctx->callback(decrypted_message); // Invoke the callback function with the decrypted message
    pthread_mutex_unlock(&mutex);

    free(decrypted_message);
    free(ctx->password);
    free(ctx->connection);
    free(ctx->config);

    return 0;
}
