```java
import java.net.*;
import java.time.*;
import java.util.*;

public abstract class URLProcessor {
    private static final int MAX_RETRIES = 3;
    private static final Duration RETRY_BACKOFF = Duration.ofSeconds(2);
    private static final long THROTTLE_DURATION = TimeUnit.SECONDS.toMillis(500); // Adjust this value according to your desired throttling rate
    private static final AtomicLong requestCounter = new AtomicLong();

    protected void processUrl(String url) {
        try {
            URL u = new URL(url);
            String host = u.getHost();

            // Validate the hostname and handle subdomains/wildcard entries if needed
            // ...

            InetAddress inetAddr = InetAddress.getByName(host);

            long startTime = System.nanoTime();
            boolean available = isServerAvailable(inetAddr);
            long endTime = System.nanoTime();

            if (available) {
                onSuccess(url, Duration.ofNanos((endTime - startTime) * 1_000_000));
            } else {
                int retryCount = 0;
                while (!isServerAvailable(inetAddr) && retryCount < MAX_RETRIES) {
                    if (System.nanoTime() - startTime + RETRY_BACKOFF.toNanos() > System.currentTimeMillis()) {
                        Thread.sleep(RETRY_BACKOFF.toMillis());
                    }
                    retryCount++;
                }

                if (retryCount >= MAX_RETRIES) {
                    onFailure(url, "Server unreachable after " + MAX_RETRIES + " retries");
                }
            }
        } catch (UnknownHostException | IOException e) {
            onFailure(url, e.getMessage());
        } catch (InterruptedException e) {
            // Interrupt handling if necessary
        }
    }

    protected abstract void onSuccess(String url, Duration latency);

    protected abstract void onFailure(String url, String message);

    private boolean isServerAvailable(InetAddress inetAddr) throws IOException {
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(inetAddr, 80), 2000); // Adjust the timeout if needed
            return true;
        } catch (UnknownHostException | SocketTimeoutException e) {
            return false;
        }
    }

    private boolean shouldThrottle() {
        long counter = requestCounter.incrementAndGet();
        long remainder = THROTTLE_DURATION - (System.currentTimeMillis() % THROTTLE_DURATION);
        return counter % (THROTTLE_DURATION / remainder) == 0;
    }
}
```

