using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace ScalableCommunicationChannel
{
    public class AesGcmEncryptionManager : IDisposable
    {
        private readonly Aes _aes;
        private readonly RandomNumberGenerator _rng;
        private readonly ICryptoTransform _encryptor;
        private readonly ICryptoTransform _decryptor;
        private byte[] _key;
        private byte[] _iv;
        private ILogger<AesGcmEncryptionManager> _logger;

        public AesGcmEncryptionManager(ILogger<AesGcmEncryptionManager> logger)
        {
            _logger = logger;
            _rng = RandomNumberGenerator.Create();
            _aes = AES.Create();
            _encryptor = _aes.CreateEncoder(_rng);
            _decryptor = _aes.CreateDecoder(_rng);
        }

        public void SetKey(byte[] key) => _key = key;
        public void SetIV(byte[] iv) => _iv = iv;

        public byte[] Encrypt(byte[] data)
        {
            if (_key == null || _iv == null)
                throw new InvalidOperationException("Key and IV must be set before encrypting.");

            using (var msEncrypt = new MemoryStream())
            {
                var gcm = new GCM(new AesManaged());
                var encryptedData = gcm.Encrypt(msEncrypt, _key, _iv, data, null);
                _logger.LogInformation($"Encryption successful: {DateTime.UtcNow}");
                return encryptedData;
            }
        }

        public byte[] Decrypt(byte[] data)
        {
            if (_key == null || _iv == null)
                throw new InvalidOperationException("Key and IV must be set before decrypting.");

            using (var msDecrypt = new MemoryStream(data))
            {
                try
                {
                    var gcm = new GCM(new AesManaged());
                    var decryptedData = gcm.Decrypt(msDecrypt, _key, _iv);
                    _logger.LogInformation($"Decryption successful: {DateTime.UtcNow}");
                    return decryptedData;
                }
                catch (CryptographicException ex)
                {
                    _logger.LogError(ex, $"Decryption failed: {DateTime.UtcNow}");
                    throw new DecryptionException("Decryption error.", ex);
                }
            }
        }

        public void Dispose()
        {
            if (_encryptor != null) _encryptor.Dispose();
            if (_decryptor != null) _decryptor.Dispose();
            _aes?.Dispose();
            _rng?.Dispose();
        }
    }
}
