public class Deserializer {
    private final Map<String, Class<?>> serializationFormats = new HashMap<>();
    private final ObjectInputStreamFactory objectInputStreamFactory = new ObjectInputStreamFactory();

    public void setup(Map<String, Class<? extends Serializable>> formats) {
