        try (ByteArrayInputStream bais = new ByteArrayInputStream(serializedData)) {
            // Check for header and determine compression type
            byte[] header = new byte[4];
            bais.readFully(header);
            if (Arrays.equals(header, "gzip".getBytes(StandardCharsets.UTF_8))) {
                bais = new GZIPInputStream(bais);
            }

            // Determine serialization format and create appropriate ObjectInputStream
            Class<?> formatClass = serializationFormats.getOrDefault("native", ObjectOutputStream.class);
            ObjectInputStream objectInput = objectInputStreamFactory.create(formatClass, bais);

            // Read checksum and verify it against the provided value
            long readChecksum = 0;
            for (int i = 0; i < Long.BYTES; i++) {
                readChecksum <<= 8;
                readChecksum |= objectInput.read();
            }

            if (checksum != readChecksum) {
                logWarning("Checksum validation failed for serialized data.");
            }

            // Perform deserialization and handle cyclic references
            T result = objectInput.readObject();
            objectInput.defaultReadObject(); // Consume any remaining data to avoid stack overflow with cyclic references

            // Verify post-deserialization integrity and throw exception if necessary
            if (!isValid(result, targetClass)) {
                throw new RuntimeException("Failed to deserialize a valid instance of " + targetClass.getName() + ". Please check the serialized data.");
            }

            return result;
        } catch (Exception e) {
            logError("Deserialization failed.", e);
            if (Collections.isEmpty(serializationFormats.values())) {
                throw new RuntimeException("Failed to deserialize any supported objects.", e);
            }
            return null; // Indicates failure to deserialize for all specified classes
        }
    }

