#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent/dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <inttypes.h>
#include <math.h>
#include <getopt.h>

typedef struct {
    char *input_dir;
    char *output_file;
    int human_readable;
} Args;

void parse_args(int argc, char **argv, Args *args) {
    const char *short_opts = "id:o:h";
    const struct option long_opts[] = {
        {"input-dir", required_argument, NULL, 'i'},
        {"output-file", required_argument, NULL, 'o'},
        {"human-readable", no_argument, NULL, 'h'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (opt) {
            case 'i':
                args->input_dir = optarg;
                break;
            case 'o':
                args->output_file = optarg;
                break;
            case 'h':
                args->human_readable = 1;
                break;
            default:
                fprintf(stderr, "Usage: %s -i <input-dir> [-o <output-file>] [-h]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (!args->input_dir) {
        fprintf(stderr, "Error: --input-dir is required.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to print file details in a user-friendly manner
void print_file_details(const char *path, off_t size, mode_t type) {
    char *size_str;
    switch ((int)(log10((double)size))) {
        case 3:
            size_str = (size / 1024 / 1024 / 1024) < 1 ? "B" :
                       (size / 1024 / 1024) < 1 ? "KB" :
                       (size / 1024) < 1 ? "MB" : "GB";
            break;
        case 2:
            size_str = (size / 1024 / 1024) < 1 ? "KB" : "MB";
            break;
        default:
            size_str = (size / 1024) < 1 ? "MB" : "GB";
    }
    printf("%s (%d bytes, %s)\n", path, (int)size, size_str);
}

void traverse_dir(const char *path, Args *args) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;

    dir = opendir(path);
    if (!dir) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        snprintf(path + strlen(path), sizeof(path) - strlen(path), "/%s", entry->d_name);
        lstat(path, &file_stat);

        if (S_ISDIR(file_stat.st_mode)) {
            traverse_dir(path, args);
        } else if (S_ISREG(file_stat.st_mode)) {
            print_file_details(path, file_stat.st_size, file_stat.st_mode);
        }

        snprintf(path, sizeof(path), "%s", args->input_dir); // Reset the path to the input directory
    }
    closedir(dir);
}

int main(int argc, char **argv) {
    Args args;
    parse_args(argc, argv, &args);

    if (args.output_file && access(args.output_file, W_OK | F_OK) < 0) {
        perror("Output file access error");
        return EXIT_FAILURE;
    }

    char path[sizeof(args->input_dir)];
    traverse_dir(args.input_dir, &args);

    if (args.output_file) {
        FILE *output = fopen(args.output_file, "w");
        if (!output) {
            perror("Output file open error");
            return EXIT_FAILURE;
        }

        fprintf(output, "# Directory Report\n");
        rewinddir(opendir(args.input_dir)); // Reset the directory to its initial state for re-traversal
        traverse_dir(args.input_dir, &args);
        fclose(output);
    }

    return EXIT_SUCCESS;
}
```

