#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <random>

class RandomGenerator {
public:
    explicit RandomGenerator(unsigned long seed) : rng(_seed), mtx() {
        _seed = seed;
    }

    ~RandomGenerator() {}

    int generate(int min, int max) const {
        std::uniform_int_distribution<> distr(min, max);
        std::lock_guard<std::mutex> lock(mtx);
        return distr(rng);
    }

    unsigned long getSeed() const { return _seed; }

    static std::unique_ptr<RandomGenerator> create(unsigned long seed) {
        auto instance = std::make_unique<RandomGenerator>(seed);
        instances.emplace_back(std::move(instance));
        return instances.back();
    }

private:
    mutable std::mutex mtx;
    static std::vector<std::unique_ptr<RandomGenerator>> instances;
    std::mt19937 rng;
    unsigned long _seed;
};

// Initialize static member variable for concurrent instances
std::vector<std::unique_ptr<RandomGenerator>> RandomGenerator::instances;

void test() {
    auto rng = RandomGenerator::create(12345); // Seed using a specific value
    std::thread threads[10];

    for (size_t i = 0; i < 10; ++i)
        threads[i] = std::thread([&rng]() {
            for (int j = 0; j < 1000000; ++j)
                rng->generate(0, RAND_MAX);
        });

    for (auto &t : threads) t.join();
}
```
