#include <sys/stat.h>
#include <errno.h>
#include <stdbool.h>
#include <semaphore.h>

static sem_t g_sem; // Global semaphore for synchronization
static char *g_dir_path; // Global variable to store directory path

typedef struct {
    int fd;
    size_t buf_size;
    char *buf;
} file_data_t;

void handle_error(const char *msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
}

void log_error(const char *file, int line, const char *func, const char *msg) {
    FILE *log_fp = fopen("error.log", "a");
    if (!log_fp) {
        handle_error("Failed to open error log file.");
        return;
    }

    fprintf(log_fp, "[%s:%d %s] %s\n", file, line, func, msg);
    fclose(log_fp);
}

void *process_file(void *arg) {
    file_data_t *data = arg;

    sem_wait(&g_sem); // Acquire the semaphore to prevent race conditions

    size_t len = lseek(data->fd, 0, SEEK_END);
    data->buf = malloc(len + 1);
    if (!data->buf) {
        handle_error("Failed to allocate memory for the file buffer.");
        sem_post(&g_sem); // Release the semaphore in case of error
        return NULL;
    }

    lseek(data->fd, 0, SEEK_SET); // Reset file position to the beginning
    ssize_t nread = read(data->fd, data->buf, len);
    if (nread != len) {
        handle_error("Failed to read the entire file.");
        free(data->buf);
        sem_post(&g_sem); // Release the semaphore in case of error
        return NULL;
    }

    data->buf[len] = '\0'; // Null-terminate the buffer

    for (size_t i = 0; i < len; ++i) {
        if (isupper((unsigned char)data->buf[i]))
            data->buf[i] += ('a' - 'A');
    }

    sem_post(&g_sem); // Release the semaphore after processing the file
    return data;
}

void write_to_file(const char *path, const void *data) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        log_error(__FILE__, __LINE__, __func__, "Failed to open file for writing.");
        return;
    }

    size_t len = strlen(data);
    ssize_t nwrite = write(fd, data, len);
    if (nwrite != len) {
        log_error(__FILE__, __LINE__, __func__, "Failed to write the entire buffer to file.");
    }

    close(fd);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        handle_error("Please provide at least one file as an argument.");
        return EXIT_FAILURE;
    }

    sem_init(&g_sem, 0, 1); // Initialize the global semaphore

    if (argc > 2 && strcmp(argv[1], "--create-dir") == 0) {
        const char *dir = argv[3];
        if (!mkdir(dir, 0755)) {
            g_dir_path = dir;
        } else {
            handle_error("Failed to create the specified directory.");
            return EXIT_FAILURE;
        }
    }

    char **files = calloc(argc - (argc > 2 ? 3 : 2), sizeof(char *));
    if (!files) {
        handle_error("Failed to allocate memory for file list.");
        return EXIT_FAILURE;
    }

    // Copy the remaining arguments into the files array, excluding --create-dir flag if present.
    int idx = 0;
    for (int i = (argc > 2 ? 3 : 1); i < argc; ++i) {
        files[idx++] = argv[i];
    }

    pthread_t *threads = malloc(idx * sizeof(pthread_t));
    if (!threads) {
        handle_error("Failed to allocate memory for the thread array.");
        free(files);
        return EXIT_FAILURE;
    }

    file_data_t **data = malloc(idx * sizeof(file_data_t*));
    if (!data) {
        handle_error("Failed to allocate memory for the data array.");
        free(threads);
        free(files);
        return EXIT_FAILURE;
    }

    // Initialize and create threads
    for (int i = 0; i < idx; ++i) {
        data[i] = malloc(sizeof(file_data_t));
        if (!data[i]) {
            handle_error("Failed to allocate memory for file data.");
            free(threads);
            free(data);
            free(files);
            return EXIT_FAILURE;
        }

        data[i]->fd = open(files[i], O_RDONLY);
        if (data[i]->fd == -1) {
            handle_error("Failed to open file for reading.");
            free(data[i]);
            continue;
        }

        data[i]->buf_size = 0; // Lazy allocation of buffer size
        pthread_create(&threads[i], NULL, process_file, data[i]);
    }

    // Wait for all threads to finish processing their files
    for (int i = 0; i < idx; ++i) {
        void *res = NULL;
        pthread_join(threads[i], &res);
        if (!res) {
            handle_error("Thread execution failed.");
        } else {
            file_data_t *file_data = res;
            write_to_file("output.txt", file_data->buf);
            free(file_data->buf);
            close(file_data->fd);
            free(file_data);
        }
    }

    // Free resources and exit
    free(threads);
    free(data);
    free(files);
    sem_destroy(&g_sem);

    if (g_dir_path) {
        setenv("MY_DIR", g_dir_path, 1);
    }

    return EXIT_SUCCESS;
}
