    res = curl_easy_perform(curl);
    if (res != CURLE_OK) return res;

    char *response_data;
    size_t response_len;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_DATA_LENGTH_total, &response_len);
    if (res != CURLE_OK) return res;

    response_data = malloc(response_len);
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_DATA, response_data);
    if (res != CURLE_OK) {
        free(response_data);
        return res;
    }

    *response = json_tokener_parse(response_data);
    curl_easy_cleanup(curl);
    free(response_data);
    return CURLE_OK;
