#include <sys/stat.h>
#include <errno.h>
#include <execinfo.h>

#define MAX_OFFSET 1000000
#define MAX_KEYS 10000
#define MAX_RECORDS 100000
#define LOG_FILE "command_execution_log.txt"

typedef struct {
    int value;
} Record;

void log_message(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

int execute_command(long *offsets, int *keys, Record *records, char *targetFile) {
    pid_t pid;
    int status;
    FILE *tempFile;
    char command[MAX_OFFSET + MAX_KEYS + 100]; // Allow for some additional space in the command string

    // Delete existing file if it exists
    if (remove(targetFile) == 0 || errno != ENOENT) {
        log_message("Deleting existing target file");
    }

    // Generate random data and initialize arrays
    srand(time(NULL));
    for (size_t i = 0; i < MAX_OFFSET; ++i) {
        offsets[i] = rand() % MAX_OFFSET;
    }
    for (size_t j = 0; j < MAX_KEYS; ++j) {
        keys[j] = rand() % MAX_KEYS;
    }
    for (size_t k = 0; k < MAX_RECORDS; ++k) {
        records[k].value = rand() % MAX_RECORDS;
    }

    // Build the command string
    snprintf(command, sizeof(command), "your_external_process --offsets=\"%ld,%ld...\" --keys=\"%d,%d...\" --records=\"%d\" --targetFile=\"%s\"", offsets[0], offsets[MAX_OFFSET - 1], keys[0], keys[MAX_KEYS - 1], records[0].value, targetFile);

    // Allocate space for the argument list and create it
    char *args[] = { "your_external_process", command };
    char **environment = NULL;

    // Create a temporary file to store the large data structures
    tempFile = tmpfile();
    if (tempFile != NULL) {
        fwrite(offsets, sizeof(long), MAX_OFFSET, tempFile);
        fwrite(keys, sizeof(int), MAX_KEYS, tempFile);
        fwrite(records, sizeof(Record), MAX_RECORDS, tempFile);
        fseek(tempFile, 0, SEEK_SET); // Reset the file position to the start for the exec call
    } else {
        log_message("Error creating temporary file");
        return -1;
    }

    // Execute the command and read the exit code
    pid = fork();
    if (pid == 0) {
        // Child process
        execv(args[0], args);
        _exit(127); // Set an error exit code for the child in case of failure to execute the command
    } else if (pid > 0) {
        // Parent process
        waitpid(pid, &status, 0);
    } else {
        log_message("Error forking process");
        return -1;
    }

    // Cleanup temporary file and log any errors
    if (tempFile != NULL) {
        fclose(tempFile);
        remove(fileno(tempFile));
    }

    return WEXITSTATUS(status);
}
