class PacketBuffer {
public:
    void append(const Packet& pkt) {
        mutex.lock();
        buffer.push_back(pkt);
        if (buffer.size() > capacity)
            buffer.pop_front();
        mutex.unlock();
    }

    const Packet& front() const {
        mutex.lock();
        auto pkt = buffer.front();
        mutex.unlock();
        return pkt;
    }

