    public class DynamicValueGenerator
    {
        private float _minValue;
        private float _maxValue;

        private readonly Random _random = new Random();
        private float _cachedMin;
        private float _cachedMax;
        private bool _isCacheDirty = true;

        public string CurrentRange { get => $"Min: {_minValue}, Max: {_maxValue}"; }

        public void SetRange(float min, float max)
        {
            if (min >= max)
                throw new ArgumentOutOfRangeException(nameof(min), "The minimum value must be less than the maximum value.");

            _minValue = Mathf.Clamp01(min);
            _maxValue = Mathf.Clamp01(max);
            _cachedMin = _minValue;
            _cachedMax = _maxValue;
            _isCacheDirty = true;

            LogRangeSet();
        }

        public float GetRandomFloat()
        {
            if (_isCacheDirty)
            {
                _cachedMin = _minValue;
                _cachedMax = _maxValue;
                _isCacheDirty = false;
            }

            return _random.Range(_cachedMin, _cachedMax);
        }

        public int GetRandomInt()
        {
            return Mathf.RoundToInt(GetRandomFloat());
        }

        public void ClearCache()
        {
            _isCacheDirty = true;
        }

        private void LogRangeSet()
        {
            // Replace this with your existing logging framework implementation
