char* processString(const char *inputStr, size_t sizeLimit, bool enforceStrictLength) {
    size_t inputLen = strlen(inputStr);

    // Check if the length of inputStr meets the criteria
    if (enforceStrictLength && inputLen > sizeLimit || !enforceStrictLength && inputLen > sizeLimit + 1) {
        return NULL;
    }

    // Allocate memory for the new string and check for failure
    char *newStr = malloc(inputLen + 2); // For inputStr + '/' + '\0'
    if (!newStr) {
        return NULL;
    }

    // Copy inputStr to newStr, followed by a slash and null terminator
    strcpy(newStr, inputStr);
    newStr[inputLen] = '/';
    newStr[inputLen + 1] = '\0';

    return newStr;
}
