['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <float.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <inttypes.h>

typedef struct {
    time_t timestamp;
    char* event_type;
    size_t num_fields;
    char** fields;
} Entry;

void free_entry(Entry* entry) {
    for (size_t i = 0; i < entry->num_fields; ++i) {
        free(entry->fields[i]);
    }
    free(entry->event_type);
    free(entry->fields);
}

int validate_entry(Entry* entry) {
    if (entry->num_fields < 3) {
        return -1;
    }
    for (size_t i = 0; i < entry->num_fields - 2; ++i) {
        if (!isdigit((int)entry->fields[i][0])) {
            return -1;
        }
    }
    return 0;
}

void process_entry(Entry* entry) {
    double sum = atof(entry->fields[entry->num_fields - 2]) + atof(entry->fields[entry->num_fields - 1]);
    entry->fields[entry->num_fields - 1] = malloc(sizeof(char) * 64); // Assumes max 64 digits for float number precision
    snprintf(entry->fields[entry->num_fields - 1], sizeof(entry->fields[entry->num_fields - 1]), "%.6f", sum / 2.0);
}

int main() {
    FILE* file = fopen("large_log.txt", "r");
    if (!file) {
        perror("Error opening log file");
        return 1;
    }

    Entry current_entry;
    char line[4096];
    size_t line_length = 0;

    while (fgets(line, sizeof(line), file)) {
        line_length = strlen(line);
        current_entry.fields = malloc((line_length + 1) * sizeof(char*));
        for (size_t i = 0; i < line_length; ++i) {
            current_entry.fields[i] = malloc((strlen(&line[i]) + 1) * sizeof(char));
            strcpy(current_entry.fields[i], &line[i]);
        }
        current_entry.fields[line_length] = NULL;
        current_entry.num_fields = line_length / (sizeof(char*) * sizeof(char)) + 1;

        if (validate_entry(&current_entry) >= 0) {
            process_entry(&current_entry);
        }
        free_entry(&current_entry);
    }

    fclose(file);

    FILE* temp_file = tmpfile();
    if (!temp_file) {
        perror("Error creating temporary file");
        return 1;
    }

    qsort(current_entry.fields, current_entry.num_fields, sizeof(char*), (int (*)(const void*, const void*))compare);
    for (size_t i = 0; i < current_entry.num_fields; ++i) {
        fprintf(temp_file, "%s ", current_entry.fields[i]);
        free(current_entry.fields[i]);
    }
    fprintf(temp_file, "\n");

    fclose(temp_file);

    return 0;
}

int compare(const void* a, const void* b) {
    double a_value = atof(*((char**)a + current_entry.num_fields - 1));
    double b_value = atof(*((char**)b + current_entry.num_fields - 1));

    if (a_value == b_value) {
        return strcmp(*((char**)a + current_entry.num_fields - 2), *((char**)b + current_entry.num_fields - 2));
    }

    return (b_value > a_value) ? 1 : -1;
}
