    if (!config) {
        fprintf(stderr, "Error: Unable to open config file\n");
        exit(1);
    }

    char line[256];
    event* session_ids = NULL;
    size_t num_session_ids = 0;

    while (fgets(line, sizeof(line), config)) {
        // Parse the configuration line and create a new session ID range
        const char *key = strtok(line, "=");
        if (!key) continue;
        const char *value = strtok(NULL, "\n");
        if (!value) continue;

        uint32_t start = strtol(value, NULL, 10);
        value += strlen(value) + 1; // Skip the ',' character and space
        uint32_t end = strtol(value, NULL, 10);

        event session_id = { .session_id = start };
        if (end > start)
            session_id.session_id = end;

        event *new_session_ids = realloc(session_ids, sizeof(event) * (num_session_ids + 1));
        if (!new_session_ids) {
            fprintf(stderr, "Error: Out of memory\n");
            free(session_ids);
            fclose(config);
            exit(1);
        }
        session_ids = new_session_ids;
        session_ids[num_session_ids++] = session_id;
    }

    fclose(config);
    return session_ids;
}

// Function for processing the binary file containing timestamps and session IDs
void process_file(const char *filename, event* session_ids, size_t num_session_ids) {
    // Map the file into memory for efficient access
    void *map = mmap(NULL, strlen(filename) + 1, PROT_READ, MAP_PRIVATE, open(filename, O_RDONLY), 0);
    if (map == MAP_FAILED) {
        perror("Error: Unable to map file");
        exit(1);
    }

    uint32_t *timestamps = malloc(sizeof(uint32_t));
    event *event_log = NULL;
    size_t num_events = 0;
    bool duplicate = false;

    for (size_t i = 0, pos = 0; i < strlen((char*)map); ++i) {
        if (((char*)map)[i] == '\n') {
            timestamps[pos++] = *(uint32_t*)((char*)map + pos);
            if (num_events >= num_session_ids) break;

            uint32_t session_id = hash("session_id", (const char*)map + pos);
            bool valid_session_id = false;

            for (size_t j = 0; j < num_session_ids && !valid_session_id; ++j) {
                if (session_ids[j].session_id <= session_id && session_id <= session_ids[j].session_id + 1)
                    valid_session_id = true;
            }

            if (!valid_session_id) {
                fprintf(stderr, "Error: Invalid session ID: %u\n", session_id);
                continue;
            }

            event *new_event_log = realloc(event_log, sizeof(event) * (num_events + 1));
            if (!new_event_log) {
                perror("Error: Out of memory");
                munmap(map, strlen(filename) + 1);
                free(timestamps);
                exit(1);
            }
            event_log = new_event_log;

            event log_entry = { .timestamp = timestamps[pos - 1], .session_id = session_id };
            if (duplicate) {
                fprintf(stderr, "Error: Duplicate timestamp: %u\n", log_entry.timestamp);
            } else {
                event_log[num_events++] = log_entry;
            }
            duplicate = false;

            pos += sizeof(uint32_t);
        }
    }

    munmap(map, strlen(filename) + 1);
    free(timestamps);

    // Log any remaining timestamps that didn't match a valid session ID
    for (size_t i = num_events; i < num_session_ids; ++i) {
        fprintf(stderr, "Error: Unmatched timestamp: %u\n", event_log[i].timestamp);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s binary_file\n", argv[0]);
        exit(1);
    }

    event* session_ids = load_config();
    process_file(argv[1], session_ids, strlen(session_ids));

    free(session_ids);
    return 0;
}
```
