```python
import os
import glob
import shutil
from PIL import Image
from ffmpeg import ffmpeg
from pydub import AudioSegment
from argparse import ArgumentParser
import logging

def get_file_size(path):
    return os.path.getsize(path)

def analyze_media(path, formats=("image", "video", "audio"), size_range=(0, None), file_type=""):
    total = 0
    count = 0
    for ext in formats:
        files = glob.glob(f"{path}/**/*.{}".format(ext))
        for file in files:
            if get_file_size(file) < size_range[1] or get_file_size(file) >= size_range[0]:
                continue
            if file_type and not file.endswith(file_type):
                continue
            count += 1
            if ext == "image":
                img = Image.open(file)
                total += img.size[0] * img.size[1]
            elif ext in ("video", "audio"):
                pass  # Implement video and audio analysis here
    return total / count if count > 0 else None

def main():
    parser = ArgumentParser()
    parser.add_argument("-t", "--format", type=str, nargs="*", help="Filter files by format")
    parser.add_argument("-s", "--size", type=tuple, nargs=2, help="Filter files by size range (min, max)")
    parser.add_argument("-f", "--filetype", type=str, help="Filter files by file type")
    parser.add_argument("-o", "--output", type=str, help="Specify output directory for the report")
    args = parser.parse_args()

    if not args.output:
        print("Usage: python script.py -o <output_directory> [options]")
        return

    os.makedirs(args.output, exist_ok=True)

    report = {
        "image": {},
        "video": {},
        "audio": {}
    }

    for root, dirs, files in os.walk("."):
        for file in files:
            ext = os.path.splitext(file)[1]
            if ext in (".exe", ".bat"):  # Avoid executables on Windows and batch files
                continue
            path = os.path.join(root, file)
            formats_matched = any([ext == f for f in args.format]) and \
                              all([f != ext or f not in args.filetype for f in ["image", "video", "audio"]]) and \
                              (args.size is None or within_range(get_file_size(path), *args.size))
            if formats_matched:
                media_type = determine_media_type(path)
                report[media_type][ext] = analyze_media(root, (ext,), args.size, file) or {"total_size": get_file_size(path)}

    with open(os.path.join(args.output, "report.txt"), "w") as f:
        for k, v in report.items():
            f.write(f"{k}:\n")
            for ext, data in v.items():
                if isinstance(data, dict):
                    f.write(f"{ext}: {str(data)} bytes\n")
                else:
                    f.write(f"{ext}: size: {data['total_size']} bytes, average_size: {data['count'] if data['count'] > 0 else None}")
                    if k == "image":
                        f.write(f", dimensions: width: {data['width']}, height: {data['height']}")
                    f.write("\n")

def within_range(value, min, max):
    return min <= value <= max or (min is None and max is None)

def determine_media_type(path):
    if os.path.isfile(path):
        ext = os.path.splitext(path)[1]
        if ext in (".jpg", ".jpeg"):
            return "image"
        elif (ffmpeg(path).format("probe"))[0].startswith("Video"):
            return "video"
        elif path.endswith((".wav", ".mp3")):
            return "audio"
    return None  # Assumes directories are not media files
```

