    for (size_t i = 0; i < numStrings; ++i) {
        if (strings[i].len > longest)
            longest = strings[i].len;
    }

    printf("The longest string is %zu characters.\n", longest);

    free(strings);
    strings = NULL;
    numStrings = 0;
