        str[maxLen] = '\0';
    }

    pthread_mutex_lock(&input_mutex);
    StringData *newStrings = realloc(strings, sizeof(StringData) * (numStrings + 1));
    if (!newStrings) {
        perror("Memory allocation failed");
        return;
    }
    strings = newStrings;
    strings[numStrings].str = strdup(str);
    strings[numStrings].len = strlen(str);
    numStrings++;
    pthread_mutex_unlock(&input_mutex);
    pthread_cond_signal(&input_cond);
}

