    while (1) {
        ssize_t n = read(STDIN_FILENO, buf, sizeof(buf));
        if (n < 0) {
            perror("Read error");
            break;
        }
        for (ssize_t i = 0; i < n && i + numStrings * sizeof(StringData) <= sizeof(buf); ) {
            addString(&buf[i]);
            i += strings[numStrings - 1].len + 1;
        }
    }
    return NULL;
}

