    jclass executorClass = (*jni_env)->FindClass(jni_env, "java/util/concurrent/Executors");
    jobject executorObj = (*jni_env)->CallStaticObjectMethod(executorClass, "newSingleThreadExecutor", "()Ljava/util/concurrent/ExecutorService;");
    executor = (*jni_env)->NewGlobalRef(jni_env, executorObj);
}

int main(int argc, char **argv) {
