public class FileHasher {
    private static final int RETRY_ATTEMPTS = 3;

    public String computeSHA256Hash(List<String> filePaths) throws Exception {
        StringBuilder outputHash = new StringBuilder();

        for (String filePath : filePaths) {
            FileSystemManager vfsManager = VFS.getManager();
            try {
                // Assuming the file exists and is accessible within the specified path
                FileObject fileObject = vfsManager.resolveFile(filePath);

                if (fileObject.getType() == FileType.FILE) {
                    FileSystemOptions options = fileObject.getFileSystem().getOptions();

                    // Async read for local/networked files
                    InputStream inputStream = fileObject.getContent().getInputStream();
                    MessageDigest md = MessageDigest.getInstance("SHA-256");

                    byte[] buffer = new byte[1024];
                    int bytesRead;

                    // Read the file content and compute its hash in chunks
                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        md.update(buffer, 0, bytesRead);
                    }

                    outputHash.append(new BigInteger(1, md.digest()).toString(16));
                }
            } catch (FileSystemException e) {
                // Handle non-existent files or permission issues gracefully
                System.err.println("Error accessing file: " + filePath + ", Error message: " + e.getMessage());
            } finally {
                vfsManager.closeAll();
            }
        }

        return outputHash.toString();
    }
}
```

