function renderFooterScripts(scripts) {
  let orderedScripts = lodash.sortBy(scripts, ['dependencies']); // Sort scripts based on dependencies

  const renderedScripts = orderedScripts.reduce((html, script) => {
    let id;
    if (!script.name) {
      id = generateIdFromContent(script.code);
    } else {
      id = `script-${script.name}`;
    }

    // Check if script is already in the cache or has valid code before rendering
    if (cachableScripts.has(id) || script.code) {
