      html += scriptTag;

      // Load dependencies asynchronously if they have not been loaded yet
      if (script.dependencies && !script.dependencies.every(depId => cachableScripts.has(depId))) {
        Promise.all(script.dependencies.map(depId => loadScriptIfNotLoaded(depId)).then(() => html += renderFooterScripts([...scripts.filter(s => s.name === script.name)])));
      }
