#include <string.h>

void processSemaphoreAndString(const char *inputStr, size_t sizeLimit, bool enforceStrictLength) {
    sem_t *semaphore;
    size_t strLen = strlen(inputStr);
    char *newStr;

    // Create semaphore with the provided initial value (1 in this case)
    semaphore = sem_open("mySemaphore", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IXUSR, 1);

    // Check if memory allocation for newStr fails
    if (!(newStr = malloc(strLen + 2))) {
        sem_close(semaphore);
        sem_unlink("mySemaphore");
        return NULL;
    }

    // Copy inputStr to newStr and append a slash (/)
    strcpy(newStr, inputStr);
    newStr[strLen] = '/';
    newStr[strLen + 1] = '\0';

    // Validate the length of inputStr against processing criteria
    if (enforceStrictLength) {
        if (strLen > sizeLimit) {
            sem_close(semaphore);
            free(newStr);
            return NULL;
        }
    } else {
        if (strLen > sizeLimit + 1) {
            sem_close(semaphore);
            free(newStr);
            return NULL;
        }
    }

    // Perform any additional processing, handle concurrent access to shared resources safely and efficiently
    // ...

    // Clean up the allocated memory for newStr and semaphore
    sem_close(semaphore);
    free(newStr);
}
