#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>

typedef struct Semaphore {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int count;
    int max_count;
    bool is_deleted;
    char *metadata;
    off_t metadata_offset;
} Semaphore;

Semaphore* create_semaphore(int initial_value, int max_count, const char *filename, off_t offset) {
    Semaphore *semaphore = malloc(sizeof(Semaphore));
    if (!semaphore) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    semaphore->count = initial_value;
    semaphore->max_count = max_count;
    semaphore->is_deleted = false;

    if (pthread_mutex_init(&semaphore->lock, NULL) != 0 || pthread_cond_init(&semaphore->cond, NULL) != 0) {
        perror("pthread_mutex_init/pthread_cond_init");
        exit(EXIT_FAILURE);
    }

    int fd = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ftruncate(fd, sizeof(int));
    semaphore->metadata_offset = offset;
    semaphore->metadata = mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (semaphore->metadata == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    *((int *)semaphore->metadata) = initial_value;

    return semaphore;
}

void delete_semaphore(Semaphore *semaphore) {
    if (munmap(semaphore->metadata, sizeof(int)) == -1) {
        perror("munmap");
    }

    close(semaphore->metadata_offset);
    free(semaphore);
}

void inc_semaphore(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->lock);
    while (semaphore->count >= semaphore->max_count) {
        pthread_cond_wait(&semaphore->cond, &semaphore->lock);
    }

    __sync_fetch_and_add(semaphore->metadata, 1);
    semaphore->count++;
    pthread_mutex_unlock(&semaphore->lock);
}

void dec_semaphore(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->lock);
    while (semaphore->count <= *((int *)semaphore->metadata)) {
        pthread_cond_wait(&semaphore->cond, &semaphore->lock);
    }

    __sync_fetch_and_sub(semaphore->metadata, 1);
    semaphore->count--;
    pthread_mutex_unlock(&semaphore->lock);
}

void log_semaphore_operation(const char *operation) {
    // Implement logging functionality here
}

// Usage example:
Semaphore *semaphore = create_semaphore(5, 10, "path/to/semaphores.dat", 0);
...
inc_semaphore(semaphore);
...
dec_semaphore(semaphore);
...
```
