// Forward List of strings with metadata
using StrMetadata = std::pair<std::string, std::chrono::time_point<std::chrono::system_clock>>;
using StringDeque = std::deque<StrMetadata>;

class TrimAndAppendSlash {
public:
    static int64_t modificationsCount;

    void trimAndAppendSlash(StringDeque& strings, size_t sizeLimit) {
        auto startTime = std::chrono::system_clock::now();
        for (auto it = strings.begin(); it != strings.end();) {
            StrMetadata md = *it;
            if (md.first.size() < sizeLimit) {
                ++modificationsCount;
                it->first += '/';
                it->second = std::chrono::system_clock::now();
                it++;
            } else {
                std::cout << "Removed: " << md.first << '\n';
                modificationsCount++;
                it = strings.erase(it);
            }
        }
        auto endTime = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
        std::cout << "Processing time: " << duration << " ms\n";
    }
};

int64_t TrimAndAppendSlash::modificationsCount = 0;

