class DOMTraversal {
public:
    void traverseDOM(DomDeque& nodes, const std::string& selector, DomCallback cb) {
        for (auto node : nodes) {
            if (matchElement(node.get(), selector)) {
                if (cb(node->className()))
                    matchedNodes.push_back(node);
            }
            for (DomNodePtr child : getChildren(node))
                traverseDOM(children, selector, cb);
        }
    }

private:
    bool matchElement(DomNodePtr node, const std::string& selector) {
        // Implement matching based on class or ID using a simple regex
        std::regex e("^(\\.|#)([a-zA-Z0-9]+)$", std::regex_constants::icase);
        auto match = std::regex_search(selector, std::regex_iterator<std::string::const_iterator>(selector.begin(), selector.end()), e);
        if (!match) return false;

        const char* str = match[2].str().c_str();
        if (strlen(str) == 1 && *(str + 0) == '#') {
            // It's an ID selector
            return node->getId() == str + 1;
        } else {
            // It's a class selector
            return std::find(node->className()->begin(), node->className()->end(), str) != node->className()->end();
        }
    }

    DomDeque getChildren(DomNodePtr node) {
        // Implement getting child nodes here
        // ...
    }

    DomDeque matchedNodes;
};
