typedef struct {
    char *dir;
    char *base;
    char *ext;
} FileInfo;

int create_filepath(FileInfo *info, const char *input) {
    size_t len = strlen(input);
    if (len > 255) return -1; // Filename too long

    int dir_count = 0;
    for (const char *p = input; *p != '\0'; ++p) {
        if (*p == '/') ++dir_count;
    }

    info->base = malloc(strlen(input - dir_count) + 4); // 4 characters for extension
    strncpy(info->base, input - dir_count, strlen(input - dir_count));

    size_t ext_len = 3; // Default to "json" extension
    if (dir_count <= 10) {
        ext_len = 1 + (strlen(info->base) - 1);
    } else {
        ext_len = 6; // Hexadecimal representation for extension
    }
    info->ext = malloc(ext_len);
    memset(info->ext, 0, ext_len);

    int base_type = -1; // -1: not yet determined
    for (const char *p = info->base; *p != '\0'; ++p) {
        if (*p >= 'a' && *p <= 'z') base_type = 0; // Lowercase letters trigger json
        else if (*p >= 'A' && *p <= 'Z') base_type = 1; // Uppercase letters trigger xml
        else if (*p >= '0' && *p <= '9') base_type = 2; // Digits trigger html
    }

    switch (base_type) {
        case 0: strcpy(info->ext, ".json"); break;
        case 1: strcpy(info->ext, ".xml"); break;
        case 2: strcpy(info->ext, ".html"); break;
    }

    info->dir = strdup(input); // Preserve original directory for checking existence and creation

    DIR *d = opendir(info->dir);
    if (d == NULL) {
        free(info->base);
        free(info->ext);
        free(info->dir);
        return -1; // Directory not found
    }

    closedir(d);

    struct stat st;
    if (stat(info->dir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        free(info->base);
        free(info->ext);
        free(info->dir);
        return -1; // Directory is not a valid directory or cannot be accessed
    }

    struct stat link_st;
    if (lstat(info->dir, &link_st) == 0 && S_ISLNK(link_st.st_mode)) {
        free(info->base);
        free(info->ext);
        free(info->dir);
        return -1; // Directory is a symbolic link loop
    }

    char fullpath[256];
    snprintf(fullpath, 256, "%s/%s%s", info->dir, info->base, info->ext);
    if (access(fullpath, F_OK) == 0) { // File already exists
        int i = 1;
        char timestamp[24];
        snprintf(timestamp, sizeof(timestamp), "%04d%02d%02d_%02d%02d%02d",
                 localtime(&time(NULL))->tm_year + 1900,
                 localtime(&time(NULL))->tm_mon + 1,
                 localtime(&time(NULL))->tm_mday,
                 localtime(&time(NULL))->tm_hour,
                 localtime(&time(NULL))->tm_min,
                 localtime(&time(NULL))->tm_sec);
        char *counter = malloc(3);
        memset(counter, 0, 3);
        while (access(fullpath, F_OK) == 0) {
            sprintf(counter, "_%03d", ++i);
            strcat(fullpath, counter);
        }
        free(counter);
    }

    FILE *fp = fopen(fullpath, "w");
    if (fp == NULL) { // Permission denied or insufficient disk space
        free(info->base);
        free(info->ext);
        free(info->dir);
        return -1;
    }

    // Handle edge cases and optimizations here...

    fclose(fp);
    return 0;
}
