#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <boost/thread/mutex.hpp>

struct record { int value; };
using Records = std::vector<record>;
using TestsMap = std::map<std::string, Records>;

class TestSuite {
public:
    void executeTestSuite(const std::string& label, const auto& f, size_t maxConcurrentTests) {
        // Initialize and synchronize blueslip mocking library
        // ...

        boost::property_tree::ptree pt;
        read_json("config.yaml", pt);

        auto minValue = pt.get<int>("minValue");
        auto maxValue = pt.get<int>("maxValue");
        auto recordsPerTestInstance = pt.get<size_t>("recordsPerTestInstance");

        // Create a pool of test instances
        std::vector<std::pair<std::string, Records>> testPool;
        for (size_t i = 0; i < maxConcurrentTests; ++i) {
            Records records(recordsPerTestInstance);
            for (auto& record : records)
                record.value = random() % (maxValue - minValue + 1) + minValue;
            testPool.push_back({label + "_" + std::to_string(i), std::move(records)});
        }

        // Run the tests in parallel
        boost::asio::io_service ioService;
        std::vector<std::unique_ptr<boost::thread>> threads;
        {
            boost::mutex mtx;
            std::lock_guard<boost::mutex> lock(mtx);
            for (auto& [name, records] : testPool) {
                auto task = std::make_shared<std::packaged_task<void()>>([name, records, f]() {
                    // Reset blueslip mocking library
                    // ...
                    f(name, records);
                    // Log information to the console
                    // ...
                });
                std::unique_ptr<std::future<void>> future = task->get_future();
                threads.push_back(std::make_unique<boost::thread>([task, recordsPerTestInstance]() {
                    // Create a new set of records for this test instance
                    Records newRecords(recordsPerTestInstance);
                    for (auto& record : newRecords)
                        record.value = random() % (maxValue - minValue + 1) + minValue;

                    (*task)(newRecords);
                }));
            }
        }

        // Run the I/O service to execute all test tasks
        ioService.run();

        // Wait for all threads to complete
        for (auto& thread : threads)
            thread->join();
    }
};
```

