import java.util.Random;
import java.io.*;

class Record {
    int value;

    public Record(int value) {
        this.value = value;
    }
}

public static Record[] createRecordArray(int size, int min, int max) {
    Random random = new Random();
    Record[] arr = new Record[size];

    for (int i = 0; i < size; ++i) {
        arr[i] = new Record(min + random.nextInt((max - min)));
    }

    return arr;
}
