typedef struct config_entry {
    const char *key;
    json_t *value;
} config_entry;

typedef struct {
    pthread_mutex_t mutex;
    int num_keys;
    size_t capacity;
    config_entry *entries;
} config_library;

config_library *config_lib_create() {
    config_library *lib = malloc(sizeof(config_library));
    pthread_mutex_init(&lib->mutex, NULL);
    lib->num_keys = 0;
    lib->capacity = 16;
    lib->entries = calloc(lib->capacity, sizeof(config_entry));
    return lib;
}

void config_lib_destroy(config_library *lib) {
    for (size_t i = 0; i < lib->num_keys; ++i) {
        json_decref(lib->entries[i].value);
    }
    free(lib->entries);
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}

int config_lib_load_file(config_library *lib, const char *filename) {
    json_t *root = json_load_file(filename);
    if (!root) {
        perror("Error loading file");
        return -1;
    }

    pthread_mutex_lock(&lib->mutex);
    size_t old_capacity = lib->capacity;
    size_t len = json_array_size(root);
    if (len > old_capacity) {
        lib->capacity *= 2;
        config_entry *new_entries = realloc(lib->entries, lib->capacity * sizeof(config_entry));
        if (!new_entries) {
            json_decref(root);
            pthread_mutex_unlock(&lib->mutex);
            return -1;
        }
        lib->entries = new_entries;
    }

    json_t *current_values = NULL;
    for (size_t i = 0; i < len; ++i) {
        json_t *item = json_array_get(root, i);
        const char *key = json_object_get_string(json_object_get(item, "key"));
        if (!key) continue;

        json_t *value = json_object_get(item, "value");
        bool has_conflict = false;
        for (size_t j = 0; j < lib->num_keys; ++j) {
            if (strcmp(lib->entries[j].key, key) == 0) {
                has_conflict = true;
                json_t *old_value = lib->entries[j].value;

                // Merge values and handle conflicts.
                // ...

                json_decref(lib->entries[j].value);
                lib->entries[j].value = json_merge(value, old_value);
                break;
            }
        }

        if (!has_conflict) {
            config_entry new_entry = {key, value};
            lib->entries[lib->num_keys] = new_entry;
            ++lib->num_keys;
        }
    }

    json_decref(root);
    pthread_mutex_unlock(&lib->mutex);

    return lib->num_keys - old_capacity;
}

int config_lib_total_keys(const config_library *lib) {
    return lib->num_keys;
}

json_t *config_lib_get_value(const config_library *lib, const char *key) {
    for (size_t i = 0; i < lib->num_keys; ++i) {
        if (strcmp(lib->entries[i].key, key) == 0) {
            return lib->entries[i].value;
        }
    }
    return json_null();
}
