#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t mutex;
} Node;

static unsigned long total_elements = 0;
static unsigned long failed_insertions = 0;

Node* head = NULL;
unsigned int capacity = 10000;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    if (head == NULL) {
        head = malloc(capacity * sizeof(Node));
        for (unsigned int i = 0; i < capacity; ++i) {
            head[i].next = (i + 1 < capacity) ? &head[i + 1] : NULL;
            pthread_mutex_init(&head[i].mutex, NULL);
        }
    }
}

void resize_list() {
    unsigned int new_capacity = capacity * 2;
    Node* temp_head = head;
    head = malloc(new_capacity * sizeof(Node));
    for (unsigned int i = 0; i < capacity; ++i) {
        if (temp_head[i].next != NULL) {
            head[i] = temp_head[i];
        }
        head[i].next = (i + 1 < new_capacity) ? &head[i + 1] : NULL;
        pthread_mutex_init(&head[i].mutex, NULL);
    }
    free(temp_head);
    capacity = new_capacity;
}

bool unique_RNTI(uint32_t RNTI) {
    Node* current = head;
    for (; current != NULL; current = current->next) {
        if (current->data.RNTI == RNTI) {
            return false;
        }
    }
    return true;
}

void insert_element(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list_mutex);

    if (unique_RNTI(data.RNTI)) {
        Node* current = head;
        Node* new_node = malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = NULL;
        pthread_mutex_init(&new_node->mutex, NULL);

        if (head == NULL) {
            head = new_node;
        } else if (current->next == NULL) {
            current->next = new_node;
        } else {
            Node* last = current;
            for (; (current = current->next) != NULL; ) {
                if (!current->next) {
                    last->next = new_node;
                    break;
                }
            }
        }

        total_elements++;
        pthread_mutex_unlock(&list_mutex);
    } else {
        failed_insertions++;
        pthread_mutex_unlock(&list_mutex);
    }
}
```
This code provides a basic dynamic list implementation in C that manages NFAPI_CRC_INDICATION_PDU_T structures. The list is resizable, and it ensures uniqueness for each RNTI before insertion, utilizing pthread_mutex_lock to handle concurrent access safely in a multi-threaded environment. It also keeps track of total elements inserted and maintains a counter for failed insertions due to duplicate RNTIs.']

