record* create_record_array() {
    record *records = malloc(max_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 1000000;
        records[i].creation_ts = time(NULL);
        records[i].last_accessed_ts = records[i].creation_ts;
    }

    return records;
}

void resize_record_array(size_t new_size) {
    if (new_size > max_records * 2 || num_records + new_size > max_records * 2) {
        log_event("Memory limit exceeded");
        return;
    }

    record *old_records = NULL;
    posix_memalign(restrict &old_records, 64, max_records * sizeof(record)); // Align to 64-byte boundary for better cache efficiency.
    if (!old_records) {
        perror("Failed to allocate aligned memory");
        free(records);
        return;
    }

    memcpy(old_records, records, num_records * sizeof(record));
    free(records);

    records = old_records;
    max_records = new_size;
}

void update_record(record *record, int value) {
    pthread_mutex_lock(&mutex);

    record->value = value;
    record->last_accessed_ts = time(NULL);

    pthread_mutex_unlock(&mutex);
}

