        (*pdu_list)[i].RX_UE_INFORMATION_TAG = i + 1000;
        (*pdu_list)[i].RNTI = (uint32_t)(i * 100);

        for (int j = 0; j < 4; ++j) {
            (*pdu_list)[i].CRC_INDICATION_REL8_TAG[j] = rand() & 0xFF;
        }
    }

