    const EVP_CIPHER *cipher;
    const char* cipher_name[] = {"DES-ECB", "DES-EDE", "DES-EDE3", "DES-CFB"};
    for (size_t i = 0; i < ARRAY_SIZE(cipher_name); ++i) {
        if ((cipher = EVP_get_cipherbyname(cipher_name[i])) == NULL) continue;

        int rc = EVP_CIPHER_CTX_set_cipher(*ctx, cipher);
