#define MAX(a, b) (((a) > (b)) ? (a) : (b))

int validate_input(size_t n, size_t max_entries, const char* variable) {
    if (!n || n > max_entries) {
        fprintf(stderr, "Error: Invalid input for %s. Must be between 1 and %zu\n", variable, max_entries);
        return -1;
    }
    return 0;
}

// Function to create the list of NFAPI_CRC_INDICATION_PDU_T structures
gsl_hash_table *create_list(size_t n) {
    if (validate_input(n, 10000, "number of entries") < 0) return NULL;

    gsl_hash_table *ht = gsl_hash_table_alloc(_gsl_hash_table_default, n);

    // Set up the random number generator with a fixed seed for reproducibility
    unsigned long seed = 123456789;
    gsl_rng *rng = gsl_rng_alloc(gsl_rng_mt19937);
    gsl_rng_set(rng, seed);

    nfapi_crc_indication_pdu_t* data;
    size_t entries = 0;

    while (entries < n && gsl_hash_table_size(ht) <= 10000) {
        data = malloc(sizeof(nfapi_crc_indication_pdu_t));
        if (!data) break;

        data->rx_ue_information_tag = rand() % UINT32_MAX;
        data->rnti = rand() % UINT16_MAX;
        data->crc_indication_rel8_tag = rand() % UINT16_MAX;
        data->crcflag = rand() % 2 == 0;

        if (!gsl_hash_table_insert(ht, (void*)data->rnti, data)) break;
        entries++;
    }

    gsl_rng_free(rng);

    // Ensure memory usage doesn't exceed 1 MB
    size_t memory_usage = sizeof(gsl_hash_table) + entries * sizeof(nfapi_crc_indication_pdu_t);
    if (memory_usage > (1024*1024)) {
        fprintf(stderr, "Error: Total memory usage exceeds 1 MB\n");
        destroy_list(ht);
        return NULL;
    }

    return ht;
}

// Function to destroy the list and free allocated memory
void destroy_list(gsl_hash_table *ht) {
    gsl_hash_table_iterator i;
    gsl_hash_table_iterate (ht, &i, NULL) {
        free(i.data);
    }
    gsl_hash_table_free(ht);
}
