#define ALIGN(x, a) (((x) + (a)-1) & ~((a)-1))
#define MAX_KEYS 1000000
#define KEY_RANGE 1000
#define RECORD_COUNT 1000000
#define MAX_KEY_SUM 100000000

typedef struct {
    long offset;
    int key;
} Record;

void *my_malloc(size_t size, size_t alignment) {
    void* ptr = malloc(ALIGN(size, alignment));
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void *ptr, size_t size, size_t alignment) {
    free(ptr);
}

int is_key_valid(int key) {
    if (key < 0 || key >= KEY_RANGE)
        return 0;
    return 1;
}

int hash_function(int key) {
    return key % MAX_KEYS;
}

int* keys = NULL;
pthread_mutex_t keys_mutex;

int find_empty_key() {
    pthread_mutex_lock(&keys_mutex);
    int i;
    for (i = 0; i < MAX_KEYS; ++i) {
        if (!keys[i]) {
            pthread_mutex_unlock(&keys_mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&keys_mutex);

    // Handle collision here (e.g., resize hash table, linear probing, etc.)
    return -1;
}

Record* records = NULL;
pthread_mutex_t records_mutex;

int check_key_sum(void) {
    int sum = 0;
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < RECORD_COUNT; ++i) {
        sum += records[i].key;
    }
    pthread_mutex_unlock(&records_mutex);

    if (sum > MAX_KEY_SUM)
        return 0;

    return 1;
}

int find_empty_record() {
    pthread_mutex_lock(&records_mutex);
    int i;
    for (i = 0; i < RECORD_COUNT; ++i) {
        if (!records[i].key) {
            pthread_mutex_unlock(&records_mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&records_mutex);

    // Handle potential memory reallocation here
    return -1;
}

void init() {
    keys = (int*)my_malloc(MAX_KEYS * sizeof(int), 64);
    records = (Record*)my_malloc((RECORD_COUNT+63) & ~63, 64); // Cache line aligned allocation
    srand(time(NULL));

    pthread_mutex_init(&keys_mutex, NULL);
    pthread_mutex_init(&records_mutex, NULL);
}

Record* create_pipeline() {
    if (!init())
        return NULL;

    for (int i = 0; i < RECORD_COUNT; ++i) {
        int key = rand() % KEY_RANGE;
        while (!is_key_valid(key))
            key = rand() % KEY_RANGE;
        if (find_empty_key() == -1 || !check_key_sum()) {
            // Handle potential memory reallocation here
            return NULL;
        }
        keys[find_empty_key()] = key;
    }

    int index;
    for (int i = 0; i < RECORD_COUNT; ++i) {
        index = find_empty_record();
        if (index == -1)
            return NULL;
        records[index].key = keys[i];
        records[index].offset = i * 64; // Aligning offset to cache line
    }

    return records;
}
