// Define a priority queue node and compare function
typedef struct InterfaceConfigPriorityQueueNode {
    InterfaceConfig config;
    int priority; // Priority based on network congestion and user-defined policies
} InterfaceConfigPriorityQueueNode;

bool interface_config_compare(const void* a, const void* b) {
    const InterfaceConfigPriorityQueueNode* na = a;
    const InterfaceConfigPriorityQueueNode* nb = b;
    return na->priority < nb->priority;
}

void init_interface_config_priority_queue(PQ* queue) {
    pq_init(queue, interface_config_compare);
}

void enqueue_interface_config(PQ* queue, InterfaceConfig config, int priority) {
    InterfaceConfigPriorityQueueNode node = { config, priority };
    pq_push(queue, &node);
}

InterfaceConfig dequeue_interface_config(PQ* queue) {
    if (pq_empty(queue)) {
        // Handle error: empty queue
        return (InterfaceConfig){0};
    }

    InterfaceConfigPriorityQueueNode node = pq_pop(queue);
    return node.config;
}
