} CacheEntry;

typedef struct {
    CacheEntry **cache;
    size_t capacity;
    size_t size;
} LRUCache;

LRUCache *create_lru_cache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->cache = calloc(capacity, sizeof(CacheEntry*));
    return cache;
}

void lru_cache_insert(LRUCache *cache, int key, void *value) {
    size_t index = key % cache->capacity;

    if (cache->cache[index] != NULL) {
        CacheEntry **previous = &cache->cache[index];

        while (*previous != NULL && (*previous)->key != key) {
            previous = &((*previous)->next);
        }

        if (*previous != NULL) {
            CacheEntry *entry = *previous;
            entry->value = value;
            entry->key = key;
            return;
        }
    }

    size_t i;
    for (i = index + 1; i < cache->capacity; ++i) {
        if (cache->cache[i] == NULL) {
            cache->cache[index]->next = malloc(sizeof(CacheEntry*));
            cache->cache[index]->next[0] = value;
            cache->cache[index]->key = key;
            cache->size++;
            return;
        }
    }

    for (i = 0; i <= index; ++i) {
        if (cache->cache[i] == NULL) {
            cache->cache[i] = malloc(sizeof(CacheEntry*));
            cache->cache[i][0] = value;
            cache->cache[i]->key = key;
            cache->size++;
            return;
        }
    }
}

void *lru_cache_get(LRUCache *cache, int key) {
    size_t index = key % cache->capacity;

    if (cache->cache[index] != NULL) {
        CacheEntry **current = &cache->cache[index];

        while (*current != NULL && (*current)->key != key) {
            current = &((*current)->next);
        }

        if (*current != NULL) {
            void *value = (*current)->value;
            CacheEntry *entry = *current;

            *current = entry->next[0];
            if (entry->next != NULL) {
                entry->next[0] = cache->cache[index]->next[0];
                cache->cache[index]->next = entry->next;
            } else {
                cache->cache[index] = NULL;
            }

            return value;
        }
    }

    return NULL;
}

void lru_cache_destroy(LRUCache *cache) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->cache[i] != NULL) {
            CacheEntry *entry = cache->cache[i];

            while (entry != NULL) {
                CacheEntry *next = entry->next[0];
                free(entry);
                entry = next;
            }
        }
    }

    free(cache->cache);
    free(cache);
}

