['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <math.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

typedef struct HashNode {
    Record data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    unsigned long size;
    HashNode** table;
    pthread_mutex_t lock;
} HashTable;

unsigned long hashFunction(unsigned long key) {
    return key % (1 << 20); // Use a power of 2 for fast bitwise operations.
}

HashTable* createHashTable(unsigned long size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->size = size;
    table->table = calloc(size, sizeof(HashNode*));
    table->lock = PTHREAD_MUTEX_INITIALIZER;
    return table;
}

void insertRecord(HashTable* table, Record record) {
    pthread_mutex_lock(&table->lock);

    unsigned long hash = hashFunction(record.key);
    HashNode** slot = &table->table[hash];
    HashNode* current = *slot;

    while (current != NULL) {
        if (current->data.key == record.key) {
            current->data = record;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        current = current->next;
    }

    HashNode* newNode = malloc(sizeof(HashNode));
    newNode->data = record;
    newNode->next = *slot;
    *slot = newNode;

    pthread_mutex_unlock(&table->lock);
}

Record findRecord(HashTable* table, int key) {
    unsigned long hash = hashFunction(key);
    HashNode** slot = &table->table[hash];
    HashNode* current = *slot;

    while (current != NULL) {
        if (current->data.key == key)
            return current->data;
        current = current->next;
    }

    return (Record){0};
}

void compactAndRehash(HashTable* table, unsigned long newSize) {
    pthread_mutex_lock(&table->lock);

    HashTable* newTable = createHashTable(newSize);
    for (unsigned long i = 0; i < table->size; ++i) {
        HashNode* current = table->table[i];
        while (current != NULL) {
            Record data = current->data;
            unsigned long hash = hashFunction(data.key);
            HashNode** slot = &newTable->table[hash];
            HashNode* newSlot = *slot;

            if (!newSlot) {
                *slot = current;
                current = current->next;
            } else {
                while (newSlot->next != NULL)
                    newSlot = newSlot->next;

                newSlot->next = current;
                current = current->next;
            }
        }
    }

    free(table->table);
    table->size = newSize;
    table->table = newTable->table;

    pthread_mutex_unlock(&newTable->lock);
}

// Implement thread-safe concurrent updates and periodic compaction/rehashing.
