```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} Metadata;

typedef struct {
    char* str;
    time_t timestamp;
} Record;

void free_record(Record* record) {
    if (record->str) free(record->str);
    free(record);
}

void fail(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}

Metadata* create_metadata() {
    Metadata* metadata = malloc(sizeof(Metadata));
    if (!metadata) fail("Out of memory");
    memset(metadata, 0, sizeof(Metadata));
    return metadata;
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) fail("Out of memory");
    record->str = NULL;
    record->timestamp = time(NULL);
    return record;
}

void extend_records(Metadata** metadata, int* size, int count) {
    if (*size >= *count) {
        Metadata* tmp = realloc(*metadata, sizeof(Metadata) * (*count + 10));
        if (!tmp) fail("Out of memory");
        *metadata = tmp;
    }
}

void extend_records_and_copy(Record** records, int* size, int count) {
    if (*size >= *count) {
        Record* tmp = realloc(*records, sizeof(Record) * (*count + 10));
        if (!tmp) fail("Out of memory");
        memcpy(tmp, *records, sizeof(Record) * *count);
        free(*records);
        *records = tmp;
    }
}

void add_record(Metadata** metadata, Record** records, int* size, char* str, int max_size) {
    if (strlen(str) > max_size) fail("String too large");

    Metadata* current = *metadata;
    extend_records(metadata, size, *size + 1);

    while (current->offset < *size) current = &(*metadata)[current->offset + 1];
    current->key = *size++;

    extend_records_and_copy(records, size, *size);
    records[current->key]->str = strdup(str);
}

void update_record(Metadata** metadata, Record** records, int* size, char* str, int max_size, int key) {
    if (strlen(str) > max_size) fail("String too large");

    Metadata* current = *metadata;
    while (current->key != key) current = &(*metadata)[current->offset + 1];

    free_record(&records[key]);
    records[key] = create_record();
    records[key]->str = strdup(str);
}

void initialize_storage(Metadata** metadata, Record** records, int* size, int count) {
    *metadata = calloc(1, sizeof(Metadata));
    if (!*metadata) fail("Out of memory");
    (*metadata)->offset = -1;

    *records = malloc(sizeof(Record) * count);
    if (!*records) fail("Out of memory");
}

void free_storage(Metadata** metadata, Record** records, int size) {
    for (int i = 0; i < size; ++i) free_record(&records[i]);
    free(*metadata);
    free(*records);
}
