typedef struct {
    uint32_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} NODE;

NODE* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Error: Out of memory");
        exit(1);
    }
    return (NODE*)ptr;
}

void free_node(NODE *node) {
    free(node);
}

NODE* create_node(uint32_t rnti, uint8_t crcflag) {
    NODE *new_node = custom_malloc(sizeof(NODE));
    new_node->data.rnti = rnti;
    new_node->data.crcflag = crcflag;
    new_node->next = NULL;
    return new_node;
}

void insert_node(NODE** head, NODE* node) {
    if (!*head) {
        *head = node;
        return;
    }
    node->next = *head;
    *head = node;
}

void find_and_print_largest_rnti(NODE** head) {
    uint32_t largest_rnti = 0;
    NODE* current = *head;

    while (current != NULL) {
        if (current->data.rnti > largest_rnti)
            largest_rnti = current->data.rnti;
        current = current->next;
    }

    printf("Largest RNTI: %u\n", largest_rnti);
}

void validate_list(NODE** head) {
    NODE* current = *head;

    while (current != NULL && current->next != NULL) {
        current = current->next;
    }

    if (current != NULL && current->next == NULL)
        return; // List is valid

    fprintf(stderr, "Error: Dangling pointer detected\n");
    exit(1);
}

void log_operation(const char* operation) {
    FILE *logfile = fopen("system_log.txt", "a");
    if (logfile == NULL) {
        perror("Error: Could not open log file for writing");
        exit(1);
    }

    fprintf(logfile, "%s\n", operation);
    fclose(logfile);
}

int main() {
    const int max_structures = 1024;
    NODE* head = NULL;
    int buffer[max_structures];
    int n = 0, rnti, i;

    printf("Enter RNTI values (Ctrl+D to exit):\n");

    while ((scanf("%d", &rnti) == 1 && n < max_structures)) {
        buffer[n] = rnti;
        n++;
        log_operation(("Read RNTI: %d").c_str());
    }

    for (i = 0; i < n; i++) {
        NODE* new_node = create_node(buffer[i], rand()%2);
        insert_node(&head, new_node);
        log_operation(("Inserted RNTI: %d, CRCFLAG: %d").c_str(), buffer[i], new_node->data.crcflag);
    }

    find_and_print_largest_rnti(&head);
    validate_list(&head);

    while (head != NULL) {
        NODE *temp = head;
        head = head->next;
        free_node(temp);
        log_operation("Freed memory");
    }

    return 0;
}
