struct line_data {
    char buffer[4096];
    size_t pos;
};

typedef struct line_data LineData;

struct nfapi_rlc_pdu_dynamic_array {
    NFAPI_RLC_PDU_T** data;
    size_t capacity;
    size_t size;
    sem_t lock;
};

NFAPI_RLC_PDU_DynamicArray* nfapi_rlc_pdu_dynamic_array_create(size_t initial_capacity) {
    NFAPI_RLC_PDU_DynamicArray* array = malloc(sizeof(NFAPI_RLC_PDU_DynamicArray));
    if (!array) {
        log_error("Failed to allocate memory for dynamic array");
        return NULL;
    }
    sem_init(&array->lock, 0, 1);
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = calloc(initial_capacity, sizeof(NFAPI_RLC_PDU_T*));
    if (!array->data) {
        log_error("Failed to allocate memory for dynamic array data");
        free(array);
        return NULL;
    }
    return array;
}

void nfapi_rlc_pdu_dynamic_array_destroy(NFAPI_RLC_PDU_DynamicArray* array) {
    if (array->data) {
        for (size_t i = 0; i < array->capacity; ++i) {
            free(array->data[i]);
        }
        free(array->data);
    }
    sem_destroy(&array->lock);
    free(array);
}

static void process_line(LineData* data, NFAPI_RLC_PDU_DynamicArray* array) {
    NFAPI_RLC_PDU_T* pdu = malloc(sizeof(NFAPI_RLC_PDU_T));
    if (!pdu) {
        log_error("Failed to allocate memory for new RLC PDU");
        return;
    }

    // Read and validate RX_UE_INFORMATION_TAG, RNTI, and RLC_STATUS_INFO fields.
    // Assume functions for reading and validation are provided (e.g., get_field)

    if (!validate_rnti(get_field(data->buffer + data->pos, "RNTI")) ||
        !validate_rlc_status_info(get_field(data->buffer + data->pos, "RLC_STATUS_INFO"))) {
        free(pdu);
        return;
    }

    // Fill the structure with the validated values and increment the array size
    set_rx_ue_information_tag(pdu, get_field(data->buffer + data->pos, "RX_UE_INFORMATION_TAG"));
    set_rnti(pdu, get_field(data->buffer + data->pos, "RNTI"));
    set_rlc_status_info(pdu, get_field(data->buffer + data->pos, "RLC_STATUS_INFO"));

    sem_wait(&array->lock);
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        NFAPI_RLC_PDU_T** temp = realloc(array->data, array->capacity * sizeof(NFAPI_RLC_PDU_T*));
        if (!temp) {
            log_error("Failed to resize dynamic array data");
            sem_post(&array->lock);
            free(pdu);
            return;
        }
        array->data = temp;
    }
    array->data[array->size] = pdu;
    array->size++;
    sem_post(&array->lock);
}

void* read_csv_and_populate(const char* filename, NFAPI_RLC_PDU_DynamicArray* array) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open CSV file");
        return NULL;
    }

    LineData data = { 0 };
    size_t line_size;
    char line[4096];

    while ((line_size = getline(&data.buffer[data.pos], sizeof(data.buffer) - data.pos, file)) != -1) {
        data.pos += line_size;
        process_line(&data, array);
        data.pos = 0;
    }

    fclose(file);
    return NULL;
}
