#include <stdio.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

#define MAX_KEYS 100000
#define MAX_OFFSET (64 * 1024 * 1024) // Max offset of 1GB aligned to 64-byte cache lines
#define MEMORY_BUDGET (1024 * 1024 * 1024) // Memory budget of 1GB
#define KEY_RANGE 1000

typedef struct {
    long offset;
    int key;
} Record;

typedef struct HashNode {
    int key;
    struct HashNode *next;
} HashNode;

struct ProcessPipeline {
    HashTable hash_table; // Hash table implementation
    Record* records; // Array of Records
    size_t record_count; // Number of records in the array
    pthread_mutex_t mutex; // Mutex for synchronization
};

// Custom error handling mechanism
enum Error {
    NO_ERROR = 0,
    MEMORY_ALLOCATION_FAILURE,
    HASH_TABLE_FULL,
    KEY_OUT_OF_RANGE,
    DNS_RESOLUTION_FAILURE
};

Error dns_resolution(const char* hostname, char** ip);

// Function to create and initialize a new ProcessPipeline instance
ProcessPipeline* create_process_pipeline(void) {
    ProcessPipeline *pipeline = malloc(sizeof(ProcessPipeline));
    if (!pipeline) return NULL;

    pipeline->records = mmap(NULL, MEMORY_BUDGET, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pipeline->records == MAP_FAILED) {
        free(pipeline);
        return NULL;
    }

    pipeline->record_count = 0;
    pipeline->hash_table = create_hash_table();
    pthread_mutex_init(&pipeline->mutex, NULL);

    return pipeline;
}

// Function to dynamically allocate and initialize a new Record within the process pipeline
Record* allocate_record(ProcessPipeline *pipeline) {
    if (pipeline->record_count + 1 > MEMORY_BUDGET / sizeof(Record))
        return NULL;

    Record* record = (Record*)((char*)pipeline->records + pipeline->record_count * sizeof(Record));
    pipeline->record_count++;
    return record;
}

// Function to insert a key-value pair into the hash table, ensuring uniqueness and fast lookups
Error insert_key(ProcessPipeline *pipeline, int key) {
    HashNode *node = malloc(sizeof(HashNode));
    if (!node) return MEMORY_ALLOCATION_FAILURE;

    node->key = key;

    pthread_mutex_lock(&pipeline->mutex);
    HashNode* current = pipeline->hash_table.head;
    while (current != NULL && current->key <= key) {
        if (current->key == key) {
            free(node);
            pthread_mutex_unlock(&pipeline->mutex);
            return HASH_TABLE_FULL;
        }
        current = current->next;
    }

    node->next = pipeline->hash_table.head;
    pipeline->hash_table.head = node;
    pthread_mutex_unlock(&pipeline->mutex);

    return NO_ERROR;
}

// Function to perform DNS resolution for a given hostname
struct ProcessPipeline* create_and_init_dns_pipeline(const char *hostname) {
    ProcessPipeline* pipeline = create_process_pipeline();
    if (!pipeline) return NULL;

    char ip[INET6_ADDRSTRLEN];
    Error error = dns_resolution(hostname, &ip);
    if (error != NO_ERROR) {
        destroy_process_pipeline(pipeline);
        return NULL;
    }

    // Insert the resolved IP into the pipeline as a key and offset value.
    // Optimize offset values to fit within 64-byte cache lines for optimal performance.

    Record* record = allocate_record(pipeline);
    if (!record) {
        destroy_process_pipeline(pipeline);
        return NULL;
    }

    error = insert_key(pipeline, atoi(ip));
    if (error != NO_ERROR) {
        destroy_process_pipeline(pipeline);
        return NULL;
    }

    record->offset = (long)(((uintptr_t)record - (uintptr_t)pipeline->records) / sizeof(Record)) << 6;

    return pipeline;
}
