#define RANDOM_SEED 123456789

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Helper function to read a list of integers from standard input
void read_and_print_largest(int* arr, int n) {
    if (n <= 0 || arr == NULL) return;
    int max = arr[0];
    for (int i = 1; i < n; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    printf("Largest integer: %d\n", max);
}

// Function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_PDUs(int n) {
    if (n <= 0 || n > ARRAY_SIZE_LIMIT) {
        printf("Invalid array size!\n");
        return NULL;
    }
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        printf("Memory allocation failed!\n");
        pthread_mutex_destroy(&lock);
        return NULL;
    }
    size_t memory_used = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    while (memory_used > MAX_MEMORY) {
        free(data);
        data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(data, n - 1);
        --n;
        memory_used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    pthread_mutex_destroy(&lock);
    return data;
}

// Helper function to generate a random integer within a specified range
int rand_within(int min, int max) {
    if (min >= max) return min;
    return rand() % (max - min + 1) + min;
}

// Function to initialize each PDU structure in the list with valid data
void init_PDUs(NFAPI_CRC_INDICATION_PDU_T* data, int n) {
    if (!data || n <= 0) return;
    for (int i = 0; i < n; ++i) {
        data[i].tag.value = RX_UE_INFORMATION_TAG_RNTI;
        data[i].rnti = rand() % 65535 + 1;
        data[i].crc_indication.crcFlag = rand_within(0, 1);
    }
