import java.io.File;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class BatchProcessor {
    private static final int NUM_RECORDS = 100000;
    private static final int MIN_KEY = 1;
    private static final int MAX_KEY = 100;
    private static final int MIN_OFFSET = 1000;
    private static final int MAX_OFFSET = 2000;
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public static void main(String[] args) {
        long[] offsets = new long[NUM_RECORDS];
        int[] keys = new int[NUM_RECORDS];
        Record[] records = new Record[NUM_RECORDS];

        Random random = new Random();
        for (int i = 0; i < NUM_RECORDS; i++) {
            offsets[i] = MIN_OFFSET + random.nextInt(MAX_OFFSET - MIN_OFFSET);
            keys[i] = MIN_KEY + random.nextInt(MAX_KEY - MIN_KEY);
            records[i] = new Record();
        }

        for (int i = 0; i < NUM_RECORDS; i++) {
            records[i].value = MIN_KEY + random.nextInt(MAX_KEY - MIN_KEY);
        }

        File[] tempFiles = new File[NUM_RECORDS];
        for (int i = 0; i < NUM_RECORDS; i++) {
            tempFiles[i] = File.createTempFile("temp", null);
        }

        for (int i = 0; i < NUM_RECORDS; i++) {
            if (tempFiles[i].exists()) {
                tempFiles[i].delete();
            }
        }

        int[] exitCodes = new int[NUM_RECORDS];

        for (int i = 0; i < NUM_RECORDS; i++) {
            ProcessBuilder pb = new ProcessBuilder(String.format("process-command %d %d %s", keys[i], offsets[i], tempFiles[i].getAbsolutePath()));
            try {
                Process process = pb.start();
                exitCodes[i] = process.waitFor();
            } catch (Exception e) {
                System.err.println("Error executing subprocess: " + e.getMessage());
            }
        }

        for (int i = 0; i < NUM_RECORDS; i++) {
            if (tempFiles[i].exists()) {
                tempFiles[i].delete();
            }
        }

        executor.shutdownNow();

        // Logging implementation can be added here

        System.out.println("Exited with codes: " + String.join(", ", Integer.toString(exitCodes)));
    }
}

class Record {
    int value;
