    public class RequestHandler
    {
        private readonly HttpClient _httpClient;
        private readonly IMemoryCache _cache;
        private readonly ILogger<RequestHandler> _logger;
        private readonly HashSet<string> _allowedSections;
        private readonly HashSet<string> _allowedElements;

        public RequestHandler(HttpClient httpClient, IMemoryCache cache, ILogger<RequestHandler> logger, HashSet<string> allowedSections, HashSet<string> allowedElements)
        {
            _httpClient = httpClient;
            _cache = cache;
            _logger = logger;
            _allowedSections = allowedSections;
            _allowedElements = allowedElements;
        }

        public async Task UpdateContentAsync(string sectionId, string elementId, string content)
        {
            if (!_allowedSections.Contains(sectionId) || !_allowedElements.Contains(elementId))
            {
                _logger.LogWarning("Unauthorized update attempt: {SectionId}:{ElementId}", sectionId, elementId);
                return;
            }

            var cacheKey = $"update:{sectionId}:{elementId}";

            if (_cache.TryGetValue(cacheKey, out object cachedResponse))
            {
                _logger.LogInformation("Retrieved cached update response for {SectionId}:{ElementId}", sectionId, elementId);
                return;
            }

            var requestData = new
            {
                SectionId = sectionId,
                ElementId = elementId,
                Content = content
            };

            using (var response = await _httpClient.PostAsJsonAsync($"api/updates", requestData))
            {
                if (response.IsSuccessStatusCode)
                {
                    var responseContent = await response.Content.ReadFromJsonAsync<bool>();

                    if (responseContent)
                    {
                        _cache.Set(cacheKey, true, new MemoryCacheEntryOptions()
                            .SetAbsoluteExpiration(TimeSpan.FromMinutes(5)));
                    }
                    else
                    {
                        _logger.LogError("Update failed for {SectionId}:{ElementId}", sectionId, elementId);
                    }
                }
                else
                {
                    _logger.LogError("Request failed for {SectionId}:{ElementId}:{StatusCode}", sectionId, elementId, response.StatusCode);
                }
            }
        }
    }
}
