struct hash_table {
    unsigned long *offsets;
    int *keys;
    record **records;
    int size;
};

void hash_init(struct hash_table *ht, int size) {
    ht->offsets = calloc(size, sizeof(unsigned long));
    ht->keys = calloc(size, sizeof(int));
    ht->records = calloc(size, sizeof(record*));
    ht->size = size;
}

unsigned long hash_func(char *key, int table_size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = (hash << 5) + hash + c; /* hash * 33 + c */

    return hash % table_size;
}

void hash_insert(struct hash_table *ht, char *key, int value) {
    unsigned long h = hash_func(key, ht->size);

    while (ht->keys[h] != 0 && strcmp(ht->records[h]->filename, key)) {
        if (++h == ht->size)
            h = 0;
    }

    ht->keys[h] = value;
    ht->records[h] = malloc(sizeof(record));
    strcpy(ht->records[h]->filename, key);
    (ht->records[h])->value = value;
    ht->offsets[value] = h;
}

int hash_search(struct hash_table *ht, char *key) {
    unsigned long h = hash_func(key, ht->size);

    while (ht->keys[h]) {
        if (!strcmp(ht->records[h]->filename, key)) {
            return ht->offsets[ht->keys[h]];
        }

        if (++h == ht->size)
            h = 0;
    }

    return -1;
}

