extern const int num_invalid_doubles[];
extern const int num_invalid_shorts[];
extern const double invalid_double_range_min;
extern const double invalid_double_range_max;

typedef struct {
    double d;
    short s;
    char c;
} DataPoint;

void init_datapoints(DataPoint** datapoints, size_t num, double min, double max, bool threshold) {
    *datapoints = mmap(NULL, sizeof(DataPoint) * num, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (*datapoints == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    size_t i;
    for (i = 0; i < num; ++i) {
        DataPoint* dp = (*datapoints + i);

        // Set double field with random value within specified range
        dp->d = min + (rand() / (RAND_MAX / (max - min)) * (max - min));

        // Validate the double value and adjust accordingly
        if (binary_search(num_invalid_doubles, sizeof(num_invalid_doubles) / sizeof(int), dp->d) ||
            (dp->d < invalid_double_range_min) || (dp->d > invalid_double_range_max)) {
            dp->d = min + ((rand() / (RAND_MAX / (max - min)) * (max - min));
        }

        // Set short field to unique sequential integers starting from zero
        dp->s = i;

        // Set char field based on double value exceeding threshold
        dp->c = (dp->d > threshold) ? 1 : 0;
    }
}

// Helper function for binary search in an array of integers
bool binary_search(const int arr[], size_t n, int val) {
    size_t left = 0;
    size_t right = n - 1;

    while (left <= right) {
        size_t mid = left + (right - left) / 2;

        if (arr[mid] < val)
            left = mid + 1;
        else if (arr[mid] > val)
            right = mid - 1;
        else
            return true; // Found the value, exit the loop
    }

    return false; // Value not found in the array
}
