struct NetworkStat {
    enum InterfaceType { WIRED, WIRELESS, CELLULAR };
    InterfaceType type;
    std::atomic<uint64_t> packetsReceived{0};
    // Add other statistics and error rates here...
};

class NetworkStatsManager {
private:
    std::deque<NetworkStat> stats;
    std::mutex mtx;
    size_t capacity;
    std::unordered_map<InterfaceType, size_t> typeCounts;
    std::atomic<uint64_t> totalPackets{0};
    uint64_t updateIntervalMs = 1000; // Update interval in milliseconds
    std::thread updateThread;

public:
    NetworkStatsManager(size_t initialCapacity) : capacity(initialCapacity), stats(capacity, NetworkStat()) {}

    void add(const NetworkStat& stat) {
        std::unique_lock<std::mutex> lock(mtx);
        if (stats.size() >= capacity) {
            stats.pop_front(); // Remove oldest entry to make room for new one
        }
        stats.push_back(stat);
        typeCounts[stat.type]++;
        lock.unlock();
        ++totalPackets;
    }

    void remove(const NetworkStat& stat) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(stats.begin(), stats.end(), [&stat](auto& s) { return s == stat; });
        if (it != stats.end()) {
            stats.erase(it);
            typeCounts[stat.type]--;
        }
        lock.unlock();
    }

    // Query API for accessing network statistics...

    void startUpdateThread() {
        if (!updateThread.joinable()) {
            updateThread = std::thread([this]() {
                while (true) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(updateIntervalMs));
                    // Update statistics here based on incoming data packets...
                }
            });
        }
    }
};
