#include <pthread.h>
#include <time.h>

typedef struct Record {
    int id;
    char* str;
} Record;

struct HashTable {
    unsigned long* offsets;
    int* keys;
    Record* records;
    unsigned long table_size;
    pthread_mutex_t mutex;
};

struct HashTable* create_hash_table(unsigned long capacity) {
    struct HashTable* table = malloc(sizeof(struct HashTable));
    if (!table) return NULL;

    table->offsets = calloc((capacity + 1), sizeof(unsigned long));
    if (!table->offsets) goto error;

    table->keys = calloc(capacity, sizeof(int));
    if (!table->keys) goto error;

    table->records = calloc(capacity, sizeof(Record));
    if (!table->records) goto error;

    table->table_size = capacity;
    pthread_mutex_init(&table->mutex, NULL);

    return table;
error:
    free_hash_table(table);
    return NULL;
}

void free_hash_table(struct HashTable* table) {
    if (!table) return;

    pthread_mutex_destroy(&table->mutex);
    free(table->offsets);
    free(table->keys);
    free(table->records);
    free(table);
}

unsigned long hash(struct HashTable* table, int key) {
    unsigned long a = 61;
    unsigned long b = 37;
    unsigned long h = 0;
    unsigned long key_length = sizeof(key) * CHAR_BIT;

    for (int i = 0; i < key_length; ++i) {
        h = (h * a + key & ((1 << key_length) - 1)) % table->table_size;
        a = b * a % table->table_size;
    }

    return h;
}

int find(struct HashTable* table, int key) {
    unsigned long offset = hash(table, key);

    for (unsigned long i = table->offsets[offset]; i < table->table_size; ++i) {
        if (table->keys[i] == key) return i;
    }

    return -1;
}

void insert(struct HashTable* table, int key, Record record) {
    unsigned long offset = hash(table, key);
    pthread_mutex_lock(&table->mutex);

    for (unsigned long i = table->offsets[offset]; i < table->table_size; ++i) {
        if (!table->keys[i]) {
            table->keys[i] = key;
            table->records[i] = record;
            table->offsets[offset] = i + 1;
            pthread_mutex_unlock(&table->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&table->mutex);
}

Record* lookup(struct HashTable* table, int key) {
    int index = find(table, key);
    if (index == -1) return NULL;

    return &table->records[index];
}
```

