} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _log_data {
    GMutex lock;
    GQueue queue;
} LogData;

void log_message(const char *message) {
    LogData *log = get_application_log_data();
    g_mutex_lock(&log->lock);
    g_queue_push_tail(log->queue, g_strdup(message));
    g_mutex_unlock(&log->lock);
}

void* log_thread(void *data) {
    LogData *log = data;
    while (true) {
        GList *link;
        g_mutex_lock(&log->lock);
        link = g_queue_pop_head(&log->queue);
        g_mutex_unlock(&log->lock);
        if (!link) break; // no more messages, exit loop
        printf("%s\n", (char*)link->data);
        g_free(link->data);
        g_list_free(link);
    }
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int ue_index) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->rx_ue_info.tag = RX_UE_INFORMATION_TAG{.value = ue_index};
    pdu->rnti = ue_index * 10 + rand() % 91 + 1;
    pdu->crc_indication.tag = CRC_INDICATION_REL8_TAG{.value = rand()};
    log_message(printf_s("Created PDU for UE %d with RNTI %d and CRCFLAG %x\n", ue_index, pdu->rnti, pdu->crc_indication.tag.value));
    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T** allocate_and_populate(int num_ues) {
    NFAPI_CRC_INDICATION_PDU_T **pdus = calloc(num_ues, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) return NULL;

    pthread_t log_thread_id;
    LogData log;
    g_mutex_init(&log.lock);
    g_queue_init(&log.queue);
    pthread_create(&log_thread_id, NULL, &log_thread, &log);

    for (int i = 0; i < num_ues; ++i) {
        pdus[i] = create_pdu(i);
        if (!pdus[i]) {
            log_message("Failed to allocate PDU for UE");
            // clean up and exit loop
            for (int j = i + 1; j < num_ues; ++j) free(pdus[j]);
            free(pdus);
            pthread_cancel(log_thread_id);
            pthread_join(log_thread_id, NULL);
            return NULL;
        }
    }

    log_message("Successfully allocated and populated PDUs for all UE instances");
    return pdus;
}
