#include <boost/container/flat_map.hpp> // For efficient key-based access
#include <boost/lockfree/slist.hpp> // For thread safety and performance
#include <boost/serialization/access.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/split_free.hpp>
#include <boost/serialization/unique_ptr.hpp>
#include <boost/algorithm/string/case_conv.hpp> // For case insensitivity
#include <memory> // For smart pointers
#include <mutex> // For synchronizing access to shared state
#include <vector>

struct Record {
    int key;
    long offset;
    mutable std::mt19937 rng; // Thread-local random number generator
    std::uniform_int_distribution<> dist; // Distribution for generating random values

    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive & ar, const unsigned int version) {
        ar & key & offset;
    }
};

// Implement caching strategy using a boost::container::flat_map for fast lookup
typedef std::unique_ptr<Record> RecordPtr;
boost::container::flat_map<int, RecordPtr> recordCache;

std::mutex cacheMutex; // For synchronizing access to the recordCache

class ThreadSafeForwardList {
public:
    void insert(long offset, int key, Record* record) {
        // Find the position where the new node should be inserted
        Node* pos = findNode(key);

        if (!pos) {
            // Key not found, insert at end
            pos = tail;
            if (pos == nullptr) {
                // Empty list, create a new head and tail
                tail.reset(new Node(nullptr, offset, record));
                head.reset(new Node(tail.get()));
            } else {
                // Non-empty list, insert at end
                pos->next.reset(new Node(record, offset));
                tail = pos->next.get();
            }
        } else {
            // Key found, insert after the current node
            pos->next.reset(new Node(record, offset));
        }
    }

private:
    struct Node {
        std::unique_ptr<Node> next;
        long offset;
        Record* record;

        friend class ThreadSafeForwardList;
        Node(Record* record, long offset) : record(record), offset(offset) {}
        Node(Node* prev) : next(nullptr), offset(0), record(nullptr) { if (prev) prev->next.reset(this); }
    };

    std::unique_ptr<Node> head, tail; // Head and tail pointers for the list

    Node* findNode(int key) const {
        // Use a mutex to synchronize access when querying recordCache
        std::lock_guard<std::mutex> lock(cacheMutex);

        auto it = recordCache.find(boost::to_upper_copied(key));
        if (it != recordCache.end()) {
            // Found in cache, return the cached node
            return it->second.get();
        } else {
            // Not found in cache, search the list and update the cache
            for (Node* node = head.get(); node; node = node->next.get()) {
                if (boost::to_upper_copied(node->record->key) == key) {
                    // Found in the list, add to cache and return the found node
                    RecordPtr cachedRecord(new Record(*node->record));
                    recordCache[key] = std::move(cachedRecord);
                    return node;
                }
            }
        }

        // Not found in either the list or the cache, return nullptr
        return nullptr;
    }
};
```

