    // Process the remaining file chunks in the worker function

    size_t remainingChunkSize = fileSize % minChunkSize == 0 ? minChunkSize : (fileSize % minChunkSize) + minChunkSize;
    while (remainingChunkSize > 0) {
        if (head == NULL) {
            Node* newNode = createNode(metadata);
            if (!newNode) {
                perror("malloc");
                free(metadata->filename);
                free(metadata);
                for (int i = 0; i < numThreads; ++i) {
                    pthread_join(threads[i], NULL);
                }
                return;
            }

            metadata->fileSize += minChunkSize;

            pthread_mutex_lock(&listLock);
            newNode->next = head;
            head = newNode;
            pthread_mutex_unlock(&listLock);
        }
    }

    // Wait for all threads to finish processing the file
    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(metadata->filename);
    free(metadata);
}
