['```csharp
using System;
using System.Buffers;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public struct Record { public int Value; public long Offset; }

public class DataManager
{
    private const int MemoryLimitMB = 100; // Adjustable at runtime
    private const int RandomRangeMax = 1000;
    private long[] _offsets;
    private int[] _keys;
    private Record[] _records;
    private int _memoryUsage;
    private Aes _aes;

    public DataManager(byte[] key, byte[] iv)
    {
        _aes = AES.Create();
        _aes.Key = key;
        _aes.IV = iv;
    }

    public int InitializeDataStructures(int size)
    {
        if (GetMemoryUsage() + (sizeof(long) * size + sizeof(int) * 2) > MemoryLimitMB * (1024 * 1024))
            throw new InvalidOperationException("Memory limit exceeded");

        _offsets = new long[size];
        _keys = new int[size];
        _records = new Record[size];
        _memoryUsage += sizeof(long) * size + sizeof(int) * 2;
        FillOffsets();
        FillKeys();
        FillRecords();
        return size;
    }

    private void FillOffsets()
    {
        for (int i = 0; i < _offsets.Length; ++i)
            _offsets[i] = i;
    }

    private void FillKeys()
    {
        var random = new Random();
        for (int i = 0; i < _keys.Length; ++i)
            _keys[i] = random.Next(RandomRangeMax);
    }

    private void FillRecords()
    {
        var rng = new Random();
        Action<int> SetRecordValueAndOffset = (index) =>
        {
            int keyIndex = _keys[index];
            long offset = _offsets[keyIndex];
            _records[index].Value = rng.Next(RandomRangeMax);
            _records[index].Offset = offset;
            if (offset >= _offsets.Length || offset < 0)
                throw new IndexOutOfRangeException();
        };

        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Math.Min(Environment.ProcessorCount, _keys.Length / 2) + 1 };
        Parallel.ForEach(_keys, options, SetRecordValueAndOffset);
    }

    private byte[] SerializeData()
    {
        using (MemoryStream ms = new MemoryStream())
        using (BinaryWriter bw = new BinaryWriter(ms))
        {
            bw.Write(_offsets);
            bw.Write(_keys);
            foreach (Record record in _records)
            {
                bw.Write(record.Value);
                bw.Write(record.Offset);
            }
            return ms.ToArray();
        }
    }

    private void DeserializeData(byte[] data)
    {
        using (MemoryStream ms = new MemoryStream(data))
        using (BinaryReader br = new BinaryReader(ms))
        {
            _offsets = br.ReadLongArray();
            _keys = br.ReadIntArray();
            _records = new Record[_keys.Length];
            for (int i = 0; i < _keys.Length; ++i)
            {
                int value = br.ReadInt32();
                long offset = br.ReadInt64();
                _records[i] = new Record { Value = value, Offset = offset };
            }
        }
    }

    private void DecryptAndSetRecordValue(int index, byte[] cipherText)
    {
        using (MemoryStream ms = new MemoryStream(cipherText))
        using (CryptoStream cs = new CryptoStream(ms, _aes.CreateDecryptor(), CryptoStreamMode.Read))
        using (BinaryReader br = new BinaryReader(cs))
        {
            int value = br.ReadInt32();
            _records[index].Value = value;
            _records[index].Offset = _offsets[_keys[index]];
        }
    }

    private int GetMemoryUsage()
    {
        // Implement logging and memory usage tracking here
        return _memoryUsage;
    }
}
```

