void read_and_find_max(int* *array, size_t* array_len) {
    int max = INT32_MIN;
    int buffer;
    size_t count = 0;

    while (scanf("%d", &buffer) == 1 && count < 500) {
        if (count >= *array_len) {
            *array_len += 500;
            *array = realloc(*array, *array_len * sizeof(int));
        }
        (*array)[count++] = buffer;
        max = (buffer > max) ? buffer : max;
    }

    if (ferror(stdin)) {
        perror("Error reading input");
        exit(EXIT_FAILURE);
    }

    if (count > 0 && count < *array_len) {
        (*array_len) = count;
    }

    printf("The largest integer is: %" PRId32 "\n", max);
    free(*array + *array_len);
    *array = realloc(*array, *array_len * sizeof(int));
}

void init_record_arrays(Record** records, size_t* records_len, int* keys, size_t* keys_len, long* offsets, size_t offsets_len) {
    srand(time(NULL));

    *records = malloc(records_len[0] * sizeof(Record));
    for (size_t i = 0; i < records_len[0]; ++i) {
        (*records)[i].value = rand() % 100 + 1;
    }

    keys_len[0] = offsets_len * 2;
    keys = realloc(keys, keys_len[0] * sizeof(int));
    offsets = realloc(offsets, offsets_len * sizeof(long));

    for (size_t i = 0; i < records_len[0]; ++i) {
        keys[2 * i] = i;
        keys[2 * i + 1] = rand() % offsets_len + 1;
        offsets[keys[2 * i + 1]]++;
    }

    for (size_t j = 0; j < offsets_len; ++j) {
        if (offsets[j]) {
            for (size_t i = 0; i < keys_len[0]; ++i) {
                if (keys[i] >= j && keys[i + 1] > j + 1) {
                    offsets[j]--;
                    keys[i]++;
                    break;
                }
            }
        }
    }
}
