class BSTNode {
public:
    std::string name;
    double weight;
    int count; // number of references to this node, including the parent and children
    std::unique_ptr<BSTNode> left;
    std::unique_ptr<BSTNode> right;

    BSTNode(std::string n, double w) : name(n), weight(w), count(1), left(nullptr), right(nullptr) {}
};

class Record {
public:
    std::unique_ptr<BSTNode> bstNode;
    std::unique_ptr<char[]> data;
    int size; // size of 'data' in bytes
    std::atomic<bool> isDeleted{false};

    Record(const char* data, int size) : size(size), data(std::make_unique<char[]>(size)) {
        memcpy(data.get(), data, size);
    }
};

class ItemManager {
private:
    std::vector<Record> records;
    std::map<std::string, std::unique_ptr<BSTNode>> bst;
    mutable std::mutex mtx;
    int numOperations = 0;
    std::atomic<int> numNodes = 0;
    const int maxMemoryUsage = 100 * 1024 * 1024; // 100 MB

public:
    ItemManager() {
        // Initialize adaptive optimizations here
    }

    Record* getRecord(const std::string& name) {
        auto it = records.begin();
        for (; it != records.end(); ++it) {
            if (it->data.get()[0] == name[0]) {
                if (it->size >= name.length() && memcmp(it->data.get(), name.c_str(), name.length()) == 0)
                    return &*it;
            }
        }
        return nullptr;
    }

    BSTNode* getBSTNode(const std::string& name) {
        auto it = bst.find(name);
        if (it != bst.end())
            return it->second.get();
        return nullptr;
    }

    void addItem(const char* data, int size, const std::string& name, double weight) {
        // Add concurrency control here

        Record* record = new Record(data, size);
        Record* existingRecord = getRecord(name);
        if (existingRecord) {
            ++(existingRecord->bstNode->count);
            return;
        }

        auto bstNode = std::make_unique<BSTNode>(name, weight);
        Record* newRecord = new Record(data, size);
        record = newRecord;
        records.push_back(std::move(newRecord));
        numNodes++;

        if (numNodes > maxMemoryUsage / sizeof(Record)) {
            // Trigger adaptive optimizations here
        }

        auto insertBST = [bstNode](BSTNode* node) {
            if (!node) return;
            if (weight < node->weight) {
                if (!node->left)
                    node->left.reset(std::move(bstNode));
                else
                    insertBST(node->left.get());
            } else {
                if (!node->right)
                    node->right.reset(std::move(bstNode));
                else
                    insertBST(node->right.get());
            }
            node->count++;
        };

        insertBST(nullptr);
        bst[name] = std::move(bstNode);
    }

    void deleteItem(const std::string& name) {
        // Add concurrency control here

        Record* record = getRecord(name);
        if (!record) throw std::invalid_argument("Item not found");
        if (--record->bstNode->count == 0) {
            numNodes--;
            bst.erase(name);
        }
    }

    const BSTNode* getBST() const { return bst.empty() ? nullptr : bst.begin()->second.get(); }
    int getNumNodes() const { return numNodes; }
};
```

