    void *longPtr = mmap(NULL, longSize*sizeof(long), PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANON, -1, 0);
    if (longPtr == MAP_FAILED) {
        logMsg(logData, "Failed to allocate memory for 'long' array\n");
        return -1;
    }

    struct stat statbuf;
    fstat(fileno(logData->logFile), &statbuf);
    long maxMemory = memoryLimitMB * (1LL << 20); // Convert MB to bytes
    if ((longSize+sizeof(int)*recordCount + statbuf.st_size) > maxMemory) {
        logMsg(logData, "Total memory usage exceeds the limit of %llu bytes\n", maxMemory);
        return -2;
    }

    void *keyPtr = malloc(sizeof(int)*recordCount);
    if (!keyPtr) {
        logMsg(logData, "Failed to allocate memory for 'int' keys\n");
        munmap(longPtr, longSize*sizeof(long));
        return -1;
    }

    void *recordPtr = malloc(sizeof(Record)*recordCount);
    if (!recordPtr) {
        logMsg(logData, "Failed to allocate memory for 'record' structures\n");
        free(keyPtr);
        munmap(longPtr, longSize*sizeof(long));
        return -1;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < recordCount; ++i) {
        Record *record = (Record*)(recordPtr + i);
        while (1) {
            record->key = rand() % (maxKey - minKey + 1) + minKey;
            if (bsearch(&record->key, keyPtr, recordCount, sizeof(int), intcmp)) continue;
            break;
        }

        long index = *(long*)((char*)longPtr + record->key * sizeof(long));
        if (index < 0 || index >= longSize) {
            logMsg(logData, "Invalid 'offset' value: %ld\n", index);
            free(recordPtr);
            free(keyPtr);
            munmap(longPtr, longSize*sizeof(long));
            return -1;
        }

        record->offset = index;
    }

    return 0;
}

