    void* offset;
    void* record;
    struct Node *next;
} Node;

sem_t memorySemaphore; // To control memory allocation/deallocation
sem_t logSemaphore;   // To control logging operations
pthread_mutex_t themeCacheMutex;  // For thread safety in theme cache access

unsigned long totalMemoryLimitKB;
int keyMin, keyMax;
char *defaultThemeDirectory;

Node* offsetList = NULL;
Node* keyList = NULL;
Node* recordList = NULL;

void log(const char* message) {
    // Implement logging with existing system here
}

void checkMemory() {
    unsigned long totalMemoryUsage = 0;
    Node* current = offsetList;
    while (current != NULL) {
        totalMemoryUsage += sizeof(long) * ((Node*)current->offset - &((long*)0));
        current = current->next;
    }

    current = keyList;
    while (current != NULL) {
        totalMemoryUsage += sizeof(int) * ((Node*)current->key - &((int*)0)) + sizeof(void*) * current->next;
        current = current->next;
    }

    current = recordList;
    while (current != NULL) {
        totalMemoryUsage += sizeof(Record) * ((Node*)current->record - &((Record*)0)) + sizeof(int) * current->key + sizeof(void*) * current->next;
        current = current->next;
    }

    if (totalMemoryUsage > totalMemoryLimitKB * 1024) {
        log("Warning: Memory limit exceeded.");
    }
}

int findKey(int key) {
    Node* current = keyList;
    while (current != NULL) {
        if (current->key == key) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void* allocateRecord() {
