#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct entry {
    char *key;
    int value;
    time_t timestamp;
} Entry;

void manage_memory(Entry **entries, size_t *size, const size_t capacity, const size_t entry_count) {
    if (*size >= capacity) {
        // Reallocate if the current size is equal to or greater than the capacity.
        *entries = realloc(*entries, sizeof(Entry) * (2 * capacity));
        if (!*entries) {
            fprintf(stderr, "Error: Out of memory\n");
            exit(EXIT_FAILURE);
        }
        capacity *= 2;
    }

    for (size_t i = *size; i < entry_count; ++i) {
        (*entries + i)->key = malloc(strlen(key) + 1);
        if (!(*entries + i)->key) {
            fprintf(stderr, "Error: Out of memory\n");
            exit(EXIT_FAILURE);
        }
        strcpy((*entries + i)->key, key);
        (*entries + i)->value = value;
        (*entries + i)->timestamp = time(NULL);
    }
    *size = entry_count;
}

void free_memory(Entry **entries, size_t size) {
    if (size > 0) {
        for (size_t i = 0; i < size; ++i) {
            free((*entries + i)->key);
        }
        free(*entries);
        *entries = NULL;
        size = 0;
    }
}
