#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    long offset;
} Record;

// Hash function for key lookups
unsigned int hashFunction(int key) {
    unsigned long hash = 5381;
    int c;

    while (key != 0) {
        c = (key & 0x7FFF);
        key >>= 14;
        hash += (hash << 5) + c;
        hash += (hash << 2) + (c << 3);
    }

    return (hash ^ (hash >> 16));
}

// Custom allocator for efficient memory management
void* customAlloc(size_t size) {
    void *memory = malloc(size);

    if (!memory) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    memset(memory, 0, size);
    return memory;
}

