        records[hashFunction(initialRecords[i]->key)] = initialRecords[i];
    }
    numRecords = capacity; // Assume the entire data source is valid. Adjust as needed.

    while (true) {
        pthread_mutex_lock(&lock);

        // Implement insertion, deletion, and lookup operations here.

        processString(inputStr, enforceStrictLength);

        if (numRecords >= capacity) {
            memoryDefrag();
            capacity *= 2;
            records = realloc(records, capacity * sizeof(Record*));
