import com.google.common.base.Stopwatch;
import com.google.common.collect.*;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.function.BiFunction;
import java.util.function.Consumer;
import java.util.stream.Collectors;

public class TransactionProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(TransactionProcessor.class);
    private static final Comparator<Instant> INSTANT_COMPARATOR = Comparator.naturalOrder().reversed();

    private BiFunction<String, Instant, Instant> transactionEndTimeFunction;
    private BiFunction<String, Instant, Integer> transactionDurationFunction;
    private Consumer<Map<String, TransactionSet>> onTransactionUpdate;
    private Multiset<TransactionSet> userTransactionsCache;
    private ConcurrentHashMap<String, TransactionSet> currentUserSets;
    private DurationCache transactionDurationsCache;

    public TransactionProcessor(BiFunction<String, Instant, Instant> transactionEndTimeFunction,
                                BiFunction<String, Instant, Integer> transactionDurationFunction,
                                Consumer<Map<String, TransactionSet>> onTransactionUpdate) {
        this.transactionEndTimeFunction = transactionEndTimeFunction;
        this.transactionDurationFunction = transactionDurationFunction;
        this.onTransactionUpdate = onTransactionUpdate;
        this.userTransactionsCache = HashMultiset.create();
        this.currentUserSets = new ConcurrentHashMap<>();
        this.transactionDurationsCache = new DurationCache(60, TimeUnit.SECONDS);
    }

    public void processTransactions(List<Transaction> transactions) {
        if (transactions == null || transactions.isEmpty()) return;

        for (Transaction transaction : transactions) {
            try {
                updateUserTransactions(transaction);
            } catch (ExecutionException | InterruptedException e) {
                LOGGER.error("Failed to process transaction", e);
            }
        }
    }

    private void updateUserTransactions(Transaction transaction) throws ExecutionException, InterruptedException {
        String userId = transaction.getUserId();
        Instant startTime = Instant.now();
        TransactionSet currentTransaction = new TransactionSet(transactionEndTimeFunction.apply(userId, startTime),
                transactionDurationFunction.apply(userId, startTime));

        updateUserTransactionsWithNewTransaction(userId, currentTransaction);
    }

    private void updateUserTransactionsWithNewTransaction(String userId, TransactionSet newTransaction) {
        // Update the cache first to handle concurrent updates efficiently.
        userTransactionsCache.add(newTransaction);
        TransactionSet mergedTransactionSet = mergeOverlappingSets(userId, newTransaction);
        if (mergedTransactionSet != null) {
            currentUserSets.putIfAbsent(userId, mergedTransactionSet);
            onTransactionUpdate.accept(currentUserSets);
        }
    }

    private TransactionSet mergeOverlappingSets(String userId, TransactionSet newTransaction) {
        List<TransactionSet> userTransactionsList = ImmutableSortedSet.copyOf(userTransactionsCache).stream()
                .filter(t -> StringUtils.equals(t.getUserId(), userId))
                .collect(Collectors.toList());
        return MergeFunction.merge(userTransactionsList, (t1, t2) -> t1.compareTo(t2, INSTANT_COMPARATOR) > 0 ? t1 : t2);
    }

    // Utils and inner classes omitted for brevity...
}
```

