package com.example;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import java.util.concurrent.TimeUnit;
import java.util.Random;
import javax.validation.ConstraintViolation;
import javax.validation.Validator;
import org.springframework.validation.annotation.Validated;

@Service
@Validated
@ConditionalOnProperty(value = "externalAuth.enabled", matchIfMissing = true)
public class ExternalAuthenticationService {
    private final String authUrl;
    private final Validator validator;
    private final ApplicationEventPublisher eventPublisher;
    private boolean isRunning;
    private long nextOperationTime;

    public ExternalAuthenticationService(
            @Value("${externalAuth.url}") String authUrl,
            Validator validator,
            ApplicationEventPublisher eventPublisher) {
        this.authUrl = authUrl;
        this.validator = validator;
        this.eventPublisher = eventPublisher;
    }

    public void start() {
        isRunning = true;
        nextOperationTime = System.currentTimeMillis() + new Random().nextInt(500); // random delay between 0 and 500ms
    }

    public void stop() {
        isRunning = false;
        eventPublisher.publishEvent(new ServiceStoppedEvent());
    }

    public boolean validateUserAndPassword(@Valid User user, String password) {
        for (ConstraintViolation<User> violation : validator.validate(user)) {
            if (!violation.getPropertyPath().toString().equals("username")) {
                throw new RuntimeException("Invalid username format.");
            }
        }

        // Send request to external authentication service and validate the response
        RestTemplate restTemplate = new RestTemplate();
        String response = restTemplate.postForObject(authUrl + "/validate", user, String.class);
        return password.equals(response);
    }
}

@Component
public class User {
    private String username;
    private String password;

    public void setUsername(String username) {
        this.username = username;
    }

    public void setPassword(String password) {
        this.password = password;
    }
}

@Component
public class ServiceStoppedEvent {
}
