// Function to read key-offset pairs from binary file
void read_pairs(FILE *file, size_t *offsets, size_t *num_records) {
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size < sizeof(size_t)) {
        fprintf(stderr, "Error: Invalid input file size\n");
        exit(EXIT_FAILURE);
    }

    *num_records = file_size / sizeof(size_t);
    offsets = realloc(offsets, *num_records * sizeof(size_t));

    fread(offsets, sizeof(size_t), *num_records, file);
}

// Function to generate random int within a specified range
int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to allocate and initialize record structures based on key-offset pairs
Record* init_records(size_t *offsets, size_t num_records, int range_min, int range_max) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand_in_range(range_min, range_max);
        if (offsets[i] < i) {
            fprintf(stderr, "Error: Offset out of order\n");
            exit(EXIT_FAILURE);
        }
    }

    return records;
}

// Function to decrypt and decompress the Base64-encoded input string
char* decode_data(const char *input) {
    int len = strlen(input);
    char *decoded = malloc(len * 3 / 4 + 1); // Allocate space for base64-decoded data plus null terminator
    if (!decoded) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }

    int decoded_len = Base64DecodeAndZlibDecompress(input, len, decoded, len * 3 / 4);
    if (decoded_len <= 0) {
        fprintf(stderr, "Error: Failed to decode data\n");
        free(decoded); // Free allocated memory in case of failure
        exit(EXIT_FAILURE);
    }

    decoded[decoded_len] = '\0';
    return decoded;
}

// Function to read and process the input file
int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen(argv[1], "rb");
    if (!file) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    size_t offsets[0];
    size_t num_records = 0;
    read_pairs(file, &offsets, &num_records);

    char *data = decode_data(argv[1]); // Decrypt and decompress the input file's data

    int range_min = atoi(strtok(data, ","));
    int range_max = atoi(strtok(NULL, ",\n"));

    Record *records = init_records(offsets, num_records, range_min, range_max);

    fclose(file);

    // Process the record structures as needed...

    free(data);
    free(records);
    free(offsets);

    return EXIT_SUCCESS;
}
