// Assumes a global string pool of MAX_STRING_POOL_SIZE strings, where each string is MAX_STRING_LENGTH bytes.
// Adjust as needed for your external data source.
extern char string_pool[MAX_STRING_POOL_SIZE][MAX_STRING_LENGTH];

int initialize_records(size_t num_records, size_t max_string_length, size_t memory_limit_bytes) {
    size_t total_allocated = 0;
    Record *records = NULL;

    // Allocate enough for the requested number of records, plus some extra to account for overhead and potential resizing.
    size_t num_extra = (num_records / 2) + 1;
    records = malloc((num_records + num_extra) * sizeof(Record));
    if (!records) {
        return -1; // Failed due to memory allocation error
    }

    total_allocated += (num_records + num_extra) * sizeof(Record);

    srand(time(NULL));

    for (size_t i = 0; i < num_records && total_allocated <= memory_limit_bytes; ++i) {
        size_t record_id = records[i].id = (size_t)(num_records * i);

        // Use string pool if possible, otherwise generate a new string.
        char* str = &string_pool[record_id % MAX_STRING_POOL_SIZE][0];
        if (!str || strlen(str) >= max_string_length) {
            snprintf(records[i].str, max_string_length + 1, "%.*s", max_string_length - 1, random_string());
        } else {
            strcpy(records[i].str, str);
        }
        records[i].str[max_string_length] = '\0'; // Ensure null terminated

        records[i].value = rand() % MAX_VALUE;

        total_allocated += sizeof(records[i].str) + sizeof(records[i].value);
    }

    if (total_allocated > memory_limit_bytes) {
        free(records);
        return -1; // Failed due to exceeding memory limit
    }

    return num_records;
}
