use std::child::Child;
use std::ffi::{CString, OsString};
use std::process::{Command, Stdio};
use std::result::Result;
use std::str;

fn run_c_program(input: &OsStr, output: Option<&OsStr>, verbose: bool) -> i32 {
    let mut args = vec!["path/to/your_c_program".to_owned()];

    if let Some(output_file) = output {
        args.push("-o".to_owned());
        args.push(output_file.to_str().unwrap().to_owned());
    }

    if verbose {
        args.push("-v".to_owned());
    }

    let c_args = OsString::from(args.concat());

    let mut cmd = Command::new("cc");
    cmd.arg("-o").arg("temp_output");
    cmd.arg(&c_args);
    cmd.arg(input);

    if let Ok(mut child) = cmd.spawn() {
        let status = match child.wait() {
            Ok(status) => status,
            Err(_) => {
                println!("Error compiling C program");
                return -1;
            }
        };

        if !status.success() {
            println!("Compilation of C program failed with exit code {}", status.code().unwrap());
            return status.code().unwrap();
        }

        let mut child = Command::new("./temp_output");

        // Redirect the input and output streams
        child.stdin(Stdio::pipes())
            .stdout(Stdio::pipes())
            .stderr(Stdio::pipes());

        match child.spawn() {
            Ok(mut subprocess) => {
                let (_, mut input) = child.stdin.take().unwrap();
                std::fs::copy(input, &subprocess.stdin.as_mut().unwrap()).expect("Error copying input to subprocess");

                if let Ok(output) = subprocess.wait() {
                    drop(input);
                    return output.code().unwrap();
                } else {
                    println!("Subprocess execution failed");
                    std::process::exit(-1);
                }
            }
            Err(_) => {
                println!("Error spawning subprocess");
                return -1;
            }
        }
    } else {
        println!("Error compiling command line arguments");
        return -1;
    }
}
```
This Rust function spawns a C program and handles the input and output streams. The function takes an input file, an optional output file, and a verbose flag as parameters. It first compiles the C program using the `cc` command, then executes it by redirecting the standard input (stdin) and standard output (stdout).

Error handling is implemented in various places to handle potential issues such as compilation errors, subprocess execution failures, or copying input to the subprocess. Usage instructions and error messages are not provided here, but can be added as needed to make the program more user-friendly.']

