typedef struct {
    int value;
} record;

static long *offset = NULL;
static int *key = NULL;
static record *records = NULL;
static size_t offsetCapacity = 0;
static size_t keyCapacity = 0;
static size_t recordCapacity = 0;
static sem_t resizeSemaphore;
static pthread_mutex_t logsMutex = PTHREAD_MUTEX_INITIALIZER;
static log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("memoryManager"));

void memoryManager_resize(size_t *capacity, size_t *current) {
    const double idleLimit = 0.10;
    while (*current > (*capacity) * (1 - idleLimit)) {
        *capacity *= 2;
    }
}

void* readRecordFromDataSource(void *data) {
    // Implement your asynchronous record reading logic here
    ...
}

void appendRecord(int key, record value) {
    pthread_mutex_lock(&logsMutex);
    log4cxx::ThreadCategory &tc = log4cxx::ThreadCategory::getThreadCategory("memoryManager");
    tc.debug("Appending record with key " << key);
    pthread_mutex_unlock(&logsMutex);

    if (recordCapacity == 0) {
        recordCapacity = 16;
        records = (record *)mmap(NULL, recordCapacity * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    }

    if (key >= keyCapacity) {
        memoryManager_resize(&keyCapacity, &key);
        key = keyCapacity - 1;
        int *newKeyArray = (int *)realloc(key, keyCapacity * sizeof(int));
        if (!newKeyArray) {
            // Handle error here
        }
        key = newKeyArray;
    }

    records[key] = value;
}

void memoryManager_init() {
    offset = (long *)mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!offset) {
        // Handle error here
    }

    sem_init(&resizeSemaphore, 0, 1);
}

void memoryManager_deinit() {
    munmap(offset, sizeof(long));
    free(key);
    free(records);
    sem_destroy(&resizeSemaphore);
}

void* memoryManager_loadData(void *data) {
    while (true) {
        record newRecord = readRecordFromDataSource(data);
        appendRecord(offset[offsetCapacity - 1] + 1, newRecord.value);
        offset[offsetCapacity - 1]++;

        // Acquire resize semaphore to ensure memory is only resized when appropriate
        sem_wait(&resizeSemaphore);
        memoryManager_resize(&offsetCapacity, &offset);
        sem_post(&resizeSemaphore);
    }
}
```

