typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

#define DEFAULT_CAPACITY 1024

void *unique_rnti_generator() {
    static uint16_t rnti = 1;
    return rnti++;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(size_t index) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("malloc failed");
        return NULL;
    }

    pthread_mutex_init(&pdu->mutex, NULL);
    pdu->RX_UE_INFORMATION_TAG = index + 1;
    pdu->RNTI = *((uint16_t*) unique_rnti_generator());
    pdu->CRC_INDICATION_REL8_TAG = rand() & ((1 << 32) - 1);
    pdu->CRCFLAG = rand() % 2;
    return pdu;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        free(pdu);
        pthread_mutex_destroy(&pdu->mutex);
    }
}

size_t find_empty_index(const NFAPI_CRC_INDICATION_PDU_T* const* list, size_t list_size) {
    for (size_t i = 0; i < list_size; ++i) {
        if (!list[i]) {
            return i;
        }
    }
    return -1;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* const* list, size_t list_size, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    size_t empty_index = find_empty_index(list, list_size);
    if (empty_index != -1) {
        pthread_mutex_lock(&new_pdu->mutex);
        list[empty_index] = new_pdu;
        pthread_mutex_unlock(&new_pdu->mutex);
    } else {
        perror("List is full");
    }
}

void remove_pdu(NFAPI_CRC_INDICATION_PDU_T* const* list, size_t list_size, NFAPI_CRC_INDICATION_PDU_T *old_pdu) {
    if (list && old_pdu) {
        pthread_mutex_lock(&old_pdu->mutex);
        for (size_t i = 0; i < list_size; ++i) {
            if (list[i] == old_pdu) {
                list[i] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&old_pdu->mutex);
    }
}

void init_pdu_list(NFAPI_CRC_INDICATION_PDU_T* const* list, size_t capacity) {
    if (list && capacity > 0) {
        for (size_t i = 0; i < capacity; ++i) {
            list[i] = create_pdu(i);
        }
    } else {
        perror("Invalid parameters");
    }
}

void destroy_pdu_list(NFAPI_CRC_INDICATION_PDU_T* const* list, size_t capacity) {
    if (list && capacity > 0) {
        for (size_t i = 0; i < capacity; ++i) {
            destroy_pdu(list[i]);
        }
    } else {
        perror("Invalid parameters");
    }
}
```

