    private Jedis redis;

    public UrlMetadataService() {
        try {
            redis = new Jedis("redis-server");
        } catch (JedisConnectionException e) {
            // Handle connection failure to the Redis server
        }
    }

    private void processUrl(String url) throws IOException {
        Request request = new Request.Builder()
                .url(url)
                .build();

        Response response = httpClient.newCall(request).execute();
        if (!response.isSuccessful()) {
            // Handle failed API requests
            return;
        }

        JsonNode metadata = parseMetadata(response.body().string());
        String contentHash = computeSha256Hash(response.body().bytes());

        redis.hset("url_metadata", contentHash, serializeMetadata(metadata));
    }

    private void processUrlBatch(Deque<String> urls) {
        int processedUrlCount = 0;
        while (!urls.isEmpty() && processedUrlCount < MAX_URLS) {
            executor.submit(() -> processUrl(urls.poll()));
            processedUrlCount++;
        }
    }

    private JsonNode parseMetadata(String jsonText) throws IOException {
        // Implement parsing of metadata from the JSON response using a library like Jackson
    }

    private String computeSha256Hash(byte[] content) {
        try {
            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
            messageDigest.update(content);
            byte[] hashBytes = messageDigest.digest();
            StringBuilder hashBuilder = new StringBuilder();
            for (byte b : hashBytes) {
                hashBuilder.append(String.format("%02x", b));
            }
            return hashBuilder.toString();
        } catch (Exception e) {
            // Handle exceptions computing hashes
        }
        return "";
    }

    private String serializeMetadata(JsonNode metadata) {
        ConcurrentMap<String, Object> serializedMetadata = new LinkedHashMap<>();
        for (Map.Entry<String, JsonNode> entry : metadata.fields()) {
            serializedMetadata.put(entry.getKey(), entry.getValue().toString());
        }
        return JacksonUtils.writeValueAsString(serializedMetadata);
    }

    public void processUrls(Deque<String> urls) {
        if (redis != null && !urls.isEmpty()) {
            CacheStrategy cacheStrategy = new CacheStrategy();
            Deque<String> cachedUrls = cacheStrategy.getFromCache(urls);
            processUrlBatch(cachedUrls);
            processUrlBatch(urls.subList(cachedUrls.size(), urls.size()));
        } else {
            processUrlBatch(urls);
        }
    }
}
```

