    private void initializeArrays() {
        deleteTempFileIfExists(logFile);
        offsets = new long[OFFSET_THRESHOLD.get()];
        keys = new int[RECORD_THRESHOLD.get()];
        records = new Record[RECORD_THRESHOLD.get()];
    }

    private void resizeArrays(int[] array, AtomicInteger threshold) {
        if (array.length >= threshold.get()) {
            int newSize = Math.max(threshold.addAndGet(array.length), 2 * array.length);
            int[] newArray = new int[newSize];
            System.arraycopy(array, 0, newArray, 0, array.length);
            array = newArray;
        }
    }

