        resizeArrays(keys, RECORD_THRESHOLD);
        resizeArrays(records, RECORD_THRESHOLD);
        int index = offsets[offsets.length - 1];
        offsets[offsets.length - 1]++;

        keys[index] = key;
        records[index].value = value;
        logEvent("added record: " + index + ", key: " + key + ", value: " + value);
        return index;
    }

    public void batchProcess(int start, int end, String command) {
