typedef struct NetworkSession {
    int id;
    int protocol_type;
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    size_t payload_size;
    pthread_mutex_t mutex;
    time_t creation_timestamp;
} NetworkSession;

typedef struct SessionsList {
    NetworkSession** sessions;
    int capacity;
    int size;
    int max_sessions;
    pthread_mutex_t list_mutex;
} SessionsList;

SessionsList* create_session_list(int max_sessions) {
    SessionsList* list = (SessionsList*)malloc(sizeof(SessionsList));
    if (!list) return NULL;
    list->capacity = 8;
    list->size = 0;
    list->max_sessions = max_sessions;
    list->sessions = (NetworkSession**)calloc(list->capacity, sizeof(NetworkSession*));
    if (!list->sessions) {
        free(list);
        return NULL;
    }
    list->list_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_init(&list->sessions[0]->mutex, NULL);
    return list;
}

int add_session(SessionsList* list, const NetworkSession* session) {
    int i;

    for (i = 0; i < list->size; ++i) {
        if (!memcmp(session->src_ip, list->sessions[i]->src_ip, INET_ADDRSTRLEN) &&
            !memcmp(session->dst_ip, list->sessions[i]->dst_ip, INET_ADDRSTRLEN)) {
            return -1;
        }
    }

    pthread_mutex_lock(&list->list_mutex);

    if (list->size >= list->max_sessions) {
        pthread_mutex_unlock(&list->list_mutex);
        return 0;
    }

    list->sessions[list->size] = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!list->sessions[list->size]) {
        pthread_mutex_unlock(&list->list_mutex);
        return -1;
    }

    memcpy(list->sessions[list->size], session, sizeof(NetworkSession));
    list->sessions[list->size]->id = list->size + 1;
    pthread_mutex_init(&list->sessions[list->size]->mutex, NULL);
    list->size++;

    if (list->capacity == list->size) {
        NetworkSession** tmp = realloc(list->sessions, (list->capacity *= 2) * sizeof(NetworkSession*));
        if (!tmp) {
            pthread_mutex_unlock(&list->list_mutex);
            return -1;
        }
        list->sessions = tmp;
    }

    pthread_mutex_unlock(&list->list_mutex);
    return 1;
}

void prune_old_sessions(SessionsList* list) {
    time_t current_time = time(NULL);
    int i, j;

    for (i = 0; i < list->size; ++i) {
        if (difftime(current_time, list->sessions[i]->creation_timestamp) > 60 * 60 * 24) { // prune sessions older than 1 day
            for (j = i + 1; j < list->size; ++j) {
                if (list->sessions[i] == list->sessions[j]) continue;
                free(list->sessions[j]);
                memmove(&list->sessions[j], &list->sessions[j + 1], sizeof(NetworkSession*) * (list->size - j));
            }
            free(list->sessions[i]);
            list->sizes[i] = list->sizes[--list->size];
        }
    }
}
```

This code defines a `NetworkSession` structure for the network packet capture sessions and a `SessionsList` structure to manage them. The function `create_session_list()` creates a new session list with a specified maximum number of sessions, ensuring that it is thread-safe using pthreads.

The `add_session()` function checks if a session with the same source and destination IP addresses already exists in the list before adding the new one, handles memory allocation failures, and ensures the list size does not exceed the maximum limit.

Lastly, the `prune_old_sessions()` function removes old sessions that are older than 1 day to maintain system performance and reduce memory consumption.']

