#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Custom logging mechanism
void custom_log(int level, const char *message) {
    // Implement log levels and filtering based on requirements
    printf("[Log Level %d] %s\n", level, message);
}

// Semaphore management library
typedef struct semaphore {
    pthread_sem_t sem;
    char name[32]; // Max length for semaphore names is 31 chars (including null terminator)
    int ref_count;
} semaphore;

semaphore* create_semaphore(const char *name, int initial_value) {
    semaphore *sem = malloc(sizeof(semaphore));
    strncpy(sem->name, name, sizeof(sem->name));
    sem->ref_count = 1;
    if (pthread_sem_init(&sem->sem, NULL, initial_value) != 0) {
        custom_log(2, "Failed to create semaphore: %s", strerror(errno));
        free(sem);
        return NULL;
    }
    return sem;
}

void delete_semaphore(semaphore *sem) {
    if (sem == NULL || --sem->ref_count > 0) return;
    pthread_sem_destroy(&sem->sem);
    free(sem);
}

int wait_semaphore(semaphore *sem, int timeout) {
    struct timespec ts = {timeout, 0};
    if (pthread_sem_timedwait(&sem->sem, &ts.tv_sec) != 0) {
        custom_log(2, "Failed to wait on semaphore: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int try_semaphore(semaphore *sem) {
    int ret = pthread_sem_trywait(&sem->sem);
    if (ret == 0) return 0;
    if (errno != EAGAIN) {
        custom_log(2, "Failed to try wait on semaphore: %s", strerror(errno));
        return -1;
    }
    return 1;
}

void signal_semaphore(semaphore *sem) {
    if (pthread_sem_post(&sem->sem) != 0) {
        custom_log(2, "Failed to signal semaphore: %s", strerror(errno));
    }
}

// Dynamic memory allocation for arrays
long* allocate_longs(size_t size) {
    long *arr = malloc(sizeof(long) * size);
    if (arr == NULL) custom_log(2, "Failed to allocate long array");
    return arr;
}

int* allocate_ints(size_t size) {
    int *arr = malloc(sizeof(int) * size);
    if (arr == NULL) custom_log(2, "Failed to allocate int array");
    return arr;
}

record* allocate_records(size_t size) {
    record *arr = malloc(sizeof(record) * size);
    if (arr == NULL) custom_log(2, "Failed to allocate record array");
    for (size_t i = 0; i < size; ++i) arr[i].value = rand() % MAX_RANDOM_VALUE;
    return arr;
}

// Function for the given programming task
