            wait_semaphore(sem_offsets, INFINITY); // Wait for available offset
            (*offsets)[idx] = rand() % MAX_OFFSET_VALUE;
            signal_semaphore(sem_offsets);

            wait_semaphore(sem_resizing, INFINITY); // Signal resize if needed

            // Resize and set the key for the new record (if array is full)
            resize_arrays(records, keys, capacity * 2);
            (*keys)[idx] = idx;
            (*records)[idx].value = rand() % MAX_RANDOM_VALUE;

            signal_semaphore(sem_resizing);
        }, thread_arg);
    }

    // Wait for all threads to finish and cleanup resources
    for (size_t i = 0; i < capacity; ++i) pthread_join(threads[i], NULL);
    delete_semaphore(sem_offsets);
    delete_semaphore(sem_resizing);
