    const size_t slash = strcspn(filename, ".\\/");
    return strndup(filename, slash);
}

// Helper function to determine the extension of a given file name
char* get_extension(const char *filename) {
    const size_t dot = strlen(filename) - 1;
    if (dot < 1 || filename[dot - 1] != '.') return "";
    return strndup(&filename[dot], MAX_EXT);
}

// Helper function to generate a unique file type extension based on the presence of certain characters in the base name
char* get_filetype(const char *base) {
    static const char* extensions[] = {"txt", "csv", "log"};
    size_t len = strlen(base);
    if (len < 4 || isdigit(base[len - 3]) && isdigit(base[len - 2])) return "";

    for (size_t i = 0; i < sizeof(extensions) / sizeof(*extensions); ++i) {
        const char* ext = extensions[i];
        size_t ext_len = strlen(ext);
        if (!strncmp(&base[len - ext_len], ext, ext_len)) return ext;
    }
    return "";
}

// Function to generate a new filename from the input filename
char* generate_filename(const char *filename) {
    // Extract base name and directory path
    const char *base = get_base_path(filename);
    size_t base_len = strlen(base);

    // Determine the number of digits for the new extension
    int num_digits = (base_len > 3) ? 4 : base_len - 1;
    if (num_digits > 4) num_digits = 4;

    // Generate the new filename components
    char *ext = malloc(num_digits + 1);
    snprintf(ext, num_digits + 1, "%0*d", num_digits, global_counter++);
    char *filetype = get_filetype(base);

    // Combine the components and append the timestamp if needed
    size_t max_total_len = TOTAL_LEN - strlen(".txt") - 1;
    char *new_filename = malloc(max_total_len + 1);
    snprintf(new_filename, max_total_len + 1, "%s%.*s.%s", base, (int)(base_len > max_total_len - num_digits - 2 ? max_total_len - num_digits - 3 : base_len), base + (base_len > max_total_len - num_digits - 2 ? max_total_len - num_digits - 3 : 0), ext);
    if (strlen(new_filename) >= max_total_len) {
        size_t slash = strcspn(base, ".\\/");
        snprintf(new_filename, max_total_len + 1, "%.*s%d.%s", (int)(max_total_len - strlen(".txt")), base, global_counter++, ext);
    }
    if (access(new_filename, F_OK) == 0 && global_counter < COUNTER_LIMIT) {
        pthread_mutex_lock(&lock);
        while (access(new_filename, F_OK)) {
            global_counter++;
            pthread_mutex_unlock(&lock);
            usleep(100000); // Sleep for 100ms before retrying to avoid busy waiting
            pthread_mutex_lock(&lock);
        }
    }

    free(ext);
    free(filetype);

    return new_filename;
}
