void LteMeasurementManager::clearOldData() {
    auto now = std::chrono::steady_clock::now();

    for (auto& elem : m_map) {
        boost::lockfree::spsc_array_queue<lte::Measurement*>& queue = elem.second;
        while (!queue.empty()) {
            auto measurementPtr = queue.front();
            if ((now - measurementPtr->Timestamp) > m_ageThreshold) {
                queue.pop();
            } else {
                break;
            }
        }
    }
