[' Due to the complexity of your request, I'll break down the task into several functions that can be used together to achieve the desired result. Here are the functions for managing semaphores in C:

1. Semaphore creation function using shmget(), shmat() and semget():

```c
#include <sys/shm.h>
#include <sys/sem.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int create_semaphore(key_t key, int value) {
    int semid = semget(key, 1, IPC_CREAT | 0644); // Create a new semaphore with the given key and initial value
    if (semid == -1) {
        perror("Failed to create semaphore");
        return -1;
    }

    union semun {
        int val;
    } arg;
    arg.val = value;

    if (semctl(semid, 0, SETVAL, arg) == -1) { // Set the semaphore value
        perror("Failed to set semaphore value");
        return -1;
    }

    return semid;
}
```

2. Semaphore attachment and detachment functions using shmget(), shmat() and shmdt():

```c
#include <sys/shm.h>

void attach_semaphore(int semid) {
    key_t shmid_key = semid;
    int shmid = shmget(shmid_key, sizeof(struct semunion), 0); // Attach the shared memory segment
    if (shmid == -1) {
        perror("Failed to attach semaphore");
        exit(EXIT_FAILURE);
    }

    void *sem = shmat(shmid, NULL, 0); // Map the shared memory segment
    if ((int)sem == -1) {
        perror("Failed to map semaphore");
        exit(EXIT_FAILURE);
    }
}

void detach_semaphore() {
    shmdt((void*)-1); // Unmap and detach the shared memory segment
}
```

3. Semaphore wait(), post(), and trywait() functions:

```c
#include <sys/sem.h>

int sem_wait(struct sembuf *sops) {
    int ret = semop(semid, sops, 1); // Wait on the semaphore
    if (ret == -1) {
        perror("Failed to wait on semaphore");
        return -1;
    }
    return ret;
}

int sem_post(struct sembuf *sops) {
    int ret = semop(semid, sops, 1); // Post on the semaphore
    if (ret == -1) {
        perror("Failed to post on semaphore");
        return -1;
    }
    return ret;
}

int sem_trywait(struct sembuf *sops) {
    struct sembuf empty_ops = { sops->sem_num, 0, SEM_UNDO }; // Prepare empty operations for semop()
    int ret = semop(semid, sops, 1);                          // Try waiting on the semaphore
    if (ret == -1 && errno != EINTR) {                        // If there's no interruption, report error
        perror("Failed to try wait on semaphore");
        return -1;
    }
    ret = semop(semid, &empty_ops, 1);                       // Reset the semaphore and return result
    if (ret == -1) {
        perror("Failed to reset semaphore after trywait()");
        return -1;
    }
    return !errno; // Return non-zero if no error occurred
}
```

4. Function to perform semaphore operations with rate limiting:

```c
#include <time.h>

int sem_operation(struct sembuf *sops, int max_ops_per_second) {
    struct timespec now = { 0 };
    clock_gettime(CLOCK_MONOTONIC, &now);
    double time_diff = (now.tv_sec - last_op_time.tv_sec) + (now.tv_nsec - last_op_time.tv_nsec)/1000000000;

    if (time_diff < 1./max_ops_per_second) {
        usleep(1000000 * (1./max_ops_per_second - time_diff)); // Sleep for the remaining time until the next operation is allowed
    }

    last_op_time = now;
    return sem_wait(sops);
}
```

5. Function to log semaphore operations:

```c
#include <stdio.h>
#include <syslog.h>

void log_semaphore_operation(struct sembuf *sops, int result) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Semaphore operation %d on semaphore %d with result %d", sops->sem_num, sops->sem_num, result);
    openlog("semaphore-logger", LOG_PID | LOG_CONS, LOG_INFO);
    syslog(LOG_INFO, "%s", log_msg);
    closelog();
}
```']

