#define MEMORY_LIMIT (100 * 1024 * 1024) // Adjustable memory limit in bytes
#define RECORD_COUNT 100
#define MAX_PAYLOAD_SIZE 128
#define MIN_VALUE 1
#define MAX_VALUE INT_MAX - MIN_VALUE

typedef struct {
    int rnti;
    unsigned short rx_ue_information_tag;
    unsigned char crc_flag;
    char payload[MAX_PAYLOAD_SIZE];
} NFAPI_RX_MESSAGE_T;

typedef struct {
    long offsets[RECORD_COUNT];
    int keys[RECORD_COUNT];
    int values[RECORD_COUNT];
} RECORDS_T;

void log_memory() {
    printf("Memory usage: %.2f MB\n", (float)malloc_usable_size(0) / (1024 * 1024));
}

int init_data_structures(NFAPI_RX_MESSAGE_T** rx_messages, RECORDS_T** records, int* error_code) {
    size_t payload_size;
    void* memory_limit_marker;

    *error_code = 0;

    // Initialize and allocate memory for the RX messages array
    *rx_messages = malloc((SIZE_MAX / sizeof(NFAPI_RX_MESSAGE_T)) < RECORD_COUNT ? RECORD_COUNT : SIZE_MAX / sizeof(NFAPI_RX_MESSAGE_T));
    if (!*rx_messages) {
        *error_code = 1;
        return -1;
    }
    memory_limit_marker = malloc(sizeof(char));
    if (malloc_usable_size(memory_limit_marker) + sizeof(NFAPI_RX_MESSAGE_T) * RECORD_COUNT > MEMORY_LIMIT) {
        free(*rx_messages);
        free(memory_limit_marker);
        *error_code = 2;
        return -1;
    }
    log_memory();

    // Initialize and allocate memory for the payloads
    for (int i = 0; i < RECORD_COUNT; ++i) {
        (*rx_messages)[i].payload[0] = '\0';
        payload_size = sizeof((*rx_messages)[i].payload);
        (*rx_messages)[i].payload = realloc((*rx_messages)[i].payload, payload_size);
        if (!(*rx_messages)[i].payload) {
            free(*rx_messages);
            free(memory_limit_marker);
            *error_code = 3;
            return -1;
        }
    }

    // Initialize and allocate memory for the records array
    *records = malloc((SIZE_MAX / sizeof(RECORDS_T)) < RECORD_COUNT ? RECORD_COUNT : SIZE_MAX / sizeof(RECORDS_T));
    if (!*records) {
        free(*rx_messages);
        free(memory_limit_marker);
        *error_code = 4;
        return -1;
    }

    return 0;
}

void generate_record(NFAPI_RX_MESSAGE_T* rx_message, RECORDS_T* records, int* error_code) {
    int offset, key;

    *error_code = 0;

    // Generate a random key and find the corresponding offset index
    do {
        key = rand() % (RECORD_COUNT - 1);
    } while (key >= records->keys[0] && key < records->keys[RECORD_COUNT]);

    offset = records->offsets[key];

    // Check bounds and generate a random value within the specified range
    if (offset >= 0 && offset < INT_MAX) {
        rx_message->rnti = rand() % INT_MAX;
        rx_message->rx_ue_information_tag = rand() % 256;
        rx_message->crc_flag = rand() % 2;
    } else {
        *error_code = 5;
        return;
    }

    // Update the record and offset structures with the new values
    records->keys[RECORD_COUNT] = rx_message->rnti;
    records->values[key] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    records->offsets[RECORD_COUNT] = offset + 1;
}

