typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} nfadb_t;

int createNfadbAndValidateConnection(nfadb_t** db, const char* title, NFAPI_CRC_INDICATION_PDU_T(*callback)(unsigned int seed)) {
    if (!db || !title || !callback)
        return -1; // invalid input

    *db = malloc(sizeof(nfadb_t));
    if (!*db)
        return -2; // memory allocation failure

    (*db)->capacity = 0;
    (*db)->count = 0;
    pthread_mutex_init(&(*db)->lock, NULL);

    // create and validate the callback function pointer
    if (!(*db)->data = callback(rand())) {
        free(*db);
        return -3; // callback function failure
    }

    // perform thread-safe operation: increment count and check capacity
    pthread_mutex_lock(&(*db)->lock);
    while ((*db)->capacity == (*db)->count) {
        if (realloc((*db)->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ((*db)->capacity + 1)) == NULL) {
            free(*db);
            pthread_mutex_unlock(&(*db)->lock);
            return -4; // memory reallocation failure
        }
        (*db)->capacity++;
    }
    (*db)->data[(*db)->count++] = (*db)->data;
    pthread_mutex_unlock(&(*db)->lock);

    return 0; // success
}
