        Path inputFile = Paths.get(args[0]);
        FileTemp tmpFile = new FileTemp("temp");

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(inputFile.toFile()), BUFFER_SIZE))){
            long totalProcessed = 0;
            long startTime = System.currentTimeMillis();
            while (totalProcessed < keys.length && reader.ready()) {
                int key = reader.readLine().trim().isEmpty() ? 0 : Integer.parseInt(reader.readLine());
                if (key >= MIN_KEY && key <= MAX_KEY) {
                    records[totalProcessed++] = records[totalProcessed - 1].updateKey((long) key * RECORD_SIZE);
                } else {
                    System.err.println("Warning: Invalid entry encountered in file.");
                }
                if (totalProcessed % BUFFER_SIZE == 0) {
                    executeSubprocess(keys, offsets, records, tmpFile);
                }
            }

            if (totalProcessed > 0 && totalProcessed < keys.length) {
                executeSubprocess(keys, offsets, Arrays.copyOfRange(records, 0, totalProcessed), tmpFile);
            }

            long largestKey = findLargestKey(keys);
            System.out.println("Finished processing. Largest key: " + largestKey);

            logProcessing(startTime);
        } catch (IOException e) {
            System.err.println("Error reading input file: " + e.getMessage());
        } finally {
            tmpFile.delete();
        }
    }

    private static int[] generateKeysArray(int minKey, int maxKey) {
        int length = (maxKey - minKey) / BUFFER_SIZE * BUFFER_SIZE + BUFFER_SIZE;
        int[] keys = new int[length];
        for (int i = 0; i < keys.length; ++i) {
            keys[i] = minKey + RANDOM.nextInt(maxKey - minKey + 1);
        }
        return keys;
    }

    private static long findLargestKey(int[] keys) {
        long largestKey = Long.MIN_VALUE;
        for (int key : keys) {
            largestKey = Math.max(largestKey, key);
        }
        return largestKey;
    }

    private static void executeSubprocess(int[] keys, long[] offsets, Record[] records, FileTemp tmpFile) throws Exception {
        if (tmpFile.exists()) {
            tmpFile.delete();
        }

        int batchSize = Math.min(keys.length / 10, BUFFER_SIZE);
        int[] subsetKeys = Arrays.copyOfRange(keys, 0, batchSize);
        long[] subsetOffsets = Arrays.copyOfRange(offsets, 0, batchSize * RECORD_SIZE);
        Record[] subsetRecords = Arrays.copyOfRange(records, 0, batchSize);

        byte[] inputData = serializeData(subsetKeys, subsetOffsets, subsetRecords);
        Path outputFile = tmpFile.createTempFile("data", ".bin");

        ProcessBuilder processBuilder = new ProcessBuilder("java", "Subprocess", Integer.toString(batchSize), outputFile.toAbsolutePath().toString());
        processBuilder.directory(new File(System.getProperty("user.dir")));

        Process process = processBuilder.start();
        try (FileOutputStream fos = new FileOutputStream(outputFile.toFile())) {
            fos.write(inputData);
        } catch (IOException e) {
            System.err.println("Error writing temporary file: " + e.getMessage());
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.err.println("Subprocess failed with error code: " + exitCode);
        }
    }

    private static byte[] serializeData(int[] keys, long[] offsets, Record[] records) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (int key : keys) {
            baos.writeInt(key);
        }
        for (long offset : offsets) {
            baos.writeLong(offset);
        }
        for (Record record : records) {
            baos.writeInt(record.getKey());
            baos.writeLong(record.getOffset());
        }
        return baos.toByteArray();
    }

    private static void initDB() throws Exception {
        String url = "jdbc:mysql://localhost:3306/mydb";
        String user = "username";
        String password = "password";
        dbConnection = DriverManager.getConnection(url, user, password);
    }

    private static void logProcessing(long startTime) throws Exception {
        long endTime = System.currentTimeMillis();
        String logFile = "processing_log.txt";
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(logFile, true))) {
            writer.write("Start time: " + startTime + "\n");
            writer.write("End time: " + endTime + "\n");
            // Write any encountered errors here
        } catch (IOException e) {
            System.err.println("Error logging processing: " + e.getMessage());
        }
    }
}

