    virtual EVP_CIPHER_CTX* createContext() = 0;
    virtual void destroyContext(EVP_CIPHER_CTX*) = 0;
};

// AES-256-CBC cipher implementation as an example
class AESEncryption : public CipherHandler {
public:
    EVP_CIPHER_CTX* createContext() override {
        EVP_CIPHER_CTX* ctx;
        EVP_EncryptInit(&ctx, EVP_aes_256_cbc());
        return ctx;
    }

