void processFile(const std::string& filePath, CipherHandler* cipher, bool encrypt) {
    std::ifstream ifs(filePath, std::ios::binary | (encrypt ? std::ios_base::out : std::ios_base::in));
    if (!ifs.is_open()) {
        std::cerr << "Error opening file: " << filePath << "\n";
        return;
    }

    EVP_CIPHER_CTX* ctx = cipher->createContext();
    unsigned char buffer[1024]; // Adjust buffer size as needed

    while (ifs.read(reinterpret_cast<char*>(buffer), sizeof(buffer))) {
        int len = ifs.gcount();
        EVP_EncryptUpdate(ctx, buffer, &len);
    }

    if (!encrypt) {
        // Read remaining data and encrypt it
        ifs.read(reinterpret_cast<char*>(buffer), sizeof(buffer));
        while (!ifs.eof()) {
            int len = ifs.gcount();
            EVP_EncryptUpdate(ctx, buffer, &len);
        }
    } else {
        // Final encryption and write to file
        EVP_EncryptFinal_ex(ctx, buffer, nullptr);
        std::ofstream ofs(filePath, std::ios::binary | std::ios_base::trunc | (std::ios_base::out));
        ofs.write(reinterpret_cast<const char*>(buffer), EVP_CIPHER_CTX_size(ctx));
    }

    cipher->destroyContext(ctx);
}

