    std::vector<std::thread> threads;
    threads.reserve(numThreads);

    for (size_t i = 0; i < filePaths.size() && threads.size() < numThreads; ++i) {
        threads.push_back(std::thread(&processFile, filePaths[i], cipher, encrypt));
