['```java
import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class TextFileProcessor {
    private static final Logger LOGGER = Logger.getLogger(TextFileProcessor.class.getName());
    private static final int MAX_CONCURRENT_THREADS = 200;
    private ConcurrentLinkedQueue<String> queue = new ConcurrentLinkedQueue<>();
    private ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);
    private ConcurrentHashMap<File, FileWriter> writerMap = new ConcurrentHashMap<>();

    public void processTextFile(String inputFilePath) {
        validateInputFile(inputFilePath);

        try (BufferedReader reader = new BufferedReader(new FileReader(inputFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                queue.add(line.toUpperCase());
            }
        } catch (IOException e) {
            LOGGER.severe("Error reading the input file: " + e.getMessage());
        }

        startProcessing();
    }

    private void validateInputFile(String inputFilePath) {
        if (inputFilePath == null || inputFilePath.isEmpty()) {
            throw new IllegalArgumentException("The input file path cannot be null or empty.");
        }

        File file = new File(inputFilePath);
        if (!file.exists() || !file.isFile() || !file.canRead()) {
            throw new IllegalArgumentException("The provided file is not a readable file.");
        }
    }

    private void startProcessing() {
        while (!queue.isEmpty() || executor.getActiveCount() < MAX_CONCURRENT_THREADS) {
            Runnable worker = new WorkerRunnable();
            if (!executor.submit(worker).isDone()) {
                break;
            }
        }
    }

    private class WorkerRunnable implements Runnable {
        @Override
        public void run() {
            while (queue.isEmpty() && executor.getActiveCount() < MAX_CONCURRENT_THREADS) {
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    LOGGER.info("Worker thread was interrupted.");
                }
            }

            if (!queue.isEmpty()) {
                String line = queue.poll();
                File outputFile = new File(inputFilePath + ".uppercase").getAbsoluteFile();
                FileWriter writer;
                synchronized (writerMap) {
                    writer = writerMap.computeIfAbsent(outputFile, f -> {
                        try {
                            return new FileWriter(f);
                        } catch (IOException e) {
                            LOGGER.severe("Error creating the output file: " + e.getMessage());
                            throw new RuntimeException(e);
                        }
                    });
                }
                try {
                    writer.write(line);
                    writer.flush();
                } catch (IOException e) {
                    LOGGER.severe("Error writing to the output file: " + e.getMessage());
                } finally {
                    try {
                        writer.close();
                    } catch (IOException e) {
                        LOGGER.warning("Warning while closing the output file: " + e.getMessage());
                    }
                }
            }
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            LOGGER.info("Worker threads were interrupted during shutdown.");
        }
    }
}
