#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    long value;
} Record;

struct HashTable {
    unsigned int size;
    unsigned int capacity;
    Record** data;
    pthread_mutex_t mutex;
};

void resize_hash_table(struct HashTable* table) {
    unsigned int new_capacity = table->capacity * 2;
    Record** new_data = malloc(new_capacity * sizeof(Record*));
    memcpy(new_data, table->data, table->size * sizeof(Record*));
    pthread_mutex_destroy(&table->mutex);
    free(table->data);
    table->capacity = new_capacity;
    table->data = new_data;
    pthread_mutex_init(&table->mutex, NULL);
}

unsigned int hash(int key, unsigned int size) {
    return key % size;
}

void insert_record(struct HashTable* table, Record* record) {
    pthread_mutex_lock(&table->mutex);
    unsigned int index = hash(record->key, table->size);
    while (table->data[index]) {
        if (table->data[index]->key == record->key) {
            record->value = table->data[index]->value;
            free(table->data[index]);
            break;
        }
        index = (index + 1) % table->size;
    }
    if (!table->data[index]) {
        table->data[index] = record;
    } else {
        Record* temp = malloc(sizeof(Record));
        memcpy(temp, record, sizeof(Record));
        table->data[index]->value += temp->value;
        free(temp);
    }
    pthread_mutex_unlock(&table->mutex);
}

Record* find_record(struct HashTable* table, int key) {
    unsigned int index = hash(key, table->size);
    Record* record = NULL;
    while ((record = table->data[index])) {
        if (record->key == key) {
            break;
        }
        index = (index + 1) % table->size;
    }
    return record;
}

void init_hash_table(struct HashTable* table, unsigned int capacity) {
    table->size = capacity;
    table->capacity = capacity;
    table->data = malloc(capacity * sizeof(Record*));
    pthread_mutex_init(&table->mutex, NULL);
}

void cleanup_hash_table(struct HashTable* table) {
    for (unsigned int i = 0; i < table->size; ++i) {
        Record* record = table->data[i];
        if (record) {
            free(record);
        }
    }
    free(table->data);
    pthread_mutex_destroy(&table->mutex);
}

void generate_random_records(struct HashTable* table, unsigned int num_records, unsigned int min, unsigned int max) {
    for (unsigned int i = 0; i < num_records; ++i) {
        Record* record = malloc(sizeof(Record));
        record->key = rand() % (max - min + 1) + min;
        record->value = rand() % 1000000000L;
        insert_record(table, record);
    }
}

struct HashTable* create_hash_table(unsigned int capacity, unsigned int num_records, unsigned int min, unsigned int max) {
    struct HashTable* table = malloc(sizeof(struct HashTable));
    init_hash_table(table, capacity);
    generate_random_records(table, num_records, min, max);
    return table;
}
```
This code provides the basic structure for a hash table that manages memory dynamically and supports concurrent access. The `create_hash_table()` function initializes the table with a specified capacity, generates random records within a given range, and returns a pointer to the table. The `insert_record()`, `find_record()`, and `cleanup_hash_table()` functions handle insertion, lookup, and cleanup operations, respectively. The hash table dynamically resizes when necessary, and error handling is incorporated to manage null inputs and out-of-range values.

This code can be extended by implementing additional functionality, such as thread safety using pthread synchronization primitives, optimizing for space and time complexity, or incorporating more advanced data structures like self-balancing binary search trees or skip lists for better performance under fluctuating workloads.']

