#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>
#include <string.h>

typedef struct Record {
    long value;
    char identifier;
} Record;

Record* resizable_array(size_t size, size_t* new_size) {
    Record* array = malloc(size * sizeof(Record));
    if (!array) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }
    *new_size = size;
    return array;
}

void resize_array(Record** array, size_t* capacity, size_t new_capacity) {
    Record* new_array = realloc(*array, new_capacity * sizeof(**array));
    if (!new_array) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

long* alloc_offsets(size_t size) {
    long* offsets = malloc(size * sizeof(long));
    if (!offsets) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* alloc_keys(size_t size) {
    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }
    return keys;
}

long read_long(FILE* file) {
    long value;
    fscanf(file, "%ld", &value);
    if (feof(file)) {
        perror("Premature end of file");
        exit(EXIT_FAILURE);
    }
    return value;
}

char read_char(FILE* file) {
    char c;
    fscanf(file, "%c", &c);
    if (feof(file)) {
        perror("Premature end of file");
        exit(EXIT_FAILURE);
    }
    return c;
}

int processFileAndManageMemory(const char* path) {
    struct stat sb;
    int num_records = 0;
    long range_min, range_max;
    size_t offsets_size = 1, keys_size = 1, records_capacity = 8;
    Record* records = resizable_array(records_capacity, &records_capacity);
    long* offsets = alloc_offsets(offsets_size);
    int* keys = alloc_keys(keys_size);

    if (stat(path, &sb) == -1) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }

    FILE* file = fopen(path, "r");
    if (!file) {
        perror("File not found");
        exit(EXIT_FAILURE);
    }

    range_min = read_long(file);
    range_max = read_long(file);

    // Initialize arrays with random records within the specified range
    for (size_t i = 0; i < records_capacity; ++i) {
        records[i].value = range_min + rand() % (range_max - range_min + 1);
        records[i].identifier = rand() % 256;
    }

    size_t current_offset = 0, record_index = 0;
    while (!feof(file)) {
        long offset = ftell(file);
        if (record_index >= records_capacity) {
            resize_array(records, &records_capacity, records_capacity * 2);
        }
        char identifier = read_char(file);
        Record current_record = { read_long(file), identifier };
        records[record_index++] = current_record;
        offsets[current_offset++] = offset;
        keys[current_offset - 1] = identifier;
    }

    fclose(file);

    // Dynamic resizing of offsets and keys arrays based on the actual number of records
    offsets_size = current_offset;
    keys_size = record_index;

    printf("Number of records: %d\n", record_index);
    for (size_t i = 0; i < record_index; ++i) {
        printf("Record %ld: value=%ld, identifier=%c\n", offsets[i], records[i].value, records[i].identifier);
    }

    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
```

This code provides a starting point for the function `processFileAndManageMemory`. The function dynamically allocates memory for the required arrays, initializes them with random data within specified ranges, and reads the file synchronously. It also handles errors during memory allocation and file reading. Additionally, it dynamically resizes the record array based on the actual number of records found in the file, ensuring efficient memory usage under varying loads.']

