struct mem_manager {
    void *offsets;
    void *keys;
    void *records;
    size_t offset_capacity;
    size_t key_capacity;
    size_t record_capacity;
    pthread_mutex_t lock;
    record_size_t record_size;
    random_range_t random_range;
};

void mem_manager_init(struct mem_manager *mm, size_t offset_size, size_t key_size,
                      const record_size_t *record_size, const random_range_t *random_range) {
    mm->offsets = malloc(offset_size * offset_size);
    mm->keys = malloc(key_size * offset_size);
    mm->records = calloc(1, sizeof(struct record));
    mm->offset_capacity = offset_size;
    mm->key_capacity = key_size * offset_size;
    mm->record_capacity = 1;
    mm->record_size = *record_size;
    mm->random_range = *random_range;
    pthread_mutex_init(&mm->lock, NULL);
}

void *resize_records(void *data, size_t new_capacity) {
    struct mem_manager *mm = data;
    void *new_records = realloc(mm->records, new_capacity * sizeof(struct record));
    if (new_records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }
    mm->records = new_records;
    mm->record_capacity = new_capacity;
    return mm->records;
}

long *get_offsets(struct mem_manager *mm) {
    pthread_mutex_lock(&mm->lock);
    long *offsets = mm->offsets;
    pthread_mutex_unlock(&mm->lock);
    return offsets;
}

int *get_keys(struct mem_manager *mm) {
    pthread_mutex_lock(&mm->lock);
    int *keys = mm->keys;
    pthread_mutex_unlock(&mm->lock);
    return keys;
}

struct record *get_records(struct mem_manager *mm) {
    pthread_mutex_lock(&mm->lock);
    struct record *records = mm->records;
    pthread_mutex_unlock(&mm->lock);
    return records;
}

void fill_record_array(struct mem_manager *mm) {
    for (long i = 0; i < mm->record_capacity; ++i) {
        struct record *r = mm->records + i;
        r->value = rand() % (mm->random_range.max_val - mm->random_range.min_val + 1) + mm->random_range.min_val;
        r->identifier = 'A' + (i % 26);
    }
}
