#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct log_entry {
    char message[256];
    int severity;
    struct log_entry *next;
    time_t timestamp;
} log_entry;

typedef struct hash_table {
    unsigned long num_buckets;
    unsigned long current_size;
    log_entry **entries;
} hash_table;

void init_hash_table(hash_table *ht, unsigned long num_buckets) {
    ht->num_buckets = num_buckets;
    ht->current_size = 0;
    ht->entries = calloc(num_buckets, sizeof(log_entry*));
}

unsigned long hash(time_t timestamp) {
    // A simple linear congruential function to generate a hash value between 0 and num_buckets-1.
    return (timestamp % ht->num_buckets);
}

void insert_log_entry(hash_table *ht, log_entry *entry) {
    // Insert the entry into the linked list at the appropriate position based on timestamp and update current_size.
    unsigned long idx = hash(entry->timestamp);
    entry->next = ht->entries[idx];
    ht->entries[idx] = entry;
    ht->current_size++;
}

void remove_log_entry(hash_table *ht, time_t timestamp) {
    // Remove the entry with the specified timestamp from the hash table and update current_size.
    unsigned long idx = hash(timestamp);
    log_entry* current = ht->entries[idx];
    log_entry* prev = NULL;

    while (current != NULL) {
        if (current->timestamp == timestamp) {
            if (prev == NULL) {
                ht->entries[idx] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            ht->current_size--;
            break;
        }
        prev = current;
        current = current->next;
    }
}

log_entry* find_oldest_entry(hash_table *ht) {
    // Find the oldest log entry in the hash table and return it.
    log_entry *oldest = NULL, *current = ht->entries[0];
    time_t oldest_timestamp = LONG_MAX;

    for (unsigned long i = 0; i < ht->num_buckets; ++i) {
        current = ht->entries[i];
        while (current != NULL) {
            if (current->timestamp < oldest_timestamp) {
                oldest = current;
                oldest_timestamp = current->timestamp;
            }
            current = current->next;
        }
    }

    return oldest;
}

