    public async Task<IDataReader> ExecuteQueryAsync(byte[] command)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                return await connection.ExecuteReaderAsync(command, System.Data.CommandType.Text);
            }
        }
