typedef struct {
    double x, y;
    time_t time;
} Point;

const int MAX_POINTS = 1000000;
const int MEMORY_LIMIT = (MAX_POINTS * sizeof(Point)) / (2 * 1024 * 1024); // Adjustable memory limit in MB
int memory_usage = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

enum { SUCCESS, MEMORY_ERROR, DATABASE_ERROR, SERIALIZATION_ERROR } result;

void* generate_point(void* arg) {
    (void)arg; // Ignore argument for thread safety

    Point* point = malloc(sizeof(Point));
    if (!point) {
        pthread_mutex_lock(&log_mutex);
        printf("Error: Memory allocation failure\n");
        pthread_mutex_unlock(&log_mutex);
        return (void*)MEMORY_ERROR;
    }

    double x = rand() % 10 + 1; // Adjust range as needed
    double y = sqrt(10 - (x * x)); // Ensures coordinates remain within a defined geographical boundary (square with side length 10)

    time_t timestamp = time(NULL);
    point->x = x;
    point->y = y;
    point->time = timestamp;

    memory_usage += sizeof(Point);

    pthread_mutex_lock(&log_mutex);
    printf("Generated Point: (%f, %f) at time %ld\n", point->x, point->y, point->time);
    if (memory_usage > MEMORY_LIMIT) {
        free(point);
        pthread_mutex_unlock(&log_mutex);
        return (void*)MEMORY_ERROR;
    }
    pthread_mutex_unlock(&log_mutex);

    // Database interaction, serialization, etc. (implemented elsewhere)

    return (void*)SUCCESS;
}

result init_data() {
    pthread_t threads[MAX_POINTS];

    for (int i = 0; i < MAX_POINTS; ++i) {
        if (pthread_create(&threads[i], NULL, generate_point, NULL)) {
            // Handle pthread_create failure
            return DATABASE_ERROR;
        }
    }

    for (int i = 0; i < MAX_POINTS; ++i) {
        void* res;
        if (pthread_join(threads[i], &res)) {
            // Handle pthread_join failure
            return DATABASE_ERROR;
        }

        if (res == MEMORY_ERROR || res == SERIALIZATION_ERROR) {
            return (enum { SUCCESS, MEMORY_ERROR, DATABASE_ERROR, SERIALIZATION_ERROR })res;
        }
    }

    return SUCCESS;
}
