#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t list_lock;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for the list\n");
        return NULL;
    }
    pthread_mutex_init(&list->list_lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

Node* allocate_node() {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for the node\n");
        return NULL;
    }
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

bool is_valid_rnti(uint16_t rnti) {
    if (rnti == 0 || rnti >= 65536) {
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
        return false;
    }
    return true;
}

bool insert_node(List* list, Node* node) {
    if (!list || !node) {
        fprintf(stderr, "Invalid input: list or node is NULL\n");
        return false;
    }
    pthread_mutex_lock(&list->list_lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        node->next = NULL;
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->list_lock);
    return true;
}

Node* find_node(List* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG.rnti == rnti) {
            break;
        }
        pthread_mutex_lock(&current->lock);
        current = current->next;
        pthread_mutex_unlock(&current->lock);
    }
    return current;
}

void destroy_node(Node* node) {
    if (!node) {
        fprintf(stderr, "Invalid input: node is NULL\n");
        return;
    }
    // Free the data and other resources as needed
    free(node);
}

bool remove_node(List* list, Node* node) {
    if (!list || !node) {
        fprintf(stderr, "Invalid input: list or node is NULL\n");
        return false;
    }
    pthread_mutex_lock(&list->list_lock);
    if (list->size == 0) {
        pthread_mutex_unlock(&list->list_lock);
        fprintf(stderr, "List is empty\n");
        return false;
    }
    if (node == list->head) {
        list->head = node->next;
        if (list->head) {
            list->head->prev = NULL;
        } else {
            list->tail = NULL;
        }
    } else if (node == list->tail) {
        list->tail = node->prev;
        if (list->tail) {
            list->tail->next = NULL;
        } else {
            list->head = NULL;
        }
    } else {
        Node* prev = node->prev;
        Node* next = node->next;
        prev->next = next;
        if (next) {
            next->prev = prev;
        }
    }
    list->size--;
    pthread_mutex_unlock(&list->list_lock);
    destroy_node(node);
    return true;
}
