using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;
using System.Numerics;

public class DataProcessor
{
    private ConcurrentBag<int> dataStream;
    public int StreamCount { get => dataStream.Count; }
    public BigInteger AverageValue { get; private set; }
    public int MaxValue { get => dataStream.Max(); }

    public DataProcessor()
    {
        dataStream = new ConcurrentBag<int>();
    }

    public async Task AddData(int value)
    {
        await Task.Run(() => dataStream.Add(value));
    }

    public int FilterStream(Func<int, bool> predicate)
    {
        return dataStream.Where(predicate).Count();
    }

    public void TransformStream(Func<int, int> transform)
    {
        var transformed = dataStream.Select(transform);
        dataStream = new ConcurrentBag<int>(transformed);
    }

    public void AggregateStats()
    {
        BigInteger sum = 0;

        ParallelLoopResult result = ParallelLoopResult.Stopped;
        Action<int> action = v => sum += (BigInteger)v;

        if (dataStream.Any())
        {
            dataStream.AsParallel().ForAll(action);
            AverageValue = sum / StreamCount;
        }
    }

    public void ResetStream()
    {
        dataStream.Clear();
        AverageValue = 0;
    }
}
