// Global variables for tracking commands and their statuses
pid_t command_pids[10];
int num_running = 0;
struct timespec start_times[10], end_times[10];
int exit_statuses[10] = {-1}; // -1 indicates not yet executed
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to execute shell command and track its status
void run_command(char* cmd) {
    pthread_mutex_lock(&lock);
    int i;
    for (i = 0; i < num_running && exit_statuses[i] != -1; ++i); // Find an empty slot or a completed command slot
    if (i == num_running) { // If all slots are full, wait for one to become available
        while (num_running >= 5 || exit_statuses[i] != -1 for (i = 0; i < num_running)) usleep(100000);
    }

    command_pids[i] = fork();
    if (!command_pids[i]) { // Child process executes the command
        execl("/bin/bash", "/bin/bash", "-c", cmd, NULL);
        perror("execl error");
        exit(1);
    }

    gettimeofday(&start_times[i], NULL); // Record start time of command execution
    num_running++;
    pthread_mutex_unlock(&lock);
}

// Function to handle child process termination and log results
void wait_for_completion(int idx) {
    pthread_mutex_lock(&lock);
    while (command_pids[idx] > 0 && exit_statuses[idx] == -1) { // Wait for the command to finish and record its status
        if (waitpid(command_pids[idx], &exit_statuses[idx], WNOHANG) > 0) {
            gettimeofday(&end_times[idx], NULL); // Record end time of command execution
        }
    }

    pthread_mutex_unlock(&lock);
}

// Function to log command results, handling slow commands and potential resource exhaustion
void log_results() {
    int i;
    for (i = 0; i < num_running; ++i) wait_for_completion(i); // Wait for all running commands to complete

    for (i = 0; i < num_running; ++i) {
        if (exit_statuses[i] != -1) { // If the command completed successfully
            struct timespec elapsed;
            if (timersub(&end_times[i], &start_times[i], &elapsed); elapsed.tv_sec > 30) { // If the command took longer than 30 seconds
                printf("Command %s took %ld seconds to execute\n", command_pids[i] > 0 ? "failed (still running)" : command_args[i], elapsed.tv_sec);
            } else {
                printf("Command %s completed successfully in %ld seconds\n", command_pids[i] > 0 ? "failed (still running)" : command_args[i], elapsed.tv_sec);
            }
        }
    }
}
