```cpp
#include <iostream>
#include <list>
#include <mutex>
#include <new>

constexpr size_t RECORD_SIZE = sizeof(Record);
constexpr size_t BUFFER_SIZE = 1024 * 1024; // 1MB buffer

struct Record {
    int key;
    long offset;
    bool validity;
};

class Allocator {
public:
    Allocator(size_t size, void* base) : _size(size), _base(base) {}

    void* allocate(std::size_t n, std::new_handler on_failure) {
        auto p = _buffer + _current;
        if (n <= (_current - _buffer)) {
            _current += n;
            return p;
        }

        // Allocate more buffer space if needed
        char* new_base = static_cast<char*>(::operator new[](BUFFER_SIZE, on_failure));
        if (new_base == nullptr) {
            throw std::bad_alloc();
        }
        _buffer = new_base;
        _current = _buffer + BUFFER_SIZE;

        return p;
    }

    void deallocate(void* p, std::size_t n) noexcept {
        static_cast<void*>(_buffer)->~char[_current - static_cast<char*>(p)];
        _current -= n;
    }

private:
    size_t _size;
    char* _base;
    char* _buffer;
    char* _current;
};

std::mutex mtx;
std::list<Record, Allocator> records(new Allocator(RECORD_SIZE, nullptr));

void init_record_range(Record& record, int min, int max) {
    record.key = (min + std::rand() / (RAND_MAX / (max - min + 1))) + min;
    record.offset = 0;
    record.validity = true;
}

void insert(int key) {
    std::unique_lock<std::mutex> lock(mtx);

    auto it = records.begin();
    while (it != records.end()) {
        if (!it->validity) {
            init_record_range(*it);
            break;
        }

        if (it->key == key) {
            it->validity = true;
            break;
        }

        ++it;
    }

    if (it == records.end()) {
        auto new_record = records.emplace_back();
        init_record_range(new_record);
        new_record.key = key;
        new_record.validity = true;
    }
}

Record* find(int key) {
    std::unique_lock<std::mutex> lock(mtx);

    auto it = records.begin();
    while (it != records.end()) {
        if (!it->validity || it->key != key) {
            ++it;
            continue;
        }

        return &*it;
    }

    return nullptr;
}

void remove(int key) {
    std::unique_lock<std::mutex> lock(mtx);

    auto it = records.begin();
    while (it != records.end()) {
        if (!it->validity || it->key != key) {
            ++it;
            continue;
        }

        it->validity = false;
        break;
    }
}

void cleanup() {
    std::unique_lock<std::mutex> lock(mtx);

    records.clear();
    records.get_allocator().deallocate(records.data(), records.max_size());
}
```

