```c
void resize_array(Array_T* array, unsigned int windowSize, double smoothingFactor) {
    size_t currentLength = array->length;
    size_t newCapacity = (currentLength / windowSize) * smoothingFactor + windowSize;

    if (newCapacity < array->capacity) {
        // Compress array to save memory
        for (size_t i = currentLength; i < array->capacity; ++i) {
            array->packets[i].~NetworkPacket_T();
        }
        array->capacity = newCapacity;
    } else if (newCapacity > array->capacity) {
        // Expand array to accommodate more packets
        NetworkPacket_T* tempPackets = realloc(array->packets, sizeof(NetworkPacket_T) * newCapacity);
        if (!tempPackets) return;
        array->packets = tempPackets;
        array->capacity = newCapacity;
    }
}
