    }

    i >> j;

    if (!j.is_object()) {
        std::cerr << "Error: JSON data is not an object." << std::endl;
        return;
    }

    auto schemaJson = json::parse(schema); // Parse the schema
    if (!schemaJson.is_object()) {
        std::cerr << "Error: Schema is not a valid JSON object." << std::endl;
        return;
    }

    for (const auto& item : j.items()) {
        const auto& key = item.key();
        const auto& val = item.value();

        if (!schemaJson.contains(key)) {
            std::cerr << "Error: JSON data contains an unexpected key: " << key << std::endl;
            continue;
        }

        if (typeid(val) != typeid(schemaJson[key])) {
            std::cerr << "Error: Incompatible data types for key: " << key << ". Expected type: " << schemaJson[key].get_ref().type() << ", received type: " << val.get_ref().type() << std::endl;
            continue;
        }

        // Acquire the lock before updating the vector
        std::unique_lock<std::mutex> lock(mtx);
        vec.push_back({key, val.get<int>()});
    }
}

// Integrate with an external system to provide additional metadata about the JSON data
void integrateWithExternalSystem(const json& j) {
    // Implementation details here
}

