use tower::ServiceBuilder;
use hyper::{Client, Uri};
use std::sync::Arc;
use std::time::Duration;

const DEFAULT_CONNECT_TIMEOUT: Duration = Duration::from_secs(10);
const DEFAULT_READ_TIMEOUT: Duration = Duration::from_secs(30);
const MAX_RETRIES: usize = 3;
const INITIAL_RETRY_DELAY: Duration = Duration::from_millis(500);

pub struct CustomHttpClient {
    client: Arc<Client<hyper::client::connect::Builder>>,
}

impl CustomHttpClient {
    pub async fn new() -> Self {
        let builder = hyper::client::Builder::new();
        builder.connect_timeout(DEFAULT_CONNECT_TIMEOUT)
            .read_timeout(DEFAULT_READ_TIMEOUT)
            .build().await.unwrap();
        CustomHttpClient {
            client: Arc::new(builder),
        }
    }
}

pub struct RequestBuilder {
    urls: Vec<String>,
    http_client: Arc<CustomHttpClient>,
    timeout: Duration,
    retries: usize,
    retry_delay: Duration,
    disable_cert_validation: bool,
}

impl RequestBuilder {
    pub fn new(urls: Vec<String>) -> Self {
        Self {
            urls,
            http_client: Arc::new(CustomHttpClient::new()),
            timeout: DEFAULT_READ_TIMEOUT,
            retries: MAX_RETRIES,
            retry_delay: INITIAL_RETRY_DELAY,
            disable_cert_validation: false,
        }
    }

    pub fn with_timeout(mut self, timeout: Duration) -> Self {
        self.timeout = timeout;
        self
    }

    pub fn with_retries(mut self, retries: usize) -> Self {
        self.retries = retries.min(MAX_RETRIES);
        self
    }

    pub fn with_retry_delay(mut self, retry_delay: Duration) -> Self {
        self.retry_delay = retry_delay;
        self
    }

    pub fn disable_cert_validation(mut self, disable: bool) -> Self {
        self.disable_cert_validation = disable;
        self
    }

    async fn build_request(&self, uri: Uri) -> reqwest::Result<reqwest::Request> {
        let mut builder = hyper::Request::builder()?;
        builder = builder.uri(uri);

        // Configure timeout and retry logic using the `tower` crate here.

        if self.disable_cert_validation {
            // Configure certificate validation to be disabled for specific environments.
        }

        let client = self.http_client.client.clone();
        let request = builder.build(client).await?;
        Ok(request)
    }
}
```

