typedef struct {
    uint32_t bits_per_sample;
    uint32_t sample_per_pixel;
    uint32_t extra_samples_count;
    uint32_t extra_samples[];
} ImageInfo;

void tiff_parse(const char *archive_path, ImageInfo *image_info, size_t *metadata_size);
int extract_metadata(char *metadata, size_t metadata_size, json_t **out_metadata);

static void parse_extra_samples(TIFF *tif, ImageInfo *image_info) {
    uint16_t num_extra_samples;
    if (tiffGetField(tif, TIFFTAG_EXTRASAMPLES, &num_extra_samples) == 0) {
        image_info->extra_samples_count = num_extra_samples;
        if (image_info->extra_samples_count > 0) {
            image_info->extra_samples = realloc(image_info->extra_samples,
                                                sizeof(uint32_t) * image_info->extra_samples_count);
            for (size_t i = 0; i < image_info->extra_samples_count; ++i) {
                TIFFSamplersample extra_sample;
                if (tiffGetField(tif, TIFFTAG_EXTRASAMPLEVALUE, &extra_sample.value, sizeof(extra_sample.value)) != 1) {
                    image_info->extra_samples_count = 0;
                    break;
                }
                image_info->extra_samples[i] = extra_sample.value;
            }
        }
    }
}

static bool is_supported_bits(uint16_t bits) {
    return (bits == 1 || bits == 2 || bits == 4 || bits == 8 || bits == 16);
}

void tiff_parse(const char *archive_path, ImageInfo *image_info, size_t *metadata_size) {
    TIFF *tif = NULL;
    CurlHandle *handle = curl_easy_init();
    size_t bytes_read;
    char *buffer = malloc(4096);
    struct curl_slist *headers = NULL;

    // Initialize image info structure with default values
    memset(image_info, 0, sizeof(*image_info));

    // Extract TIFF images from compressed archive using libcurl
    curl_easy_setopt(handle, CURLOPT_URL, archive_path);
    curl_easy_setopt(handle, CURLOPT_NOBODY, 1L);
    curl_easy_setopt(handle, CURLOPT_HEADERFUNCTION, tiff_parse_headerfunction);
    curl_easy_setopt(handle, CURLOPT_WRITEDATA, buffer);

    headers = curl_slist_append(headers, "Accept-Encoding: identity");
    curl_easy_setopt(handle, CURLOPT_HTTPHEADER, headers);

    CURLcode res;
    res = curl_easy_perform(handle);

    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to download archive: %s\n", curl_easy_strerror(res));
        goto cleanup;
    }

    size_t archive_size = curl_easy_getinfo(handle, CURLINFO_SIZE_DOWNLOAD);
    if (archive_size <= 0) {
        fprintf(stderr, "Invalid archive size\n");
        goto cleanup;
    }

    tif = TIFFClientOpen("mem://", buffer, archive_size, IFNEWIMAGE);
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF image from memory\n");
        goto cleanup;
    }

    // Parse TIFF images and extract required metadata
    while (TIFFReadDirectory(tif) == 1) {
        ImageInfo temp_image_info;
        tiff_parse(TIFFName(tif), &temp_image_info, NULL);

        if (!is_supported_bits(temp_image_info.bits_per_sample)) {
            continue;
        }

        // Merge parsed image info with current image info and update count of extra samples
        temp_image_info.extra_samples_count += image_info->extra_samples_count;
        if (temp_image_info.extra_samples_count > 0) {
            temp_image_info.extra_samples = realloc(temp_image_info.extra_samples,
                                                   sizeof(uint32_t) * temp_image_info.extra_samples_count);
            memcpy(temp_image_info.extra_samples + image_info->extra_samples_count,
                   image_info->extra_samples,
                   sizeof(uint32_t) * image_info->extra_samples_count);
        }

        image_info->bits_per_sample = temp_image_info.bits_per_sample;
        image_info->sample_per_pixel = temp_image_info.sample_per_pixel;
        image_info->extra_samples_count += temp_image_info.extra_samples_count;
        if (image_info->extra_samples_count > 0) {
            image_info->extra_samples = realloc(image_info->extra_samples,
                                               sizeof(uint32_t) * image_info->extra_samples_count);
            memcpy(image_info->extra_samples + image_info->extra_samples_count - temp_image_info.extra_samples_count,
                   temp_image_info.extra_samples,
                   sizeof(uint32_t) * temp_image_info.extra_samples_count);
        }
    }

    TIFFClose(tif);

cleanup:
    curl_easy_cleanup(handle);
    free(buffer);
    curl_slist_free_all(headers);
}

static size_t tiff_parse_headerfunction(void *ptr, size_t size, size_t nmemb, void *userp) {
