    uint16_t payload_len; // Should be multiple of 64 for cache line alignment
} PacketHeader;

typedef struct PayloadData {
    unsigned char* data;
    const PacketHeader* header;
} PayloadData;

void validate(const PacketHeader* header) {
    // Add validation checks here, such as source_ip and dest_ip within valid ranges,
    // protocol is a valid type, payload_len is non-zero and multiple of 64.
}

PayloadData* create_pipeline(unsigned int max_packets, unsigned int min_payload, unsigned int max_payload) {
    if (max_packets <= 0 || min_payload > max_payload) {
        perror("Invalid arguments");
        return NULL;
    }

    PayloadData* pipeline = malloc(sizeof(PayloadData) * max_packets);
    if (!pipeline) {
        perror("Memory allocation failed for pipeline.");
        return NULL;
    }

    PacketHeader* headers = calloc(max_packets, sizeof(PacketHeader));
    if (!headers) {
        free(pipeline);
        perror("Memory allocation failed for packet headers.");
        return NULL;
    }

    for (unsigned int i = 0; i < max_packets; ++i) {
        unsigned char* buffer = align_malloc(max_payload, BUFFER_ALIGNMENT);
        if (!buffer) {
            free(headers);
            free(pipeline);
            perror("Memory allocation failed for payload.");
            return NULL;
        }

        headers[i].src_ip = htonl(rand() << 16 | rand()); // Randomize source IP
        headers[i].dest_ip = htonl(rand() << 24 | rand() << 16 | rand()); // Randomize dest IP
        headers[i].protocol = rand() % 256; // Randomize protocol
        headers[i].payload_len = (rand() % ((max_payload - min_payload) / 64 + 1)) * 64 + min_payload;

        PayloadData payload{buffer, &headers[i]};
        validate(&headers[i]); // Validate each header before proceeding.
        pipeline[i] = payload;
    }

    return pipeline;
}

unsigned char* align_malloc(size_t size, size_t alignment) {
    size_t aligned_size = ((size + alignment - 1) / alignment) * alignment;
    unsigned char* ptr = malloc(aligned_size);
    if (ptr) memset((char *)ptr + size, 0, aligned_size - size);
    return ptr;
}
```

