        fclose(infile);
        fclose(outfile);
        return NULL;
    }

    while (!feof(infile)) {
        size_t readSize = fread(buffer, 1, ALIGNMENT, infile);
        if (readSize == 0) break; // End of file

        for (size_t i = 0; i < readSize; i += alignment) {
            PayloadData *pd = &payloads[i / ALIGNMENT];

            // Validate the packet header and parse data here, randomizing IP addresses as needed

            pd->data = malloc(pd->header->payloadLength);
            if (!pd->data) {
                perror("Error allocating memory for payload");
                free_payloads(payloads, i / ALIGNMENT); // Free up to the current position
                fclose(infile);
                fclose(outfile);
                return NULL;
            }

            size_t written = fwrite(pd->data, 1, pd->header->payloadLength, outfile);
            if (written != pd->header->payloadLength) {
                perror("Error writing to output file");
                free(pd->data);
                free_payloads(payloads, i / ALIGNMENT); // Free up to the current position
                fclose(infile);
                fclose(outfile);
                return NULL;
            }
        }
    }

    fclose(infile);
    fclose(outfile);

    return payloads;
}

void free_payloads(PayloadData *payloads, size_t index) {
    for (size_t i = 0; i < index; ++i) {
        if (payloads[i].data) free(payloads[i].data);
    }
}
