public class PokemonParser {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static Map<Integer, Function<JsonNode, Pokemon>> factories = new ConcurrentHashMap<>();

    public String toJson(Pokemon pokemon) throws IOException {
        return objectMapper.writeValueAsString(pokemon);
    }

    public Pokemon fromJson(String json) throws IOException {
        JsonNode node = objectMapper.readTree(json);
        int id = node.get("id").asInt();
        Function<JsonNode, Pokemon> factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("Invalid Pokémon ID: " + id);
        }
        return factory.apply(node);
    }

    public String getWeaknesses(Pokemon pokemon) {
        String type = pokemon.getType(); // Assuming you have a method to get the Pokémon's type
        switch (type) {
            case "FIRE":
                return "WATER, GROUND";
            case "WATER":
                return "ELECTRIC, GRASS";
            // Add more cases for other types here...
            default:
                return "DEFAULT WEAKNESSES"; // Use this when the type is not found or unavailable
        }
    }

    public static void registerFactory(int id, Function<JsonNode, Pokemon> factory) {
        factories.putIfAbsent(id, factory);
    }

    public Pokemon createPokemon(int id, JsonNode json) throws IOException {
        Function<JsonName, Pokemon> factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("Invalid Pokémon ID: " + id);
        }
        return factory.apply(json);
    }
}
