const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const async = require('async');
const nodemailer = require('nodemailer'); // For generating summary reports via email
const Discord = require('discord.js'); // For logging progress and errors in a discord channel
const caches = new Map();
const metadataServiceUrl = 'https://metadata-service.com';
const concurrencyLimit = 10;
const cacheDurationInMinutes = 10;

function readFile(filePath) {
  const cachedContent = caches.get(filePath);
  if (cachedContent && Date.now() - cachedContent.timestamp <= cacheDurationInMinutes * 60000) {
    return Promise.resolve(cachedContent.content);
  }

  return promisify(fs.readFile)(filePath).then((content) => {
    caches.set(filePath, { content, timestamp: Date.now() });
    return content;
  }).catch((err) => {
    console.error(`Error reading file ${filePath}:`, err);
  });
}

async function fetchMetadata(filePath) {
  try {
    const response = await fetch(`${metadataServiceUrl}/files/${encodeURIComponent(filePath)}`);
    if (!response.ok) throw new Error(`Failed to fetch metadata for file ${filePath}: ${response.statusText}`);
    return await response.json();
  } catch (err) {
    console.error(`Error fetching metadata for file ${filePath}:`, err);
    return null;
  }
}

async function processFile(filePath, callback) {
  try {
    const content = await readFile(filePath);
    const metadata = await fetchMetadata(filePath);

    // Process the file content and metadata as needed
    const summary = {
      fileName: path.basename(filePath),
      fileSize: content.length,
      content: truncateContent(content),
      metadata // Include metadata if available
    };

    callback(null, summary);
  } catch (err) {
    console.error(`Error processing file ${filePath}:`, err);
    callback(err);
  }
}

function truncateContent(content, length = 100) {
  return content.length > length ? content.slice(0, length - 1) + '...' : content;
}

async function run() {
  const directoryPath = './files'; // Replace with your desired starting directory

  const workQueue = async.queue((task, callback) => {
    const filePath = task;
    async.parallel([processFile.bind(null, filePath)], (err, results) => {
      if (err) return callback(err);
      // Generate summary report and send it via email or log it in a discord channel as needed
      callback(null, results[0]);
    });
  }, { concurrencyLimit });

  fs.readdir(directoryPath, (err, files) => {
    if (err) throw err;

    workQueue.push(directoryPath + '/' + file); // Iterate through each file in the directory and push it to the work queue
  });
}

run();
```

