        {"format", required_argument, NULL, 'f'},
        {"verbose", no_argument, NULL, 'v'},
        {"help", no_argument, NULL, 'h'},
        {0},
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "i:o:f:vh", long_options, NULL)) != -1) {
        switch (opt) {
            case 'i':
                opts.input_file = optarg;
                break;
            case 'o':
                opts.output_path = optarg;
                break;
            case 'f':
                opts.output_format = atoi(optarg);
                break;
            case 'v':
