    std::unique_ptr<Node> _root;
    mutable std::mutex _m; // Mutex for thread safety during Octree access and modification.
    std::unordered_map<std::shared_ptr<T>, Node*> _dataMap; // Map to store data associated with nodes.

public:
    Octree(int featureSize, int numLeafNodes, size_t dataCapacity, size_t maxMemory)
        : _featureSize(featureSize), _numLeafNodes(numLeafNodes), _dataCapacity(dataCapacity), _maxMemory(maxMemory) {
        _root = std::make_unique<Node>();
        _root->featureSize = featureSize;
        _root->isLeaf.store(static_cast<int>(!numLeafNodes), std::memory_order_relaxed);
    }

    ~Octree() {
        clear();
    }

    void insert(const std::shared_ptr<T>& data) {
        if (_maxMemory <= _dataMap.size() + sizeof(*this->root)) {
            garbageCollect();
        }
        Node* node = findNodeForData(data);
        if (node->children.empty()) {
            balanceTree(node);
        }
        node->children.emplace_back(std::make_unique<Node>());
        node->children.back().get()->parent = node;
        node->children.back().get()->featureSize = _featureSize;
        node->children.back().get()->isLeaf.store(static_cast<int>(_numLeafNodes > 0), std::memory_order_relaxed);
        if (_numLeafNodes == 0) {
            ++_numLeafNodes;
        }
        node->children.back().get()->data = data;
        _dataMap[data] = node->children.back().get();
    }

    void remove(const std::shared_ptr<T>& data) {
        Node* node = _dataMap[data].get();
        --_numLeafNodes;
        if (node->isLeaf.load() && node->children.empty()) {
            delete node;
            _dataMap.erase(data);
            return;
        }
        for (auto child : node->children) {
            if (_dataMap.find(child->data) != _dataMap.end()) {
                remove(child->data);
            }
        }
        delete node;
        _dataMap.erase(data);
    }

    std::shared_ptr<T> query(const glm::vec3& position) const {
        Node* node = findNodeForPosition(position, _root.get());
        if (node->isLeaf.load()) {
            return node->data;
        }
        for (const auto& child : node->children) {
            if (child->isLeaf.load() && position.x >= child->featureSize && position.y >= child->featureSize && position.z >= child->featureSize) {
                return child->data;
            }
        }
        return nullptr;
    }

    void clear() {
        std::vector<Node*> nodesToDelete;
        for (auto& [data, node] : _dataMap) {
            nodesToDelete.push_back(node.get());
        }
        for (const auto node : nodesToDelete) {
            delete node;
        }
        _dataMap.clear();
        _numLeafNodes = 0;
    }

    void garbageCollect() {
        // Implement a garbage collection mechanism here to reclaim unused memory and maintain memory limit.
    }

    std::vector<std::pair<Node*, size_t>> getStats() const {
        // Return detailed statistics on memory usage, tree balance, and performance metrics.
    }

private:
    Node* findNodeForData(const std::shared_ptr<T>& data) const {
        auto it = _dataMap.find(data);
        if (it != _dataMap.end()) {
            return it->second;
        }
        return nullptr;
    }

    Node* findNodeForPosition(const glm::vec3& position, Node* node) const {
        if (!node) {
            return nullptr;
        }
        if (position.x < node->featureSize && position.y < node->featureSize && position.z < node->featureSize) {
            return node;
        }
        for (const auto& child : node->children) {
            if (child->isLeaf.load()) {
                continue;
            }
            if (position.x >= child->featureSize && position.y >= child->featureSize && position.z >= child->featureSize) {
                return findNodeForPosition(position, child.get());
            }
        }
        return nullptr;
    }

    void balanceTree(Node* node) {
        // Implement a balancing strategy for the octree here to ensure optimal performance.
    }
};
```

