// Function to filter transactions based on specific criteria
struct Record* filter_transactions(int transaction_age, int num_transactions, double weighted_sum, size_t max_memory) {
    // Calculate the memory required for offsets, keys and records
    size_t offset_size = transaction_age * sizeof(long);
    size_t key_size = num_transactions * sizeof(int);
    size_t record_size = sizeof(struct Record) * num_transactions;

    // Allocate memory for offsets, keys and records, ensuring total memory usage does not exceed max_memory
    void* offsets = mmap(NULL, offset_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (offset_size + key_size + record_size > max_memory) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    void* keys = offsets + offset_size;
    void* records = keys + key_size;

    // Initialize offsets and keys with appropriate values
    for (int i = 0; i < transaction_age; ++i) {
        *(long *)((char *)offsets + i * sizeof(long)) = i;
        *(int *)((char *)keys + i * sizeof(int)) = 1 << i % 32; // Set keys to powers of 2 to simplify filtering
    }

    // Initialize records with random values in a specified range and update total_allocated and peak_memory accordingly
    struct Record* record_ptr = (struct Record *)records;
    for (int i = 0; i < num_transactions; ++i, ++record_ptr) {
        *record_ptr = (struct Record){rand() % 100 + 1}; // Adjust the range as needed
        total_allocated += sizeof(struct Record);
        if (total_allocated > peak_memory || peak_memory == 0)
            peak_memory = total_allocated;
    }

    log_memory("Before filtering");

    // Filter records based on the given criteria and return a new array containing only the filtered records
    size_t num_filtered = 0;
    struct Record* filtered_records = calloc(num_transactions, sizeof(struct Record));
    for (int i = 0; i < num_transactions; ++i, ++record_ptr, ++filtered_records) {
        if (weighted_sum > (*record_ptr).value)
            filtered_records[num_filtered++] = *record_ptr;
    }

    // Deallocate memory and update total_allocated accordingly
    munmap(offsets, offset_size);
    munmap(keys, key_size);
    free(record_ptr); // Free the extra records that were not filtered
    total_allocated -= (sizeof(struct Record) * num_transactions) - sizeof(struct Record) * num_filtered;

    log_memory("After filtering");

    return filtered_records;
}
