struct Skill {
    int id;
    double weight; // probability of being selected
    int cooldown; // in seconds
    bool onCooldown = false;
    std::time_t lastUsed;
};

std::vector<Skill> getSkills() {
    std::vector<Skill> skills;
    // Initialize your skills here with their weights, ids, and cooldowns

    return skills;
}

void updateCooldowns(std::vector<Skill>& skills) {
    for (auto& skill : skills) {
        if (!skill.onCooldown) continue;

        auto currTime = std::chrono::system_clock::now().time_since_epoch().count();
        auto elapsedSeconds = static_cast<double>(std::chrono::duration_cast<std::chrono::seconds>(currTime - skill.lastUsed).count());

        if (elapsedSeconds >= skill.cooldown) {
            skill.onCooldown = false;
        } else {
            skill.lastUsed += elapsedSeconds;
        }
    }
}

std::pair<int, int> selectSkill(const std::vector<Skill>& skills) {
    updateCooldowns(skills);

    double totalWeight = 0;
    for (const auto& skill : skills) totalWeight += skill.weight;

    std::mt19937 generator(std::chrono::system_clock::now().time_since_epoch().count());
    std::uniform_real_distribution<double> distribution(0, totalWeight);

    double accumulatedWeight = 0;
    int selectedSkillIndex = -1;

    for (size_t i = 0; i < skills.size(); ++i) {
        if (skills[i].onCooldown) continue;

        accumulatedWeight += skills[i].weight;
        if (accumulatedWeight > distribution(generator)) {
            selectedSkillIndex = i;
            break;
        }
    }

    if (selectedSkillIndex == -1) {
        // Handle edge case where no non-cooldown skills are available
    }

    auto& selectedSkill = skills[selectedSkillIndex];
    selectedSkill.onCooldown = true;
    selectedSkill.lastUsed = std::chrono::system_clock::now().time_since_epoch().count();

    return {selectedSkillIndex, selectedSkill.cooldown};
}

int main() {
    auto skills = getSkills();
    auto [index, cooldown] = selectSkill(skills);
    std::cout << "Selected skill index: " << index << ", Cooldown duration: " << cooldown << std::endl;
}
