const MAX_RETRIES = 3;

async function aggregate(data, initialValue, callback) {
  let accumulator = initialValue;
  let retriesLeft = MAX_RETRIES;

  for (let i = 0; i < data.length; i++) {
    try {
      const result = await callback(accumulator, data[i], i);
      accumulator = result;
    } catch (error) {
      if (retriesLeft > 0) {
        retriesLeft--;
        console.warn(`Callback function failed for data point ${i}, retrying...`);
      } else {
        throw error; // Reject the promise if all retries are exhausted
      }
    }
  }

  return accumulator;
}
```

