2. Semaphore Management Library (`semaphore.c`)

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

typedef struct Semaphore {
    pthread_sem_t sem;
    size_t capacity;
    char name[64];
} Semaphore;

Semaphore *semaphore_create(const char *name, size_t capacity) {
    Semaphore *sem = malloc(sizeof(Semaphore));
    if (!sem) return NULL;

    sem->capacity = capacity;
    strncpy(sem->name, name, sizeof(sem->name));
    pthread_mutex_init(&sem->sem, NULL);
    if (pthread_sem_init(&sem->sem, 0, capacity) != 0) {
        free(sem);
        return NULL;
    }

    return sem;
}

void semaphore_destroy(Semaphore *sem) {
    pthread_mutex_destroy(&sem->sem);
    free(sem);
}

int semaphore_wait(Semaphore *sem, int timeout_ms) {
    int ret = 0;

    struct timespec abs_time;
    clock_gettime(CLOCK_REALTIME, &abs_time);
    abs_time.tv_sec += timeout_ms / 1000;
    abs_time.tv_nsec += (timeout_ms % 1000) * 1000000;

    pthread_mutex_lock(&sem->sem);
    if (pthread_sem_wait(&sem->sem) == 0) {
        ret = 1;
    } else {
        fprintf(stderr, "Error: %s::wait() failed\n", sem->name);
        ret = -errno;
    }
    pthread_mutex_unlock(&sem->sem);

    if (timeout_ms > 0 && time_since(abs_time) >= timeout_ms) {
        fprintf(stderr, "Warning: %s::wait() timed out after %d ms\n", sem->name, timeout_ms);
    }

    return ret;
}

int semaphore_trywait(Semaphore *sem) {
    int ret = 0;

    pthread_mutex_lock(&sem->sem);
    if (pthread_sem_trywait(&sem->sem) == 0) {
        ret = 1;
    } else {
        fprintf(stderr, "Error: %s::trywait() failed\n", sem->name);
        ret = -errno;
    }
    pthread_mutex_unlock(&sem->sem);

    return ret;
}

void semaphore_signal(Semaphore *sem) {
    pthread_mutex_lock(&sem->sem);
    if (pthread_sem_post(&sem->sem) != 0) {
        fprintf(stderr, "Error: %s::signal() failed\n", sem->name);
    }
    pthread_mutex_unlock(&sem->sem);
}

void *semaphore_signaler(void *arg) {
    Semaphore *sem = arg;
    while (1) {
        if (semaphore_trywait(sem)) semaphore_signal(sem);
        sleep(1);
    }
}

size_t time_since(const struct timespec *ts) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    return (now.tv_sec - ts->tv_sec) * 1000 + (now.tv_nsec - ts->tv_nsec) / 1000000;
}
