using Microsoft.Extensions.Primitives;
using Newtonsoft.Json;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class WebsiteFooterScripts
{
    public string Name { get; set; }
    public string Code { get; set; }
    public string[] Dependencies { get; set; }
}

public static async Task<string> addAndRenderWebSiteFooterScripts(string directoryPath, string siteName)
{
    var webConfigExists = Directory.GetFiles(directoryPath, "web.config").Any();
    if (!webConfigExists) return null;

    var builder = WebApplication.CreateBuilder(args => args.UseKestrel());
    var app = builder.Build();
    var scriptDependencyGraph = new Dictionary<string, List<string>>();

    Func<List<WebsiteFooterScripts>, Task<string>> renderFooterScripts = scripts =>
    {
        var sb = new StringBuilder();
        foreach (var script in scripts)
        {
            if (string.IsNullOrEmpty(script.Code))
            {
                Console.Error.WriteLine($"Warning: Script '{script.Name}' is missing code.");
                continue;
            }

            var dependencies = scriptDependencyGraph[script.Name] ?? new List<string>();
            var scriptWithDependencies = new List<WebsiteFooterScripts>(dependencies.Concat(new[] { script }));
            var resolvedScripts = await Task.WhenAll(scriptWithDependencies.Select(RenderFooterScripts));
            var combinedCode = resolvedScripts.Aggregate((a, b) => a + b);

            sb.AppendLine($"<script>{combinedCode}</script>");
        }

        return sb.ToString();
    };

    Func<List<WebsiteFooterScripts>, Task<List<string>>> resolveDependencies = scripts =>
    {
        var resolvedScripts = new List<string>();
        foreach (var script in scripts)
        {
            if (!scriptDependencyGraph.ContainsKey(script.Name))
                scriptDependencyGraph[script.Name] = script.Dependencies?.ToList() ?? new List<string>();

            if (scriptDependencyGraph[script.Name].All(d => resolvedScripts.Contains(d)))
            {
                resolvedScripts.Add(script.Name);
                continue;
            }

            var dependentScripts = scriptDependencyGraph[script.Name];
            var pendingDependencies = dependentScripts.Except(resolvedScripts).ToList();
            if (pendingDependencies.Any())
                await resolveDependencies(pendingDependencies);

            resolvedScripts.Add(script.Name);
        }

        return Task.FromResult(resolvedScripts);
    };

    var provider = new PhysicalFileProvider(directoryPath);
    app.UseStaticFiles(new StaticFileOptions() { FileProvider = provider });
    app.Run(async context =>
    {
        if (context.Request.Path == "/footer-scripts")
        {
            var scripts = JsonConvert.DeserializeObject<List<WebsiteFooterScripts>>(await context.Request.ReadFromStreamAsync());
            var resolvedScripts = await resolveDependencies(scripts);
            context.Response.ContentType = "application/javascript";
            await context.Response.WriteAsync(await renderFooterScripts(resolvedScripts));
        }
        else
        {
            context.Response.StatusCode = 404;
        }
    });

    var server = app.CreateDefaultBuilder().UseRouting().Build();
    await server.StartAsync();

    // Conditionally load scripts based on user-agent or device type
    // Implement fallback mechanism for external dependencies
    // Enable caching mechanisms where applicable

    return await renderFooterScripts(await resolveDependencies(app.Services.GetRequiredService<IEnumerable<WebsiteFooterScripts>>()));
}
