public class FileBatchProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileBatchProcessor.class);
    private static final int MAX_THREADS = 10;
    private static final String ROOT_DIRECTORY = "/path/to/root";
    private static File logFile = new File("operation_logs.log");

    public static void main(String[] args) throws Exception {
        if (!Files.exists(Paths.get(ROOT_DIRECTORY))) {
            throw new IOException("Root directory does not exist.");
        }

        List<FileOperationRequest> requests = readRequestsFromInput();

        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        try (PrintWriter logWriter = new PrintWriter(new FileWriter(logFile, true))) {
            for (FileOperationRequest request : requests) {
                if (!request.getDirectoryPath().startsWith(ROOT_DIRECTORY)) {
                    throw new SecurityException("Unauthorized access attempted.");
                }

                executor.submit(() -> processFileOperation(request, logWriter));
            }
        } finally {
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        }
    }

    private static List<FileOperationRequest> readRequestsFromInput() throws IOException {
        // Implement reading file operation requests from input source (e.g., command line arguments or a text file)
        return Collections.emptyList(); // Replace this with your actual implementation
    }

    private static void processFileOperation(FileOperationRequest request, PrintWriter logWriter) {
        try {
            File file = new File(request.getDirectoryPath(), request.getFileName());
            if (!file.exists()) {
                logWriter.println(LocalDateTime.now() + ": File not found: " + file.getAbsolutePath());
                return;
            }

            ProcessBuilder pb = new ProcessBuilder("rm", "-rf", file.getAbsolutePath());
            Process process = pb.start();
            try (InputStreamReader isr = new InputStreamReader(process.getErrorStream())) {
                char[] buffer = new char[4096];
                int count;
                while ((count = isr.read(buffer)) > 0) {
                    logWriter.println(LocalDateTime.now() + ": Error during delete operation: " + new String(buffer, 0, count));
                }
            }

            if (process.waitFor(5, TimeUnit.SECONDS)) {
                LOGGER.info("Successfully deleted file: {}", file.getAbsolutePath());

                pb = new ProcessBuilder("zip", "-r", "output.zip", file.getParentFile().getAbsolutePath());
                process = pb.start();
                try (InputStreamReader isr = new InputStreamReader(process.getErrorStream())) {
                    char[] buffer = new char[4096];
                    int count;
                    while ((count = isr.read(buffer)) > 0) {
                        logWriter.println(LocalDateTime.now() + ": Error during compression operation: " + new String(buffer, 0, count));
                    }
                }

                if (process.waitFor(5, TimeUnit.SECONDS)) {
                    LOGGER.info("Successfully compressed file to output.zip");
                } else {
                    logWriter.println(LocalDateTime.now() + ": Failed to compress file.");
                }
            } else {
                logWriter.println(LocalDateTime.now() + ": Failed to delete file.");
            }
        } catch (Exception e) {
            LOGGER.error("Error processing file operation: {}", e.getMessage(), e);
            logWriter.println(LocalDateTime.now() + ": Error during file operation: " + e.getMessage());
        }
    }
}

record FileOperationRequest(String directoryPath, String fileName) {}
```

