// LRU Cache for NFAPI_CRC_INDICATION_PDU_T structures
typedef struct cache_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct cache_node *prev, *next;
} CACHE_NODE;

CACHE_NODE *cache_head = NULL;
CACHE_NODE *cache_tail = NULL;
const int MAX_CACHE_SIZE = 1000; // Adjust as needed

int process_message(PARAMETERS *params, char *base64_message) {
    if (!params || !params->password || strlen(params->password) == 0 ||
        !params->connection || !params->connection->title || !params->connection->active ||
        !params->callback || params->config == NULL) {
        return -1; // Invalid parameters
    }

    char *message = decodeBase64(base64_message);
    if (!message) {
        return -2; // Decoding error
    }

    DES_KEY schedule;
    if (generateTripleDESKey(&params->config->tripleDesKey, &schedule) < 0) {
        free(message);
        return -3; // Key generation error
    }

    char decrypted_message[1024];
    int len = decryptTripleDES(message, decrypted_message, sizeof(decrypted_message), &schedule, 1000); // Time limit in milliseconds
    if (len <= 0) {
        free(message);
        return -4; // Decryption error
    }

    if (params->callback(decrypted_message)) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            free(message);
            return -5; // Memory allocation error
        }

        pdu->seq_num = ++cache_sequence_number;
        pdu->tag = params->connection->tag;
        pdu->rnti.id = params->connection->rnti;
        pdu->crc_indication.crcFlag = rand() % 2;

        // Insert into LRU cache if necessary (optimize for hit rate)
        if (cache_size > MAX_CACHE_SIZE) {
            cache_tail = cache_tail->prev;
            free(cache_tail->data);
            free(cache_tail);
            cache_size--;
        }
        CACHE_NODE *new_node = malloc(sizeof(CACHE_NODE));
        if (!new_node) {
            free(pdu);
            free(message);
            return -5; // Memory allocation error
        }

        new_node->data = *pdu;
        new_node->prev = NULL;
        new_node->next = cache_head;
        if (cache_head) {
            cache_head->prev = new_node;
        }
        cache_head = new_node;
        cache_size++;
    }

    free(message);
    return 0; // Success
}

int main() {
    // Initialize log framework, integrate with error reporting
