struct PCI_DEVICE_STATUS_RECORD {
    int id;
    double read_speed;
    double write_speed;
    int error_count;
    double temperature;
};

class DeviceMonitor {
private:
    std::list<PCI_DEVICE_STATUS_RECORD> devices; // Dynamic list of PCI_DEVICE_STATUS_RECORD
    boost::container::circular_buffer<PCI_DEVICE_STATUS_RECORD, 5000> deviceBuffer;
    mutex mtx;
    condition_variable cv;
    boost::asio::io_service ioService;

public:
    DeviceMonitor() {}

    void addDevice(const PCI_DEVICE_STATUS_RECORD& record) {
        lock_guard<mutex> lock(mtx);
        devices.push_back(record);
        if (devices.size() > deviceBuffer.capacity()) {
            deviceBuffer.pop_front(); // Remove oldest entry in the buffer
        }
        deviceBuffer.push_back(record);
    }

    std::vector<PCI_DEVICE_STATUS_RECORD> getDeviceStatus() {
        lock_guard<mutex> lock(mtx);
        return devices;
    }
};
