import java.security.MessageDigest;
import java.math.BigInteger;
import java.nio.charSet;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class HashHelper {
    public static String md5Hash(String input) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hash = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static List<String> concatenateMd5Hashes(List<String> inputs) throws Exception {
        if (inputs.isEmpty()) return Arrays.asList("");

        String[] hashArrays = new String[inputs.size()];
        for (int i = 0; i < inputs.size(); ++i) {
            hashArrays[i] = md5Hash(inputs.get(i));
        }

        StringBuilder sb = new StringBuilder();
        for (String s : hashArrays) {
            sb.append(s);
        }
        return Arrays.asList(sb.toString());
    }

    public static List<String> processInputs(List<String> inputs, int maxConcurrent) throws InterruptedException, Exception {
        List<Thread> threads = new ArrayList<>();
        List<String> results = new ArrayList<>();
        if (inputs.size() <= maxConcurrent) {
            // Process all inputs sequentially or concurrently if number of inputs exceeds maxConcurrent
            for (String input : inputs) {
                Thread t = new Thread(() -> {
                    try {
                        results.add(md5Hash(input));
                    } catch (Exception e) {
                        System.err.println("Error processing input '" + input + "': " + e.getMessage());
                    }
                });
                t.start();
                threads.add(t);
            }
            for (Thread t : threads) {
                t.join();
            }
        } else {
            // Implement a concurrent processing mechanism here, considering potential I/O errors and hash computation failures
        }

        return results;
    }
}
