#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t RNTI;
    RLC_STATUS_INFO status;
} NFAPI_RLC_PDU_T;

#define BUFFER_SIZE (1024 * 64) // Adjust as needed for your specific use case
#define BATCH_SIZE (100000)      // Adjustable batch size for writing to output file

struct thread_data {
    FILE *input, *output;
    NFAPI_RLC_PDU_T *buffer;
    size_t buffer_size;
    size_t processed;
    size_t batch_counter;
    sem_t sem;
};

void* process_log(void *arg) {
    struct thread_data *data = arg;
    char line[BUFFER_SIZE];
    NFAPI_RLC_PDU_T *ptr = data->buffer;

    while (fgets(line, sizeof(line), data->input)) {
        sscanf(line, "%*d %u %u %u", &ptr->tag.value, &ptr->RNTI, &ptr->status.logicalChannelIdentity);
        if (ptr->RNTI >= start_rnti && ptr->RNTI <= end_rnti) {
            data->processed++;
            ptr++;
            if (ptr - data->buffer == data->buffer_size) {
                sem_wait(&data->sem);
                fwrite(data->buffer, sizeof(NFAPI_RLC_PDU_T), data->processed, data->output);
                data->processed = 0;
                ptr = data->buffer;
                sem_post(&data->sem);
            }
        }
    }
    return NULL;
}

void manage_log(FILE *input, FILE *output, uint32_t start_rnti, uint32_t end_rnti) {
    NFAPI_RLC_PDU_T *data = mmap(NULL, BUFFER_SIZE * sizeof(NFAPI_RLC_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    struct thread_data thread_args[num_threads];
    sem_t sem;
    pthread_t threads[num_threads];

    size_t i = 0;
    for (i = 0; i < num_threads; ++i) {
        thread_args[i].input = input;
        thread_args[i].output = output;
        thread_args[i].buffer = data;
        thread_args[i].buffer_size = BUFFER_SIZE;
        sem_init(&thread_args[i].sem, 0, BATCH_SIZE);
    }

    for (i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, process_log, &thread_args[i]);
    }

    // Wait for all threads to finish processing the log file
    for (i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Write remaining data if any
    fwrite(data, sizeof(NFAPI_RLC_PDU_T), data - buffer, output);

    munmap(data, BUFFER_SIZE * sizeof(NFAPI_RLC_PDU_T));
}
