#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Event {
    time_t timestamp;
    int identifier;
    double x, y; // coordinates
    int ref_count;
    struct Event* next;
};

struct CoordinateMap {
    struct Event** events;
    size_t capacity;
    size_t size;
};

void init_coordinate_map(struct CoordinateMap* map) {
    map->capacity = 16;
    map->size = 0;
    map->events = calloc(map->capacity, sizeof(struct Event*));
}

void resize_coordinate_map(struct CoordinateMap* map) {
    if (map->capacity < 2 * map->size) {
        map->capacity *= 2;
        map->events = realloc(map->events, map->capacity * sizeof(struct Event*));
    }
}

void insert_event(struct CoordinateMap* map, struct Event* event) {
    size_t index = hash(event->y) % map->capacity;
    resize_coordinate_map(map);

    if (!map->events[index]) {
        map->events[index] = event;
    } else {
        struct Event* current = map->events[index];
        while (current != NULL) {
            if (current->y == event->y && current->x == event->x) {
                current->ref_count++;
                free(event);
                return;
            }
            current = current->next;
        }

        event->next = map->events[index];
        map->events[index] = event;
    }
}

struct Event* find_event(struct CoordinateMap* map, double x, double y) {
    size_t index = hash(y) % map->capacity;
    struct Event* current = map->events[index];

    while (current != NULL) {
        if (current->x == x && current->y == y) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

int query_ref_count(struct CoordinateMap* map, double x, double y) {
    struct Event* event = find_event(map, x, y);
    return event ? event->ref_count : 0;
}

unsigned int hash(double key) {
    unsigned long long hash = (unsigned long long)key * key;
    hash ^= (hash >> 32);
    hash += (hash << 5);
    hash ^= (hash >> 9);
    hash *= 0x7ed55d16;
    hash ^= (hash >> 12);
    hash *= 0x7ed55d16;
    hash ^= (hash >> 15);
    return (unsigned int)(hash % INT_MAX);
}

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

struct Event* create_event(time_t timestamp, int identifier, double x, double y) {
    struct Event* event = malloc(sizeof(struct Event));
    if (!event) {
        log_error("Out of memory error");
        return NULL;
    }

    event->timestamp = timestamp;
    event->identifier = identifier;
    event->x = x;
    event->y = y;
    event->ref_count = 1;
    event->next = NULL;

    return event;
}

void free_event(struct Event* event) {
    if (event) {
        free(event);
    }
}

void free_coordinate_map(struct CoordinateMap* map) {
    for (size_t i = 0; i < map->capacity; ++i) {
        struct Event* current = map->events[i];
        while (current != NULL) {
            struct Event* temp = current;
            current = current->next;
            free_event(temp);
        }
    }
    free(map->events);
}
```
