        ("d,dir", boost::program_options::value<std::vector<std::string>>(), "Include or exclude directories based on their names")
        ("o,output_dir", boost::program_options::value<std::string>()->default_value("./"), "Specify a directory where the summary report will be written instead of being printed to the console");

    variables_map options;
    store(parse(argc, argv, desc, options), options);
    notify(options);

    if (options.count("help")) {
        fmt::print(desc);
        return 0;
    }

    fs::path start_dir = fs::current_path();

    if (!options.count("filter")) {
        start_dir /= options["output_dir"].as<std::string>();
    } else {
        start_dir /= ".";
        for (auto& filter : options["filter"].as<std::vector<std::string>>()) {
            start_dir /= filter;
        }
    }

    fs::path output_dir = options["output_dir"].as<std::string>();

    if (!fs::exists(output_dir)) {
