        return 1;
    }

    try {
        fs::create_directories(output_dir);
    } catch (const std::exception& e) {
        fmt::print("Error: Could not create output directory '{}': {}\n", output_dir.generic_string(), e.what());
        return 1;
    }

    for (auto& dir : options["dir"].as<std::vector<std::string>>()) {
        if (dir[0] == '-') { // Exclude directories
            continue;
        }

        start_dir /= dir;
        fs::path current_path = start_dir;

        for (int depth = 1; depth <= MAX_DEPTH && fs::exists(current_path); ++depth) {
            if (!fs::is_directory(current_path)) {
                continue;
            }

            process_file(current_path, output_dir);
            current_path /= "..";
        }
    }

    process_file(start_dir, output_dir);

    return 0;
}
