using System.Compression;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using Amazon;
using Amazon.S3;
using Amazon.Runtime;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Formats.Jpeg;
using SixLabors.ImageSharp.Processing;

public class CompressAndUploadService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<CompressAndUploadService> _logger;
    private readonly AmazonS3Client _s3Client;

    public CompressAndUploadService(HttpClient httpClient, ILogger<CompressAndUploadService> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
        RegionEndpoint region = RegionEndpoint.USWest2;
        AWSCredentials credentials = new BasicAWSCredentials("ACCESS_KEY", "SECRET_KEY");
        _s3Client = new AmazonS3Client(credentials, region);
    }

    public async Task<Dictionary<string, object>> UploadByteArrayAsync(byte[] byteArray)
    {
        using (var memoryStream = new MemoryStream(byteArray))
        {
            var image = Image.Load(memoryStream);
            int compressionLevel = 80; // Adjust as needed

            await using var compressedStream = new GzipStream(memoryStream, CompressionMode.Compress, compressionLevel);
            memoryStream.Position = 0;

            var uploadResult = new Dictionary<string, object>();

            try
            {
                var key = $"compressed_{Guid.NewGuid()}.gz";
                var putRequest = new PutObjectRequest
                {
                    BucketName = "your_bucket_name",
                    Key = key,
                    FileStream = memoryStream,
                    ContentType = "application/gzip"
                };

                PutResponse response;
                var retryAttempts = 3;
                Action<Exception> onException = ex =>
                {
                    _logger.LogError(ex, "Failed to upload file.");
                    if (retryAttempts-- > 0)
                    {
                        await Task.Delay(Math.Pow(2, retryAttempts));
                        response = await Retry.OnRetry(_s3Client.PutObjectAsync, putRequest, ex);
                    }
                };

                response = await _s3Client.PutObjectAsync(putRequest).Catch(onException);

                uploadResult["Status"] = response.HttpStatusCode == HttpStatusCode.OK ? "Success" : "Error";
                uploadResult["Key"] = key;
                uploadResult["Size"] = byteArray.Length;
                uploadResult["UploadTime"] = DateTime.UtcNow;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process and upload data.");
                uploadResult["Status"] = "Error";
                uploadResult["Message"] = ex.Message;
            }

            if ((bool)uploadResult["Status"] == true)
            {
                File.Delete($"{Path.GetTempPath()}\\tempFile.gz");
            }

            return uploadResult;
        }
    }
}
