        private readonly int _maxSize;
        private readonly TimeSpan _invalidationInterval;
        private readonly Queue<UserRecord> _queue;
        private readonly SemaphoreSlim _semaphore;

        public Cache(int maxSize, TimeSpan invalidationInterval)
        {
            _maxSize = maxSize;
            _invalidationInterval = invalidationInterval;
            _queue = new Queue<UserRecord>();
            _semaphore = new SemaphoreSlim(_maxSize);
            Task.Run(CacheExpirationTask);
        }

        public void Enqueue(UserRecord userRecord)
        {
            lock (_queue)
            {
                _queue.Enqueue(userRecord);
                if (_queue.Count > _maxSize) _queue.Dequeue();
                _semaphore.Release();
            }
        }

        public UserRecord Dequeue()
        {
            lock (_queue)
            {
                return _queue.Dequeue();
            }
        }

        private async Task CacheExpirationTask()
        {
            while (true)
            {
                await Task.Delay(_invalidationInterval);

                foreach (var userRecord in _queue)
                {
                    if (!userRecord.IsValidForDatabase()) continue; // Skip expired records.

                    PerformDatabaseOperation(userRecord);
                }
            }
        }

        private bool UserRecordIsExpired(UserRecord userRecord) => DateTime.UtcNow - userRecord.Timestamp > _invalidationInterval;
    }
