```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

namespace YourNamespace
{
    public static class HashHelper
    {
        private static readonly Dictionary<char, int> _characterSetFrequency;
        private const string ConfigFile = "CharacterSet.config";

        static HashHelper()
        {
            var characterSet = new List<char>();
            if (File.Exists(ConfigFile))
                using (var reader = new StreamReader(ConfigFile))
                    while (!reader.EndOfStream)
                        characterSet.Add(reader.ReadLine());

            _characterSetFrequency = new Dictionary<char, int>(characterSet.Count);
            foreach (var c in characterSet)
                _characterSetFrequency[c] = 0;

            foreach (var c in characterSet)
                for (int i = 0; i < characterSet.Count; i++)
                    if (i != characterSet.IndexOf(c))
                        _characterSetFrequency[c]++;
        }

        public static string GenerateSecureRandomHash(int hashLength, IEnumerable<char> allowedCharacterSet = null)
        {
            var characterSet = allowedCharacterSet ?? _characterSet.Keys;

            if (hashLength <= 0 || !characterSet.Any())
                throw new ArgumentException("Invalid input.");

            var buffer = new byte[hashLength];
            using (var random = new RNGCryptoServiceProvider())
            {
                random.GetBytes(buffer);
            }

            var sb = new StringBuilder();
            foreach (var b in buffer)
                sb.Append(characterSet[(b % _characterSet.Count)]);

            return MD5.Create().ComputeHash(Encoding.ASCII.GetBytes(sb.ToString())).ToHexString();
        }

        private static string ToHexString(this byte[] array)
        {
            StringBuilder builder = new StringBuilder(array.Length * 2);
            foreach (byte b in array)
                builder.AppendFormat("{0:x2}", b);
            return builder.ToString();
        }
    }
}
```

2. PHP `generateSecureRandomHashPhp` function:

```php
<?php

namespace YourNamespace;

use InvalidArgumentException;
use RuntimeException;
use SplFileObject;

class HashHelper
{
    private static $characterSetFrequency = [];
    private const CONFIG_FILE = __DIR__ . "/CharacterSet.ini";

    public static function generateSecureRandomHash(int $hashLength, array $allowedCharacterSet = null)
    {
        if ($hashLength <= 0 || !$allowedCharacterSet) {
            throw new InvalidArgumentException("Invalid input.");
        }

        $characterSet = isset($allowedCharacterSet) ? $allowedCharacterSet : self::getAllowedCharacters();

        $buffer = [];
        for ($i = 0; $i < $hashLength; $i++) {
            $buffer[] = $characterSet[mt_rand(0, count($characterSet) - 1)];
        }

        return md5(implode("", $buffer));
    }

    private static function getAllowedCharacters()
    {
        if (!file_exists(self::CONFIG_FILE)) {
            throw new RuntimeException("Config file not found.");
        }

        $allowedCharacters = [];
        $iniFile = new SplFileObject(self::CONFIG_FILE, 'r');
        while (!$iniFile->eof()) {
            $iniFile->nextLine();
            $line = trim($iniFile->currentLine());
            if (!empty($line)) {
                $allowedCharacters[] = $line;
            }
        }

        $frequency = [];
        foreach ($allowedCharacters as $char) {
            $frequency[$char] = 0;
            for ($i = 0; $i < count($allowedCharacters); $i++) {
                if ($i != array_search($char, $allowedCharacters)) {
                    $frequency[$char]++;
                }
            }
        }

        return $allowedCharacters;
    }
}
