typedef struct {
    uint8_t* data;
    size_t capacity;
    size_t current;
} MemoryPool;

// ResourceUnit structure definition in custom_types.h

void initializeMemoryPool(MemoryPool* pool, size_t initialSize) {
    pool->data = malloc(initialSize);
    if (!pool->data) {
        perror("Error allocating memory for MemoryPool");
        exit(EXIT_FAILURE);
    }

    pool->capacity = initialSize;
    pool->current = 0;
}

void* getMemoryFromPool(MemoryPool* pool) {
    if (pool->current >= pool->capacity) {
        pool->data = realloc(pool->data, pool->capacity * 2);
        if (!pool->data) {
            perror("Error allocating more memory for MemoryPool");
            exit(EXIT_FAILURE);
        }
        pool->capacity *= 2;
    }

    void* memory = &pool->data[pool->current];
    pool->current++;
    return memory;
}

void freeMemoryToPool(void* memory, MemoryPool* pool) {
    pool->current--;
}

// Error codes and message strings definition
