const char* errorMessages[] = {"No error", "Invalid task identifier", "Invalid resource manager", "Invalid callback"};

int processURLsWithResourceManager(Task* task) {
    if (task->task_id <= 0 || !task->resource_manager || !task->callback)
        return INVALID_TASK_ID;

    MemoryPool logMemoryPool;
    initializeMemoryPool(&logMemoryPool, 1024); // Initial memory allocation for logs

    pthread_t threads[MAX_THREADS];
    size_t processedURLs = 0;
    char hostname[NI_MAXHOST];

    for (const char* url : task->resource_manager->urls) {
        gethostbyname2(url, AF_INET, &hostname, NI_MAXHOST);
        if (!hostname || !inet_ntop(AF_INET, &(reinterpret_cast<struct in6_addr*>(hostnames)[0]), hostname, NI_MAXHOST)) {
            continue; // Skip invalid or unreachable URLs
        }

        if (task->resource_manager->availabilityCheck(hostname)) {
            TaskLog* log = static_cast<TaskLog*>(getMemoryFromPool(&logMemoryPool));
            getTimeStamp(log->timestamp);
            log->logLevel = task->resource_manager->logLevel;
            log->successFlag = true;
            task->callback(log, url);
            processedURLs++;
        } else {
            TaskLog* log = static_cast<TaskLog*>(getMemoryFromPool(&logMemoryPool));
            getTimeStamp(log->timestamp);
            log->logLevel = task->resource_manager->logLevel;
            log->successFlag = false;
            task->callback(log, url);
        }
    }

    free(logMemoryPool.data);

    if (processedURLs == 0)
        return INVALID_RESOURCE_MANAGER; // No URLs processed means there's an issue with the resource manager

    return NO_ERROR;
}
