#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <ctype.h>
#include <openssl/sha.h>

typedef struct {
    uint32_t timestamp;
    char session_id[32];
    int session_type;
} SessionData;

struct DataContainer {
    SessionData* data;
    size_t size;
    size_t capacity;
};

void* read_binary_file(const char* filepath, struct DataContainer* container) {
    FILE* file = fopen(filepath, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    container->data = malloc(file_size / sizeof(uint32_t));
    if (!container->data) {
        perror("Memory allocation error");
        fclose(file);
        return NULL;
    }

    size_t read = fread(container->data, sizeof(uint32_t), file_size / sizeof(uint32_t), file);
    if (read != file_size / sizeof(uint32_t)) {
        perror("Error reading file");
        free(container->data);
        fclose(file);
        return NULL;
    }

    fclose(file);
    container->capacity = file_size / sizeof(uint32_t);
    container->size = 0;
    return container;
}

void hash_session_id(const uint32_t timestamp, char session_id[32]) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, &timestamp, sizeof(uint32_t));
    SHA256_Final(session_id, &ctx);
}

void process_timestamps(struct DataContainer* container, SessionData** session_list, size_t* session_count) {
    qsort(container->data, container->capacity, sizeof(uint32_t), (int (*)(const void*, const void*)) compare_timestamps);

    pthread_t threads[container->capacity];
    SessionData thread_data[container->capacity];

    for (size_t i = 0; i < container->capacity; ++i) {
        thread_data[i].timestamp = container->data[i];
        memcpy(thread_data[i].session_id, "", sizeof(thread_data[i].session_id));
        thread_data[i].session_type = -1; // Invalid session type

        pthread_create(&threads[i], NULL, process_timestamp, &thread_data[i]);
    }

    for (size_t i = 0; i < container->capacity; ++i) {
        pthread_join(threads[i], NULL);

        if (session_list[thread_data[i].session_type]) {
            if (!memcmp(session_list[thread_data[i].session_type]->session_id, thread_data[i].session_id, sizeof(thread_data[i].session_id))) {
                printf("Duplicate timestamp detected: %u\n", thread_data[i].timestamp);
            }
        } else {
            session_list[thread_data[i].session_type] = malloc(sizeof(SessionData));
            memcpy(session_list[thread_data[i].session_type], &thread_data[i], sizeof(SessionData));
            ++(*session_count);
        }
    }
}

int compare_timestamps(const void* a, const void* b) {
    return (*(const uint32_t*)a - *(const uint32_t*)b);
}

void* process_timestamp(void* data) {
    SessionData* sd = (SessionData*)data;
    hash_session_id(sd->timestamp, sd->session_id);

    for (int i = 0; i < NUM_SESSION_TYPES; ++i) {
        if (isValidSessionType(i)) {
            SessionData* session = session_list[i];
            if (memcmp(sd->session_id, session->session_id, sizeof(session->session_id))) {
                sd->session_type = i;
                break;
            }
        }
    }

    return data;
}

int main() {
    const char* filepath = "large_binary_file.bin";
    struct DataContainer container;

    if (!read_binary_file(filepath, &container)) {
        return 1;
    }

    SessionData** session_list = malloc(NUM_SESSION_TYPES * sizeof(SessionData*));
    size_t session_count = 0;

    process_timestamps(&container, session_list, &session_count);

    // Further processing and logging of the session data goes here

    for (size_t i = 0; i < NUM_SESSION_TYPES; ++i) {
        if (session_list[i]) {
            free(session_list[i]);
        }
    }
    free(session_list);

    free(container.data);

    return 0;
}
