/**
 * Deserializes a byte array containing serialized Record objects using an ObjectInputStream.
 * Handles potential deserialization scenarios gracefully, such as malformed data and missing class definitions.
 */
public List<Record> deserialize(byte[] data) {
    try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
        // Use a fixed-size array for improved iteration performance over ArrayList.
        Record[] records = new Record[10_000];
        int count = 0;

        // Validate each deserialized object and memory allocation.
        while (true) {
            try {
                // Deserialize a single Record object.
                records[count] = (Record) ois.readObject();
                count++;
            } catch (EOFException eof) {
                break; // Reached the end of the input stream.
            } catch (ClassNotFoundException cnfe) {
                System.err.println("Missing class definition for object: " + cnfe.getMessage());
            } catch (IOException ioe) {
                System.err.println("Error deserializing object: " + ioe.getMessage());
            }
        }

        // Use an ArrayList for dynamic memory management and better handling of large collections.
        List<Record> result = new ArrayList<>(count);
        System.arraycopy(records, 0, result.toArray(), 0, count);

        return result;
    } catch (IOException e) {
        System.err.println("Error reading serialized data: " + e.getMessage());
        throw new RuntimeException(e); // Propagate the exception for proper error handling.
    }
}

/**
 * Represents a single record containing a Value instance and a timestamp (in milliseconds).
 */
public class Record {
    private final long timestamp;
    private final int value;

    public Record() {
        this.timestamp = Instant.now().toEpochMilli();
        // Randomly initialize the value within the specified range.
        this.value = new Random().ints(0, 1_000_000).limit(1).findFirst().getAsInt();
    }
}
