int upload_and_execute(char* input_file, char* command, char* working_directory, int verbosity, logger_t* logger) {
    // Check if the target file exists and delete it if necessary
    struct stat st;
    if (stat(input_file, &st) == 0 && S_ISREG(st.st_mode)) {
        delete_file(input_file);
    }

    // Upload the input file
    char uploaded_file[1024];
    snprintf(uploaded_file, sizeof(uploaded_file), "temp_%d.data", getpid());
    int upload_status = Bluebird.upload(input_file, uploaded_file);

    if (upload_status != 0) {
        // Handle error during file upload
        return upload_status;
    }

    // Spawn the command process and handle its exit code
    pid_t child = spawn_upload_process(command, working_directory, &command, uploaded_file);

    if (child == -1) {
        // Fork failed; handle error
        return -1;
    }

