  try {
    // Authenticate and refresh tokens automatically
    await s3Client. HeadBucket({ Bucket: process.env.AWS_S3_BUCKET }).promise();

    const batchSize = parseInt(process.env.BATCH_SIZE) || 10;

    for (let startIndex = 0; startIndex < urls.length; startIndex += batchSize) {
      const batchUrls = urls.slice(startIndex, startIndex + batchSize);

      // Upload batch of files and track progress
      await Promise.all(batchUrls.map(async (url) => {
        try {
          // Handle file validation
          // Validate file size, type, etc.

          // Prepare metadata (tags, descriptions, expiration dates, etc.)
          const metadata = { /* Your metadata here */ };

          // Create unique file name and prepare for chunked uploads
          const uniqueFileName = generateUniqueFileName();
          let filePartNumber = 1;

          // Upload the file in chunks (handle large files efficiently)
          const params = {
            Bucket: process.env.AWS_S3_BUCKET,
            Key: uniqueFileName,
            Body: await getFileStream(url),
            ContentType: 'application/octet-stream', // Set appropriate content type
            ACL: 'private',
          };

          let completedChunks = 0;
          const chunkSize = parseInt(process.env.CHUNK_SIZE) || 5 * 1024 * 1024; // 5MB chunks by default

          do {
            const chunkParams = { ...params, ...{ ContentLength: chunkSize } };
            const uploadResult = await s3Client.putObject(chunkParams).promise();

            completedChunks++;
            progressTracker.set(url, completedChunks);

            if (completedChunks === batchSize) {
              // Finalize the file metadata upon completion of all chunks
              await s3Client.completeMultipartUpload({ ...params, PartNumber: filePartNumber++, UploadId: uploadResult.UploadId }).promise();
            }
          } while (completedChunks < batchSize);

          // Send notifications and log success
          sendNotification('File uploaded successfully: ' + url);
        } catch (error) {
          if (error.code === 'ExpiredToken') {
            await refreshAccessToken();
            // Retry the upload with the refreshed token
            await uploadFiles([url]);
          } else {
            sendNotification(`Error while uploading file: ${url} - ${error.message}`);
          }
        }
      }));
    }
  } catch (error) {
    console.error('Error during the upload process:', error.message);
  }

  // Return status report and detailed data for debugging
  const failureReports = [...progressTracker.entries()].filter(([, value]) => value === 0).map(([url]) => ({ url, status: 'Failed' }));
  const successReports = progressTracker.entries().map(([url, value]) => ({ url, status: 'Success', completedChunks: value }));

  return { failureReports, successReports };
}
