    srand(seed);

    list = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Error: Out of memory.\n");
        return;
    }

    memset(list, 0, MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_elements; ++i) {
