    struct node* prev;
    struct node* next;
};

static struct node head = { .prev = &head, .next = &head };
static size_t num_nodes = 0;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static bool is_node_active[16384] = {false}; // Max 16k nodes, assuming RNTI values up to 65535

// Function to add a new node to the list
void add_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory\n");
        return;
    }

    // Populate the new node with the given data and a random CRC flag
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->data.crcflag = rand();

    pthread_mutex_lock(&list_lock);
    if (num_nodes >= 10000) {
        free(new_node);
        pthread_mutex_unlock(&list_lock);
        fprintf(stderr, "Error: List full\n");
        return;
    }

    // Validate RNTI uniqueness and handle any conflicts
    for (struct node* curr = head.next; curr != &head && num_nodes > 0; curr = curr->next) {
        if (curr->data.rnti == new_node->data.rnti && curr != new_node) {
            free(new_node);
            pthread_mutex_unlock(&list_lock);
            fprintf(stderr, "Error: RNTI collision\n");
            return;
        }
    }

    // Add the new node to the list and update is_node_active
    new_node->prev = &head;
    new_node->next = head.next;
    head.next->prev = new_node;
    head.next = new_node;

    is_node_active[new_node->data.rnti] = true;
    num_nodes++;

    pthread_mutex_unlock(&list_lock);
}

// Function to retrieve the head of the list
struct node* get_head() {
    return head.next;
}

// Function to clean up the entire list when no longer needed
void cleanup_list() {
    pthread_mutex_lock(&list_lock);
    struct node* curr = head.next;
    while (curr != &head) {
        struct node* temp = curr;
        curr = curr->next;
        free(temp);
        is_node_active[temp->data.rnti] = false;
    }
    num_nodes = 0;
    pthread_mutex_unlock(&list_lock);
}
