#include <time.h>

typedef struct Node {
    RNTI_T rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication;
    void *next, *prev;
} Node;

typedef struct DList {
    int size, capacity;
    pthread_mutex_t mutex;
    Node *head, *tail;
} DList;

void init_dlist(DList *dlist) {
    dlist->size = 0;
    dlist->capacity = 10000;
    dlist->head = NULL;
    dlist->tail = NULL;
    pthread_mutex_init(&dlist->mutex, NULL);
}

void destroy_dlist(DList *dlist) {
    if (dlist->head == NULL) return;

    Node *current = dlist->head;
    while (current != NULL) {
        Node *next = (Node *) current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&dlist->mutex);
}

bool is_valid_rnti(RNTI_T rnti) {
    if (rnti < 1 || rnti > 65535) return false;
    return true;
}

int dlist_add(DList *dlist, const RNTI_T rnti, const CRC_INDICATION_REL8_TAG_T crc_indication) {
    if (dlist->size + 1 >= dlist->capacity) return -1;

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->rnti = rnti;
    new_node->crc_indication = crc_indication;
    new_node->next = NULL;
    new_node->prev = NULL;

    pthread_mutex_lock(&dlist->mutex);

    bool duplicate_found = false;
    Node *current = dlist->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            fprintf(stderr, "RNTI conflict: %u\n", rnti);
            duplicate_found = true;
            break;
        }
        current = (Node *) current->next;
    }

    if (!duplicate_found) {
        if (dlist->size > 0) dlist->tail->next = new_node;
        else dlist->head = new_node;
        dlist->tail = new_node;
        dlist->size++;
    }

    pthread_mutex_unlock(&dlist->mutex);

    if (duplicate_found) return 0;
    else return 1;
}

Node *dlist_get_head(const DList *dlist) {
    return dlist->head;
}

int dlist_batch_process(DList *dlist, const int batch_size, void (*callback)(Node *node)) {
    if (dlist->size == 0 || batch_size <= 0) return 0;

    pthread_mutex_lock(&dlist->mutex);

    Node *current = dlist->head;
    int processed_count = 0;

    while (processed_count < batch_size && current != NULL) {
        if (processed_count + 1 >= dlist->size) break;

        Node *next = (Node *) current->next;
        (*callback)(current);
        processed_count++;
        current = next;
    }

    pthread_mutex_unlock(&dlist->mutex);

    return processed_count;
}
```

