    sev.sigev_value.sival_ptr = handler;
    sigemptyset(&sev.sigev_thread_id);

    setitimer(ITIMER_REAL, &iti, &sev);
    iti.it_interval.tv_usec = 0;
    iti.it_value.tv_usec = (unsigned long)milliseconds * 1000;
}

