<?php

class UserPasswordService {
    private $userRepository;
    private $passwordValidator;
    private $rateLimiter;
    private $mfaService;
    private $logger;
    private $auditLogService;

    public function __construct(
        UserRepository $userRepository,
        PasswordValidator $passwordValidator,
        RateLimiter $rateLimiter,
        MFAService $mfaService,
        Logger $logger,
        AuditLogService $auditLogService
    ) {
        $this->userRepository = $userRepository;
        $this->passwordValidator = $passwordValidator;
        $this->rateLimiter = $rateLimiter;
        $this->mfaService = $mfaService;
        $this->logger = $logger;
        $this->auditLogService = $auditLogService;
    }

    public function updatePassword(string $userId, string $newPassword): int {
        if (!$this->userRepository->isAccountActive($userId)) {
            return ErrorCodes::ACCOUNT_INACTIVE;
        }

        if (!$this->rateLimiter->canChangePassword($userId)) {
            return ErrorCodes::RATE_LIMIT_EXCEEDED;
        }

        if (!$this->passwordValidator->validate($newPassword)) {
            return ErrorCodes::INVALID_PASSWORD;
        }

        $unique = true;
        foreach ($this->passwordValidator->getCommonPasswords() as $commonPassword) {
            if (strcmp($newPassword, $commonPassword) === 0) {
                $unique = false;
                break;
            }
        }

        if (!$unique) {
            return ErrorCodes::COMMON_PASSWORD;
        }

        // Start asynchronous MFA challenge
        $this->mfaService->startChallenge($userId);

        // Atomic transaction using your preferred method (e.g. RDBMS transaction, SAGA)
        try {
            // Lock account to prevent concurrent requests during MFA verification
            $this->userRepository->lockAccount($userId);

            // Update password in the backend service
            $response = $this->backendService->updatePassword($userId, $newPassword);

            if ($response->isSuccess()) {
                $this->auditLogService->logPasswordChange($userId);
                $this->logger->info("Password changed for user {$userId}");
                return ErrorCodes::NO_ERROR;
            } else {
                // Unlock account and handle retries based on service response
                $this->userRepository->unlockAccount($userId);
                return ErrorCodes::BACKEND_ERROR;
            }
        } catch (Exception $e) {
            // Handle errors gracefully, e.g. by retrying or escalating the issue
            $this->userRepository->unlockAccount($userId);
            $this->logger->error("Error updating password for user {$userId}: {$e->getMessage()}");
            return ErrorCodes::INTERNAL_ERROR;
        }
    }
}
```

