#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} Record;

struct ValueGenerator {
    long min, max;
    pthread_mutex_t mutex;
    long cache[1000]; // Cache for 1000 random values
    int cacheIndex;
};

void ValueGenerator_init(struct ValueGenerator* gen, long min, long max) {
    gen->min = min;
    gen->max = max;
    gen->cacheIndex = -1;
    pthread_mutex_init(&gen->mutex, NULL);
}

long ValueGenerator_next(struct ValueGenerator* gen) {
    pthread_mutex_lock(&gen->mutex);
    if (gen->cacheIndex != -1 && gen->cache[gen->cacheIndex] <= gen->max) {
        long val = gen->cache[gen->cacheIndex];
        gen->cacheIndex--;
        pthread_mutex_unlock(&gen->mutex);
        return val;
    }
    long val = rand() % (gen->max - gen->min + 1) + gen->min;
    if(val <= gen->max) {
        gen->cache[gen->cacheIndex++] = val;
    }
    pthread_mutex_unlock(&gen->mutex);
    return val;
}

typedef struct MemoryManager {
    long *offsets;
    int *keys;
    Record *records;
    struct ValueGenerator gen;
    pthread_rwlock_t rwLock;
    size_t size;
} MemoryManager;

void MemoryManager_init(MemoryManager* mm, size_t size) {
    mm->offsets = calloc(size, sizeof(long));
    mm->keys = calloc(size, sizeof(int));
    mm->records = calloc(size, sizeof(Record));
    ValueGenerator_init(&mm->gen, 1, 100); // Adjust min and max as needed
    pthread_rwlock_init(&mm->rwLock, NULL);
    mm->size = size;
}

void MemoryManager_insert(MemoryManager* mm, int key, long offset) {
    pthread_rwlock_wrlock(&mm->rwLock);
    mm->offsets[key] = offset;
    mm->keys[offset] = key;
    mm->records[offset].value = ValueGenerator_next(&mm->gen);
    pthread_rwlock_unlock(&mm->rwLock);
}

long MemoryManager_getOffset(MemoryManager* mm, int key) {
    pthread_rwlock_rdlock(&mm->rwLock);
    long offset = mm->offsets[key];
    if (offset == -1) { // Offset not found
        pthread_rwlock_unlock(&mm->rwLock);
        offset = -2; // Indicate failure
    }
    pthread_rwlock_unlock(&mm->rwLock);
    return offset;
}

```
In this implementation, a thread-safe `ValueGenerator` class is used to generate random integers within a specified range. The generator utilizes a caching mechanism and a lightweight synchronization approach (mutex) to manage concurrent access. The memory manager leverages a read-write lock (pthread_rwlock) for safe access to shared resources in a multi-threaded environment. This allows for both reading and writing when no other threads are accessing the data, optimizing performance. Additionally, proper memory allocation is ensured using calloc() to ensure proper alignment of allocated memory blocks.']

