#include <iostream>
#include <unordered_map>
#include <mutex>
#include <vector>
#include <memory>
#include <sys/mman.h>
#include <fstream>
#include <boost/serialization/access.hpp>
#include <boost/archive/binary_iarchive.hpp>
#include <boost/archive/binary_oarchive.hpp>
#include <boost/functional/hash.hpp>
#include <boost/circular_buffer.hpp>

class RandomValueGenerator {
public:
    explicit RandomValueGenerator(int min, int max) : min_(min), max_(max), cache_() {}

    int generate() {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = cache_.find(hash_combine(min_, max_, key_++));
        if (it != cache_.end()) {
            return it->second;
        }

        int value = min_ + std::rand() % (max_ - min_ + 1);
        lock.unlock();
        cache_[hash_combine(min_, max_, key_)] = value;
        lock.lock();
        return value;
    }

private:
    const int min_;
    const int max_;
    std::unordered_map<std::size_t, int> cache_;
    mutable std::mutex mutex_;
    std::atomic<int> key_{0};

    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive & ar, const unsigned int version) {
        ar & min_ & max_ & cache_ & key_;
    }
};

struct Record {
    int value;
    long offset;

    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive & ar, const unsigned int version) {
        ar & value & offset;
    }
};

std::vector<long>* allocate_offsets(size_t size) {
    auto memory = static_cast<long*>(mmap(nullptr, size * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0));
    if (memory == MAP_FAILED) {
        std::cerr << "Error allocating memory for offsets" << std::endl;
        exit(EXIT_FAILURE);
    }
    return new std::vector<long>(memory, memory + size);
}

std::vector<Record>* allocate_records(size_t size) {
    auto memory = static_cast<Record*>(malloc(size * sizeof(Record)));
    if (!memory) {
        std::cerr << "Error allocating memory for records" << std::endl;
        exit(EXIT_FAILURE);
    }
    return new std::vector<Record>(memory, memory + size);
}

std::vector<int>* allocate_keys(size_t size) {
    auto memory = static_cast<int*>(malloc(size * sizeof(int)));
    if (!memory) {
        std::cerr << "Error allocating memory for keys" << std::endl;
        exit(EXIT_FAILURE);
    }
    return new std::vector<int>(memory, memory + size);
}

std::vector<char>* allocate_work_buffer(size_t size) {
    auto memory = static_cast<char*>(malloc(size));
    if (!memory) {
        std::cerr << "Error allocating memory for work buffer" << std::endl;
        exit(EXIT_FAILURE);
    }
    return new std::vector<char>(memory, memory + size);
}

void free_resources(std::vector<long>* offsets) {
    if (offsets) {
        munmap(const_cast<void*>(offsets->data()), offsets->size() * sizeof(long));
        delete offsets;
    }
}

void free_resources(std::vector<Record>* records) {
    if (records) {
        delete records;
    }
}

void free_resources(std::vector<int>* keys) {
    if (keys) {
        free(const_cast<void*>(keys->data()));
        delete keys;
    }
}

void free_resources(std::vector<char>* work_buffer) {
    if (work_buffer) {
        free(const_cast<void*>(work_buffer->data()));
        delete work_buffer;
    }
}
```

