        private readonly ICipher _cipher;

        public DataProcessor(string password)
        {
            _cryptographicKey = new CryptographicPersistentKey(password);
            _cipher = new AesCbc(_cryptographicKey.DeriveKey());
        }

        public int RandomIntegerInRange(int min, int max)
        {
            if (min >= max) throw new ArgumentException("Minimum value must be less than the maximum value.");

            var rand = new Random();
            return Math.Max(Math.Min(rand.Next(min, max + 1), max), min);
        }

        public float RandomFloatInRange(float min, float max)
        {
            if (min >= max) throw new ArgumentException("Minimum value must be less than the maximum value.");

            var rand = new Random();
            return (float)(Math.Max(Math.Min((double)rand.NextDouble() * (max - min) + min, max), min));
        }

        public ICipherKey DeriveKey(string password)
        {
            if (_cryptographicKey is null)
                _cryptographicKey = new CryptographicPersistentKey(password);
            return _cryptographicKey.DeriveKey();
        }

        public ICipher InitializeCipher() => _cipher;

        private void CleanupResources()
        {
            if (_cipher is IDisposable disposable)
                disposable.Dispose();
        }
    }
}
