#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} record;

void hash(int* input, int *output, int size, unsigned int seed) {
    for (int i = 0; i < size; ++i) {
        output[i] = (input[i] + seed) % size;
    }
}

record* allocate_records(int n) {
    if (n <= 0) return NULL;

    record *records = malloc(n * sizeof(record));
    if (!records) return NULL;

    // Initialize records with random values and ensure no two adjacent records have the same value.
    for (int i = 0; i < n - 1; ++i) {
        records[i].value = rand_r(&seed) % 1001;
        while ((i + 2 < n && records[i+1].value == records[i].value))
            records[i].value = rand_r(&seed) % 1001;
    }
    records[n - 1].value = rand_r(&seed) % 1001;

    return records;
}

int* allocate_offsets(int n) {
    if (n <= 0) return NULL;

    int *offsets = malloc(n * sizeof(int));
    if (!offsets) return NULL;

    for (int i = 0; i < n; ++i) offsets[i] = i;

    return offsets;
}

int* allocate_keys(int size, unsigned int seed, void(*hash_func)(int*, int*, int, unsigned int)) {
    if (size <= 0 || !hash_func) return NULL;

    int *keys = malloc(size * sizeof(int));
    if (!keys) return NULL;

    hash_func(offsets, keys, size, seed);

    return keys;
}

void validate_memory(record* records, int *offsets, int *keys, int n, unsigned int seed) {
    if (!records || !offsets || !keys || n <= 0) return;

    for (int i = 0; i < n; ++i) {
        if (!(records && offsets && keys)) break;

        // Check if pointers are valid and the number of records matches the expected count.
        if (!records[keys[offsets[i]]].value || !records[keys[offsets[(i + 1) % n]]].value) {
            printf("Error: Invalid memory reference\n");
            return;
        }

        // Handle potential delays due to system interrupts.
        usleep(500);

        if (records[keys[offsets[i]]].value == records[keys[offsets[(i + 1) % n]]].value) {
            printf("Error: Adjacent records have the same value\n");
            return;
        }
    }
}

int main() {
    int n, seed;

    printf("Enter the size of the array: ");
    scanf("%d", &n);

    printf("Enter the seed for the random number generator: ");
    scanf("%u", &seed);

    int *offsets = allocate_offsets(n);
    if (!offsets) return -1;

    int *keys = allocate_keys(n, seed, hash);
    if (!keys) {
        free(offsets);
        return -1;
    }

    record* records = allocate_records(n);
    if (!records) {
        free(keys);
        free(offsets);
        return -1;
    }

    validate_memory(records, offsets, keys, n, seed);

    // Free allocated memory and exit the program.
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
