typedef struct {
    pthread_rwlock_t lock;
    int min, max;
    int *cache;
    size_t cache_size;
} ValueGenerator;

struct Record {
    int key;
    int value;
};

ValueGenerator gen;
long offsets[3];
int keys[3];
struct Record data[3];

void init_gen(int min, int max) {
    gen.min = min;
    gen.max = max;
    gen.cache = malloc((max - min + 1) * sizeof(int));
    gen.cache_size = max - min + 1;
    pthread_rwlock_init(&gen.lock, NULL);
}

int get_value(ValueGenerator *gen, int key) {
    if (key < gen->min || key > gen->max) return -1;
    int index = key - gen->min;
    pthread_rwlock_rdlock(&gen->lock);
    int value = gen->cache[index];
    pthread_rwlock_unlock(&gen->lock);
    if (value != 0) return value;

    // Generate and cache the value if not found in the cache.
    pthread_rwlock_wrlock(&gen->lock);
    if (gen->cache[index] == 0) {
        gen->cache[index] = rand() % (gen->max - gen->min + 1) + gen->min;
    }
    pthread_rwlock_unlock(&gen->lock);
    return gen->cache[index];
}

void manage_memory(int num_threads, ValueGenerator *gen) {
    // Initialize memory allocations.
    for (int i = 0; i < 3; ++i) {
        offsets[i] = 0;
        keys[i] = -1;
    }

    // Fetch initial offset values from the external data source.
    // ...

    // Allocate memory for records using the generated values.
    for (int i = 0; i < num_threads; ++i) {
        keys[offsets[2]] = get_value(gen, i);
        data[offsets[2]++].key = i;
        data[offsets[2] - 1].value = 42; // Placeholder value.
    }
}
```

