The `get_value()` function ensures that previously generated values are reused when possible, providing a thread-safe caching mechanism to minimize redundant computations. It also handles potential inconsistencies due to race conditions during data fetching and updating by implementing a read-write lock for synchronization.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *str;
    int val;
    struct Node *next;
} Node;

typedef struct DataStruct {
    Node **nodes;
    int *int_arr;
    char **str_arr;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DataStruct;

DataStruct *init_data_struct(size_t size) {
    DataStruct *ds = malloc(sizeof(DataStruct));
    ds->size = size;
    ds->capacity = size;
    ds->nodes = calloc(size, sizeof(Node*));
    ds->int_arr = malloc(size * sizeof(int));
    ds->str_arr = malloc(size * sizeof(char*));
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void free_data_struct(DataStruct *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->nodes[i]) {
            free(ds->nodes[i]->str);
            free(ds->nodes[i]);
        }
    }
    free(ds->int_arr);
    free(ds->str_arr);
    free(ds);
}

char *generate_unique_id(size_t size) {
    static char ids[1024][32];
    static size_t pos = 0;
    return strdup(&ids[pos % size][0]);
}

void insert_node(DataStruct *ds, int index, const char *str, int val) {
    Node **current = ds->nodes + index;
    Node *new_node = malloc(sizeof(Node));
    new_node->str = strdup(str);
    new_node->val = val;
    new_node->next = NULL;

    pthread_mutex_lock(&ds->mutex);
    while (*current) {
        current = &(*current)->next;
    }
    *current = new_node;
    pthread_mutex_unlock(&ds->mutex);
}

void remove_node(DataStruct *ds, int index) {
    Node **current = ds->nodes + index;
    if (!*current) return;

    pthread_mutex_lock(&ds->mutex);
    Node *prev = NULL;
    while ((*current)) {
        prev = current;
        current = &(*current)->next;
    }
    if (prev) {
        prev->next = (*current)->next;
    } else {
        ds->nodes[index] = NULL;
    }
    free((*current)->str);
    free(*current);
    pthread_mutex_unlock(&ds->mutex);
}

void populate(DataStruct *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        insert_node(ds, i, generate_unique_id(ds->size), rand() % 100 + 1);
        ds->int_arr[i] = rand() % 100 + 1;
    }
}

