[' Here is a C++11 solution using `libxml2` library for XML parsing and dynamic memory allocation with smart pointers from `<memory>`. The function, named `DataManager`, takes an XPath string and a number of records as parameters and manages the memory for offsets, keys, and record structures.

```cpp
#include <iostream>
#include <vector>
#include <map>
#include <memory>
#include <libxml/parser.h>

using Record = struct { int value; };

class DataManager {
public:
    DataManager(const char* xpath, size_t numRecords) {
        parseXML(xpath);
        resizeArrays(numRecords);
    }

    void resizeArrays(size_t numRecords) {
        offsets.resize(numRecords + 1);
        keys.resize(numRecords);
        records.resize(numRecords);
    }

    int getNextOffset() { return ++offsets[lastOffset]; }
    void setKey(size_t index, int key) { keys[index] = key; }
    Record& getRecord(size_t index) { return records[index]; }

private:
    void parseXML(const char* xpath) {
        xmlDocPtr doc = xmlReadFile(xpath, NULL, 0);
        if (!doc || !xmlStrcmp(xmlGetProp(xmlDocGetRootElement(doc), (xmlChar*)"name"))) {
            xmlFreeDoc(doc);
            std::cerr << "Error: No element found or multiple elements returned." << std::endl;
            return;
        }

        xmlNodeSetPtr nodes = xmlSearchGeneral(doc, (xmlChar*)"*", xpath);
        if (!nodes || !xmlNodesDoFunc(nodes->nodeTab, this, reinterpret_cast<xmlNodeVisitorFunc>(elementHandler), 0)) {
            std::cerr << "Error: No element found or multiple elements returned." << std::endl;
        }
    }

    static int elementHandler(void* data, xmlNodePtr node) {
        auto dm = reinterpret_cast<DataManager*>(data);
        if (node->type == XML_ELEMENT_NODE && !xmlStrcmp(node->name, (xmlChar*)"record")) {
            auto recordIt = records.begin();
            std::advance(recordIt, dm->lastOffset);
            xmlNodePtr keyNode = xmlGetProp(node, (xmlChar*)"key");
            int key = atoi((char*)keyNode->content);
            if (key >= 0 && static_cast<size_t>(key) < records.size()) {
                Record& record = *recordIt;
                xmlNodePtr valueNode = xmlGetProp(node, (xmlChar*)"value");
                record.value = atoi((char*)valueNode->content);
                dm->lastOffset++;
            }
        }
        return 0;
    }

    std::vector<long> offsets;
    std::vector<std::unique_ptr<int[]>> keys;
    std::vector<std::unique_ptr<Record[]>> records;
    size_t lastOffset = 0;
};
```

To use the DataManager, you can do:

```cpp
