    for (size_t i = 0; i < numRecords; ++i) {
        int key = i * 2 + 1;
        dataManager.setKey(i, key);
        dataManager.getRecord(i).value = key * 3;
    }

    // Access the managed arrays and structures using getNextOffset(), setKey(), and getRecord() functions
}
