void register_callback(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*));

// Helper functions for memory management and error handling
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void safe_free(void* ptr) {
    free(ptr);
}

// Function to read RNTI values from standard input and store in a dynamically allocated array
NFAPI_CRC_INDICATION_PDU_T* read_rntis() {
    size_t num_entries = 0;
    int max_num_entries = 10000;
    NFAPI_CRC_INDICATION_PDU_T* rnti_list = safe_malloc(max_num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < max_num_entries; ++i) {
        int rnti;
        if (scanf("%d", &rnti) != 1) break; // Break if invalid input

        bool duplicate = false;
        for (size_t j = 0; j < num_entries && !duplicate; ++j) {
            if (rnti == rnti_list[j].rnti) {
                char suffix = 'a';
                while (true) {
                    duplicate = false;
                    for (size_t k = 0; k < num_entries && !duplicate; ++k) {
                        if (rnti + suffix - 'a' == rnti_list[k].rnti) {
                            suffix++;
                            break;
                        }
                        if (rnti + suffix == rnti_list[k].rnti) {
                            duplicate = true;
                            break;
                        }
                    }
                    if (!duplicate) {
                        rnti = rnti + suffix - 'a';
                        rnti_list[i] = (NFAPI_CRC_INDICATION_PDU_T){ .rxi = i, .rnti = rnti };
                        num_entries++;
                        break;
                    }
                }
            } else if (j == num_entries - 1) { // If not a duplicate, add the RNTI to the list and increment the number of entries
                rnti_list[i] = (NFAPI_CRC_INDICATION_PDU_T){ .rxi = i, .rnti = rnti };
                num_entries++;
            }
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* final_list = safe_malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < num_entries; ++i) {
        final_list[i] = rnti_list[i];
    }
    safe_free(rnti_list);
    return final_list;
}

void find_min_max_rntis(NFAPI_CRC_INDICATION_PDU_T* list, size_t len, int* min_unused, int* max) {
    *min_unused = INT32_MAX;
    *max = INT32_MIN;

    for (size_t i = 0; i < len; ++i) {
        if (list[i].rnti < *min_unused) {
            *min_unused = list[i].rnti;
        }
        if (list[i].rnti > *max && list[i].rnti <= MAX_RNTI) {
            *max = list[i].rnti;
        }
    }
}

