[' Here is a simplified C++ example using an unordered_map (hash table) for efficient lookups, a mutex for thread safety, and a cache for reducing external data source access.

```cpp
#include <iostream>
#include <unordered_map>
#include <mutex>
#include <memory>
#include <atomic>
#include <functional>
#include <thread>
#include <future>

class CRCIndicationPdu {
public:
    explicit CRCIndicationPdu(uint32_t rnti) : rnti_(rnti), crcFlag_(false) {}
    uint32_t GetRNTI() const { return rnti_; }
    bool GetCRCFlag() const { return crcFlag_.load(); }
    void SetCRCFlag(bool value) { crcFlag_.store(value); }
private:
    uint32_t rnti_;
    std::atomic<bool> crcFlag_;
};

class NFAPI_CRC_INDICATION_PDU_T_Manager {
public:
    void Add(const CRCIndicationPdu& pdu) {
        mutex_.lock();
        data_[pdu.GetRNTI()] = std::make_unique<CRCIndicationPdu>(pdu);
        mutex_.unlock();
    }

    std::shared_ptr<CRCIndicationPdu> Get(uint32_t rnti) {
        auto it = data_.find(rnti);
        if (it == data_.end()) return nullptr;

        mutex_.lock();
        auto ptr = it->second.get();
        mutex_.unlock();
        return std::shared_ptr<CRCIndicationPdu>(ptr);
    }

    void UpdateCRCFlag(uint32_t rnti, bool value) {
        auto it = data_.find(rnti);
        if (it == data_.end()) return;

        mutex_.lock();
        it->second->SetCRCFlag(value);
        mutex_.unlock();
    }

private:
    std::unordered_map<uint32_t, std::unique_ptr<CRCIndicationPdu>> data_;
    std::mutex mutex_;
};

// Example usage in a thread-safe manner
void ProcessPDU(const NFAPI_CRC_INDICATION_PDU_T_Manager& manager, uint32_t rnti) {
    auto pdu = manager.Get(rnti);
    if (pdu) {
        // Process the PDU here...
        manager.UpdateCRCFlag(rnti, true);
    }
}

void RunExample() {
    NFAPI_CRC_INDICATION_PDU_T_Manager manager;
    std::vector<std::thread> threads;

    // Add some PDUs to the collection
    for (int i = 0; i < 1000; ++i) {
        manager.Add(CRCIndicationPdu(i));
    }

    // Process each PDU in a thread-safe manner
    for (auto& pdu : manager.GetAllPDUs()) {
        threads.emplace_back(ProcessPDU, std::ref(manager), pdu->first);
    }

    for (auto& t : threads) t.join();
}
