typedef struct Node {
    char* key;
    int value;
    struct Node* next;
} Node;

struct DataStruct {
    size_t capacity;
    size_t currentSize;
    Node** nodes;
    char** strings;
    int* integers;
    pthread_mutex_t mutex;
};

void initDS(struct DataStruct* ds, size_t maxStrings, size_t maxNodes, size_t maxIntegers) {
    ds->capacity = maxStrings + maxNodes + maxIntegers;
    ds->currentSize = 0;
    ds->strings = (char**)malloc(ds->capacity * sizeof(char*));
    ds->nodes = (Node**)calloc(ds->capacity, sizeof(Node*));
    ds->integers = (int*)malloc(ds->capacity * sizeof(int));
    memset(ds->integers, 0, ds->capacity * sizeof(int));
    pthread_mutex_init(&ds->mutex, NULL);
}

void expandDS(struct DataStruct* ds) {
    if (ds->currentSize == ds->capacity) {
        size_t newCapacity = ds->capacity * 2;
        char** tmpStrings = realloc(ds->strings, newCapacity * sizeof(char*));
        Node** tmpNodes = realloc(ds->nodes, newCapacity * sizeof(Node*));
        int* tmpIntegers = realloc(ds->integers, newCapacity * sizeof(int));

        if (tmpStrings && tmpNodes && tmpIntegers) {
            ds->strings = tmpStrings;
            ds->nodes = tmpNodes;
            ds->integers = tmpIntegers;
            ds->capacity *= 2;
        }
    }
}

void logEvent(const char* message) {
