#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

struct MemoryPool {
    void* data;
    size_t capacity;
    size_t count;
};

struct MemoryPool *record_pool = NULL;
pthread_mutex_t record_pool_lock = PTHREAD_MUTEX_INITIALIZER;
size_t max_records = 0;

void init_memory_pool(size_t capacity) {
    if (capacity > max_records) return;

    pthread_mutex_lock(&record_pool_lock);

    if (!record_pool) {
        record_pool = malloc(sizeof(struct MemoryPool));
        record_pool->data = calloc(capacity, sizeof(Record));
        record_pool->capacity = capacity;
        record_pool->count = 0;
    } else {
        free(record_pool);
        record_pool = malloc(sizeof(struct MemoryPool));
        record_pool->data = realloc(record_pool->data, (capacity + record_pool->count) * sizeof(Record));
        record_pool->capacity += capacity;
    }

    pthread_mutex_unlock(&record_pool_lock);
}

Record* get_record() {
    pthread_mutex_lock(&record_pool_lock);
    Record* record = (Record*) ((char*) record_pool->data + record_pool->count * sizeof(Record));
    record_pool->count++;
    pthread_mutex_unlock(&record_pool_lock);

    if (record_pool->count > max_records) {
        free(record_pool);
        record_pool = NULL;
        return NULL;
    }

    return record;
}

void free_record(Record* record) {
    pthread_mutex_lock(&record_pool_lock);
    memcpy((char*) record_pool->data + (record - (Record*) record_pool->data), record, sizeof(Record));
    pthread_mutex_unlock(&record_pool_lock);
}

void* generate_unique_filepath(const char* input_dir, const char* input_filename) {
    // Extract directory path, base name and file extension from the input filename
    size_t dir_len = strlen(input_dir);
    size_t base_name_len;
    size_t file_extension_len = 4; // Default extension length (e.g., .json, .xml, .html)
    const char* base_name = strrchr(input_filename, '.');
    if (!base_name) {
        base_name_len = strlen(input_filename);
    } else {
        base_name_len = base_name - input_filename;
        file_extension_len = base_name_len + 1;
    }

    char dir[256], base[256], ext[16];
    strncpy(dir, input_dir, sizeof(dir) - 1);
    strncpy(base, input_filename, sizeof(base) - file_extension_len);
    strncpy(ext, ".json", sizeof(ext) - 1);

    // Generate a unique file extension based on the base name
    for (size_t i = base_name_len; i < strlen(base); ++i) {
        if (strchr(".json.xml.html", base[i])) {
            strcpy(ext, &base[i]);
            break;
        }
    }

    // Set the number of digits for the new file extension based on the count of directories in the path
    int num_dirs = 0;
    const char* dir_ptr = dir;
    while (*dir_ptr && *dir_ptr != '/') ++num_dirs, dir_ptr++;
    if (num_dirs > 10) {
        snprintf(ext + file_extension_len - num_digits(num_dirs), sizeof(ext) - 1, "%x", num_dirs);
        ext[sizeof(ext) - 1] = '\0';
    }

    // Check if the directory exists and create it if necessary
    DIR* dir_fd = opendir(dir);
    if (!dir_fd) {
        // Handle issues such as insufficient permissions, symbolic link loops, etc.
        // ...
        return NULL;
    }
    closedir(dir_fd);

    // Generate the new file path and check for existence
    char file[256];
    snprintf(file, sizeof(file), "%s/%s%s", dir, base, ext);
    FILE* fp = fopen(file, "w");
    if (!fp) {
        // Handle issues such as insufficient disk space, permission denied errors, etc.
        // ...
        return NULL;
    }
    fclose(fp);

    return file;
}

