Record records[MAX_RECORDS];
int keys[MAX_RECORDS];
long offsets[MAX_RECORDS];
char *stringPool[STRINGS_COUNT] = {"str1", "str2", "str3", "str4", "str5"};

Record* createRecord(int key, long offset) {
    Record* record = calloc(1, sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    strcpy(record->buffer, stringPool[key % STRINGS_COUNT]);
    return record;
}

void destroyRecord(Record* record) {
    free(record);
}

bool validateRecords() {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (!records[i] || !keys[i] || !offsets[i] || records[i]->key != keys[i] || records[i]->offset != offsets[i]) {
            return false;
        }
    }
    return true;
}

Record* getRecordByKey(int key) {
    if (key < 0 || key >= MAX_RECORDS || !keys[key]) return NULL;
    return records[key];
}

void cacheRecord(int key, Record* record) {
    // Implement a simple LRU caching strategy here.
    // For simplicity, we assume that the cache is always empty at program start.
    int index = -1;
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (!keys[i]) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        keys[index] = 0;
        records[index] = NULL;
        offsets[index] = 0;
    }

    if (record) {
        keys[key] = 1;
        records[key] = record;
        offsets[key] = record->offset;
    }
}

