typedef struct Record {
    char name[10];
    double probability;
    int offset, key;
} Record;

Record* create_records(int n) {
    if (n <= 0) return NULL;

    Record *records = malloc(n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Insufficient memory.\n");
        return NULL;
    }

    int *offsets = malloc(n * sizeof(int));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Error: Insufficient memory.\n");
        return NULL;
    }

    int *keys = malloc(n * sizeof(int));
    if (!keys) {
        free(records);
        free(offsets);
        fprintf(stderr, "Error: Insufficient memory.\n");
        return NULL;
    }

    // Initialize pointers in each record to point to corresponding elements in the offsets and keys arrays.
    for (int i = 0; i < n; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    return records;
}

void resize_arrays(Record **records, int *old_size, int new_size, int **new_array) {
    if (new_size <= 0 || !*records || (*old_size >= new_size)) return;

    *new_array = realloc(*new_array, new_size * sizeof(**new_array));
    if (!*new_array) {
        fprintf(stderr, "Error: Insufficient memory.\n");
        return;
    }

    // Move elements from the old array to the new one while updating pointers in records.
    for (int i = 0; i < *old_size && i < new_size; ++i) {
        (*records)[i].offset = (*new_array)[i];
        (*new_array)[i] = (&((*records)[i]))[(*old_size >= new_size ? new_size - 1 : *old_size)][0].key;
    }

    *old_size = new_size;
}

Record* initialize_records(int n, int offsets_size, int keys_size) {
    if (n <= 0 || offsets_size <= 0 || keys_size < n) return NULL;

    Record *records = create_records(n);
    if (!records) return NULL;

    int *offsets = malloc(offsets_size * sizeof(int));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Error: Insufficient memory.\n");
        return NULL;
    }

    int *keys = malloc(keys_size * sizeof(int));
    if (!keys) {
        free(records);
        free(offsets);
        fprintf(stderr, "Error: Insufficient memory.\n");
        return NULL;
    }

    // Initialize offsets and keys arrays with user input.
    for (int i = 0; i < offsets_size && i < keys_size; ++i) {
        offsets[i] = -1;
        keys[i] = -1;
    }

    resize_arrays(&records, &n, offsets_size, &offsets);
    resize_arrays(&records, &n, keys_size, &keys);

    srand(time(NULL)); // Initialize random seed.

    for (int i = 0; i < n; ++i) {
        strcpy(records[i].name, "");
        records[i].probability = ((double) rand() / RAND_MAX); // Generate random probability values.
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    return records;
}

void free_memory(Record **records, int *offsets, int *keys) {
    if (!records) return;

    free(*records);
    free(offsets);
    free(keys);
}
