#define MAX_ELEMENTS 10000
#define POOL_GRANULARITY (MAX_ELEMENTS / 4)
#define HEAP_SIZE 512 * 1024

NFAPI_CRC_INDICATION_PDU_T* pool;
size_t currentPoolSize = 0;
size_t allocatedPoolSize = 0;

void customAlloc(size_t size) {
    void* memoryBlock = malloc(size);
    if (!memoryBlock) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(1);
    }
    allocatedPoolSize += size;
}

void customFree(void* ptr) {
    allocatedPoolSize -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

void resizePool() {
    if (currentPoolSize == MAX_ELEMENTS) return;

    // Adjust pool size heuristically based on observed insertion patterns
    double loadFactor = (double) currentPoolSize / allocatedPoolSize;
    if (loadFactor > 0.75) {
        customAlloc(POOL_GRANULARITY * (MAX_ELEMENTS - currentPoolSize));
    }
}

NFAPI_CRC_INDICATION_PDU_T* getElementFromPool() {
    resizePool();
    if (currentPoolSize >= MAX_ELEMENTS) return NULL;
    NFAPI_CRC_INDICATION_PDU_T* element = pool + currentPoolSize++;
    element->CRCFLAG = rand() % 2;
    return element;
}

int createDynamicList(size_t n) {
    if (n > MAX_ELEMENTS) return -1; // List size exceeds maximum capacity

    customAlloc(HEAP_SIZE);
    pool = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    currentPoolSize = 0;

    srand(time(NULL)); // Seed random number generator for CRCFLAG generation

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    int i;
    for (i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* newElement = getElementFromPool();
        if (!newElement) return -1; // Pool exhaustion

        if (!head) {
            head = current = newElement;
        } else {
            current->next = newElement;
            current = current->next;
        }
    }
    current = NULL;

    return 0;
}

void verifyListIntegrity(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        if (current->CRCFLAG >= 2 || (current->CRX_UE_INFORMATION_TAG & ~0xFFFFFFFF)) {
            fprintf(stderr, "List integrity error: invalid structure field\n");
            exit(1);
        }
        current = current->next;
    }
}
