    list->capacity = (max_elements > SIZE_MAX - sizeof(NFAPI_CRC_INDICATION_PDU_T)) ? SIZE_MAX : max_elements;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->elements = calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
