#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <json-c/json.h>

typedef struct {
    char buffer[256]; // Task description
    int priority;
    struct task *dependent;
} task;

typedef struct {
    time_t timestamp;
    char buffer[128]; // Status message
} status;

struct collection {
    pthread_mutex_t lock;
    size_t count;
    task **tasks;
    status *statuses;
};

task* task_new() {
    task *task = malloc(sizeof(task));
    if (!task) return NULL;
    snprintf(task->buffer, sizeof(task->buffer), "Task #%zu", (size_t)(task - *((task**)tasks)));
    task->priority = rand() % 5 + 1;
    task->dependent = NULL;
    return task;
}

status* status_new() {
    status *status = malloc(sizeof(status));
    if (!status) return NULL;
    return status;
}

void collect_init(struct collection *coll, size_t capacity) {
    coll->count = 0;
    coll->tasks = calloc(capacity, sizeof(task*));
    if (!coll->tasks) goto error;
    coll->statuses = calloc(capacity, sizeof(status));
    if (!coll->statuses) goto error;
    pthread_mutex_init(&coll->lock, NULL);
}

void collect_deinit(struct collection *coll) {
    size_t i;
    for (i = 0; i < coll->count; ++i) {
        free(coll->tasks[i]);
    }
    free(coll->tasks);
    free(coll->statuses);
    pthread_mutex_destroy(&coll->lock);
}

void collect_push(struct collection *coll, task *task, status *status) {
    pthread_mutex_lock(&coll->lock);
    coll->tasks[coll->count++] = task;
    coll->statuses[coll->count - 1] = status;
    pthread_mutex_unlock(&coll->lock);
}

char* collect_serialize(const struct collection *coll) {
    json_object *root, *tasks, *task_item, *status_item;
    char *serialized;
    size_t i, j;

    root = json_object_new_array();

    tasks = json_object_new_array();
    for (i = 0; i < coll->count; ++i) {
        task_item = json_object_new_object();
        json_object_object_add(task_item, "id", json_string(coll->tasks[i]->buffer));
        json_object_object_add(task_item, "priority", json_int(coll->tasks[i]->priority));
        if (coll->tasks[i]->dependent) {
            json_object_object_add(task_item, "dependency", json_string(coll->tasks[i]->dependent->buffer));
        } else {
            json_object_object_add(task_item, "dependency", json_null());
        }
        json_object_array_append(tasks, task_item);
    }
    json_object_array_append(root, tasks);

    statuses = json_object_new_array();
    for (i = 0; i < coll->count; ++i) {
        status_item = json_object_new_object();
        json_object_object_add(status_item, "timestamp", json_int((long int)(coll->statuses[i].timestamp)));
        json_object_object_add(status_item, "message", json_string(coll->statuses[i].buffer));
        json_object_array_append(statuses, status_item);
    }
    json_object_array_append(root, statuses);

    serialized = json_object_to_json_string(root);
    json_object_put(root);
    return serialized;
error:
    collect_deinit(coll);
    return NULL;
}

void *collect_save(const struct collection *coll, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return (void*)-1;
    fputs(collect_serialize(coll), file);
    fclose(file);
    return 0;
}
