#include <sys/stat.h>

#define MAX_BUFFER_SIZE 512
#define FILE_EXTENSION_LENGTH 8 // Assuming typical extensions like .txt, .jpg, etc., adjust as needed
static char static_buffer[MAX_BUFFER_SIZE] = {0};
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* constructFileName(const char *filePath, size_t maxBufferSize, const char *extension) {
    pthread_mutex_lock(&mutex);
    strncpy(static_buffer, filePath, min(MAX_BUFFER_SIZE-1, strlen(filePath))); // -1 to account for null terminator
    static_buffer[MAX_BUFFER_SIZE-1] = '\0'; // Ensure buffer is null-terminated

    size_t pathLength = strlen(static_buffer);
    if (pathLength + extensionLength > maxBufferSize) {
        strncpy(static_buffer, static_buffer, min(MAX_BUFFER_SIZE-1, MAX_BUFFER_SIZE/2)); // Truncate original file path
    }

    size_t extPosition = pathLength - 1;
    while (extPosition > 0 && static_buffer[extPosition] != '.') {
        --extPosition;
    }

    if (!extension || !extPosition || extPosition == 0) { // No extension or extension already present in file path
        strcat(static_buffer, extension);
    }

    pthread_mutex_unlock(&mutex);
    return static_buffer;
}
