    static std::regex pattern(R"(([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})|([A-Fa-f0-9]{1,4}:([A-Fa-f0-9:%.]+):)([A-Za-z0-9._-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,}))");
