    }
    return false;
}

// ParseAndValidateEmails function
std::vector<const char*>* parseAndValidateEmails(const std::string& input, size_t maxSize) {
    std::istringstream iss(input);
    std::vector<const char*> emails;
    std::string email;
    while (iss >> email) {
        if (isValidEmail(email)) {
            emails.push_back(strdup(email.c_str()));
            if (emails.size() >= maxSize) break;
        }
    }
    if (emails.empty()) return nullptr;
    std::sort(emails.begin(), emails.end());
    emails.resize(maxSize);
    return &emails[0];
}

// FilterAndAggregateData function
std::unordered_map<std::string, int> filterAndAggregateData(const std::string& jsonFile, int minAge, int maxAge, const std::string& location) {
    Json::CharReaderBuilder builder;
    Json::CharReader* reader = builder.newCharReader();
    Json::Value root;
    std::string errs;
    bool parsingSuccessful = reader->parse(jsonFile.c_str(), jsonFile.c_str() + jsonFile.size(), &root, &errs);
    delete reader;
    if (!parsingSuccessful) {
        std::cerr << "Error parsing JSON: " << errs << std::endl;
        return {};
    }

    std::unordered_map<std::string, int> locationCounts;
    std::mutex mtx;

    auto processUser = [&](Json::Value user) {
        if (!user.isMember("age") || !user["age"].isInt() || !user["location"].isString()) return;
        int age = user["age"].asInt();
        if (age < minAge || age > maxAge) return;
        if (location.empty() || location == user["location"].asString()) {
            std::lock_guard<std::mutex> lock(mtx);
            ++locationCounts[user["location"].asString()];
        }
    };

    for (auto& item : root) {
        processUser(item);
    }
    return locationCounts;
}
```

This code uses the Boost library for email validation and jsoncpp for JSON parsing and manipulation. It adheres to the requirements of efficient memory usage, performance, concurrency safety, and graceful error handling while balancing flexibility and scalability with custom data structures.']

