AES_CTX* initializeNfaApiWithCrcIndications(const char *password) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;
    AES_KEY aesKey;
    unsigned char iv[AES_BLOCK_SIZE];

    // Generate random RNTI and CRCFLAG for each structure
    uint64_t rnti = 0x1234567890abcdef;
    int crcFlag = (rand() % 2) + 1;

    // Initialize the list
    head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) {
        perror("malloc error");
        goto cleanup;
    }
    current = head;

    // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG for the first structure
    current->rxUeInformationTag = RX_UE_INFO_TAG_CRC_INDICATION;
    current->rnti = rnti;
    current->crcIndicationRel8.crcFlag = crcFlag;

    // Initialize AES-256-CBC cipher with password and set IV
    SHA256(password, strlen(password), iv, sizeof(iv));
    AES_set_encrypt_key((const unsigned char *)password, 256, &aesKey);
    AES_cbc_init(&aesKey, iv, iv);

    // Create the remaining structures in the list if needed (assuming you have a mechanism to fetch CRC indications)
    while (/* condition to create more structures */) {
        current->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current->next) {
            perror("malloc error");
            goto cleanup;
        }
        current = current->next;

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG for the new structure
        current->rxUeInformationTag = RX_UE_INFO_TAG_CRC_INDICATION;
        current->rnti = rnti++; // Increment RNTI for each new structure
        current->crcIndicationRel8.crcFlag = (rand() % 2) + 1;
    }

    current->next = head; // Circular list
    current = head;       // Reset current to the start of the list

    AES_CTX *aesCtx = malloc(sizeof(AES_CTX));
    if (!aesCtx) {
        perror("malloc error");
        goto cleanup;
    }
    memcpy(aesCtx, &aesKey, sizeof(AES_KEY));

    return aesCtx;

cleanup:
    cleanupNfaApi((NFAPI_CRC_INDICATION_PDU_T **)&head, aesCtx);
    return NULL;
}

void cleanupNfaApi(NFAPI_CRC_INDICATION_PDU_T **crcIndications, AES_CTX *aesCtx) {
    NFAPI_CRC_INDICATION_PDU_T *current = *crcIndications;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    if (aesCtx != NULL) {
        free(aesCtx);
    }
}
```

