#define MAX_ALLOCATION (0.9 * getenv("MEMORY_LIMIT") ? atoi(getenv("MEMORY_LIMIT")) : 1000000) // Set maximum allocation limit based on MEMORY_LIMIT environment variable or default to 1M

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
