NFAPI_CRC_INDICATION_PDU_T* createPDUs(uint16_t N, uint32_t seed) {
    if (N <= 0 || N > MAX_ALLOCATION) {
        fprintf(stderr, "Invalid UE count: %d\n", N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for %d PDUs\n", N);
        return NULL;
    }

    srand(seed); // Set seed for CRCFLAG generation

    uint64_t totalMemory = getenv("TOTAL_MEMORY") ? atoi(getenv("TOTAL_MEMORY")) : 100000000; // Total system memory in bytes (for memory usage calculation)
    size_t usedMemory = 0;

    for (uint16_t i = 0; i < N && usedMemory / (double)totalMemory <= 0.9; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = i % 65536; // Use the modulo operator to ensure RNTI is within valid range
        pdus[i].CRC_INDICATION_REL8_TAG = i / 256;
        pdus[i].CRCFLAG = rand() % 2;
        usedMemory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    if (N > usedMemory / sizeof(NFAPI_CRC_INDICATION_PDU_T)) { // Ensure all PDUs were correctly initialized and allocated
        pdus = realloc(pdus, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            fprintf(stderr, "Failed to reallocate memory for %d PDUs\n", N);
            free(pdus); // Free previously allocated memory before returning NULL
            return NULL;
        }
    }

    return pdus;
}
