    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

// Helper function for initializing a new TX_DATA_RECORD_T structure.
TX_DATA_RECORD_T *init_record() {
    TX_DATA_RECORD_T *data = malloc(sizeof(TX_DATA_RECORD_T));
    if (data == NULL) {
        log("Memory allocation failure.");
        return NULL;
    }

    data->tag = (TX_UE_INFORMATION_TAG)(rand() % UINT16_MAX);
    data->sequence_number = rand() % 0xFFFF;
    data->modulation = (MODULATION_AND_CODEWORD_INDICATION_REL15_TAG)(rand() % 32);

