}

// Helper function for initializing a new packet structure with a random byte value.
struct packet *init_packet(unsigned char min, unsigned char max) {
    struct packet *packet = malloc(sizeof(struct packet));
    if (packet == NULL) {
        log("Memory allocation failure.");
        return NULL;
    }

    packet->payload = rand() % (max - min + 1) + min;

    return packet;
}

void list_add(TX_DATA_RECORD_T *record) {
    sem_wait(&mem_sem);
    list_node_t *new_node = malloc(sizeof(list_node_t));
    if (new_node == NULL) {
        log("Memory allocation failure.");
        sem_post(&mem_sem);
        return;
    }

    new_node->data = *record;
    new_node->next = head;
    pthread_mutex_init(&new_node->lock, NULL);

    if (head != NULL) {
        // Use a mutex to ensure thread-safety when updating the head pointer.
        pthread_mutex_lock(&(new_node->lock));
        head->next = new_node;
        pthread_mutex_unlock(&(new_node->lock));
    } else {
        head = new_node;
    }

    sem_post(&mem_sem);
}

TX_DATA_RECORD_T *list_remove() {
    sem_wait(&mutex_sem);
    list_node_t *temp = head;
    if (head != NULL) {
        head = head->next;
        pthread_mutex_destroy(&(temp->lock));
    }
    sem_post(&mutex_sem);

    return &(temp->data);
}

// Initialize the logging system, mutexes, and semaphores.
void init() {
    log_file = fopen("log.txt", "w");
    if (log_file == NULL) {
        log("Failed to open log file.");
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    sem_init(&mutex_sem, 0, 1);
    sem_init(&mem_sem, 0, 50000);
}
