    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_NFAPI_PDU_COUNT 1024

struct nfapi_pdu_manager {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t mutex;
};

void nfapi_pdu_init(struct nfapi_pdu_manager** manager, size_t max_elements) {
    *manager = malloc(sizeof(struct nfapi_pdu_manager));
    if (!*manager) {
        return;
    }

    (*manager)->max_size = (max_elements > MAX_NFAPI_PDU_COUNT) ? MAX_NFAPI_PDU_COUNT : max_elements;
    (*manager)->current_size = 0;
    (*manager)->pdu_array = calloc((*manager)->max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*manager)->pdu_array) {
        free(*manager);
        *manager = NULL;
        return;
    }

    pthread_mutex_init(&(*manager)->mutex, NULL);
}

void nfapi_pdu_destroy(struct nfapi_pdu_manager** manager) {
    if (!*manager) {
        return;
    }

    free((*manager)->pdu_array);
    pthread_mutex_destroy(&(*manager)->mutex);
    free(*manager);
    *manager = NULL;
}

bool nfapi_pdu_is_full(const struct nfapi_pdu_manager* manager) {
    return (manager->current_size >= manager->max_size);
}

size_t nfapi_pdu_get_capacity(const struct nfapi_pdu_manager* manager) {
    return manager->max_size;
}

size_t nfapi_pdu_get_size(const struct nfapi_pdu_manager* manager) {
    return manager->current_size;
}

void nfapi_pdu_push(struct nfapi_pdu_manager* manager, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (nfapi_pdu_is_full(manager)) {
        return;
    }

    pthread_mutex_lock(&manager->mutex);
    memcpy(&manager->pdu_array[manager->current_size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->current_size++;
    pthread_mutex_unlock(&manager->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_pdu_pop(struct nfapi_pdu_manager* manager) {
    if (nfapi_pdu_get_size(manager) == 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = &manager->pdu_array[0];

    pthread_mutex_lock(&manager->mutex);
    memmove(&manager->pdu_array[0], &manager->pdu_array[1], (manager->current_size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->current_size--;
    pthread_mutex_unlock(&manager->mutex);

    return result;
}

void nfapi_pdu_reset_crcflag(struct nfapi_pdu_manager* manager, size_t index) {
    if (index >= manager->max_size || index >= manager->current_size) {
        return;
    }

    pthread_mutex_lock(&manager->mutex);
    manager->pdu_array[index].crc_indication.CRCFLAG = rand() % 2;
    pthread_mutex_unlock(&manager->mutex);
}
