    const char *code;
    char **dependencies;
    size_t dependencies_count;
} script_obj_t;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
static script_obj_t **scripts = NULL;
static size_t scripts_count = 0;

void renderFooterScripts(const script_obj_t *scripts, size_t N) {
    if (N > MAX_NFAPI_PDU_COUNT) {
        fprintf(stderr, "Error: Input size exceeds maximum limit\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    // Allocate memory for pdus and scripts arrays
    if (N > scripts_count) {
        script_obj_t **new_scripts = realloc(scripts, N * sizeof(script_obj_t*));
        if (!new_scripts) {
            fprintf(stderr, "Error: Out of memory\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        scripts = new_scripts;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(pdus, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) {
        fprintf(stderr, "Error: Out of memory\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    pdus = new_pdus;

    // Initialize structures with default values and allocate memory for dependencies arrays if necessary
    for (size_t i = scripts_count; i < N; ++i) {
        scripts[i] = mmap(NULL, sizeof(script_obj_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (scripts[i] == MAP_FAILED) {
            fprintf(stderr, "Error: Out of memory\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        scripts[i]->name = NULL;
        scripts[i]->code = NULL;
        scripts[i]->dependencies = NULL;
        scripts[i]->dependencies_count = 0;
    }

    size_t processed_scripts = 0;
    for (size_t i = 0; i < N && processed_scripts < N; ++i) {
        if (!scripts[i]->name || !scripts[i]->code) continue;

        // Ensure dependencies are resolved and loaded before executing the script
        resolveDependencies(scripts[i]);

        char id[32];
        snprintf(id, sizeof(id), (scripts[i]->name ? scripts[i]->name : hashFunction((const uint8_t*)scripts[i]->code, strlen(scripts[i]->code))), i);

        // Render script as <script> tag
        char *script_tag = renderScriptTag(scripts[i], id);

        // Concatenate rendered script tags into a single HTML string and store in the pdus array
        pdus[processed_scripts].RX_UE_INFORMATION_TAG = 0x1234;
        pdus[processed_scripts].RNTI = getpid();
        pdus[processed_scripts].CRC_INDICATION_REL8_TAG = (uint16_t)(rand() & 0xFFFF);
        pdus[processed_scripts].CRCFLAG = rand() % 2;

        size_t script_len = strlen(script_tag);
        char *new_pdus_ptr = &pdus[processed_scripts] + sizeof(NFAPI_CRC_INDICATION_PDU_T) - script_len;
        memcpy(new_pdus_ptr, script_tag, script_len);

        ++processed_scripts;
    }

    pthread_mutex_unlock(&mutex);

    // Return concatenated HTML string
    char *html = malloc((processed_scripts + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(html, pdus, processed_scripts * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    html[processed_scripts] = '\0';

    return html;
}

