    char *placeholders[];
    char replacements[][];
};

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRTC_INDICATION_PDU_T* generate_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return pdus;
}

void modify_config(const char *profile, int n, NFAPI_CRC_INDICATION_PDU_T *pdus) {
    struct config_profile *cp = get_config_profile(profile);
    FILE *file = fopen(cp->file, "r+");

    if (!file) {
        log_error("Failed to open configuration file '%s'", cp->file);
        return;
    }

    char buffer[1024];
    size_t len = 0;
    ssize_t nread;

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    while ((nread = getdelim(&buffer, sizeof(buffer), '\n', file)) != EOF) {
        len += nread;

        for (int i = 0; cp->placeholders[i]; ++i) {
            size_t placeholder_len = strlen(cp->placeholders[i]);
            size_t found = buffer + len - placeholder_len;

            if (strncmp(found, cp->placeholders[i], placeholder_len) == 0) {
                char replacement[sizeof(char*)];
                sprintf(replacement, cp->replacements[i]);
                memmove(found + strlen(replacement), found + cp->placeholders[i], len - (found - buffer));
                memcpy(found, replacement, strlen(replacement));
                len -= placeholder_len;
            }
        }
    }

    fseek(file, 0, SEEK_SET);
    fwrite(buffer, len, 1, file);

    pthread_mutex_destroy(&mutex);
}

void process() {
    // Initialize your config profiles and logging framework here

    const int num_pdus = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdus = generate_pdu(num_pdus);

    // Use multiple threads to modify the configuration file simultaneously
    pthread_t threads[num_pdus];

    for (int i = 0; i < num_pdus; ++i) {
