    if (attackRecords.empty()) {
        for (auto& record : attackRecords) {
            record.attackType = rand() % 2;
            record.isStale = false;
        }
    }

    auto currentTime = std::chrono::system_clock::now().time_since_epoch().count();
    const int COOLDOWN_SECONDS = 9;
    static const int UPDATE_INTERVAL_SECONDS = 60 * 5; // 5 minutes
    static uint64_t lastUpdateTime = currentTime - UPDATE_INTERVAL_SECONds;

    for (auto& record : attackRecords) {
        if (!record.isStale && currentTime - record.lastUpdatedTime > COOLDOWN_SECONDS) {
            // Handle external data source query here
            record.attackType = rand() % 2;
            record.isStale = false;
            lastUpdateTime = currentTime;
        } else if (record.isStale) {
            // Stale data handling
            record.attackType = (record.attackType + 1) % 2;
        }
    }

    int selectedAttack = rand() % MAX_ATTACKS;
    auto& selectedRecord = attackRecords[selectedAttack];
    if (selectedRecord.isStale) {
        std::cout << "Selected stale attack: " << selectedAttack << "\n";
    } else {
        std::cout << "Selected attack: " << selectedAttack << "\n";
    }
