typedef struct LockFreeRingBuffer {
    void** buffer;
    size_t capacity;
    size_t head;
    size_t tail;
} LockFreeRingBuffer;

void lockfree_ringbuffer_init(LockFreeRingBuffer* buffer, size_t capacity) {
    buffer->capacity = capacity;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->buffer = mmap(NULL, sizeof(void*) * capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buffer->buffer == MAP_FAILED) {
        perror("mmap failed");
        exit(-1);
    }
}

size_t lockfree_ringbuffer_push(LockFreeRingBuffer* buffer, void* item) {
    size_t index = buffer->head;
    while (1) {
        size_t next = index + 1 == buffer->capacity ? 0 : index + 1;
        if (__sync_val_compare_and_swap(buffer->buffer + index, item, buffer->buffer[next]) == buffer->buffer[next]) {
            buffer->head = next;
            return 1;
        }
    }
}

void* lockfree_ringbuffer_pop(LockFreeRingBuffer* buffer) {
    size_t index = buffer->tail;
    while (1) {
        size_t next = index + 1 == buffer->capacity ? 0 : index + 1;
        if (__sync_val_compare_and_swap(buffer->buffer + index, buffer->buffer[index], NULL)) {
            buffer->tail = next;
            return buffer->buffer[index];
        }
    }
}

