#define MAX_NFAPI_PDU_COUNT 10000
#define RESIZE_THRESHOLD 95
#define NUM_THREADS 4

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
