2. Implement a function to dynamically resize the array:

```c
void resize(NFAPI_CRC_INDICATION_PDU_T ***arr, int old_size, int new_size) {
    NFAPI_CRC_INDICATION_PDU_T **new_arr = mmap(NULL, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_arr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    memcpy(new_arr, *arr, old_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(*arr);
    *arr = new_arr;
}
```

3. Implement the main function handling thread creation and data insertion:

```c
void* worker(void* args) {
    THREAD_ARGS* ta = (THREAD_ARGS*)args;
    int idx = ta->id;
    while (true) {
        // Acquire a semaphore to signal resizing
        sem_wait(ta->resize_sem);
        // Resize the array if necessary
        if (idx >= MAX_NFAPI_PDU_COUNT) break;
        ta->pdu_arr[idx]->crc_indication.crcflag = rand() % 2;
        idx++;
    }
}
```

4. Implement the main function to handle configuration and manage resources:

```c
int main(int argc, char** argv) {
    // Load configuration from a file or command-line arguments
    int resize_threshold = RESIZE_THRESHOLD;
    NUM_THREADS = atoi(argv[1]);
    MAX_NFAPI_PDU_COUNT = atoi(argv[2]);

    // Initialize necessary resources
    pthread_t threads[NUM_THREADS];
    sem_t resize_sem;
    sem_init(&resize_sem, 0, 0);
    NFAPI_CRC_INDICATION_PDU_T **pdu_arr = malloc(MAX_NFAPI_PDU_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_arr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Create and start worker threads
    for (int i = 0; i < NUM_THREADS; ++i) {
        THREAD_ARGS* ta = malloc(sizeof(THREAD_ARGS));
        ta->id = i;
        ta->pdu_arr = &pdu_arr;
        ta->resize_sem = &resize_sem;
        if (pthread_create(&threads[i], NULL, worker, (void*)ta)) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    // Monitor and manage the resizing of the array based on the threshold
    int curr_size = 0;
    while (curr_size < MAX_NFAPI_PDU_COUNT) {
        if ((float)(MAX_NFAPI_PDU_COUNT - curr_size) / NUM_THREADS <= resize_threshold / 100.f) {
            sem_post(&resize_sem);
            resize(&pdu_arr, curr_size, curr_size + (MAX_NFAPI_PDU_COUNT - curr_size) / NUM_THREADS + 1);
            curr_size = curr_size + (MAX_NFAPI_PDU_COUNT - curr_size) / NUM_THREADS + 1;
        }
    }

    // Wait for worker threads to finish
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(pdu_arr);
    sem_destroy(&resize_sem);
    return EXIT_SUCCESS;
}
```

