    for (int i = 0; i < retries; ++i) {
        if (loadConfigFromURL(config)) {
            break;
        }
        usleep((uint64_t)pow(2, i) * 100000); // Exponential backoff
    }

    if (!config->remote_config) {
        fprintf(stderr, "Failed to load configuration from URL\n");
        return -1;
    }

    mprotect(config, sizeof(config), PROT_READ);
    return 0;
}

