typedef struct {
    int size;
    int capacity;
    pthread_mutex_t mutex;
    void** records;
    char** strings;
} Context;

Context* context_init(size_t initial_capacity) {
    Context* ctx = mmap(NULL, sizeof(Context), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    ctx->size = 0;
    ctx->capacity = initial_capacity;
    pthread_mutex_init(&ctx->mutex, NULL);
    ctx->records = malloc(initial_capacity * sizeof(void*));
    ctx->strings = malloc((initial_capacity + 1) * sizeof(char*));
    return ctx;
}

int is_string_used(Context* ctx, const char* str) {
    for (int i = 0; ctx->strings[i] != NULL; ++i) {
        if (strcmp(ctx->strings[i], str) == 0) {
            return 1;
        }
    }
    return 0;
}

char* get_unused_string(Context* ctx) {
    for (int i = 0; ctx->strings[i] != NULL; ++i) {
        if (!ctx->strings[i]) {
            ctx->strings[i] = strdup("empty string"); // replace with your predefined list of strings
            return ctx->strings[i];
        }
    }
    int size = ctx->capacity + 1;
    char** new_strings = realloc(ctx->strings, size * sizeof(char*));
    if (new_strings == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    ctx->strings = new_strings;
    return ctx->strings[ctx->capacity] = strdup("empty string"); // replace with your predefined list of strings
}

Record* context_insert(Context* ctx, int key, const char* value) {
    pthread_mutex_lock(&ctx->mutex);
    Record* record;
    if (is_string_used(ctx, value)) {
        record = get_unused_string(ctx);
        strcpy(record, value);
    } else {
        record = (Record*) ctx->records[key];
    }
    ctx->records[key] = malloc(sizeof(Record));
    Record* new_record = ctx->records[key];
    new_record->key = key;
    new_record->value = record;
    pthread_mutex_unlock(&ctx->mutex);
    return new_record;
}

Record* context_get(Context* ctx, int key) {
    pthread_mutex_lock(&ctx->mutex);
    Record* record = (Record*) ctx->records[key];
    if (!record) {
        pthread_mutex_unlock(&ctx->mutex);
        return NULL;
    }
    return record;
}

void context_destroy(Context* ctx) {
    munmap(ctx, sizeof(Context));
}

// Implement serialization and deserialization functions here.
