        AtomicInteger count = activeTasks.get(taskKey);
        if (count == null || count.decrementAndGet() <= 0) return;

        if (!success) {
            notificationService.sendFailureAlert(taskKey);
        } else {
            notificationService.sendSuccessAlert(taskKey);
        }
    }
}
