}

class LoadBalancer {
    private final Map<String, BigDecimal> scores;
    private final ExecutorService executor;
    private final PoolingHttpClientConnectionManager cm;
    private final ConnectionKeepAliveStrategy keepAliveStrategy = new DefaultConnectionKeepAliveStrategy() {
        @Override
        public long getKeepAliveDuration(HttpResponse response, HttpContext context) {
            return 60 * 1000; // 1 minute
        }
    };
    private final Gson gson = new Gson();

    public LoadBalancer(int corePoolSize, int maximumPoolSize, long timeUnit, Duration responseTimeThreshold) {
        this.scores = new ConcurrentHashMap<>();
        this.executor = Executors.newFixedThreadPool(corePoolSize, r -> new ThreadFactoryNamed("LoadBalancer-" + r.hashCode()));
        this.cm = new PoolingHttpClientConnectionManager(keepAliveStrategy);
        // list of RESTful service URLs
    }

    public void addUser(String userId) {
        scores.putIfAbsent(userId, new BigDecimal(new Random().nextInt((int) Math.pow(10, 6))));
    }

    public void processRequests() throws IOException {
        Deque<Server> servers = new LinkedList<>(this.servers);
        while (!servers.isEmpty()) {
            Server server = servers.poll();
            Runnable task = () -> {
                try {
                    HttpPost httpPost = new HttpPost(server.url);
                    CloseableHttpResponse response = cm.execute(httpPost);
                    ApiResponse apiResponse = new ApiResponse(response.getStatusLine().getStatusCode(), Duration.ofMillis(response.getHeader("X-Response-Time").map(x -> Long.parseLong(x)).orElse(0L)));
                    server.addResponse(apiResponse);
                } catch (OutOfMemoryError | IOException e) {
                    // handle exception gracefully, log error and return specific error code
                } finally {
                    executor.submit(() -> checkAndAdjustServerPriorities(server));
                }
            };
            executor.execute(task);
        }
    }

    private void checkAndAdjustServerPriorities(Server server) {
        // adjust server priorities based on response times and success rates
    }
}

public class Main {
    public static void main(String[] args) throws IOException, InterruptedException {
        LoadBalancer lb = new LoadBalancer(10, 20, TimeUnit.SECONDS.toMillis(5), Duration.ofMinutes(1));
        // read user identifiers from standard input and add them to the map
        for (String userId : getUserIdsFromInput()) {
