        lb.serializeScores("scores.dat");

        // deserialize the scores map from the file and calculate average scores for each user
    }

    private static Deque<String> getUserIdsFromInput() {
        Deque<String> userIds = new LinkedList<>();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine()) != null) {
            userIds.add(line);
        }
        return userIds;
    }
}
