```gremlin
import org.apache.tinkerpop.gremlin.driver.RequestOptions
import org.apache.tinkerpop.gremlin.structure.Vertex
import org.apache.tinkerpop.gremlin.structure.Graph
import org.apache.tinkerpop.gremlin.structure.Property
import org.apache.tinkerpop.gremlin.process.traversal.dsl.graph.__
import java.time.Instant
import java.util.UUID
import scala.concurrent.duration._
import akka.actor.ActorSystem
import akka.pattern.ask
import scala.concurrent.Future
import com.typesafe.config.Config

class GraphDataManager(implicit system: ActorSystem, config: Config) {
  val graph: Graph = // Initialize your distributed graph database here
  val loggingService: LoggingService = new LoggingService(system, config)
  val rateLimiter: RateLimiter = new RateLimiter(config)

  def insertVerticesAndEdges(verticesData: Seq[VertexData], edgesData: Seq[EdgeData]): Future[Unit] = {
    for {
      // Initialize rate limiter and validate input data
      _ <- rateLimiter.validateAndGetToken()
      _ <- validateInputData(verticesData, edgesData)
    } yield {
      val startTime = Instant.now()

      // Begin transaction to handle concurrent inserts gracefully
      graph.tx(() => {
        // Add vertices with specified labels and attributes
        for ((vertexData, i) <- verticesData.zipWithIndex) {
          val vertex = graph.addVertex(label = vertexData.label)
            .property(FieldNames.id, i)
            .property(fieldName(vertexData.attributes), vertexData.attributes)
            .next()
          loggingService.logVertexAddition(vertex, startTime)
        }

        // Add edges with specified relationship types and properties
        for ((edgeData, i) <- edgesData.zipWithIndex) {
          val from = graph.traversal().V(edgeData.fromId).next()
          val to = graph.traversal().V(edgeData.toId).next()
          val edge = from
            .addE(edgeData.relType)
            .property(fieldName(edgeData.properties), edgeData.properties)
            .to(to)
            .property("timestamp", Instant.now())
            .next()
          loggingService.logEdgeAddition(edge, startTime)
        }
      }).thenAcceptOf { _ => // Commit transaction if successful
        val endTime = Instant.now()
        // Log overall operation duration and rate limits
        loggingService.logOperationDuration(endTime - startTime)
        rateLimiter.markUsed()
      }.recoverWith { case e =>
        loggingService.logError(e, startTime)
        Future.successful(())
      }
    }
