use tokio::runtime::{Builder as TokioRuntimeBuilder, RuntimeExecutor};
use tokio::sync::watch::{Receiver, Sender};
use tokio::task::{self, spawn};

type TaskFn = Box<dyn FnOnce() + Send + 'static>;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <task_name>", args[0]);
        std::process::exit(1);
    }

    let concurrency_limit = 5;
    let mut runtime = TokioRuntimeBuilder::new_multi_thread()
        .worker_threads(concurrency_limit)
        .build()
        .expect("Failed to create tokio runtime");

    let task_names: Vec<&str> = ["task1", "task2", "task3"] // Add more tasks here as needed
        .into_iter()
        .filter(|name| args[1].eq_ignore_ascii_case(name))
        .collect();
    if task_names.is_empty() {
        eprintln!("Invalid task name provided");
        std::process::exit(1);
    }

    let mut tasks = Vec::with_capacity(task_names.len());

    for name in task_names {
        // Replace this with your actual task implementation
        let task = Box::new(move || {
            println!("Executing {}...", name);
            // Your async task implementation goes here
            tokio::time::sleep(Duration::from_secs(3)).await; // Simulate task delay
            println!("Finished executing {}", name);
        });

        tasks.push((task, name));
    }

    let (tx, rx) = std::sync::mpsc::channel(tasks.len());
    let mut running_tasks = tasks;

    // Spawn a task that listens for termination signals and performs cleanup when received
    let _cleanup_task = task::spawn(async move {
        let signal = async {
            tokio::signal::ctrl_c().await || tokio::signal::terminate().await
        };

        if let Some(sig) = await!(signal) {
            println!("Received termination signal, shutting down...");
            for (task, _name) in &mut running_tasks {
                task.0.abort();
            }
        }
    });

    // Spawn tasks dynamically based on command-line arguments and manage concurrency using the tokio runtime
    while let Some((task, name)) = running_tasks.drain(..) {
        let (tx_signal, rx_signal) = std::sync::mpsc::channel(1);
        let name_clone = name.to_owned();
        spawn(async move {
            println!("Starting {}...", name_clone);
            task.0().await; // Execute the task asynchronously
            tx_signal.send(()).expect("Failed to send signal");
        })
        .on_drop(|| {
            println!("Dropping task {}", name_clone);
            tx.send((name_clone, false)).expect("Failed to send task status")
        })
        .with_handle(runtime.handle()) // Ensure task is executed concurrently within the runtime
        .detach();

        let rx_status = rx_signal.recv().await; // Wait for task completion signal or error
        tx.send((name, rx_status.is_ok())).expect("Failed to send task status");
    }

    if let Err(err) = runtime.block_on(cleanup_task) {
        eprintln!("Error during cleanup: {}", err);
    }
}
