    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, fetch_and_cache, source, cache);
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_t end = clock();
    double elapsed_seconds = (double)(end - start) / CLOCKS_PER_SEC;
    fprintf(log->fd, "Processed %lu items in %.2fs\n", cache->count, elapsed_seconds);
