    struct cache* cache = *(struct cache**)((char*)args + sizeof(void*));

    while (1) {
        DataItem data_item;
        source->fetch(source->source, &data_item, 0); // Fetch data from the source

        validate_data(&data_item); // Validate data item

        if (!cache->count || cache->capacity <= cache->count) {
            DataItem* new_cache = realloc(cache->data, sizeof(DataItem) * (2 * cache->capacity));
            if (!new_cache) {
                fprintf(log->fd, "Out of memory\n");
                return NULL;
            }
            cache->data = new_cache;
            cache->capacity *= 2;
        }

        cache->data[cache->count] = data_item;
        ++cache->count;
    }

    return NULL;
}
