public:
    FetchDataFromNetworkAndDatabase() : db(nullptr), pthread_mutex_init(&mutex, NULL) {}

    ~FetchDataFromNetworkAndDatabase() {
        if (db) sqlite3_close(db);
        pthread_mutex_destroy(&mutex);
    }

    void openDB(const std::string& dbName) {
        int rc = sqlite3_open(dbName.c_str(), &db);
        if (rc) std::cerr << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
    }

    FetchDataResult fetchDataFromNetworkAndDatabase(const std::string& hostname, const std::string& username, const std::string& password, const std::vector<int>& supervisorIDs, const std::vector<std::string>& fields) {
        // Implement DNS resolution using Boost.Asio
        tcp::resolver resolver(boost::asio::io_service());
        auto iter = cachedIPs.find(hostname);
        u_char* ip;
        IDataReader reader;

        if (iter != cachedIPs.end()) {
            ip = iter->second;
        } else {
            auto results = resolver.resolve(hostname, "http");
            boost::asio::connect(..., ...); // Perform network connection
            // Send HTTP request for DNS resolution
            // Parse the response to get IP address
            ip = new u_char[sizeof(u_char) * results.endpoint().address().to_bytes().size()];
            std::copy(results.endpoint().address().to_bytes().begin(), results.endpoint().address().to_bytes().end(), ip);
            cachedIPs[hostname] = ip;
        }

        // Perform SQL queries using sqlite3
        char sql[1024];
        std::snprintf(sql, sizeof(sql), "SELECT %s FROM employees WHERE supervisor_id IN (%s)",
                      fields.front().c_str(), FormatSQLArgs(supervisorIDs).c_str());

        sqlite3_stmt* stmt;
        int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);

        if (rc == SQLITE_OK) {
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                reader.addColumn(std::string(reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0)), sqlite3_column_bytes(stmt, 0)));
            }
        } else {
            std::cerr << "SQL error: " << sqlite3_errmsg(db) << std::endl;
        }

        EmployeeInfo result;
        // Populate the EmployeeInfo object using SQL columns

        pthread_mutex_lock(&mutex);
        if (cachedResults.count({ip, fields[0]})) {
            result = cachedResults[{ip, fields[0]}];
        } else {
            result.employee_name = reader.getColumn(0);
            // Perform additional database queries to populate other fields
            // Store the result in cachedResults for future use
            cachedResults[{ip, fields[0]}] = result;
        }
        pthread_mutex_unlock(&mutex);

        return {ip, reader};
    }
};
