class Status {
public:
    explicit Status(bool success) : success_(success), attempt_(0) {}

    void fail() {
        if (++attempt_ >= MAX_ATTEMPTS)
            throw std::runtime_error("Failed to transmit log entry after maximum attempts.");
        sleepingTime_ *= BACKOFF_FACTOR;
    }

    void success() {
        sleepingTime_ = INITIAL_SLEEPING_TIME;
    }

    bool isSuccessful() const { return success_; }
    int getAttempts() const { return attempt_; }
    boost::posix_time::time_duration getSleepingTime() const { return sleepingTime_; }

private:
