    static const float BACKOFF_FACTOR = 2.0f;
    static const boost::posix_time::time_duration INITIAL_SLEEPING_TIME = boost::posix_time::milliseconds(100);
    bool success_;
    int attempt_;
    boost::posix_time::time_duration sleepingTime_;
};

class LogEntryQueue : private boost::noncopyable {
public:
    void enqueue(const Record& record) {
        if (current_.empty() || current_.back().timestamp < record.timestamp) {
            current_.push_front(record);
            if (current_.size() > MAX_SIZE)
                buffer_.pop_back();
        }
    }

    Record dequeue() {
        Record top = current_.front();
        current_.pop_front();
        buffer_.push_back(top);
        return top;
    }

    const Record& front() const {
        if (current_.empty())
            return buffer_.front();
        return current_.front();
    }

    size_t size() const { return current_.size() + buffer_.size(); }

private:
    static const size_t MAX_SIZE = 1000; // Adjustable queue size limit
    std::forward_list<Record> current_;
    boost::circular_buffer<Record> buffer_;
};

