// Function to add a new connection to the list
void add_connection(const char *ip, int port) {
    if (num_connections >= MAX_CONNECTIONS || getrlimit(&rlim, RLIM_RSS) > MEMORY_LIMIT) return;

    // Ensure uniqueness of connection ID
    pthread_mutex_lock(&mutex);
    int id = 0;
    for (int i = 0; i < num_connections; ++i) {
        if (connections[i].id == 0) {
            connections[i].id = id++;
            strcpy(connections[i].ip, ip);
            connections[i].port = port;
            connections[i].last_active = time(NULL);
            num_connections++;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Thread-safe function to iterate through the list of connections
void for_each_connection(void (*func)(Connection *)) {
    Connection *iter = NULL;

    pthread_mutex_lock(&mutex);
    iter = &connections[0];
    int i = 0;
    while (i < num_connections) {
        if (!(*func)(iter + i)) break;
        ++i;
    }
    pthread_mutex_unlock(&mutex);
}
