struct list_data {
    size_t size;
    NFAPI_CRCI_PDU_T *items;
    pthread_mutex_t lock;
};

void destroy(struct list_data *list) {
    free(list->items);
    free(list);
}

struct list_data* create_list(size_t size) {
    if (size == 0) return NULL;

    struct list_data *list = malloc(sizeof(struct list_data));
    if (!list) {
        perror("malloc failed\n");
        return NULL;
    }

    list->size = size;
    list->items = malloc(sizeof(NFAPI_CRCI_PDU_T) * size);
    if (!list->items) {
        perror("malloc failed\n");
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        list->items[i].crcflag = rand() % 2;
    }

    return list;
}

NFAPI_CRCI_PDU_T* get_item(struct list_data *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRCI_PDU_T *item = &list->items[index];
    pthread_mutex_unlock(&list->lock);
    return item;
}

void set_item(struct list_data *list, size_t index, const NFAPI_CRCI_PDU_T *new_value) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRCI_PDU_T *item = &list->items[index];
    memcpy(item, new_value, sizeof(NFAPI_CRCI_PDU_T));
    pthread_mutex_unlock(&list->lock);
}

struct list_data* resize_list(struct list_data *list, size_t new_size) {
    if (new_size == list->size || !list) return list;

    NFAPI_CRCI_PDU_T *new_items = realloc(list->items, sizeof(NFAPI_CRCI_PDU_T) * new_size);
    if (!new_items) {
        perror("realloc failed\n");
        return NULL;
    }

    list->size = new_size;
    list->items = new_items;

    for (size_t i = list->size; i < new_size; ++i) {
        list->items[i].crcflag = rand() % 2;
    }

    return list;
}
