#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <openssl/md5.h>

pid_t executeCommandAndHashOutput(char *command) {
    pid_t childPid;
    int pipefd[2];
    pid_t sessionId = setsid();
    if (sessionId == -1) {
        perror("setsid");
        return 0;
    }

    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 0;
    }

    childPid = fork();
    if (childPid == -1) {
        perror("fork");
        return 0;
    }

    if (childPid > 0) { // parent process
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);
        char *envp[] = { NULL };
        if (execvp(command, (char*[]) { command, NULL }) == -1) {
            perror("execvp");
            return 0;
        }
    } else { // child process
        close(pipefd[1]);
        char buffer[4096];
        ssize_t nread;
        while ((nread = read(STDIN_FILENO, buffer, sizeof(buffer))) > 0) {
            write(STDOUT_FILENO, buffer, nread);
        }
        exit(0);
    }

    int status;
    waitpid(childPid, &status, WNOHANG);

    if (WIFEXITED(status)) {
        close(pipefd[0]);
        char hashOutputBuffer[MD5_DIGEST_LENGTH];
        int fd = open("/dev/null", O_RDONLY); // or any other way to get a known file descriptor, e.g., fileno(stdin)
        unsigned char digest[MD5_DIGEST_LENGTH];
        if (fd != -1) {
            FILE *fp = fdopen(fd, "rb");
            if (fp != NULL) {
                while ((nread = read(pipefd[0], buffer, sizeof(buffer))) > 0) {
                    fwrite(buffer, nread, 1, fp);
                }
                fclose(fp);
            }
            MD5_Final(digest, (unsigned char*)pipefd[0]); // read from pipe fd
            hexencode((const unsigned char*)digest, sizeof(digest), hashOutputBuffer);
        }
        close(pipefd[0]);
        return 1;
    } else {
        perror("Child process terminated unexpectedly");
        return 0;
    }
}

void hexencode(const unsigned char *input, size_t length, char *output) {
    for (size_t i = 0; i < length; ++i) {
        sprintf(&output[2 * i], "%02x", input[i]);
    }
    output[length*2] = '\0'; // null terminate the output string
}
```
