typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static Node* head = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static uint64_t allocated_structures = 0;
static uint64_t time_elapsed = 0;

void log_error(const char* message) {
    printf("[ERROR] %s\n", message);
}

Node* create_node(RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication, bool crcflag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed");
        return NULL;
    }

    new_node->data.tag = tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication = crc_indication;
    new_node->data.crcflag = crcflag;
    new_node->next = NULL;

    return new_node;
}

void insert_node(Node* new_node) {
    pthread_mutex_lock(&list_lock);
    Node* current = head;
    Node** prev = &head;

    while (current != NULL) {
        if (current->data.rnti == new_node->data.rnti) {
            pthread_mutex_unlock(&list_lock);
            free(new_node);
            return;
        }

        prev = &current->next;
