    }

    private void ValidateSiteNameAndDirectory(string siteName, string directory)
    {
        // Validate site name format and length
        if (!Regex.IsMatch(siteName, @"^[a-zA-Z0-9]{1,50}$")) throw new ArgumentException("Invalid site name.");

        // Check if the directory exists
        if (!Directory.Exists(directory)) throw new DirectoryNotFoundException($"Directory: {directory} not found.");
    }

    private bool IsWebConfigValid(string webConfigPath)
    {
        try
        {
            using var file = File.OpenRead(webConfigPath);
            // Perform integrity check on the web.config file
            // ...
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError($"Web.config file: {webConfigPath} - {ex.Message}");
            return false;
        }
    }

    private void AdjustDirectoryPermissions(string directory)
    {
        // Adjust permissions for the application pool identity
        var identity = new NTAccount("IIS APPPOOL\\DefaultAppPool");
        DirectorySecurity security = null;
        try
        {
            security = Directory.GetAccessControl(directory);
        }
        catch (UnauthorizedAccessException)
        {
            _logger.LogError($"Unable to access directory: {directory} - Adjusting permissions.");
        }

        if (security == null) security = new DirectorySecurity();
        identity.AddAccessRule(new FileSystemAccessRule(identity, FileSystemRights.ReadAndExecute | FileSystemRights.ListContents | FileSystemRights.Modify, AccessControlType.Allow));
        Directory.SetAccessControl(directory, security);
    }

    private Process StartSiteProcess(string siteName, string directory)
    {
        var processStartInfo = new ProcessStartInfo($"{_config["SiteExecutable"]} {siteName}", "", Directory.GetCurrentDirectory());
        processStartInfo.WorkingDirectory = directory;
        return new Process { StartInfo = processStartInfo };
    }

    private async Task<bool> WaitForProcessToStartAsync(Process process, TimeSpan timeout)
    {
        var startTime = DateTime.Now;
        while ((DateTime.Now - startTime) < timeout)
        {
            if (process.HasExited || !process.StartInfo.RedirectStandardOutput) break;

            // Monitor process output for status messages
            await Task.Delay(100);
            var line = process.StandardOutput.ReadLine();
            if (!string.IsNullOrEmpty(line))
            {
                if (line.Contains("Started")) return true;
            }
        }

        _logger.LogError($"Process for site: {process.StartInfo.Arguments} did not start within the specified timeout.");
        return false;
    }
}
