['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Cell {
    double value;
    bool initialized;
    pthread_mutex_t mutex;
} Cell;

typedef Cell** Grid;

Grid create_grid(size_t dims, size_t* sizes) {
    size_t product = 1;
    for (size_t i = 0; i < dims; ++i) product *= sizes[i];

    Grid grid = malloc(dims * sizeof(Cell*));
    if (!grid) return NULL;

    for (size_t i = 0; i < dims; ++i) {
        grid[i] = calloc(sizes[i], sizeof(Cell));
        if (!grid[i]) {
            free(grid);
            return NULL;
        }
    }

    return grid;
}

void destroy_grid(Grid grid, size_t dims) {
    for (size_t i = 0; i < dims; ++i) free(grid[i]);
    free(grid);
}

Cell* get_cell(Grid grid, size_t dims, size_t* sizes, size_t index) {
    for (size_t i = dims - 1; i > 0; --i) {
        index %= sizes[i];
        if (!index) index = sizes[i-1];
        index /= sizes[i];
    }
    return grid[dims - 1] + index;
}

bool try_lock(pthread_mutex_t* lock) {
    int res = pthread_mutex_trylock(lock);
    if (res == 0) return true;
    else if (res != EBUSY) pthread_exit(NULL);
    return false;
}

void update_cell(Cell* cell, double value) {
    if (!try_lock(&cell->mutex)) return;

    cell->value = value;
    cell->initialized = true;
    pthread_mutex_unlock(&cell->mutex);
}

void reset_grid(Grid grid, size_t dims, size_t* sizes) {
    for (size_t i = 0; i < dims; ++i)
        for (size_t j = 0; j < sizes[i]; ++j) {
            Cell* cell = get_cell(grid, dims, sizes, i * sizes[i] + j);
            cell->initialized = false;
            pthread_mutex_init(&cell->mutex, NULL);
        }
}

void traverse_and_update(Grid grid, size_t dims, size_t* sizes, void (*func)(Cell*, double)) {
    for (size_t i = 0; i < dims; ++i)
        for (size_t j = 0; j < sizes[i]; ++j) {
            Cell* cell = get_cell(grid, dims, sizes, i * sizes[i] + j);
            if (!cell->initialized || func(cell, cell->value)) update_cell(cell, func(cell, 0.0));
        }
}

// Example usage with custom condition for updating grid values:
void custom_condition(Cell* cell, double value) {
    return (cell->value + value) * 2 > 5;
}

int main() {
    size_t dims = 3;
    size_t sizes[] = {4, 5, 6};
    Grid grid = create_grid(dims, sizes);
    if (!grid) return EXIT_FAILURE;

    traverse_and_update(grid, dims, sizes, &custom_condition);

    // ... other operations on the grid here ...

    reset_grid(grid, dims, sizes);

    destroy_grid(grid, dims);
    return EXIT_SUCCESS;
}
