char *generate_id(const char *input) {
    uint32_t hash = 5381;
    int c;

    while ((c = *input++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return (char *) &hash;
}

void renderFooterScripts(SCRIPT_T *scripts, size_t N) {
    if (N > MAX_NFAPI_PDU_COUNT || rate_limit <= time(NULL) - last_request) {
        return;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    if (pdu_count + N > MAX_NFAPI_PDU_COUNT) {
        pthread_mutex_unlock(&lock);
        return;
    }

    SCRIPT_T *script = scripts;
    char html[4096];
    size_t html_length = 0;

    for (size_t i = 0; i < N; ++i, ++script) {
        if (!script->name || !script->code) {
            continue;
        }

