        snprintf(html + html_length, sizeof(html) - html_length, "<script id=\"%s\">\n", id);
        html_length += strlen(html);
        snprintf(html + html_length, sizeof(html) - html_length, "%s", script->code);
        html_length += strlen(script->code);
        snprintf(html + html_length, sizeof(html) - html_length, "</script>\n");
        html_length += strlen(html);
    }

    if (pdu_count < MAX_NFAPI_PDU_COUNT) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_pdu) {
            pthread_mutex_unlock(&lock);
            return;
        }

        memcpy(new_pdu, &pdu_array[pdu_count], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_pdu->RX_UE_INFORMATION_TAG = 0x1234;
        new_pdu->RNTI = htonl(0x5678);
        new_pdu->CRC_INDICATION_REL8_TAG = htonl(rand() % 0xFFFFFFFF);
        strcpy(new_pdu->session_id, "abcd1234ef");
        new_pdu->timestamp = time(NULL);

        pdu_array[pdu_count++] = new_pdu;
    }

    pthread_mutex_unlock(&lock);
}
