struct Record {
    int value;
    long offset;

    friend class boost::serialization::access;
    template<typename Archive> void serialize(Archive& ar, const unsigned int version) {
        ar & value & offset;
    }
};

class Metadata {
public:
    std::vector<size_t> sizes;

    size_t currentOffset() const {
        return data.get_address() + data.get_space().get_memory_manager().get_allocation_point();
    }

    void addRecord(size_t size) {
        sizes.push_back(size);
    }
};

class MemoryPool {
public:
    std::unique_ptr<char[]> allocate(size_t size) {
        if (freeSpace <= size) {
            throw std::runtime_error("Memory pool out of space");
        }
        auto ptr = data.get_address() + freeSpace;
        freeSpace -= size;
        return std::unique_ptr<char[]>(ptr, [this](char* p) { freeSpace += size; });
    }

private:
    boost::interprocess::managed_shared_memory data;
    size_t freeSpace = 0;
};

class Cache {
public:
    virtual void load() = 0;
    virtual void save(const std::string& filename) const = 0;

protected:
    virtual void serializeData(boost::archive::text_oarchive& ar) const = 0;
};

class LocalCache : public Cache {
public:
    void load() override {
        // Load data from local storage
    }

    void save(const std::string& filename) const override {
        boost::iostreams::filtering_streambuf<boost::iostreams::output> osb;
        osb.push(boost::iostreams::compress::gzip_compressor());
        osb.push(std::ofstream(filename));

        serializeData(boost::archive::text_oarchive(osb));
    }

