        recordSpace.reset(memoryPool->allocate(recordSize * numRecords));
        longSpace.reset(memoryPool->allocate(numRecords * sizeof(long)));
        keySpace.resize(numRecords);
    }

    void addRecord() {
        auto r = std::unique_ptr<Record>(new Record);
        randomDevice dev;
        uniform_int_distribution<> dis(0, numLongs - 1);
        r->value = randInt();
        r->offset = *longSpace++;
        keySpace[r->offset] = r->value;
        metadata.addRecord(sizeof(*r));
    }

    void serializeData(boost::archive::text_oarchive& ar) const {
        ar & boost::serialization::make_nvp("metadata", metadata);
        ar & boost::serialization::make_nvp("records", recordSpace.get());
        ar & boost::serialization::make_nvp("keys", keySpace);
    }

private:
