// Custom comparator for qsort function to handle source IPs
bool ip_cmp(const void *a, const void *b) {
    return (*(in_addr_t*)a) > *(in_addr_t*)b;
}

void enqueue_packet(packet_t **queue, packet_t *packet, size_t max_packets) {
    if (max_packets <= 0 || queue == NULL) return;

    // Sort packets by source IP to avoid duplicates
    qsort(*queue, max_packets, sizeof(packet_t), ip_cmp);

    bool duplicate = false;
    for (size_t i = 0; i < max_packets && !duplicate; ++i) {
        if ((*queue)[i].src_ip == packet->src_ip) {
            duplicate = true;
        }
    }

    if (!duplicate) {
        // If no duplicates are found, enqueue the packet
        *queue = realloc(*queue, sizeof(packet_t) * (max_packets + 1));

        (*queue)[max_packets] = *packet;
        (*queue)[max_packets].payload = calloc(1, packet->payload_size); // Assuming payload size is defined for packet_t struct
        ++max_packets;
    } else {
        // If a duplicate source IP is found, handle it based on requirements (e.g., log, retry, or discard)
        printf("Duplicate source IP detected: %s\n", inet_ntoa(packet->src_ip));
    }
}

// Function for high-throughput scenarios using pthreads
void process_queue_async(packet_t **queue, size_t max_packets) {
    // Implement async processing logic here using pthreads or other concurrency mechanisms
}
