class Session {
public:
    std::string sessionID;
    std::string userAgent;
    std::string IPaddress;
    std::time_t lastActive;

    Session(const std::string& sessionID, const std::string& userAgent, const std::string& IPaddress)
        : sessionID{sessionID}, userAgent{userAgent}, IPaddress{IPaddress}, lastActive(std::time(nullptr)) {}
};

class UserSessions {
private:
    std::mutex mtx;
    std::unordered_map<std::string, Session> sessions;
    std::deque<Session> activeSessionsQueue;
    std::condition_variable cv;
    bool isDataUpdating = false;

    void updateActiveSessions() {
        while (isDataUpdating) {
            cv.wait(mtx);
        }
        auto start = std::chrono::high_resolution_clock::now();
        auto it = sessions.begin();
        for (; it != sessions.end(); ++it) {
            if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::high_resolution_clock::now() - std::chrono::system_clock::to_time_t(it->second.lastActive)).count() > 60) { // Adjust time window as per requirement
                it = sessions.erase(it);
            } else {
                activeSessionsQueue.push_back(it->second);
            }
        }
        isDataUpdating = true;
        cv.notify_all();
    }

public:
    void addSession(const std::string& sessionID, const std::string& userAgent, const std::string& IPaddress) {
        std::lock_guard<std::mutex> lock(mtx);
        sessions[sessionID] = Session{sessionID, userAgent, IPaddress};
        cv.notify_one();
    }

    void removeSessionByUserAgent(const std::string& userAgent) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = sessions.begin();
        while (it != sessions.end()) {
            if (it->second.userAgent == userAgent) {
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
        cv.notify_all();
    }

    std::vector<Session> getActiveSessionsInTimeWindow(std::time_t startTime, std::time_t endTime) {
        std::vector<Session> result;
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& session : activeSessionsQueue) {
            if (session.lastActive >= startTime && session.lastActive <= endTime) {
                result.push_back(session);
            }
        }
        return result;
    }

    void startPeriodicUpdates() {
        std::thread updater([this]() { while (true) { updateActiveSessions(); std::this_thread::sleep_for(std::chrono::seconds(10)); }; }).detach(); // Adjust thread sleep time as per requirement
    }
};
```

