    if (!result || logger.capacity() + sizeof(Record) * numKeys > memCap) {
        std::cerr << "Memory allocation error: Capacity exceeded." << std::endl;
        return nullptr;
    }

    IntArray array1(arraySize1);
    IntArray array2(arraySize2);
    LongVector offsets(arraySize1);

    logger.push_back({sizeof(array1), sizeof(array2)});

    for (size_t i = 0; i < numKeys; ++i) {
        // Generate random integers within specified ranges
        array1[i] = rand() % std::max(1, arraySize1 - i);
        array2[i] = rand() % std::max(1, arraySize2 - i);

        long currentOffset = offsets[i];
        while (currentOffset >= arraySize1 || result[currentOffset].key != 0) {
            // Ensure that the offset is a valid index in the 'long' array
            currentOffset++;
        }
        result[currentOffset].key = i;
        result[currentOffset].value1 = array1[i];
        result[currentOffset].value2 = array2[i];
        result[currentOffset].offset = static_cast<long>(i);

        offsets[i] = currentOffset + 1;
