int trim(char* str, int max_len) {
    if (max_len <= 0 || strlen(str) <= max_len) return strlen(str);
    char *end = &str[max_len - 1];
    while (*end != '\0' && end > str) {
        if (*end != ' ') {
            end--;
        } else {
            *end = '\0';
            break;
        }
    }
    return strlen(str);
}

char* generate_filename(const char* original, int* offset, int* key, struct Record** records, size_t num_records) {
    char base[256], ext[8] = ".txt";
    char dir[4096];
    trim(original, 120);
    strncpy(base, original, sizeof(base));
    getcwd(dir, sizeof(dir));

    int i;
    time_t t = time(NULL);
    for (i = 0; i < num_records; ++i) {
        char filename[128];
        snprintf(filename, sizeof(filename), "%s%d%s", base, t, ext);
        if (strlen(filename) + strlen(dir) <= 4096) {
            struct stat st;
            snprintf(filename, sizeof(filename), "%s/%s", dir, filename);
            if (stat(filename, &st) == -1 || S_ISDIR(st.st_mode)) continue;
            *offset = i;
            *key = atoi(base);
            *records = realloc(*records, sizeof(*(*records)) * (num_records + 1));
            (*records)[*offset].value = i;
            return filename;
        }
    }

    for (i = 0; i < num_records; ++i) {
        char filename[128];
        snprintf(filename, sizeof(filename), "%s%d%s", base, t, ext);
        if (strlen(filename) <= 120) return filename;
    }

    for (int j = 0; j < 99; ++j) {
        char filename[128];
        snprintf(filename, sizeof(filename), "%s%d_%d%s", base, t, j, ext);
        if (strlen(filename) + strlen(dir) <= 4096) {
            struct stat st;
            snprintf(filename, sizeof(filename), "%s/%s", dir, filename);
            if (stat(filename, &st) == -1 || S_ISDIR(st.st_mode)) continue;
            *offset = j * num_records + atoi(base);
            *key = atoi(base);
            *records = realloc(*records, sizeof(*(*records)) * (num_records + 1));
            (*records)[*offset].value = j * num_records + i;
            return filename;
        }
    }

    return NULL;
}

void init(int* offset, int* key, struct Record** records, size_t num_records) {
