#define MAX_ELEMENTS 1000000

struct FrameStats {
    time_t timestamp;
    int successful_packets;
    int congestion_flag; // 0: not congested, 1: congested
};

typedef struct FrameStats *FrameStatsPtr;

// External network monitoring service callback function prototype
typedef void (*PacketCallback)(FrameStatsPtr);

struct PacketCallbackData {
    FrameStatsPtr frame_stats;
    int packet;
};

static pthread_mutex_t frame_stats_mutex = PTHREAD_MUTEX_INITIALIZER;
FrameStatsPtr frame_stats_array;
PacketCallback network_monitoring_callback;

void update_congestion(int i) {
    double packet_rate = (double)(i + 1) / (time(NULL) - frame_stats_array[i].timestamp);

    if (packet_rate > 0.95)
        frame_stats_array[i].congestion_flag = 1;
    else
        frame_stats_array[i].congestion_flag = 0;
}

void init_frame_stats_array() {
    int i;

    frame_stats_array = malloc(MAX_ELEMENTS * sizeof(FrameStats));

    for (i = 0; i < MAX_ELEMENTS; ++i) {
        frame_stats_array[i].timestamp = time(NULL);
        frame_stats_array[i].successful_packets = 0;
        frame_stats_array[i].congestion_flag = 0;
    }
}

void increment_success_count(int i) {
    pthread_mutex_lock(&frame_stats_mutex);
    ++frame_stats_array[i].successful_packets;
    update_congestion(i);
    pthread_mutex_unlock(&frame_stats_mutex);
}

void set_network_monitoring_callback(PacketCallback callback) {
    network_monitoring_callback = callback;
}

void network_monitoring_service_callback(int packet) {
    struct PacketCallbackData data;
    int i, index;

    data.packet = packet;

    pthread_mutex_lock(&frame_stats_mutex);
    for (i = 0; i < MAX_ELEMENTS; ++i) {
        if (!frame_stats_array[i].timestamp) {
            index = i;
            break;
        }
    }

    if (index != MAX_ELEMENTS) {
        data.frame_stats = &frame_stats_array[index];
        frame_stats_array[index].timestamp = time(NULL);
        increment_success_count(index);

        if (network_monitoring_callback) {
            network_monitoring_callback(&data);
        }
    }
    pthread_mutex_unlock(&frame_stats_mutex);
}
```

