#include <memory>
#include <thread>
#include <mutex>
#include <random>
#include <jsoncons/json.hpp>
#include <fstream>

struct Record {
    int value;
    size_t offset, key;
};

std::vector<long> offsets;
std::vector<int> keys;
std::vector<Record> records;
std::list<int> integers;

constexpr size_t MAX_MEMORY = 1024 * 1024 * 10; // Max memory usage (10 MB)
size_t totalMemory = 0;
std::mutex memMutex;

void logMemoryUsage() {
    std::unique_lock<std::mutex> lock(memMutex);
    auto currentMemory = offsets.size() + keys.size() + records.size() * sizeof(Record) + integers.size() * sizeof(int);
    lock.unlock();
    if (currentMemory > MAX_MEMORY) {
        std::cout << "Error: Memory usage exceeded the limit" << std::endl;
        exit(EXIT_FAILURE);
    }
    totalMemory = currentMemory;
}

int initialize() {
    // Random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    offsets.resize(records.capacity());
    keys.resize(records.capacity());
    records.reserve(10000); // Reserve space for some records

    integers.emplace_back(dis(gen));
    logMemoryUsage();

    std::thread t([]() {
        while (true) {
            integers.emplace_back(dis(gen));
            logMemoryUsage();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });
    t.detach();

    return 0;
}

int serialize() {
    nlohmann::json j;

    for (const auto& record : records) {
        nlohmann::json obj = {
            {"value", record.value},
            {"offset", record.offset},
            {"key", record.key}
        };
        j.push_back(obj);
    }

    std::ofstream out("data.json");
    if (!out) {
        return 1;
    }

    out << j.dump() << std::endl;
    return 0;
}

int deserialize() {
    nlohmann::json j;

    std::ifstream in("data.json");
    if (!in) {
        return 1;
    }

    in >> j;

    for (const auto& record : j.get<std::vector<nlohmann::json>>()) {
        Record newRecord = {record["value"].get<int>(), offsets.size(), keys.size()};
        records.push_back(newRecord);

        offsets.emplace_back(-1);
        keys.emplace_back(-1);
    }

    return 0;
}
```

