typedef struct {
    int value;
} record;

// Custom malloc function to minimize fragmentation and improve performance
void* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to dynamically allocate and initialize the required arrays
record* init_arrays(int offsets_size, int keys_size, int min, int max) {
    long *offsets = (long*)custom_malloc(sizeof(long) * offsets_size);
    int *keys = (int*)custom_malloc(sizeof(int) * keys_size);
    record *records = NULL;

    if (!offsets || !keys) {
        fprintf(stderr, "Error: Failed to allocate memory for arrays.\n");
        exit(EXIT_FAILURE);
    }

    // Input validation and edge cases handling
    if (offsets_size <= 0 || keys_size <= 0) {
        fprintf(stderr, "Error: Invalid array sizes.\n");
        exit(EXIT_FAILURE);
    }

    int total_records = offsets_size + keys_size;
    records = (record*)custom_malloc((total_records + 1) * sizeof(record));

    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (int i = 0; i < offsets_size; ++i) {
        offsets[i] = -1;
    }
    for (int i = 0; i < keys_size; ++i) {
        keys[i] = -1;
    }

    // Initialize records with random values in the specified range
    for (int i = 0, idx = offsets_size; idx < total_records; ++i, ++idx) {
        records[idx].value = min + rand() % (max - min + 1);
        if (i < offsets_size) {
            offsets[i] = idx;
        }
        if (i < keys_size) {
            keys[i] = idx;
        }
    }

    return records;
}

// Function to free allocated memory when the function returns
void cleanup(record *records, long *offsets, int *keys) {
    free(records);
    free(offsets);
    free(keys);
}
