public class HashingUtility {
    private static final Logger LOGGER = LoggerFactory.getLogger(HashingUtility.class);
    private static final int MAX_DOCUMENTS_PER_MINUTE = 10_000;
    private ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private String hashingServiceUrl;

    public HashingUtility(String hashingServiceUrl) {
        this.hashingServiceUrl = hashingServiceUrl;
    }

    public void hashDocuments(List<String> documents, String algorithm) throws NoSuchAlgorithmException {
        var taskQueue = new PriorityBlockingQueue<>(MAX_DOCUMENTS_PER_MINUTE);
        var processor = new DocumentProcessor(taskQueue, executor, hashingServiceUrl, algorithm);
        for (var document : documents) {
            taskQueue.put(document);
        }
        processor.start();
        processor.join();
    }

    private class DocumentProcessor extends Thread {
        private final BlockingQueue<String> taskQueue;
        private final ExecutorService executor;
        private final String hashingServiceUrl;
        private final String algorithm;

        public DocumentProcessor(BlockingQueue<String> taskQueue, ExecutorService executor, String hashingServiceUrl, String algorithm) {
            this.taskQueue = taskQueue;
            this.executor = executor;
            this.hashingServiceUrl = hashingServiceUrl;
            this.algorithm = algorithm;
        }

        @Override
        public void run() {
            try {
                while (!Thread.currentThread().isInterrupted()) {
                    var document = taskQueue.take();
                    var hashValue = generateHash(document, algorithm);
                    validateHash(hashValue);
                    LOGGER.info("Document hashed: [{}]", document);
                }
            } catch (InterruptedException | IOException e) {
                LOGGER.error("Error processing documents", e);
            } finally {
                executor.shutdown();
                try {
                    executor.awaitTermination(1, TimeUnit.MINUTES);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        private BigInteger generateHash(String document, String algorithm) throws NoSuchAlgorithmException {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            digest.update(document.getBytes());
            return digest.digest();
        }

        private void validateHash(BigInteger hashValue) throws IOException {
            // Implement cross-validation with external service (e.g., send HTTP request to validator API)
            // ...
        }
    }
}
