typedef struct {
    long *offset;
    int *id;
    int ref_count;
} record;

static long offsets[10000];
static int ids[5000];
static record *records = NULL;
static size_t num_records = 0;
static size_t max_records = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
static int num_active_ops = 0;
static const int max_concurrent_ops = 100;

void init_data_structures(size_t size) {
    if (max_records < size) {
        // Reallocate records array and initialize new records with valid pointers
        record *new_records = realloc(records, sizeof(record) * size);
        if (!new_records) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            exit(EXIT_FAILURE);
        }
        records = new_records;
        max_records = size;
    }

    // Shuffle the order of records in-place without changing their content
    for (size_t i = 0; i < num_records; ++i) {
        size_t j = rand() % (i + 1);
        if (i != j) {
            record tmp = records[i];
            records[i] = records[j];
            records[j] = tmp;
        }
    }
}

record *allocate_record() {
    pthread_mutex_lock(&mutex);

    if (num_records >= max_records) {
        fprintf(stderr, "No more memory available for records\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    record *new_record = &records[num_records];
    new_record->offset = &offsets[rand() % 10000];
    new_record->id = &ids[rand() % 5000];
    new_record->ref_count = 0;
    ++num_records;

    pthread_mutex_unlock(&mutex);

    return new_record;
}

void increment_ref_count(record *r) {
    pthread_mutex_lock(&mutex);

    if (r->ref_count < INT_MAX - 1) {
        ++r->ref_count;
    }

    pthread_mutex_unlock(&mutex);
}

void decrement_ref_count(record *r) {
    pthread_mutex_lock(&mutex);

    if (r->ref_count > 0) {
        --r->ref_count;

        if (r->ref_count == 0) {
            // Free the record when its reference count reaches zero
            free(r->offset);
            free(r->id);
            memmove(&records[num_records - 1], r, sizeof(record));
            --num_records;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void *operation(void *arg) {
    int *op_id = arg;

    // Acquire the lock and wait if necessary to ensure thread safety
    pthread_mutex_lock(&mutex);

    while (num_active_ops >= max_concurrent_ops) {
        pthread_cond_wait(&cond, &mutex);
    }
    ++num_active_ops;
    pthread_mutex_unlock(&mutex);

    // Perform the operation using the allocated record
    record *r = allocate_record();
    if (r) {
        increment_ref_count(r);
        // ... do some operation with the record r ...
    }

    pthread_mutex_lock(&mutex);

    --num_active_ops;
    if (num_active_ops == 0) {
        pthread_cond_broadcast(&cond);
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

void cleanup() {
    // Free resources and reallocate smaller arrays
    while (num_records > 0) {
        record *r = &records[0];
        memmove(&records[0], &records[1], sizeof(record) * (--num_records));
        free(r->offset);
        free(r->id);
    }
    records = realloc(records, sizeof(record) * num_records);
}
