    $tokenExpirationTime = 3600;
    $refreshTokenLifetime = 86400;

    $cache = new Redis(); // Use a Redis instance for caching frequently accessed tokens

    // Retrieve the token from cache if available
    $tokenFromCache = $cache->get($request['token']);

    if ($tokenFromCache !== false) {
        return json_encode(['status' => 'success', 'token' => $tokenFromCache]);
    }

    // Validate the given credentials and generate/refresh a token (if necessary)
    $username = $request['username'];
    $password = $request['password'];

    if (!validateCredentials($username, $password)) {
        return json_encode(['status' => 'failure']);
    }

    // Refresh the token if refresh_token is provided
    if (isset($request['refresh_token'])) {
        $refreshToken = $request['refresh_token'];
        $storedToken = $db->prepare("SELECT token, expiration FROM tokens WHERE refresh_token = :refresh_token")->execute([':refresh_token' => $refreshToken]);

        if ($storedToken->rowCount() == 0) {
            return json_encode(['status' => 'error', 'message' => 'Invalid refresh token']);
        }

        $tokenData = $storedToken->fetch(PDO::FETCH_ASSOC);

        if (time() > $tokenData['expiration']) {
            // Token has expired, remove it from the cache and database
            $cache->del($request['token']);
            $db->exec("DELETE FROM tokens WHERE token = :token", [':token' => $tokenData['token']]);

            return json_encode(['status' => 'error', 'message' => 'Token has expired']);
        }

        // Refresh the token and update its expiration time
        $newExpirationTime = time() + $tokenExpirationTime;
        $db->exec("UPDATE tokens SET expiration = :newExpiration WHERE refresh_token = :refresh_token", [':newExpiration' => $newExpirationTime, ':refresh_token' => $refreshToken]);

        // Save the refreshed token in cache and return it
        $newToken = generateToken();
        $cache->set($newToken, $request['refresh_token']);

        return json_encode(['status' => 'success', 'token' => $newToken]);
    }

    // Generate a new token if no refresh_token is provided
    $newToken = generateToken();
    $newExpirationTime = time() + $tokenExpirationTime;
    $refreshToken = generateRefreshToken();
    $refreshTokenLifetime = time() + $refreshTokenLifetime;

    // Insert the new token into the database and cache
    $db->exec("INSERT INTO tokens (username, token, refresh_token, expiration) VALUES (:username, :token, :refresh_token, :expiration)", [':username' => $username, ':token' => $newToken, ':refresh_token' => $refreshToken, ':expiration' => $newExpirationTime]);
    $cache->set($newToken, $refreshToken);

    return json_encode(['status' => 'success', 'token' => $newToken]);
}

