typedef struct Record {
    int value;
    size_t offset;
    int key;
    time_t create_time;
    time_t last_access_time;
} Record;

typedef struct DataStore {
    size_t capacity;
    size_t size;
    long *longs;
    int *ints;
    Record *records;
    Record *metadata;
    pthread_mutex_t lock;
} DataStore;

DataStore* create_data_store(size_t initial_capacity) {
    DataStore* ds = (DataStore*) mmap(NULL, sizeof(DataStore), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!ds) return NULL;

    ds->capacity = initial_capacity;
    ds->size = 0;
    ds->longs = ds->longs + initial_capacity * sizeof(long);
    ds->ints = ds->ints + initial_capacity * sizeof(int);
    ds->records = ds->records + initial_capacity * sizeof(Record);
    ds->metadata = ds->metadata + initial_capacity * sizeof(Record);
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void resize_data_store(DataStore* ds) {
    if (ds->size >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        long *new_longs = realloc(ds->longs, new_capacity * sizeof(long));
        int *new_ints = realloc(ds->ints, new_capacity * sizeof(int));
        Record *new_records = realloc(ds->records, new_capacity * sizeof(Record));
        Record *new_metadata = realloc(ds->metadata, new_capacity * sizeof(Record));

        if (!new_longs || !new_ints || !new_records || !new_metadata) {
            // Handle memory allocation failure gracefully
            return;
        }

        ds->longs = new_longs;
        ds->ints = new_ints;
        ds->records = new_records;
        ds->metadata = new_metadata;
        ds->capacity *= 2;
    }
}

void insert(DataStore* ds, int key, int value) {
    pthread_mutex_lock(&ds->lock);
    resize_data_store(ds);

    size_t index = ds->size++;
    ds->ints[index] = key;
    ds->longs[ds->records[index].offset] = index;
    ds->records[index].value = value;
    ds->records[index].key = key;
    ds->records[index].offset = ds->longs - ds->capacity * sizeof(long);
    ds->metadata[index].create_time = time(NULL);
    ds->metadata[index].last_access_time = time(NULL);

    pthread_mutex_unlock(&ds->lock);
}

int find(DataStore* ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->ints[i] == key && ds->longs[ds->records[i].offset] >= 0) {
            pthread_mutex_unlock(&ds->lock);
            return ds->records[i].value;
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return -1;
}

void delete(DataStore* ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->ints[i] == key) {
            size_t index = ds->records[i].offset;
            memmove(ds->longs + index, ds->longs + index + sizeof(long), (ds->size - 1 - i) * sizeof(long));
            memmove(ds->ints + index, ds->ints + index + 1, (ds->size - 1 - i) * sizeof(int));
            memmove(ds->records + index, ds->records + index + 1, (ds->size - 1 - i) * sizeof(Record));
            memmove(ds->metadata + index, ds->metadata + index + 1, (ds->size - 1 - i) * sizeof(Record));
            --ds->size;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

