    if (metadata->bits_per_sample > 16 || metadata->bits_per_sample < 1 || metadata->sample_per_pixel > 4 || metadata->sample_per_pixel < 1) {
        fprintf(stderr, "Error: Unsupported number of bits per sample or samples per pixel in file %s\n", filepath);
        TIFClose(tif);
