NFAPI_CRC_INDICATION_PDU_T* allocate_array(struct net_config *config, size_t N) {
    static NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    static size_t current_size = 0;

    if (!array || current_size < N) {
        size_t new_size = (current_size == 0 ? N : current_size * 2);
        sem_wait(&config->mem_mutex);

        while (!(array = realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
            if (new_size > current_size)
                sem_post(&config->mem_mutex);
            sleep(1);
        }

        current_size = new_size;
        sem_post(&config->mem_mutex);
    }

    return array;
}

// Thread-safe access to the allocated memory by multiple threads
void *get_element(struct net_config *config, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_array(config, index + 1);
    sem_wait(&config->mem_mutex);
    NFAPI_CRC_INDICATION_PDU_T *element = &array[index];
    sem_post(&config->mem_mutex);
    return element;
}
