```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int value;
    char *description;
} Record;

typedef struct Collection {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection* collection = malloc(sizeof(Collection));
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->records = calloc(initial_capacity, sizeof(Record));
    collection->mutex = PTHREAD_MUTEX_INITIALIZER;
    return collection;
}

void destroy_collection(Collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].description);
    }
    free(collection->records);
    free(collection);
}

int add_record(Collection *collection, int value, const char *description) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count == collection->capacity) {
        collection->capacity *= 2;
        Record *new_records = realloc(collection->records, collection->capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Error: Failed to resize memory
        }
        collection->records = new_records;
    }
    collection->records[collection->count].value = value;
    collection->records[collection->count].description = strdup(description);
    ++collection->count;
    pthread_mutex_unlock(&collection->mutex);
    return 0; // Success
}

void update_record(Collection *collection, size_t index, int value, const char *new_description) {
    pthread_mutex_lock(&collection->mutex);
    if (index >= collection->count) {
        pthread_mutex_unlock(&collection->mutex);
        return; // Error: Index out of bounds
    }
    Record* record = &collection->records[index];
    record->value = value;
    free(record->description);
    record->description = strdup(new_description);
    pthread_mutex_unlock(&collection->mutex);
}

void remove_record(Collection *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);
    if (index >= collection->count) {
        pthread_mutex_unlock(&collection->mutex);
        return; // Error: Index out of bounds
    }
    memmove(collection->records + index, collection->records + index + 1, --collection->count - index);
    free(collection->records[collection->count].description);
    pthread_mutex_unlock(&collection->mutex);
}
```

This code defines a `Collection` structure managing an array of `Record` structures. The `create_collection`, `destroy_collection`, `add_record`, `update_record`, and `remove_record` functions provide the necessary functionality to manage the collection, with thread safety ensured using a `pthread_mutex_t`."]

