#include <gzip.h>

typedef struct LTE_RRC_CU_TRANSPORT_PDU {
    RRC_MESSAGE msg;
    bool has_ue_tag;
    UE_CONTEXT_TAG ue_tag;
} LTE_RRC_CU_TRANSPORT_PDU;

struct dynamic_array {
    LTE_RRC_CU_TRANSPORT_PDU** data;
    size_t capacity;
    size_t count;
    sem_t mutex;
};

void compress(LTE_RRC_CU_TRANSPORT_PDU* pdu, gzFile* fp) {
    gzwrite(fp, &pdu->msg.data, sizeof(pdu->msg.data));
    if (pdu->has_ue_tag) {
        gzwrite(fp, &pdu->ue_tag, sizeof(pdu->ue_tag));
    }
}

void decompress(LTE_RRC_CU_TRANSPORT_PDU* pdu, gzFile* fp) {
    gzread(fp, &pdu->msg.data, sizeof(pdu->msg.data));
    if (gzeof(fp)) return;
    if (gzeof(fp)) {
        gzread(fp, &pdu->ue_tag, sizeof(pdu->ue_tag));
        pdu->has_ue_tag = true;
    } else {
        pdu->has_ue_tag = false;
    }
}

void* dynamic_array_init(size_t capacity) {
    struct dynamic_array* da = malloc(sizeof(struct dynamic_array));
    if (!da) return NULL;
    da->capacity = capacity;
    da->count = 0;
    da->data = calloc(capacity, sizeof(LTE_RRC_CU_TRANSPORT_PDU*));
    if (!da->data) {
        free(da);
        return NULL;
    }
    sem_init(&da->mutex, 0, 1);
    return da;
}

void dynamic_array_destroy(struct dynamic_array* da) {
    for (size_t i = 0; i < da->capacity; ++i) {
        if (da->data[i]) free(da->data[i]);
    }
    free(da->data);
    sem_destroy(&da->mutex);
    free(da);
}

void dynamic_array_add(struct dynamic_array* da, LTE_RRC_CU_TRANSPORT_PDU* pdu) {
    sem_wait(&da->mutex);
    if (da->count >= da->capacity) {
        void** new_data = realloc(da->data, sizeof(LTE_RRC_CU_TRANSPORT_PDU*) * (2 * da->capacity));
        if (!new_data) {
            sem_post(&da->mutex);
            return;
        }
        da->data = new_data;
        da->capacity *= 2;
    }
    pdu->has_ue_tag = false; // Ensure the tag is not set upon adding
    gzFile fp = gzopen("temp.gz", "wb");
    compress(pdu, fp);
    gzclose(fp);

    LTE_RRC_CU_TRANSPORT_PDU* temp = mmap(NULL, sizeof(LTE_RRC_CU_TRANSPORT_PDU), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    fp = gzopen("temp.gz", "rb");
    decompress(temp, fp);
    gzclose(fp);
    da->data[da->count++] = temp;
    sem_post(&da->mutex);
}

void dynamic_array_get(struct dynamic_array* da, size_t index, LTE_RRC_CU_TRANSPORT_PDU** pdu) {
    sem_wait(&da->mutex);
    if (index >= da->count) {
        *pdu = NULL;
    } else {
        *pdu = da->data[index];
    }
    sem_post(&da->mutex);
}

void dynamic_array_log(struct dynamic_array* da, const char* op, size_t index) {
    if (op == "add") {
        if (index < da->count) {
            FILE* log = fopen("log.txt", "a");
            fprintf(log, "Add operation successful at position %zu\n", index);
            fclose(log);
        }
    } else if (op == "get") {
        if (index < da->count) {
            FILE* log = fopen("log.txt", "a");
            fprintf(log, "Get operation successful at position %zu\n", index);
            fclose(log);
        } else {
            FILE* log = fopen("log.txt", "a");
            fprintf(log, "Get operation failed at position %zu (index out of bounds)\n", index);
            fclose(log);
        }
    }
}
