    void* function_ptr; // Function pointer for operation implementation
    int params_size; // Number of parameters for the operation
} DataType;

// Custom hash function with collision resolution using open addressing (linear probing)
unsigned long long hash(char *key, unsigned long long table_size) {
    unsigned long long h = 0;
    while (*key) {
        h = (h << 5) + h + *(key++);
    }
    return h % table_size;
}

void resize_hashmap(element*** hash, unsigned long long new_size) {
    element **old_hash = *hash;
    *hash = malloc(new_size * sizeof(element*));
    for (unsigned long long i = 0; i < new_size; ++i) {
        (*hash)[i] = NULL;
    }

    unsigned long long old_size = sizeof(old_hash) / sizeof(element*);
    element **current = old_hash;
    for (unsigned long long i = 0; i < old_size; ++i) {
        if (current[i]) {
            add_to_hash(hash, current[i]->key, current[i]);
        }
    }
    free(old_hash);
}

void add_to_hash(element*** hash, char *key, element* elem) {
    unsigned long long index = hash(key, (*hash)->size);
    if (!(*hash)[index]) {
        (*hash)[index] = elem;
    } else {
        for (element** current = (*hash)[index]; current != NULL; current = (*current)->next) {
            if (strcmp((*current)->key, key) == 0) {
                // Collision resolution: replace the existing element with the new one
                free((*current)->value);
                free((*current)->key);
                (*current)->value = elem->value;
                (*current)->key = elem->key;
                break;
            }
            index = (index + 1) % (*hash)->size;
        }
        if (current == NULL) {
            // Collision resolution: add the new element to the next available slot using linear probing
            element** trail = *hash;
            for (unsigned long long i = index + 1; i < (*hash)->size; ++i) {
                if (!trail[i]) {
                    trail[i] = elem;
                    break;
                }
                trail = &trail[i];
            }
        }
    }
}

void remove_from_hash(element*** hash, char *key) {
    unsigned long long index = hash(key, (*hash)->size);
    element **current = (*hash)[index];
    if (current == NULL) return;

    if (strcmp((*current)->key, key) == 0) {
        (*hash)[index] = current->next;
        free(current->value);
        free(current->key);
        free(current);
    } else {
        for (; current != NULL; current = current->next) {
            if (strcmp((*current)->key, key) == 0) {
                (*current)->prev->next = current->next;
                if (current->next) current->next->prev = current->prev;
                free(current->value);
                free(current->key);
                free(current);
                break;
            }
        }
    }
}

