import java.io.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.time.Instant;
import org.apache.commons.lang3.StringUtils;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class CustomTask {
    private static final int MAX_TRIES = 3;
    private static final long OFFSET_MAX = 1000000;
    private static final int KEY_MAX = 99999;
    private static final double DOUBLE_MAX = 1E15;
    private static final String API_URL = "http://yourapiurl.com/validate";

    public void execute(int size) throws IOException, InterruptedException {
        AtomicInteger retryCounter = new AtomicInteger(0);

        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            if (!isDataValid(size, httpClient)) {
                throw new IllegalArgumentException("Invalid input size");
            }
        }

        long[] offsets = new long[size];
        int[] keys = new int[size];
        double[] doubles = new double[size];
        Record[] records = new Record[size];

        for (int i = 0; i < size; i++) {
            offsets[i] = Math.abs(new Random().nextLong() % OFFSET_MAX);
            keys[i] = Math.abs(new Random().nextInt(KEY_MAX));
            doubles[i] = Math.random() * DOUBLE_MAX;
            records[i] = new Record(Math.abs(new Random().nextInt()), Math.random() * DOUBLE_MAX, StringUtils.leftPad(String.valueOf(i), 10, '0'));
        }

        StringBuilder command = new StringBuilder();
        command.append("echo Offset\tKey\tDouble\tRecord\n");
        for (int i = 0; i < size; i++) {
            command.append(offsets[i]).append("\t").append(keys[i]).append("\t")
                    .append(doubles[i]).append("\t").append(records[i].toString()).append("\n");
        }

        File tempFile = File.createTempFile("command", ".txt");
        try (PrintWriter writer = new PrintWriter(tempFile)) {
            writer.print(command.toString());
        }

        ProcessBuilder processBuilder = new ProcessBuilder("sh", "-c", "chmod 777 " + tempFile.getAbsolutePath() + "; cat " + tempFile.getAbsolutePath() + " | yourcommand");
        processBuilder.redirectErrorStream(true);
        try {
            while (retryCounter.get() < MAX_TRIES) {
                Process process = processBuilder.start();
                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    break;
                }
                retryCounter.incrementAndGet();
            }
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        } finally {
            tempFile.deleteOnExit();
        }

        // Logging and error handling are not included in this example for brevity, but can be easily added as required.
    }

    private boolean isDataValid(int size, CloseableHttpClient httpClient) throws IOException {
        String data = "{\"size\": " + size + "}";
        HttpPost postRequest = new HttpPost(API_URL);
        postRequest.setEntity(new StringEntity(data));

        CloseableHttpResponse response = httpClient.execute(postRequest);
        boolean validData = EntityUtils.toString(response.getEntity()).equals("true");
        if (!validData) {
            int triesRemaining = MAX_TRIES - retryCounter.get();
            if (triesRemaining > 0) {
                Thread.sleep((long) Math.pow(2, triesRemaining));
            } else {
                throw new RuntimeException("Data is not valid after multiple attempts");
            }
        }
        return validData;
    }
}

class Record {
    private final int integer;
    private final BigDecimal bigDecimal;
    private final String string;

    public Record(int integer, double value, String string) {
        this.integer = integer;
        this.bigDecimal = new BigDecimal(value);
        this.string = string;
    }

    @Override
    public String toString() {
        return integer + "\t" + bigDecimal + "\t" + string;
    }
}
