typedef struct {
    LTE_PHY_TEST_FRAME_TYPE frame_type;
    uint32_t frame_number;
    bool frame_error_flag;
} LTE_PHY_TEST_FRAME_INFO_T;

void* allocate_frame_info(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be a positive integer.\n");
        return NULL;
    }

    void* memory_pool = malloc(sizeof(LTE_PHY_TEST_FRAME_INFO_T) * N);
    if (!memory_pool) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    LTE_PHY_TEST_FRAME_INFO_T* frame_infos = (LTE_PHY_TEST_FRAME_INFO_T*) memory_pool;

    // Seed random number generator for each call to this function.
    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        frame_infos[i].frame_type = rand() % MAX_FRAME_TYPES;
        frame_infos[i].frame_number = i + 1;
        frame_infos[i].frame_error_flag = (rand() % 2 == 0); // Set to true with a 50% probability.
    }

    return memory_pool;
}

void deallocate_frame_info(void* memory_pool) {
    if (!memory_pool) {
        fprintf(stderr, "Invalid input: Memory pool is NULL.\n");
        return;
    }

    free(memory_pool);
}
