async fn execute_functions(args: &[String]) {
    let mut function_map = Arc::new(Mutex::new(HashMap::new()));

    for arg in args {
        match load_function(&arg, &mut *function_map.lock().unwrap()).await {
            Ok(_) => debug!("Loaded function {}", arg),
            Err(e) => error!("Failed to load function {}: {}", arg, e),
        }
    }

    let mut concurrent_tasks = 0;
    let function_map_ref = &function_map;

    task::spawn_blocking(move || {
        for func in function_map_ref.lock().unwrap().values() {
            if concurrent_tasks < 5 {
                concurrent_tasks += 1;
                (*func)();
                concurrent_tasks -= 1;
            }
        }
    })
    .with_name("FunctionExecutor")
    .unwrap()
    .forward(|_, output| {
        if let Err(e) = output {
            error!("Error executing function: {}", e);
        }
    });
}

