std::atomic<size_t> peakMemory(0);

class DataGenerator {
public:
    explicit DataGenerator(double minVal, double maxVal) : dist(minVal, maxVal) {}
    std::unique_ptr<double[]> generate(size_t size) const {
        auto data = std::make_unique<double[]>(size);
        #pragma omp parallel for
        for (size_t i = 0; i < size; ++i)
            data[i] = dist();
        return data;
    }

    Point generatePoint() const {
        double x, y;
        generate(2, x, y);
        return {x, y};
    }

private:
    std::mt19937 distEngine;
    std::uniform_real<double> dist;
};

class Cache {
public:
    explicit Cache(size_t cacheSize) : cache(cacheSize), lock() {}

    void addData(const double* data, size_t size) {
        std::unique_lock<std::mutex> lockGuard(lock);
        if (dataPool.size() + size > cacheSize) {
            dataPool.erase(dataPool.begin(), std::prev(dataPool.end()));
        }
        dataPool.insert(dataPool.end(), data, data + size);
    }

    const double* getData(size_t index) {
        std::unique_lock<std::mutex> lockGuard(lock);
        if (dataPool.empty()) return nullptr;
        auto it = dataPool.begin();
        peakMemory += sizeof(double) * (it->size());
        if (index >= it->size()) {
            it = std::next(it);
            peakMemory -= sizeof(double) * it->size();
            index %= it->size();
        }
        auto dataPtr = &(*it)[index];
        peakMemory -= sizeof(double);
        return dataPtr;
    }

private:
    std::vector<std::unique_ptr<double[]>> dataPool;
    mutable std::mutex lock;
};

class SerializedData {
public:
    explicit SerializedData(const void* data, size_t size) : buffer(data, data + size), size(size) {}

    void save(const std::string& filename) const {
        std::ofstream outFile(filename, std::ios::binary | std::ios::out);
        gzstream compressedOut(&outFile);
        compressedOut.put(reinterpret_cast<char*>(&size), sizeof(size));
        compressedOut.write(buffer.data(), buffer.size());
    }

    static std::unique_ptr<SerializedData> load(const std::string& filename) {
        std::ifstream inFile(filename, std::ios::binary | std::ios::in);
        gzstream compressedIn(&inFile);
        size_t size;
        compressedIn.read(reinterpret_cast<char*>(&size), sizeof(size));
        auto buffer = std::make_unique<char[]>(size);
        compressedIn.read(buffer.get(), size);
        return SerializedData{buffer.get(), size};
    }

private:
    std::vector<char> buffer;
    size_t size;
};

