typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
    pthread_mutex_t mutex;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);
    return new_node;
}

Node* insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) {
        return *head;
    }

    Node* current = *head;
    Node** prev = head;

    while (current && current->data.RNTI < data.RNTI) {
        prev = &current;
        current = current->next;
    }

    pthread_mutex_lock(&new_node->mutex);
    new_node->next = current;
    pthread_mutex_unlock(&new_node->mutex);

    if (prev == head) {
        *head = new_node;
    } else {
        (*prev)->next = new_node;
    }
    return *head;
}

void remove_node(Node** head, Node* node_to_remove) {
    if (!head || !(*head)) {
        return;
    }

    pthread_mutex_lock(&node_to_remove->mutex);

    if ((*head) == node_to_remove) {
        *head = (*head)->next;
    } else {
        Node* current = *head;
        while (current->next && current->next != node_to_remove) {
            current = current->next;
        }

        if (!current->next) {
            return;
        }

        current->next = node_to_remove->next;
    }

    pthread_mutex_unlock(&node_to_remove->mutex);
}

void update_data(Node* node, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!node || !new_data.RNTI) {
        return;
    }

    pthread_mutex_lock(&node->mutex);
    node->data = new_data;
    pthread_mutex_unlock(&node->mutex);
}

