    sem_wait(&buffer_mutex);
    void* updated_data = get_data(request->id);
    if (updated_data != request->data) {
        free(request->data);
        request->data = updated_data;
    }
    sem_post(&buffer_mutex);
}

void cleanup() {
    for (size_t i = 0; i < MAX_REQUESTS; ++i) {
        if (requests[i].id) {
            free(requests[i].data);
        }
    }
