    // Calculate the required memory for long and int arrays based on worst-case scenario (4 bytes for 'long' and 4 bytes for 'int')
    size_t memory_required = sizeof(long) * num_records + sizeof(int) * 2 * num_records;

    // Adjust for overhead, e.g., 10% for dynamic allocation and record structure
    memory_required *= 1.1;

    // Check if the available memory is sufficient
    return (memory_required <= RSIZE_MAX);
}

Record* generate_records(size_t num_records, size_t max_key, size_t min_offset) {
    Record *records = nullptr;

    // Allocate memory for the record array and check for failure
    records = static_cast<Record*>(malloc(num_records * sizeof(Record)));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return nullptr;
    }

    // Allocate memory for the long and int arrays, ensuring unique values for each record's key
    long *offsets = static_cast<long*>(malloc(num_records * sizeof(long)));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        free(records);
        return nullptr;
    }
    int *keys = static_cast<int*>(calloc(2 * num_records, sizeof(int)));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        free(offsets);
        free(records);
        return nullptr;
    }

    // Populate the key array with unique values and store their corresponding offsets
    size_t current_key = 0;
    size_t populated_keys = 0;
    for (size_t i = 0; i < num_records; ++i) {
        while (populated_keys < i) {
            keys[current_key] = rand() % max_key + min_offset;
            current_key++;
        }

        // Find the first unused key within the range and store its index in the offset array
        size_t j;
        for (j = 0; j < i; ++j) {
            if (keys[j] == keys[i]) break;
        }
        offsets[i] = j;

        // Update the key and store the record in the record array
        records[j].key = keys[i];
        records[j].offset = offsets[i];
        populated_keys++;
    }

    qsort(records, num_records, sizeof(Record), compare_records);

    // Free the key array since it's no longer needed
    free(keys);

    return records;
}

