import json
import hashlib
from typing import Dict, Any, Callable

class ScriptObjRegistry:
    def __init__(self):
        self.factories = {}

    def add_factory(self, id: str, factory: Callable) -> None:
        self.factories[id] = factory

    def get_script_obj_from_json(self, json_str: str) -> Any:
        data = json.loads(json_str)
        if '__class_id__' not in data:
            raise ValueError("JSON string does not contain a class ID.")
        id = data['__class_id__']
        factory = self.factories.get(id, None)
        if factory is None:
            raise KeyError(f"No factory found for ID {id}.")
        return factory(**data)

    def to_json(self, obj: Any) -> str:
        data = obj.__dict__
        data['__class_id__'] = type(obj).__name__
        return json.dumps(data)

# Example usage:
