        let hash = 0;
        for (let i = 0; i < code.length; i++) {
            hash = ((hash << 5) + hash) + code.charCodeAt(i);
            hash |= 0; // Convert to 32bit integer
        }
        return hash.toString(16);
    }

    async function getScriptObjectById(id) {
        const scripts = await fetchScripts();
        for (const script of scripts) {
            if (script.name || script.codeHash === id) {
                return script;
            }
        }
        return null;
    }

    async function loadCriticalScripts() {
        const criticalScriptIds = ['critical1', 'critical2']; // Define your critical scripts here
        for (const id of criticalScriptIds) {
            const script = await getScriptObjectById(id);
            if (script) insertScriptTag(script);
        }
    }

    async function loadNonCriticalScripts() {
        const nonCriticalScriptIds = scripts.filter(script => !criticalScriptIds.includes(script.name)).map(script => script.name);
        for (const id of nonCriticalScriptIds) {
            const script = await getScriptObjectById(id);
            if (script) insertScriptTag(script);
        }
    }

    function insertScriptTag(script) {
        const scriptElement = document.createElement('script');
        scriptElement.src = script.url || `data-hash=${script.codeHash}`; // Use data-hash attribute for caching
        scriptElement.async = true;
        document.head.appendChild(scriptElement);
    }

    (async () => {
        try {
            const criticalScriptsPromises = await loadCriticalScripts();
            const nonCriticalScriptsPromises = nonCriticalScriptsPromises || await loadNonCriticalScripts();
            Promise.all([...criticalScriptsPromises, ...nonCriticalScriptsPromises]).then(() => {
                // Handle page load complete event here
            });
        } catch (error) {
            console.error(`Error loading scripts: ${error.message}`);
        }
    })();
}
