typedef struct {
    int32_t value;
} record_t;

void print_array(const char *name, void *arr, size_t size) {
    printf("%s:", name);
    for (size_t i = 0; i < size; ++i) {
        printf(" %p", ((uintptr_t *)arr)[i]);
    }
    putchar('\n');
}

void *random_record(const double mean, const double stddev) {
    static thread_local double r = 0.0;
    if (r == 0.0) r = rand() / (double)RAND_MAX;

    double z = sqrt(-2.0 * log(r)) * sqrt(1.0 / stddev);
    return ((int32_t)(mean + z * stddev));
}

void initialize_arrays(size_t *input_sizes, size_t *offset_size, size_t *key_size, int64_t max_sum) {
    // Ensure valid input sizes and max_sum
    if (*offset_size > INT_MAX || *key_size > INT_MAX || *offset_size == 0 || *key_size == 0 || max_sum <= 0) {
        fprintf(stderr, "Invalid input: offset size %zu, key size %zu, max sum %" PRId64 "\n", *offset_size, *key_size, max_sum);
        exit(EXIT_FAILURE);
    }

    long *offsets = malloc(*offset_size * sizeof(long));
    if (!offsets) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(*key_size * sizeof(int));
    if (!keys) {
        perror("malloc failed");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    record_t *records = malloc((*input_sizes + NUM_THREADS - 1) / NUM_THREADS * sizeof(record_t));
    if (!records) {
        perror("malloc failed");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize offset and key arrays with user input values, assuming they are already validated
    for (size_t i = 0; i < *offset_size; ++i) {
        offsets[i] = input_sizes[i];
    }
    for (size_t i = 0; i < *key_size; ++i) {
        keys[i] = input_sizes[i + *offset_size];
    }

    // Initialize record array with weighted random numbers, using a custom distribution function
    double sum = 0.0;
    for (size_t i = 0; i < (*input_sizes + NUM_THREADS - 1) / NUM_THREADS; ++i) {
        record_t *record = &records[i];
        record->value = (int32_t)(random_record(mean, stddev));
        sum += record->value;
    }

    // Ensure the sum of all record values does not exceed the specified maximum threshold
    if (sum > max_sum) {
        fprintf(stderr, "Record values sum exceeds the maximum allowed value %" PRId64 "\n", max_sum);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    free(records);
    free(keys);
