        pthread_create(&tdArray[i].thread_id, &attr, threadFunction, &tdArray[i]);
        pthread_join(tdArray[i].thread_id, NULL);

        // Calculate and limit memory usage per thread based on the maximum allowed memory usage
        totalMemoryUsage += (sizeof(long) + sizeof(int) + sizeof(Data)) * dataStructSize * tdArray[i].arraySize;
        if (totalMemoryUsage > tdArray[i].maxMemoryPerThread * numConcurrentThreads) {
            tdArray[i].gc(); // Call garbage collection function to free unnecessary memory
