void validate_sfn_rb(const int sfn, const int rb) {
    // Validate SFN and RB against predefined frequency bands and resource allocation policies.
    // If out-of-bounds values are detected, log warnings and return false.
    // For simplicity, assume a valid SFN range is [0, 1023] and a valid RB range is [0, 64].
    if (sfn < 0 || sfn > 1023 || rb < 0 || rb > 64) {
        printf("Warning: Invalid SFN or RB value detected.\n");
        return false;
    }
    return true;
}

void init_rx_message(NFAPI_RX_MESSAGE_T** head, RX_STREAM_T stream) {
    NFAPI_RX_MESSAGE_T* new_msg = malloc(sizeof(NFAPI_RX_MESSAGE_T));
    if (new_msg == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    sem_init(&new_msg->lock, 0, 1);
    new_msg->stream = malloc(sizeof(RX_STREAM_T));
    if (new_msg->stream == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(new_msg);
        return;
    }

    sem_init(&new_msg->lock, 0, 1);
    new_msg->stream->sfn = stream.sfn;
    new_msg->stream->rb_start = stream.rb_start;
    // Initialize other members of RX_STREAM_T structure

    if (!validate_sfn_rb(new_msg->stream->sfn, new_msg->stream->rb_start)) {
        free(new_msg->stream);
        free(new_msg);
        return;
    }

    new_msg->next = *head;
    *head = new_msg;
}

void add_rx_message(NFAPI_RX_MESSAGE_T** head, RX_STREAM_T stream) {
    if (!validate_sfn_rb(stream.sfn, stream.rb_start)) return;

    NFAPI_RX_MESSAGE_T* new_msg = malloc(sizeof(NFAPI_RX_MESSAGE_T));
    if (new_msg == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    sem_init(&new_msg->lock, 0, 1);
    new_msg->stream = malloc(sizeof(RX_STREAM_T));
    if (new_msg->stream == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(new_msg);
        return;
    }

    sem_init(&new_msg->lock, 0, 1);
    new_msg->stream->sfn = stream.sfn;
    new_msg->stream->rb_start = stream.rb_start;
    // Initialize other members of RX_STREAM_T structure

    if (!validate_sfn_rb(new_msg->stream->sfn, new_msg->stream->rb_start)) {
        free(new_msg->stream);
        free(new_msg);
        return;
    }

    sem_wait(&((*head)->lock));

    NFAPI_RX_MESSAGE_T* last = *head;
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = new_msg;

    sem_post(&new_msg->lock);
}

