typedef struct Point {
    float x, y;
    float magnitude;
    struct Point *next;
} Point;

typedef struct CoordinateData {
    float *coords;
    char **labels;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CoordinateData;

void check_index(size_t idx, size_t size) {
    if (idx >= size) {
        fprintf(stderr, "Index out of bounds\n");
        exit(1);
    }
}

CoordinateData* create_coordinate_data(size_t capacity) {
    CoordinateData *cd = malloc(sizeof(CoordinateData));
    if (!cd) {
        perror("Memory allocation failed\n");
        exit(1);
    }
    cd->coords = calloc(capacity, sizeof(float));
    if (!cd->coords) {
        perror("Memory allocation failed\n");
        free(cd);
        exit(1);
    }
    cd->labels = calloc(capacity, sizeof(char*));
    if (!cd->labels) {
        perror("Memory allocation failed\n");
        free(cd->coords);
        free(cd);
        exit(1);
    }
    pthread_mutex_init(&cd->mutex, NULL);
    cd->capacity = capacity;
    cd->size = 0;
    return cd;
}

Point* create_point(float x, float y) {
    Point *new_point = malloc(sizeof(Point));
    if (!new_point) {
        perror("Memory allocation failed\n");
        exit(1);
    }
    new_point->x = x;
    new_point->y = y;
    // Generate random magnitude within [0, max_magnitude] range
    new_point->magnitude = rand() / (RAND_MAX / 100.0);
    new_point->next = NULL;
    return new_point;
}

void add_point(CoordinateData *cd, float x, float y) {
    pthread_mutex_lock(&cd->mutex);
    check_index(cd->size, cd->capacity);
    Point *new_point = create_point(x, y);
    cd->coords[cd->size] = new_point->x;
    if (strlen(cd->labels[cd->size]) < 1) {
        strcpy(cd->labels[cd->size], "Point");
    }
    new_point->next = cd->points;
    cd->points = new_point;
    ++cd->size;
    pthread_mutex_unlock(&cd->mutex);
}

