            try {
                byte[] imgData = future.get();
                baos.write(imgData);
            } catch (ExecutionException | InterruptedException e) {
                // Log and handle errors, for example by skipping the current image or retrying
            }
        }

        return baos.toByteArray();
    }

    private Future<byte[]> downloadAndResizeImage(String url, ExecutorService executor) {
        Future<URL> futureUrl = Jsoup.asyncGet(url).timeout(30_000).get(); // Timeout after 30 seconds

        return futureUrl.thenApplyAsync(this::downloadAndResizeImageFromUrl).or(() -> {
            AtomicInteger retries = new AtomicInteger(MAX_RETRIES);
            return () -> {
                if (retries.decrementAndGet() > 0) {
                    try {
                        Thread.sleep(RETRY_BACKOFF_MILLIS);
                    } catch (InterruptedException e) {
                        // Log and handle errors, for example by skipping the current image or retrying
                    }
                    return downloadAndResizeImage(url, executor);
                } else {
                    throw new RuntimeException("Maximum number of retries exceeded");
                }
            };
        });
    }

    private byte[] downloadAndResizeImageFromUrl(URL url) throws IOException {
        try (HttpURLConnection connection = (HttpURLConnection) url.openConnection()) {
            connection.setRequestMethod("GET");
            connection.addRequestProperty("User-Agent", "MyApp/1.0");
            BufferedImage originalImage;

            try (InputStream inputStream = connection.getInputStream()) {
                originalImage = ImageIO.read(inputStream);
            }

            BufferedImage resizedImage = resizeImage(originalImage, MAX_WIDTH, MAX_HEIGHT);
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
