                ImageIO.write(resizedImage, getFormatFromInputStream(connection.getInputStream()), outputStream);
            }

            return baos.toByteArray();
        } catch (IOException e) {
            // Log and handle errors gracefully, for example by skipping the current image or retrying
            throw new RuntimeException("Failed to download and resize image", e);
        }
    }

    private String getFormatFromInputStream(InputStream inputStream) throws IOException {
        byte[] signature = Arrays.copyOfRange(inputStream.readAllBytes(), 0, Math.min(8, inputStream.available()));
        String format = ImageIO.getReaderFromStream(new ByteArrayInputStream(signature)).getFormatName();
        if (format == null) {
            throw new IOException("Could not determine image format");
        }
        return format;
    }

