#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fnmatch.h>

typedef struct file_entry {
    char* filename;
    size_t size;
    void* data;
} file_entry;

int is_regular_file(const char *path) {
    struct stat sb;
    return (stat(path, &sb) == 0 && S_ISREG(sb.st_mode));
}

void resolve_symbolic_link(char **path, size_t *size) {
    char linkbuf[1024];
    ssize_t len = readlink(*path, linkbuf, sizeof(linkbuf) - 1);
    if (len < 0) {
        perror("readlink");
        free(*path);
        *path = NULL;
        *size = 0;
        return;
    }
    (*path)[len] = '\0';
    char *resolved_path = malloc(strlen(getcwd(NULL, 1024)) + len + 2);
    strcpy(resolved_path, getcwd(NULL, 1024));
    strcat(resolved_path, "/");
    strcat(resolved_path, *path);
    free(*path);
    *path = resolved_path;
    (*size)++; // accounting for the symbolic link itself
}

file_entry* populate_file_entries(char **dir, size_t *size, size_t cap, char *filter) {
    DIR *dp;
    struct dirent *dent;
    dp = opendir(*dir);
    if (!dp) {
        perror("opendir");
        return NULL;
    }

    file_entry **entries = malloc(cap * sizeof(file_entry*));
    size_t used = 0;

    while ((dent = readdir(dp)) != NULL) {
        char *path = malloc(strlen(*dir) + strlen(dent->d_name) + 2);
        strcpy(path, *dir);
        strcat(path, "/");
        strcat(path, dent->d_name);

        if (fnmatch(filter, dent->d_name, 0)) {
            if (is_regular_file(path)) {
                struct stat sb;
                stat(path, &sb);
                file_entry *fe = malloc(sizeof(file_entry));
                fe->filename = strdup(dent->d_name);
                fe->size = sb.st_size;
                if (used == cap) { // reallocate memory if the current capacity is reached
                    cap *= 2;
                    entries = realloc(entries, cap * sizeof(file_entry*));
                }
                entries[used++] = fe;
            } else if (dent->d_type == DT_LNK) { // handle symbolic links
                resolve_symbolic_link(&path, &fe->size);
                file_entry *fe = malloc(sizeof(file_entry));
                fe->filename = strdup(path);
                fe->size = 1; // accounting for the symbolic link itself
                if (used == cap) { // reallocate memory if the current capacity is reached
                    cap *= 2;
                    entries = realloc(entries, cap * sizeof(file_entry*));
                }
                entries[used++] = fe;
            }
        }
        free(path);
    }

    closedir(dp);
    file_entry *final_array = malloc((used + 1) * sizeof(file_entry));
    memcpy(final_array, entries, used * sizeof(file_entry*));
    final_array[used] = NULL;
    free(entries);

    return final_array;
}
```

