    int iterations = 1000000;
    while (iterations--) {
        pthread_mutex_lock(&locks[id]);
        // Perform some operations on the shared data structure here.
        shared_data *shared_data_ptr = &shared_data_arr[id];
        shared_data_ptr->value++;
        pthread_mutex_unlock(&locks[id]);
    }
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s num_threads num_shared_data\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    size_t num_threads = atoi(argv[1]);
    size_t num_shared_data = atoi(argv[2]);

    if (num_threads * sizeof(shared_data) + num_threads * sizeof(pthread_t) > RLIMIT_DATA || num_threads > sysconf(_SC_NPROCESSORS_CONF)) {
        fprintf(stderr, "Exceeded resource limits. Please adjust thread and shared data sizes accordingly.\n");
        exit(EXIT_FAILURE);
    }

    init_mutex();

    locks = alloc_locks(num_threads);
    threads = alloc_threads(num_threads);
    shared_data_arr = alloc_shared_data(num_shared_data);

    for (size_t i = 0; i < num_threads; ++i) {
        size_t thread_id = i * THREAD_ID_CONSTANT;
        shared_data *shared_data_ptr = &shared_data_arr[i];
        void *arg = &thread_id;

        if (pthread_create(&threads[i], NULL, thread_function, arg)) {
            perror("pthread_create failed");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join failed");
            exit(EXIT_FAILURE);
        }
    }

    munmap(shared_data_arr, num_shared_data * sizeof(shared_data));
    free(locks);
    free(threads);
    pthread_mutexattr_destroy(&mutex_attr);

    return 0;
}
