void processIntegerList() {
    const size_t MAX_ELEMENTS = 500;
    size_t numElements = 0, offset = 0;
    Record *records = NULL, tempRecords = {};
    int *keys = NULL, longKeys = {}, shortKeys = {};

    while (numElements < MAX_ELEMENTS && scanf("%d", &tempRecords[numElements].value) == 1) {
        ++numElements;
    }

    if (numElements > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Too many integers provided.\n");
        return;
    }

    records = realloc(records, numElements * sizeof(Record));
    keys = realloc(keys, numElements * sizeof(int));

    for (size_t i = 0; i < numElements; ++i) {
        records[i].value = rand() % 100 + 1; // Set random value within the range [1, 100]
        keys[i] = (i + offset) & 1 ? longKeys : shortKeys;
        keys[i]++;
        if (keys[i] > offset + MAX_ELEMENTS) {
            offset += MAX_ELEMENTS;
            if (shortKeys < offset) shortKeys = offset;
            if (longKeys < offset - MAX_ELEMENTS) longKeys = offset - MAX_ELEMENTS;
        }
        records[i].value = keys[i] > longKeys ? records[i].value : keys[i] + MAX_ELEMENTS - longKeys;
    }

    Record maxVal = { .value = INT32_MIN };
    findMax(records, numElements, &maxVal);

    printf("Largest integer: %d\n", maxVal.value);
    double sum = 0;
    for (size_t i = 0; i < numElements; ++i) {
        sum += records[i].value;
    }
    printf("Average of integers: %.2f\n", sum / numElements);

    free(records);
    free(keys);
}
