#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double temperature;
    char location[50];
} Sensor;

typedef struct Node {
    Sensor sensor;
    struct Node *next;
} Node;

Node* create_sensor(const char* location, double temperature) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    strcpy(new_node->sensor.location, location);
    new_node->sensor.temperature = temperature;
    new_node->next = NULL;
    return new_node;
}

void register_sensor(Node** head, Node* sensor) {
    if (!head || !*head) {
        *head = sensor;
        return;
    }

    Node* current = *head;
    while (current->next != NULL) current = current->next;
    current->next = sensor;
}

void deregister_sensor(Node** head, const char* location) {
    if (!head || !*head) return;

    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && strcmp(current->sensor.location, location) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) *head = current->next;
    else previous->next = current->next;

    free(current);
}

void remove_duplicates(Node** head) {
    if (!head || !*head || !(*head)->next) return;

    Node* current = *head;
    while (current->next != NULL) {
        Node* temp = current->next;
        while (temp != NULL && strcmp(current->sensor.location, temp->sensor.location) == 0) {
            Node* next_temp = temp->next;
            free(temp);
            temp = next_temp;
        }
        current = temp;
    }
}

Node* get_active_sensors() {
    Node* head = NULL;
    remove_duplicates(&head);
    return head;
}

void generate_data(int num, Node** head) {
    srand(time(NULL));

    for (int i = 0; i < num; ++i) {
        char location[50];
        sprintf(location, "Location%d", i);
        double temperature = (double)(rand() / RAND_MAX * 100);
        Node* sensor = create_sensor(location, temperature);
        if (!sensor) break;
        register_sensor(head, sensor);
    }
}

Node* manage_memory(int operation, int num, Node** head) {
    if (operation == 1) generate_data(num, head); // Operation 1: Add sensors
    else deregister_sensors(*head, num); // Operation 2: Remove sensors by location count

    remove_duplicates(head);

    return *head;
}
