    unsigned long load_factor;
    void** buckets;
    KEY_TYPE key_type;
};

void* find_bucket(struct hash_table* ht, const void* key) {
    size_t index = (unsigned long)(ht->key_type * hash(key) % ht->size);
    size_t next = index + 1;
    if (next >= ht->size) next = 0;

    do {
        void* current = ht->buckets[index];
        if (!current || ht->key_type != get_key_type(current)) continue;

        return current;
    } while ((next != index) && (ht->buckets[next] != NULL));

    return NULL;
}

int hash(const void* key) {
    unsigned long a = 61;
    unsigned long b = 37;
    unsigned long h = 0;
    const char* str_key = (const char*)key;
    while (*str_key++) h = (h * a + b) % ht->size;
    return h;
}

KEY_TYPE get_key_type(const void* key) {
    if (typeof(key) == int*) return INTEGER;
    else if (typeof(key) == double*) return DOUBLE;
    else if (sizeof(struct node) == sizeof(key)) return NODE;
    else if (sizeof(enum type) == sizeof(key)) return TYPE;
    assert(false);
    return -1; // Unreachable code, handle this gracefully in a real-world implementation
}

