        do {
            if (current->next == NULL) {
                current->next = malloc(sizeof(**(void**)ht->buckets));
                memcpy(current->next, value, sizeof(*value));
                current->next->prev = current;
                break;
            }
            current = current->next;
        } while (1);
    }
}

