            break;
        }
    }

    // Find or create a category for this point
    for (int i = 0; i < num_categories; i++) {
        if (strcmp(points[size]->category, categories[i].id) == 0) break;
        if (!strcmp(points[size]->category, categories[i].id)) return -1; // Edge case: duplicate category ID
    }

    Category *new_cat = malloc(sizeof(Category));
    strcpy(new_cat->id, points[size]->category);
    new_cat->count = 1;
    new_cat->next = categories;

    if (num_categories == 0) {
        categories = new_cat;
    } else {
        Category *current = categories;
        while (current->next != NULL) current = current->next;
        current->next = new_cat;
    }
    num_categories++;

    return 0;
}

void delete_point(int index) {
    if (index < 0 || index >= size) return;

    pthread_mutex_lock(&mem_lock);
    free(points[index]);
    total_allocated -= sizeof(Point);
    pthread_mutex_unlock(&mem_lock);

    for (int i = 0; i < num_categories; i++) {
        if (strcmp(points[index]->category, categories[i].id) == 0) {
            categories[i].count--;
            if (categories[i].count <= 0) {
                Category *prev = NULL;
                for (Category *current = categories; current != NULL; prev = current, current = current->next) {
                    if (strcmp(current->id, points[index]->category) == 0) {
                        if (prev == NULL) categories = current->next;
                        else prev->next = current->next;
                        free(current);
                        num_categories--;
                        break;
                    }
                }
            }
            break;
        }
    }

    memmove(&points[index], &points[size - 1], sizeof(Point*) * (size - index));
    size--;
}

