};

class distributed_log_storage {
private:
    std::map<int, std::shared_ptr<batch_entry>> batches_;
    boost::asio::io_service io_service_;
    std::shared_ptr<metadata_service> metadataService_;

public:
    distributed_log_storage(std::shared_ptr<metadata_service> metadataService) : metadataService_(metadataService) {}

    void log(const log_entry& entry) {
        auto batchIt = batches_.find(entry.timestamp.time_of_day().total_seconds());
        if (batchIt == batches_.end()) {
            batchIt = batches_.emplace(entry.timestamp.time_of_day().total_seconds(), std::make_shared<batch_entry>()).first;
        }
        batchIt->second->log_entries.push_back(entry);
    }

    void flush() {
        // Flush batches to disk asynchronously
    }

    void fetchMetadata(const log_entry& entry) {
        metadataService_->fetchMetadata(entry.message, [this, entry](const auto& result) {
