using System;
using System.Collections.Concurrent;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DataTransformer
{
    public Func<dynamic, dynamic> TransformationRule { get; set; }
    public Action<string> Log { get; set; }
}

public class MigrationSummaryReport
{
    public int ProcessedRecords { get; set; }
    public int FailedOperations { get; set; }
    public Exception LastException { get; set; }
}

public async Task<bool> migrateAndOptimizeDataFlowPipeline(IAsyncEnumerable<dynamic> sourceStream, string targetDatabaseConnectionString, string targetTableSchema, DataTransformer config)
{
    var stopwatch = new Stopwatch();
    stopwatch.Start();

    var dataBuffer = new ConcurrentQueue<dynamic>();
    var taskCompletionSource = new TaskCompletionSource<bool>();

    var parallelismFactor = SystemInformation.ProcessorCount * 2; // Adjust according to system capabilities and network latency conditions
    var workerTasks = Enumerable.Range(0, parallelismFactor)
                                .Select(_ => Task.Run(() => ProcessDataAsync(sourceStream, dataBuffer, targetDatabaseConnectionString, targetTableSchema, config)))
                                .ToArray();

    try
    {
        await Task.WhenAll(workerTasks);

        if (!dataBuffer.IsEmpty)
            ProcessDataAsync(sourceStream, dataBuffer, targetDatabaseConnectionString, targetTableSchema, config);
    }
    catch (Exception ex)
    {
        // Log the exception and continue processing without halting
        config.Log?.Invoke($"Error during data migration: {ex}");
    }

    stopwatch.Stop();

    var summaryReport = new MigrationSummaryReport
    {
        ProcessedRecords = dataBuffer.Count + workerTasks.Sum(t => t.Status == TaskStatus.RanToCompletion ? 1 : 0),
        // Other statistics and error handling can be added here
    };

    taskCompletionSource.SetResult(summaryReport.ProcessedRecords > 0);

    return await taskCompletionSource.Task;
}

private async Task ProcessDataAsync(IAsyncEnumerable<dynamic> sourceStream, ConcurrentQueue<dynamic> dataBuffer, string targetDatabaseConnectionString, string targetTableSchema, DataTransformer config)
{
    while (await foreach var item in sourceStream.WithCancellation(CancellationToken.None))
    {
        if (config.TransformationRule != null)
            item = config.TransformationRule(item); // Apply transformation rules if provided

        dataBuffer.Enqueue(item); // Buffer data for parallel processing and storage

        var bufferSizeThreshold = Math.Max(dataBuffer.Count, 10_000); // Adjust buffer size threshold as needed
        if (dataBuffer.Count >= bufferSizeThreshold)
        {
            await AsyncStoreDataToDatabase(dataBuffer, targetDatabaseConnectionString, targetTableSchema, config);
        }
    }
}

private async Task AsyncStoreDataToDatabase(ConcurrentQueue<dynamic> dataBuffer, string connectionString, string tableSchema, DataTransformer config)
{
    // Integrate with an external data validation service here if needed

    var sqlConnection = new SqlConnection(connectionString);
    await sqlConnection.OpenAsync();

    using (var transaction = sqlConnection.BeginTransaction())
    {
        try
        {
            var recordsToInsert = dataBuffer.Take(100).ToList(); // Adjust the number of records to insert at a time as needed

            Parallel.ForEach(recordsToInsert, record =>
            {
                var random = new Random();
                foreach (var property in record.GetType().GetProperties())
                {
                    property.SetValue(record, GenerateRandomPropertyValue(property.Name)); // Set random values for each record
                }

                using (var command = new SqlCommand($"INSERT INTO {tableSchema}.{tableSchema}_{Guid.NewGuid().ToString()} VALUES (@{string.Join(", @", record.GetType().GetProperties().Select(p => p.Name))})", sqlConnection))
                {
                    command.Transaction = transaction;
                    foreach (var property in record.GetType().GetProperties())
                    {
                        command.Parameters.AddWithValue($"@{property.Name}", record[property.Name]);
                    }
                }
            });

            await transaction.CommitAsync();
        }
        catch (Exception ex)
        {
            // Log the exception and continue processing without halting
            config.Log?.Invoke($"Error during database storage: {ex}");

            try
            {
                await transaction.RollbackAsync();
            }
            catch { } // Ignore any errors during rollback to avoid deadlocks
        }
    }

    sqlConnection.Close();

    dataBuffer.Clear();
}

private object GenerateRandomPropertyValue(string propertyName)
{
    if (propertyName == "keyField")
    {
        return new Random().Next(10_000); // Set a random value within the specified range for key fields
    }

    // Implement logic to generate random values for other properties as needed
    return null;
}
