int insert_event(HashTable* hash_table, const char* timestamp, const char* event_type, void* metadata, size_t metadata_size) {
    // Find appropriate index and node based on the timestamp
    size_t idx = hash_function(timestamp);
    Node* node = find_node(&((*hash_table)->table[idx]), timestamp);

    if (node->event.timestamp > atoi(timestamp)) return -1; // Timestamp out of order

    // Allocate memory for event metadata if needed
