    node->event.metadata = metadata;
    node->event.metadata_size = metadata_size;

    // Update time-series data if needed
    double* current_ts = timeseries + idx;
    if (current_ts[node->event.timestamp] == 0.0) {
        current_ts[node->event.timestamp] = get_current_time();
