void processFileChunks(const char* filename, const char* compressionFormat) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return;
    }

    void* mappedData;
    size_t mapSize;
    off_t offset = 0;
    ssize_t readBytes;

    while ((readBytes = fseek(file, offset, SEEK_SET)) > 0) {
        if (offset + readBytes > maxChunkSize) {
            offset -= ftell(file);
            continue;
        }

        mapSize = (readBytes < minChunkSize) ? minChunkSize : readBytes;
        mappedData = mmap(NULL, mapSize, PROT_READ, MAP_PRIVATE, fileno(file), offset);
        if (mappedData == MAP_FAILED) {
            fprintf(stderr, "Failed to map data: %s\n", strerror(errno));
            fclose(file);
            return;
        }

        ChunkNode* node = malloc(sizeof(ChunkNode));
        if (!node) {
            munmap(mappedData, mapSize);
            fclose(file);
            return;
        }

        node->data = mappedData;
        node->checksum = calloc(1, SHA256_DIGEST_LENGTH);
        if (!node->checksum) {
            free(node);
            munmap(mappedData, mapSize);
            fclose(file);
            return;
        }

        // Process chunk here using the processFileChunk function.

        pthread_mutex_lock(&listLock);
        node->next = head;
        head = node;
        totalDataProcessed += mapSize;
        pthread_mutex_unlock(&listLock);

        if (totalDataProcessed > maxListSize) {
            ChunkNode* current = head;
            while (totalDataProcessed > maxListSize && current != NULL) {
                totalDataProcessed -= current->fileSize;
                ChunkNode* temp = current;
                current = current->next;
                free(temp->checksum);
                free(temp);
            }
        }

        offset += readBytes;
    }

    fclose(file);
}

