["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    char* name;
} item;

// Memory pool structure and functions
typedef struct MemPool {
    size_t size;
    size_t allocated;
    void* buffer;
    size_t element_size;
} MemPool;

MemPool* mem_pool_create(size_t initial_size, size_t element_size) {
    MemPool* pool = malloc(sizeof(MemPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->buffer = malloc(initial_size * element_size);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }

    pool->size = initial_size;
    pool->allocated = 0;
    return pool;
}

void* mem_pool_acquire(MemPool* pool) {
    if (pool->allocated >= pool->size) {
        void* new_buffer = realloc(pool->buffer, (2 * pool->size) * pool->element_size);
        if (!new_buffer) return NULL;
        pool->buffer = new_buffer;
        pool->size *= 2;
    }

    void* result = (char*)pool->buffer + pool->allocated * pool->element_size;
    pool->allocated++;
    return result;
}

void mem_pool_release(MemPool* pool, void* ptr) {
    if (!ptr) return;

    char* pool_ptr = (char*)ptr - pool->element_size;
    if (pool_ptr < (char*)pool->buffer && pool_ptr + pool->element_size <= (char*)pool->buffer + pool->allocated * pool->element_size) {
        pool->allocated--;
    }
}

void mem_pool_destroy(MemPool* pool) {
    free(pool->buffer);
    free(pool);
}

// Function to create and initialize item array
item* create_items(int num_items, char* input_string, size_t max_length, MemPool* mem_pool, FILE* log) {
    srand(time(NULL));
    item* items = mem_pool_acquire(mem_pool);
    if (!items) return NULL;

    for (int i = 0; i < num_items; ++i) {
        double random_value = (double)rand() / RAND_MAX * 100.0;
        size_t substring_length = rand() % max_length + 1;
        if (substring_length > strlen(input_string)) substring_length = strlen(input_string);

        char* name = mem_pool_acquire(mem_pool);
        if (!name) {
            free(items);
            return NULL;
        }
        strncpy(name, input_string + (input_string[i % strlen(input_string)] == '\0' ? rand() % strlen(input_string) : 0), substring_length);
        name[substring_length] = '\0';

        items[i].value = random_value;
        items[i].name = name;
    }

    return items;
}
```

