2. Dynamic Field Refresh in AngularJS:

```javascript
app.service('DynamicFieldService', function ($http, $q) {
    var queue = [],
        lastUpdated = {},
        timeout = 5000; // milliseconds

    this.refreshFields = function (resourceId, url, fieldNames) {
        if (!fieldNames || !fieldNames.length) return;

        for (var i = 0; i < fieldNames.length; i++) {
            var fieldName = fieldNames[i];
            if (lastUpdated[fieldName] && new Date() - lastUpdated[fieldName] < timeout) continue;

            queue.push({ resourceId: resourceId, url: url, fieldName: fieldName });
        }

        if (!queue.length) return $q.when();

        return $http.get(url).then(function (response) {
            for (var i = 0; i < queue.length; i++) {
                var data = response.data[queue[i].fieldName];
                lastUpdated[queue[i].fieldName] = new Date();
                parent.postMessage({ type: 'refresh', fieldName: queue[i].fieldName, data: data }, "*");
            }
            return queue.length;
        });
    };
});
