    if (!new_node) return;

    new_node->data = *data;
    new_node->next = head;
    head = new_node;

    memory_used++;

    if (memory_used > max_memory) {
        free(head);
        head = NULL;
        memory_used--;
    }
}

void* get_data(size_t index) {
    Node* current = head;
    for (size_t i = 0; i < index; i++) {
