    if ((*data)->keys == NULL) goto error; // Memory allocation error

    (*data)->records = calloc(records_capacity, sizeof(record));
    if ((*data)->records == NULL) goto error; // Memory allocation error

    (*data)->length = 0;
    (*data)->capacity = records_capacity;
    sem_init(&(*data)->sem, 0, 1);

    log_memory("Initialization", sizeof(struct data));
    return 0;

error:
    free((*data)->keys);
    free((*data)->records);
    munmap((*data)->offsets, offsets_capacity * sizeof(long));
    free(*data);
    return 1; // Memory allocation error
}

int add_record(struct data *data, int key, int value) {
    if (data->length >= data->capacity) {
        void *tmp_offsets = realloc((*data)->offsets, sizeof(long) * (data->capacity * 2));
        if (tmp_offsets == NULL) return 1; // Memory allocation error
        (*data)->offsets = tmp_offsets;

        record *tmp_records = realloc((*data)->records, sizeof(record) * (data->capacity * 2));
        if (tmp_records == NULL) {
            free((*data)->offsets);
            return 1; // Memory allocation error
        }
        (*data)->records = tmp_records;
        data->capacity *= 2;
    }

    sem_wait(&(data->sem));

    int index = data->length++;
    (*data->keys + index) = key;
    long *tmp_offset = (*data->offsets + index);

    // Ensure valid index in the 'long' array
    if (index >= data->capacity || *(tmp_offset - 1) > *tmp_offset) {
        sem_post(&(data->sem));
        return 2; // Invalid index error
    }

    (*data->records + index)->value = value;
    (*tmp_offset) = index;

    sem_post(&(data->sem));
    return 0;
}

