[' ```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <tbb/tbb.h>
#include <vector>
#include <map>
#include <atomic>
#include <mutex>
#include "UEContext.h" // Assuming UEContext structure is defined here
#include "NetworkConfig.h" // Assuming network configuration module interface

class DynamicUEList {
private:
    std::vector<UEContext> ueContexts;
    std::map<uint64_t, uint32_t> rntiMap;
    mutex rntiMutex;
    atomic_int capacity;
    NetworkConfig* networkConfig;
    pthread_mutex_t configMutex;

public:
    DynamicUEList(NetworkConfig* netConfig) : networkConfig(netConfig), capacity(0) {
        pthread_mutex_init(&configMutex, NULL);
    }

    ~DynamicUEList() {
        clear();
        pthread_mutex_destroy(&configMutex);
    }

    void initialize(size_t initialCapacity) {
        if (initialCapacity > 0) {
            capacity.store(initialCapacity);
            ueContexts.reserve(initialCapacity);
        }
    }

    UEContext* addUEContext(const UEID& id, const RNTI& rnti, CRCStatus crcStatus) {
        if (findUEContextByRNTI(rnti)) {
            throw std::invalid_argument("RNTI already exists");
        }

        UEContext context{id, rnti, crcStatus};
        ueContexts.push_back(context);
        rntiMap[rnti] = ueContexts.size() - 1;
        return &ueContexts.back();
    }

    UEContext* findUEContextById(const UEID& id) const {
        for (auto& context : ueContexts) {
            if (context.id == id) {
                return &context;
            }
        }
        return nullptr;
    }

    bool findUEContextByRNTI(const RNTI& rnti) const {
        std::unique_lock<std::mutex> lock(rntiMutex);
        auto iter = rntiMap.find(rnti);
        if (iter != rntiMap.end()) {
            return true;
        }
        lock.unlock();

        for (const UEContext& context : ueContexts) {
            if (context.rnti == rnti) {
                return true;
            }
        }
        return false;
    }

    void clear() {
        ueContexts.clear();
        rntiMap.clear();
        capacity = 0;
    }

    size_t size() const {
        return ueContexts.size();
    }

    // Synchronized access to network configuration for multi-threading
    NetworkConfig* getNetworkConfig() {
        std::unique_lock<std::mutex> lock(configMutex);
        return networkConfig;
    }
};
```
