```cpp
#include <iostream>
#include <vector>
#include <random>
#include <memory>
#include <mutex>
#include <boost/log/trivial.hpp>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class Allocator {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    size_t max_size;
    int batch_size;
    unsigned seed;
    std::mutex mtx;
    bool failed = false;

public:
    Allocator(size_t maxSize, int logLevel, unsigned seed) : max_size(maxSize), batch_size(std::min(max_size, 100)), seed(seed) {
        if (logLevel > BOOST_LOG_TRIVIAL_INFO) {
            BOOST_LOG_TRIVIAL(info) << "Allocator initialized with max_size: " << max_size << ", batch_size: " << batch_size << ", seed: " << seed;
        }
    }

    void allocate() {
        std::unique_lock<std::mutex> lock(mtx);
        if (failed) {
            return;
        }

        for (int i = 0; i < batch_size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = new NFAPI_CRC_INDICATION_PDU_T();
            data.emplace_back(pdu);
            pdu->rnti = rand() % 10000;
            pdu->crc_indication.crcflag = rand() % 2;
        }

        if (data.size() == max_size) {
            failed = false;
            BOOST_LOG_TRIVIAL(info) << "Successfully allocated: " << data.size();
        } else {
            failed = true;
            batch_size *= 2;
            allocate();
        }
    }

    ~Allocator() {
        for (auto& pdu : data) {
            delete pdu.get();
        }
    }
};
```

You can use the Allocator class like this:

