    unsigned seed = (argc > 1) ? atoi(argv[1]) : std::random_device{}();
    Allocator allocator(10000, BOOST_LOG_TRIVIAL_INFO, seed);
    for (int i = 0; i < 5; ++i) {
        allocator.allocate();
    }
    return 0;
}
