// Custom UEContext structure
typedef struct {
    unsigned long UEID;
    unsigned long RNTI;
    enum CRCStatus { PASS, FAIL } CRC;
} UEContext;

// Global variables
static sem_t semaphore;
static UEContext* contexts = NULL;
static size_t capacity = 0;
static size_t count = 0;
static bool external_source_available = false;

// Custom comparator for qsort function to ensure uniqueness of RNTI values
static int compare_RTNIs(const void* a, const void* b) {
    return (*((UEContext*)a)->RNTI - *((UEContext*)b)->RNTI);
}

// Function to initialize the dynamic array and semaphore
void init_contexts(size_t initial_capacity) {
    capacity = initial_capacity;
    count = 0;
    contexts = malloc(initial_capacity * sizeof(UEContext));
    if (!contexts) {
        fprintf(stderr, "Failed to allocate memory for context array\n");
        exit(EXIT_FAILURE);
    }
    sem_init(&semaphore, 0, initial_capacity);
}

// Function to populate the dynamic array with new UEContext instances
void add_context(unsigned long UEID, unsigned long RNTI) {
    if (count == capacity) {
        capacity *= 2;
        contexts = realloc(contexts, capacity * sizeof(UEContext));
        if (!contexts) {
            fprintf(stderr, "Failed to resize memory for context array\n");
            exit(EXIT_FAILURE);
        }
    }
    sem_wait(&semaphore);
    UEContext* ctx = &contexts[count];
    ctx->UEID = UEID;
    ctx->RNTI = RNTI;
    ctx->CRC = PASS; // Assume CRC is initially pass until it's calculated

    // Check for uniqueness of RNTI values
    if (count > 1) {
        qsort(contexts, count, sizeof(UEContext), compare_RTNIs);
        int i;
        for (i = 0; i < count - 1; ++i) {
            if (contexts[i].RNTI == ctx->RNTI) {
                // Handle error condition - RNTI is not unique
                fprintf(stderr, "Error: RNTI %ld already exists in context array\n", RNTI);
                sem_post(&semaphore);
                free(contexts + i);
                memmove(contexts + i, contexts + i + 1, (count - i - 1) * sizeof(UEContext));
                --count;
                break;
            }
        }
    }

    ++count;
    sem_post(&semaphore);
}

// Cleanup function to deallocate memory when the program terminates or contexts array is no longer needed
void free_contexts() {
    if (contexts) {
        free(contexts);
        contexts = NULL;
        capacity = 0;
        count = 0;
        sem_destroy(&semaphore);
    }
}
