class UEContextManager {
public:
    explicit UEContextManager(size_t num_threads) {
        // Initialize concurrent hash table and forward list
        // ...
    }

    boost::container::optional<UEContext*> InsertUEContext(const UEContext& ctx) {
        RNTI rnti = ctx.GetRNTI();

        auto it = contexts_.find(rnti);
        if (it != contexts_.end()) {
            // Found an existing context, update its CRCStatus if necessary
            (*it).second->SetCRCStatus(ctx.GetCRCStatus());
            return *it;
        }

        UEContext new_context(ctx);
        RNTI_VALIDATION(new_context.GetRNTI())

        contexts_.emplace_after(*it, std::move(new_context)); // Insert new_context after it
        return *it;
    }

private:
    using ContextContainer = boost::container::flat_map<RNTI, boost::container::shared_ptr<UEContext>>;
    ContextContainer contexts_;
};
