typedef struct {
    int key;
    long offset;
    char *buffer;
} record;

void generate_keyed_record(record **records, size_t *num_records, size_t max_offset, size_t max_buffer) {
    if (!(*records = realloc(*records, sizeof(record) * (*num_records + 1)))) {
        perror("Memory allocation failed");
        return;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = *num_records; i < (*num_records + 1); ++i) {
        (*records)[i].key = i + 1;
        (*records)[i].offset = rand() % (max_offset + 1);
        if (!((*records)[i].buffer = malloc(max_buffer))) {
            perror("Memory allocation failed");
            return;
        }
        memset((*records)[i].buffer, 0, max_buffer);
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_setdeferrable(&mutex);
    pthread_mutex_init(&mutex, &attr);
}

void destroy_record(record *record) {
