        capacity = max_records / 10;
        records = malloc(capacity * sizeof(Record));
    }
}

void cleanup() {
    free(records);
    capacity = 0;
    num_records = 0;
}

int get_num_records() {
    pthread_mutex_lock(&lock);
    int temp = num_records;
    pthread_mutex_unlock(&lock);
    return temp;
}

Record* allocate_record() {
    if (capacity == 0) init();

    Record *new_record = &records[num_records];
    new_record->offset = num_records;
    new_record->key = -1; // placeholder value
    new_record->value = rand() % 100 + 1;
    num_records++;

    if (get_free_percent() < min_free_percent) {
        compress();
    }

    return new_record;
}

void deallocate_record(Record* record) {
    pthread_mutex_lock(&lock);

    if (record->key != -1) {
        int i;
        for (i = record->offset + 1; i < num_records; ++i) {
            records[i - 1] = records[i];
        }
        num_records--;
    }

    pthread_mutex_unlock(&lock);
}

int get_free_percent() {
