void trimString(char* str, size_t maxLength) {
    if (str && maxLength > 0) {
        char *end;
        size_t len = strlen(str);
        if (len > maxLength)
            len = maxLength - 1;
        end = &str[len];
        *end = '\0';
    }
}

char* generateFilename(const char* base, const char* extension) {
    size_t baseLength = strlen(base);
    size_t pathLength = MAX_FILENAME_LENGTH - (baseLength + EXTENSION_LENGTH);
    size_t dirLength = 0;
    if (pathLength > 0) {
        char path[pathLength];
        snprintf(path, pathLength, "/%.*s", pathLength, base);
        trimString(path, pathLength);
        dirLength = strlen(path);
    }

    char* filename = malloc(MAX_FILENAME_LENGTH + 1);
    if (filename) {
        size_t extIndex = baseLength + dirLength;
        snprintf(filename, EXTENSION_LENGTH, "%s", extension);
        memcpy(&filename[extIndex], filename, EXTENSION_LENGTH);
        trimString(filename, MAX_FILENAME_LENGTH);
    }
    return filename;
}

