        for (size_t i = 0; i < size; ++i) {
            records[i].key = keys[i];
            records[i].offset = offsets[i];
            records[i].ref_count = 0;
            pthread_mutex_init(&records[i].mutex, NULL);
        }
    }
    return records;
}

void shuffle(Record* records, size_t size) {
