}

char* allocateFilename(const char* filename, size_t maxMemory) {
    char* optimizedName = generateFilename(filename, "txt");
    if (optimizedName && strlen(optimizedName) + 1 > MAX_FILENAME_LENGTH) {
        time_t timestamp = time(NULL);
        int counter = 0;
        do {
            char temp[MAX_FILENAME_LENGTH];
            snprintf(temp, sizeof(temp), "%s%ld%d.txt", optimizedName, timestamp, ++counter);
            trimString(temp, MAX_FILENAME_LENGTH);
            free(optimizedName);
            optimizedName = generateFilename(temp, NULL);
        } while (strlen(optimizedName) + 1 > MAX_FILENAME_LENGTH);
    }
    return optimizedName;
}

void deallocateMemory(Record* records, long* offsets, int* keys, char* filename) {
