    private readonly ResourceBundle _resourceBundle;
    private readonly List<NFAPI_CRC_INDICATION_PDU_T> _eventLog = new();
    private readonly SortedSet<ulong> _timestampSet = new();
    private readonly Random _random;

    public EventLogProcessor()
    {
        _resourceBundle = LoadResourceBundle();
        _random = new System.Security.Cryptography.RNGCryptoServiceProvider();
    }

    private ResourceBundle LoadResourceBundle()
    {
        // Load resource bundle from binary file or external data source
        // ...
    }

    public void ProcessEventLog(byte[] eventData)
    {
        if (eventData == null || eventData.Length == 0)
            return;

        var events = DeserializeEvents(eventData);

        foreach (var @event in events)
        {
            if (_timestampSet.Contains(@event.Timestamp))
                LogDuplicateTimestamp(@event.Timestamp);

            _timestampSet.Add(@event.Timestamp);
            _eventLog.Add(@event);
        }
    }

    private IEnumerable<NFAPI_CRC_INDICATION_PDU_T> DeserializeEvents(byte[] data)
    {
        var buffer = new Span<NFAPI_CRC_INDICATION_PDU_T>(data);
        for (int i = 0; i < data.Length / sizeof(ulong); i++)
            yield return buffer[i];
    }

    private void LogDuplicateTimestamp(ulong timestamp)
    {
        // Log the duplicate timestamp event to a file or external service
        Console.WriteLine($"Duplicate timestamp detected: {timestamp}");
    }

    public void Cleanup()
    {
        foreach (var item in _resourceBundle.Items)
            GC.SuppressFinalize(item);

        GC.SuppressFinalize(_resourceBundle);
    }
}
