#include <iostream>
#include <algorithm>
#include <random>
#include <vector>
#include <string>
#include <unordered_map>

// Record structure definition
struct Record {
    long* offset = nullptr;
    int key = 0;
    char name[16];
};

class DataManager {
private:
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
    std::unordered_map<int, Record*> keyToRecord;
    int nextKey = 1;

public:
    DataManager(int n, int m) {
        offsets.resize(n, 0);
        keys.resize(m);
        for (auto& k : keys) k = nextKey++;
        records.resize(n);

        // Initialize record structures with random keys and empty names
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 100);
        for (auto& rec : records) {
            rec.key = dis(gen);
            std::fill(rec.name, rec.name + sizeof(rec.name), '\0');
        }
    }

    Record* getRecordByKey(int key) {
        auto it = keyToRecord.find(key);
        if (it == keyToRecord.end()) return nullptr;
        return it->second;
    }

    void setOffsetForRecord(Record* rec, long offset) {
        rec->offset = &offset;
        keyToRecord[rec->key] = rec;
    }

    void printAllRecords() const {
        for (const auto& rec : records) {
            if (!rec.offset) continue;
            std::cout << "Key: " << rec.key << ", Offset: " << *rec.offset << ", Name: " << rec.name << '\n';
        }
    }

    ~DataManager() {
        for (auto& rec : records) delete[] rec.name;
    }
};
```

