#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    size_t memory_usage;
    double cpu_utilization;
    // Error recovery strategies...
} config;

typedef struct list_node {
    config data;
    struct list_node *next;
} list_node;

struct adaptive_list {
    semaphore_t lock;
    size_t capacity;
    size_t length;
    list_node *head;
    list_node *tail;
};

adaptive_list create_list(size_t initial_capacity) {
    adaptive_list list = malloc(sizeof(struct adaptive_list));
    list->lock = sem_init(0, 1, 1);
    list->capacity = initial_capacity;
    list->length = 0;
    list->head = NULL;
    list->tail = NULL;
    return list;
}

void resize(adaptive_list list) {
    // Determine new capacity based on operational metrics...
    list_node* temp_list = malloc((list->capacity * 2) * sizeof(struct list_node));
    if (temp_list == NULL) return;

    size_t old_length = list->length;
    list->capacity *= 2;

    list_node* new_head = temp_list;
    list_node* current = temp_list;
    sem_wait(&(list->lock));
    if (old_length > 0) {
        current->next = list->head;
        list->head = temp_list;
    } else {
        list->head = temp_list;
    }
    list->tail = temp_list + old_length;
    sem_post(&(list->lock));
}

void push_back(adaptive_list list, config data) {
    sem_wait(&(list->lock));
    if (list->length == list->capacity) resize(list);
    if (list->tail != NULL) list->tail->next = malloc(sizeof(struct list_node));
    else list->head = malloc(sizeof(struct list_node));
    if (list->tail != NULL) list->tail = list->tail->next;
    else list->tail = list->head;
    list->tail->next = NULL;
    list->tail->data = data;
    list->length++;
    sem_post(&(list->lock));
}

config pop_front(adaptive_list list) {
    config data;
    sem_wait(&(list->lock));
    if (list->head != NULL) {
        data = list->head->data;
        list->head = list->head->next;
        if (list->head == NULL) list->tail = NULL;
        list->length--;
    }
    sem_post(&(list->lock));
    return data;
}
