int initialize_dyna_array(NFAPI_CRC_INDICATION_PDU_T** arr, size_t N, uint32_t min_RNTI, uint32_t max_RNTI, size_t mem_limit) {
    Node **head = (Node**)malloc(sizeof(Node*) * mem_limit);
    if (!head) return -1;

    for (size_t i = 0; i < mem_limit; ++i) head[i] = NULL;

    size_t index = 0, alloc_count = 0;
    srand(time(NULL));

    while (alloc_count < N && index < mem_limit) {
        uint32_t RNTI = min_RNTI + index++;
        bool rnti_found = false;

        for (Node *cur = head[RNTI % mem_limit]; cur != NULL; cur = cur->next) {
            if (cur->data.RNTI == RNTI) {
                rnti_found = true;
                break;
            }
        }

        if (!rnti_found) {
            Node *new_node = (Node*)malloc(sizeof(Node));
            if (!new_node) return -1;

            new_node->data.RX_UE_INFORMATION_TAG = rand() % 0xFFFF;
            new_node->data.RNTI = RNTI;
            new_node->data.CRC_INDICATION_REL8_TAG = (rand() & 1) + ((rand() >> 1) & 0x7F);
            new_node->data.CRCFLAG = rand() % 2;
            new_node->next = head[RNTI % mem_limit];
            head[RNTI % mem_limit] = new_node;

            alloc_count++;
        }
    }

    if (alloc_count < N) {
        // Reallocate memory and continue until all elements are allocated
        size_t new_mem_limit = mem_limit * 2;
        Node **new_head = (Node**)realloc(head, sizeof(Node*) * new_mem_limit);
        if (!new_head) return -1;

        for (size_t i = mem_limit; i < new_mem_limit; ++i) head[i] = NULL;

        size_t index = 0, alloc_count_temp = alloc_count;
        srand(time(NULL));

        while (alloc_count < N && index < new_mem_limit) {
            // ... Continue the same logic as before, but with new_head and new_mem_limit instead of head and mem_limit
        }
    }

    *arr = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*arr) return -1;

    size_t index = 0;
    for (Node *cur = head[0]; cur != NULL; cur = cur->next, ++index) {
        (*arr + index)->RX_UE_INFORMATION_TAG = cur->data.RX_UE_INFORMATION_TAG;
        (*arr + index)->RNTI = cur->data.RNTI;
        (*arr + index)->CRC_INDICATION_REL8_TAG = cur->data.CRC_INDICATION_REL8_TAG;
        (*arr + index)->CRCFLAG = cur->data.CRCFLAG;
    }

    free(head);
    return alloc_count;
}
