typedef struct {
    int key;
    double value;
    char data[50];
} Record;

// Maximum number of records and peak memory usage will be tracked globally
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int max_records = 0;
size_t peak_memory = 0;

bool add_record(Record **data, size_t *memory_usage, int key, double value, const char *data_) {
    if (*memory_usage + sizeof(Record) + strlen(data_) > MAX_MEMORY || strlen(data_) > 20) {
        return false;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        return false;
    }

    new_record->key = key;
    new_record->value = value;
    strncpy(new_record->data, data_, 50);
    new_record->data[50] = '\0'; // Ensure null termination

    pthread_mutex_lock(&mutex);
    if (max_records < INT_MAX) {
        (*data)[max_records++] = new_record;
    } else {
        free(new_record);
    }
    peak_memory = *memory_usage + sizeof(Record) + strlen(data_);
    pthread_mutex_unlock(&mutex);

    if (fabs(value) > MAX_DOUBLE) {
        fprintf(stderr, "Error: Value exceeds the threshold\n");
        return false;
    }

    return true;
}

// Thread-safe serialization function using pthread_mutex_lock() and a helper function to recursively serialize the data structure
void serialize(Record *data, FILE *fp) {
    if (!data) {
        return;
    }

    pthread_mutex_lock(&mutex);
    size_t index = 0;
    for (int i = 0; i < max_records; ++i) {
        if (data[i]) {
            fprintf(fp, "Record %ld:\n", index++);
            fprintf(fp, "  key: %d\n", data[i]->key);
            fprintf(fp, "  value: %.2f\n", data[i]->value);
            fprintf(fp, "  data: %s\n", data[i]->data);
        }
    }
    pthread_mutex_unlock(&mutex);
}

