    Record *record;
    HashKey hash;
    struct HTEntry *next;
};

const int RECORD_CAPACITY = 10;
const float LOAD_FACTOR = 0.75f;
const int ID_RANGE = 1000;

HashKey hashFunction(int key) {
    return (HashKey)(key % strlen(key) * strlen(key) + hash(key, strlen(key)));
}

unsigned int hash(char *str, int len) {
    unsigned long h = 5381;
    for (int i = 0; i < len; ++i)
        h = ((h << 5) + h) + str[i];
    return h % INT_MAX;
}

void resizeHashTable(struct HTEntry **table) {
    const int newSize = *table ? (*table)->size * 2 : RECORD_CAPACITY;
    struct HTEntry **newTable = malloc(newSize * sizeof(struct HTEntry*));
    memset(newTable, 0, newSize * sizeof(struct HTEntry*));

    for (int i = 0; i < newSize; ++i) {
        struct HTEntry *entry = &(*table)[i];
        if (entry && entry->next) {
            int j = i;
            struct HTEntry *temp = entry->next;
            while (temp) {
                struct HTEntry *nextTemp = temp->next;
                newTable[j % newSize] = temp;
                j++;
                temp = nextTemp;
            }
        }
    }

    free(*table);
    *table = newTable;
}

