            updatePriority(record);
            return current;
        }

        if (current->hash == hashFunction(record->identifier)) {
            index = (index + 1) % (*table)->size;
            entry = &((*table)[index]);
            current = entry->next;
        } else {
            current = NULL;
        }
    }

    resizeHashTable(table);
    return findOrInsert(table, record);
}

