#define MAX_MEMORY_USAGE // Define this macro to set the maximum memory usage limit

typedef struct Record {
    int key;
    long *offset;
    int *value;
    struct Record *next;
} Record;

struct DataSource {
    void (*update)(Record *, const void *); // Function pointer to update a record with new data
};

static Record *head = NULL;
static Record **tail = &head;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static sem_t resize_sem = SEM_INITIALIZER(1);
static size_t total_memory = 0;
static struct DataSource data_source;

void init_linked_list() {
    // Initialize the data source function pointer
    data_source.update = NULL;
}

void set_data_source(void (*update)(Record *, const void *)) {
    data_source.update = update;
}

void *long_array = NULL; // Dynamically allocated long array for offsets
void *int_key_array = NULL; // Dynamically allocated int array for keys
void *record_array = NULL; // Dynamically allocated memory for record structures
size_t num_records = 0; // Number of records currently in use

// Function to allocate more memory if needed, handling memory allocation failures gracefully
void resize_memory() {
    if (total_memory + (sizeof(Record) * (MAX_MEMORY_USAGE - num_records)) > MAX_MEMORY_USAGE) {
        // Reduce the size of the arrays to fit within the limit while preserving as much data as possible
        if (long_array != NULL) free(long_array);
        if (int_key_array != NULL) free(int_key_array);
        if (record_array != NULL) free(record_array);

        num_records = 0;

        long_array = mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (long_array == MAP_FAILED) {
            perror("mmap failed for long_array");
            return;
        }

        int_key_array = mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (int_key_array == MAP_FAILED) {
            perror("mmap failed for int_key_array");
            free(long_array);
            return;
        }

        record_array = mmap(NULL, sizeof(Record) * MAX_MEMORY_USAGE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (record_array == MAP_FAILED) {
            perror("mmap failed for record_array");
            free(long_array);
            free(int_key_array);
            return;
        }
    } else {
        // Allocate more memory without reducing the current size
        long *new_longs = realloc(long_array, sizeof(long) * (num_records + MAX_MEMORY_USAGE - num_records));
        if (!new_longs) {
            perror("realloc failed for long_array");
            return;
        }
        long_array = new_longs;

        int *new_keys = realloc(int_key_array, sizeof(int) * (num_records + MAX_MEMORY_USAGE - num_records));
        if (!new_keys) {
            perror("realloc failed for int_key_array");
            free(long_array);
            return;
        }
        int_key_array = new_keys;

        Record *new_records = realloc(record_array, sizeof(Record) * (num_records + MAX_MEMORY_USAGE - num_records));
        if (!new_records) {
            perror("realloc failed for record_array");
            free(long_array);
            free(int_key_array);
            return;
        }
        record_array = new_records;
    }

    total_memory += sizeof(Record) * MAX_MEMORY_USAGE - sizeof(Record) * num_records;
}

void insert_record(int key, long offset) {
    pthread_mutex_lock(&list_mutex);

    Record *new_record = (Record *)((char *)record_array + num_records++ * sizeof(Record));
    new_record->key = key;
    new_record->offset = long_array + total_memory - num_records * sizeof(long);
    new_record->value = int_key_array + total_memory - num_records * sizeof(int);
    new_record->next = NULL;

    if (*tail) {
        (*tail)->next = new_record;
        tail = &((*tail)->next);
    } else {
        head = new_record;
        tail = &head;
    }

    pthread_mutex_unlock(&list_mutex);

    if (data_source.update) {
        data_source.update(new_record, NULL);
    }
}

Record *find_record(int key) {
    Record *current = head;

    pthread_mutex_lock(&list_mutex);
    while (current != NULL) {
        if (current->key == key) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);

    return current;
}

void delete_record(int key) {
    Record *current = head;
    Record **previous = &head;

    pthread_mutex_lock(&list_mutex);
    while (current != NULL) {
        if (current->key == key) {
            *previous = current->next;
            break;
        }
        previous = &current->next;
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);

    if (current != NULL && data_source.update) {
        data_source.update(current, NULL);
    }

    free(current);
    num_records--;
}

