        block->free = block_size;
        block->data = malloc(block_size);
    }
}

void *mem_malloc(struct mem_manager *manager, size_t size) {
    if (size > manager->blocks[manager->current_index].free) {
        ++manager->current_index %= manager->num_blocks;
    }

    struct mem_block *block = &manager->blocks[manager->current_index];

    if (size <= block->free) {
        void *ptr = block->data + block->used;
        block->used += size;
        block->free -= size;
        return ptr;
    } else {
        // Handle memory allocation failure gracefully
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void mem_log_usage() {
    // Log memory usage to a file or system log
}

void *compress(const void *src, size_t src_size, size_t *dest_size) {
    gzInputStream gz_input = gzopen_memstream((const char*) src, src_size);
    gzFile gz_file = gzdopen(gz_input, "wb");

    // Compress data and write to dest_ptr
    void *dest_ptr = malloc(*dest_size);
    size_t written = gzwwrite(gz_file, dest_ptr, *dest_size);
    fclose(gz_file);
    gzclose(gz_input);

    *dest_size = written;
    return dest_ptr;
}

void serialize_and_write(const char *filename, const void *data, size_t size) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    write(fd, data, size);
    close(fd);

    // Compress and write the serialized data to disk
    void *compressed = compress(data, size, NULL);
    size_t compressed_size;
    write(fd, compressed, size);
    free(compressed);
}

void deserialize(const char *filename, void **data, size_t *size) {
    int fd = open(filename, O_RDONLY);
    struct stat file_stat;
    fstat(fd, &file_stat);

    // Decompress and read the data from disk
    off_t filesize = file_stat.st_size;
    void *buffer = malloc(filesize);
    read(fd, buffer, filesize);
    close(fd);

    gzFile gz_file = gzdopen(fdopen(filename, "rb"), "r");
    void *decompressed = gzread(gz_file, size);
    fclose(gz_file);

    // Validate data integrity and check for malformed input formats
    if (memcmp(buffer, decompressed, *size) != 0 || *size > filesize - sizeof(gzFile)) {
        fprintf(stderr, "Data corruption detected\n");
        exit(1);
    }

    *data = malloc(*size);
    memcpy(*data, decompressed, *size);
    free(buffer);
}

void create_pdus(DMAE_EVENT_RECORD **event_records, size_t num_events) {
    for (size_t i = 0; i < num_events; ++i) {
