int init_dynamic_array(PHY_RX_CONTEXT_T** array, size_t M, PHY_RX_BUFFER_T* buffer_pool, PHY_RX_QCI_T* qci_pool, unsigned int min_id, unsigned int max_id) {
    if (!array || !buffer_pool || !qci_pool)
        return -1;

    *array = calloc(M, sizeof(PHY_RX_CONTEXT_T));
    if (!*array)
        return -1;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

