    PHY_RX_BUFFER_T* buffer_batch;
    PHY_RX_QCI_T* qci_batch;

    for (size_t i = 0; i < batches; ++i) {
        if (!(buffer_batch = calloc(batch_size, sizeof(PHY_RX_BUFFER_T)))) {
            free(*array);
            return -1;
        }
        if (!(qci_batch = calloc(batch_size, sizeof(PHY_RX_QCI_T)))) {
            free(buffer_batch);
            free(*array);
            return -1;
