#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <semaphore.h>

#define MAX_ELEMENTS 10000
#define STRING_DELIMITER "/"
#define MAX_STRING_LENGTH 256
#define LOG_FILE_PATH "log.txt"
#define BUFFER_SIZE 4096
#define FLUSH_INTERVAL 1000

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

struct list {
    struct list_node* head;
    struct list_node* tail;
    int elements;
    int failed_duplicates;
    pthread_mutex_t mutex;
    sem_t space, items;
};

struct log_entry {
    time_t timestamp;
    char msg[MAX_STRING_LENGTH];
};

void* log_flush(void* arg) {
    struct log_entry entries[BUFFER_SIZE];
    int num_entries = 0, fd, i;
    while (1) {
        sem_wait(&((struct list*)arg)->items);
        pthread_mutex_lock(&((struct list*)arg)->mutex);
        for (i = 0; i < BUFFER_SIZE && ((struct list*)arg)->head != NULL; ++i) {
            entries[num_entries++] = ((struct list_node*)((struct list*)arg)->head)->data;
            ((struct list*)arg)->head = ((struct list*)arg)->head->next;
        }
        pthread_mutex_unlock(&((struct list*)arg)->mutex);
        sem_post(&((struct list*)arg)->space);

        if (num_entries > 0) {
            fd = open(LOG_FILE_PATH, O_WRONLY | O_APPEND | O_CREAT | O_SYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
            write(fd, &num_entries, sizeof(int));
            for (i = 0; i < num_entries; ++i) {
                write(fd, &(entries[i].timestamp), sizeof(time_t));
                write(fd, entries[i].msg, strlen(entries[i].msg));
            }
            close(fd);
        }
        usleep(FLUSH_INTERVAL * 1000);
    }
    return NULL;
}

void* insert(struct list* list, char* input, size_t size, bool enforceStrictLength, int maxDelay) {
    // Create dynamically allocated string with delimiter only if input string meets length requirements
    char* dataString = malloc((strlen(input) + 1 + (enforceStrictLength ? 1 : 0)) * sizeof(char));
    if (dataString == NULL || strlen(input) + (enforceStrictLength ? 1 : 0) > size) {
        free(dataString);
        return NULL;
    }
    strcpy(dataString, input);
    if (enforceStrictLength && strlen(input) >= size) {
        free(dataString);
        return NULL;
    } else if (!enforceStrictLength && strlen(input) + 1 >= size) {
        free(dataString);
        return NULL;
    }
    strcat(dataString, STRING_DELIMITER);

    struct list_node* newNode = malloc(sizeof(struct list_node));
    if (newNode == NULL) {
        free(dataString);
        return NULL;
    }
    memcpy(&(newNode->data), dataString, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(dataString);

    pthread_mutex_lock(&list->mutex);
    sem_wait(&list->space);

    // Check for unique RNTI and set CRCFLAG randomly
    bool unique = true;
    struct list_node* currentNode = list->head;
    while (currentNode != NULL) {
        if (currentNode->data.rnti == newNode->data.rnti) {
            list->failed_duplicates++;
            unique = false;
            break;
        }
        currentNode = currentNode->next;
    }

    if (unique) {
        list->elements++;

        // Resize the list dynamically if required
        if (list->elements > MAX_ELEMENTS * 2 / 3) {
            struct list_node** newArray = realloc(list->head, sizeof(struct list_node) * (MAX_ELEMENTS * 2));
            if (newArray == NULL) {
                pthread_mutex_unlock(&list->mutex);
                sem_post(&list->space);
                return NULL;
            }
            list->head = newArray;
            MAX_ELEMENTS *= 2;
        }

        // Insert the new node at the end of the list
        if (list->tail == NULL) {
            list->tail = newNode;
            list->head = newNode;
        } else {
            list->tail->next = newNode;
            list->tail = newNode;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    sem_post(&list->items);

    return &newNode->data;
}
