    total_allocated += snprintf(new_filename, 100, "%s%.*s_%ld_%d.%s", dir_path, (int)(dir_path_len + base_name_len + extension_len), base_name, time(&timestamp), file_type++, file_type == 1 ? "txt" : file_type == 2 ? "csv" : "log");

