#include <cassert>
#include <dom/minidom.h> // Include your preferred DOM library here

namespace {
    boost::mt19937_64 prng;
}

class StringManipulator {
public:
    StringManipulator() : prng(std::random_device{}()) {}
    ~StringManipulator() = default;

    std::string trimAndAppendSlash(const std::string& str, size_t limit) const {
        if (str.length() >= limit) return nullptr;

        std::regex prohibited("[-/\\\\|:*;<>,?\"{}()[]$@!%#^~`+=");
        auto sanitized = std::regex_replace(str, prohibited, "");
        return sanitized + "/";
    }

    void traverseDOM(const minidom::Node* root, const std::string& selector, std::function<void(minidom::Node*)> callback) {
        boost::mutex mtx;
        std::vector<minidom::Node*> elements;
        std::deque<minidom::Node*> queue;
        queue.push_back(root);

        while (!queue.empty()) {
            auto node = queue.front();
            queue.pop_front();

            if (node->hasAttr("class")) {
                const std::string& className = node->getAttr("class");
                if (std::regex_match(className, std::regex(selector))) {
                    elements.push_back(node);
                    callback(node);
                }
            }

            for (auto child : *node) {
                queue.push_back(&*child);
            }
        }

        boost::mutex::scoped_lock lock(mtx);
        elements.erase(std::remove_if(elements.begin(), elements.end(), [](const auto& node) {
            return !node;
        }), elements.end());
    }

    std::string generateRandomString(size_t length) const {
        std::string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()";
        std::stringstream ss;
        boost::random::shuffle_order<decltype(prng)> shuffle(prng);
        boost::random::uniform_int_distribution<> dist(0, chars.size() - 1);

        for (size_t i = 0; i < length; ++i) {
            ss << chars[shuffle(prng, dist)];
        }
        return ss.str();
    }

private:
    static boost::mt19937_64& getRandomGenerator() {
        static boost::mt19937_64 generator;
        return generator;
    }
};
