void *parseAndValidateEmail(const char *email) {
    regfree(&emailRegex);
    regcomp(&emailRegex, (char*)emailRegexPattern, REG_EXTENDED | REG_NEWLINE);

    if (regexec(&emailRegex, email, match) == 0) {
        ++emailCount;
        return (void*)email;
    }

    free((void*)email);
    return NULL;
}

void* parseAndValidateEmails(const char *input, size_t maxEmails) {
    char *tokens[128], *token = strtok(const_cast<char*>(input), ",");
    size_t numTokens = 0;

    pthread_t threads[maxEmails];
    void **validEmails = (void**)malloc(sizeof(void*) * maxEmails);

    while (token) {
        validEmails[numTokens] = parseAndValidateEmail(token);
        if (!validEmails[numTokens]) {
            // Handle memory allocation failures and return NULL
            for (size_t i = 0; i < numTokens; ++i) free(validEmails[i]);
            free(validEmails);
            return NULL;
        }
        if (++numTokens == maxEmails) break;
        token = strtok(NULL, ",");
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    for (size_t i = 0; i < numTokens; ++i) {
        pthread_create(&threads[i], &attr, parseAndValidateEmail, validEmails[i]);
    }

    emailCount = numTokens;
    for (size_t i = 0; i < numTokens; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Filter and sort the valid emails array here
    validEmails = realloc(validEmails, sizeof(void*) * emailCount);

    return (void*)validEmails;
}
