```python
import json, sys, collections
from jsonschema import Validator, Draft7Validator
from warnings import filterwarnings

def filterAndAggregateData(filepath, age_range=(18, 60), locations=None):
    with open(filepath, 'r') as f:
        data = json.load(f)

    validator = Draft7Validator.format(data[0])
    for profile in data:
        try:
            validator.validate(profile)
        except Exception as e:
            continue

    filtered_data = [profile for profile in data if (18 <= int(profile['age']) <= 60)]

    if locations:
        location_filtered_data = [profile for profile in filtered_data if profile['location'] == locations]
        result = collections.defaultdict(int)
        for profile in location_filtered_data:
            result[profile['location']] += 1
    else:
        result = collections.defaultdict(int)
        for profile in filtered_data:
            result[profile['location']] += 1

    return dict(result)
```']

