    std::thread maintenanceThread;

public:
    InterfaceListManager(const std::function<double()>& congestionCallback)
        : congestionCallback(congestionCallback) {}

    void addConfig(const NetworkInterfaceConfig& config) {
        std::unique_lock<std::mutex> lock(listMutex);
        list.push_back(config);
        lock.unlock();
    }

    void resizeList() {
        // Implement resizing logic based on network load metrics
    }

    NetworkInterfaceConfig getConfigWithHighestPriority() {
        std::unique_lock<std::mutex> lock(listMutex);
        if (!queue.empty()) {
            auto front = queue.front();
            lock.unlock();
            return front;
        }
        auto highestPriorityConfig = std::max_element(list.begin(), list.end(),
                                                      [](const NetworkInterfaceConfig& a, const NetworkInterfaceConfig& b) {
                                                          return congestionCallback() * a.qosLevel > congestionCallback() * b.qosLevel;
                                                      });
        if (highestPriorityConfig != list.end()) {
            lock.unlock();
            queue.push_back(*highestPriorityConfig);
            return *highestPriorityConfig;
        }
        throw std::runtime_error("No config with higher priority found");
    }

    void startMaintenance() {
        maintenanceThread = std::thread(&InterfaceListManager::maintenanceTask, this);
    }

    void stopMaintenance() {
        running = false;
        if (maintenanceThread.joinable())
            maintenanceThread.join();
    }

private:
