static char processed_filepath[PATH_MAX]; // Static buffer for the new file name

char* process_file_path(const char* filePath, int maxSize, const char* fileExtension) {
    if (!filePath || !*filePath) return NULL;

    size_t filePathLength = strlen(filePath);
    size_t extensionIndex = filePathLength - 1;

    // Check if there's an extension and it matches the given one
    while (extensionIndex > 0 && filePath[extensionIndex] == '.') {
        if (!strcmp(&filePath[extensionIndex], fileExtension)) break;
        extensionIndex--;
    }

    // If the given extension does not match, ignore it
    if (extensionIndex > 0 && !strcmp(&filePath[extensionIndex], fileExtension)) {
        extensionIndex++;
    }

    // Truncate the file path if necessary
    if ((filePathLength - extensionIndex) + strlen(fileExtension) > maxSize) {
        filePathLength = (maxSize - strlen(fileExtension)) < 1 ? 1 : (maxSize - strlen(fileExtension));
        strncpy(processed_filepath, filePath, filePathLength);
        processed_filepath[filePathLength] = '\0';
    } else {
        strncpy(processed_filepath, filePath, filePathLength);
        processed_filepath[filePathLength + strlen(fileExtension)] = '\0';
        strcat(processed_filepath, fileExtension);
    }

    return processed_filepath;
}
