typedef struct Record {
    int value;
    char status;
    char* string;
} Record;

enum { ARRAY_SIZE, STRING_SIZE };

int initDataStructures(size_t n, size_t* offsets, int* keys, Record** records) {
    if (n <= 0 || !offsets || !keys || !records) return -1;

    // Allocate memory for long offset values
    *offsets = malloc(sizeof(long) * n);
    if (!(*offsets)) return -2;
    memset(*offsets, 0, sizeof(long) * n);

    // Allocate memory for int keys
    *keys = malloc(sizeof(int) * n);
    if (!(*keys)) {
        free(*offsets);
        return -3;
    }
    memset(*keys, -1, sizeof(int) * n);

    // Allocate memory for record structures and strings
    *records = calloc(n, sizeof(Record));
    if (!(*records)) {
        free(*offsets);
        free(*keys);
        return -4;
    }

    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        (*records)[i].value = rand() % 1001;
        (*records)[i].status = 'A';
        (*records)[i].string = calloc(STRING_SIZE, sizeof(char));
        if (!((*records)[i].string)) {
            free(*offsets);
            free(*keys);
            free(*records);
            return -5;
        }
    }

    return 0;
}

void deallocateDataStructures(size_t n, size_t* offsets, int* keys, Record** records) {
    if (!offsets || !keys || !records) return;

    for (size_t i = 0; i < n; ++i) {
        free((*records)[i].string);
    }
    free(*records);
    free(*offsets);
    free(*keys);
}
