['```java
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ProcessManager {
    private static final int MAX_KEY = 100;
    private static final int MAX_OFFSET = 200;
    private static final int MAX_RECORDS = 500;

    public static int executeProcess(String configFile) {
        File config = new File(configFile);

        if (Files.exists(config.toPath())) {
            config.delete();
        }

        long[] offsets = new long[MAX_KEY];
        int[] keys = new int[MAX_KEY];
        Record[] records = new Record[MAX_RECORDS];

        Random random = new Random();

        for (int i = 0; i < MAX_KEY; i++) {
            offsets[i] = Math.abs(random.nextLong() % (MAX_OFFSET + 1));
            keys[i] = random.nextInt(MAX_KEY);
        }

        for (int i = 0; i < MAX_RECORDS; i++) {
            records[i] = new Record(random.nextInt());
        }

        ProcessBuilder pb = new ProcessBuilder();
        String[] cmdArgs = { "command1", "-k", Integer.toString(keys[0]), "-o", Long.toString(offsets[0]) };
        Arrays.stream(records).forEach(record -> cmdArgs.add("-r").add(Integer.toString(record.value)));

        pb.command(cmdArgs);
        Process process = null;

        try {
            process = pb.start();

            Executors.newCachedThreadPool().submit(() -> {
                try {
                    process.getErrorStream().close();
                } catch (IOException e) {
                    System.err.println("Error closing error stream: " + e.getMessage());
                }
                try {
                    process.getInputStream().close();
                } catch (IOException e) {
                    System.err.println("Error closing input stream: " + e.getMessage());
                }
            });

            process.waitFor(30, TimeUnit.SECONDS);
        } catch (IOException | InterruptedException e) {
            System.err.println("Error executing command: " + e.getMessage());
            return -1;
        } finally {
            if (process != null) {
                process.destroy();
            }
        }

        return process.exitValue();
    }

    static class Record {
        int value;

        public Record(int value) {
            this.value = value;
        }
    }
}
```']

