// Custom memory pool
struct MemPool {
    void* start;
    size_t size;
    size_t allocated;
};

void* mempool_alloc(struct MemPool* mp, size_t size) {
    if (mp->allocated + size > mp->size) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    void* ptr = (char*)mp->start + mp->allocated;
    mp->allocated += size;
    return ptr;
}

void mempool_free(struct MemPool* mp, void* ptr) {
    if (!ptr || !mp) return;

    char* p = (char*)ptr - (char*)mp->start;
    mp->allocated -= (size_t)(p - (char*)mp->start);
}

void init_data(struct MemPool* mp, size_t n, long* offsets, int* keys, struct Record* records) {
    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        offsets[i] = 0;
        keys[i] = -1;

        records[i].value = rand() % 1001;
        records[i].status = 'A';
