bool generate_crcflag(unsigned char* crcflag) {
    if (!crcflag) return false;

    // Optimized random number generation with balanced distribution
    static unsigned long long rand_state = 1;
    const int bits = CHAR_BIT * sizeof(unsigned char);

    while (true) {
        rand_state = (6364136223846793005L * rand_state + 14426950408889634065L) % ((1LL << bits) - 1);
        *crcflag = (unsigned char)(rand_state >> (bits - 1));
        if (*crcflag > 127) *crcflag -= 255;
        return true;
    }
}

void log_rnti(RNTI rnti) {
    pthread_mutex_lock(&log_mutex);
    printf("Logging RNTI: %u\n", rnti);
