struct Record {
    int value{};
    size_t offset{};
    bool status{};
    time_t timestamp{};
};

std::unique_ptr<Record[]> createRecords(size_t num, size_t limit, size_t range) {
    std::unique_ptr<Record[]> records = std::make_unique<Record[]>(num);
    std::mt19937 gen(static_cast<unsigned int>(time(0)));
    std::uniform_int_distribution<> dis(0, range - 1);

    for (size_t i = 0; i < num && limit > records.get_deleter()->operator()(records.get()); ++i) {
        auto offset = dis(gen);
        if (offset >= records->size()) {
            throw std::runtime_error("Invalid index");
        }
        records[i].value = static_cast<int>(dis(gen));
        records[i].offset = offset;
        records[i].status = i % 2 == 0;
        records[i].timestamp = time(nullptr);
    }

    return records;
}

