import java.security.MessageDigest;
import java.math.BigInteger;
import java.util.Base64;

public class MD5Hasher {
    private static final int MAX_STRINGS = 100;
    private static final int CHAR_LIMIT = 10000;

    public String md5(String... strings) {
        if (strings.length > MAX_STRINGS) {
            throw new IllegalArgumentException("Too many strings");
        }

        StringBuilder result = new StringBuilder();

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");

            for (String str : strings) {
                if (str.length() > CHAR_LIMIT) {
                    throw new IllegalArgumentException("String too long");
                }

                md.reset();
                md.update(str.getBytes());
                byte[] digest = md.digest();

                BigInteger bigInt = new BigInteger(1, digest);
                String hashtext = bigInt.toString(16);
                while (hashtext.length() < 32) {
                    hashtext = "0" + hashtext;
                }
                result.append(hashtext);
            }
        } catch (Exception e) {
            throw new RuntimeException("Error computing MD5 hash", e);
        }

        return result.toString();
    }
}
