#define HASH_TABLE_SIZE 1024

typedef struct Record {
    int key;
    long offset;
} Record;

struct HashTableNode {
    Record record;
    struct HashTableNode *next;
};

struct HashTable {
    struct HashTableNode **table;
    pthread_mutex_t mutex;
};

struct HashTable* createHashTable(int min, int max) {
    struct HashTable *hashTable = malloc(sizeof(struct HashTable));
    if (!hashTable) return NULL;

    hashTable->table = calloc(HASH_TABLE_SIZE, sizeof(struct HashTableNode*));
    if (!hashTable->table) {
        free(hashTable);
        return NULL;
    }

    hashTable->mutex = PTHREAD_MUTEX_INITIALIZER;
    return hashTable;
}

Record createRecord(int key, long offset) {
    Record record = {key, offset};
    return record;
}

unsigned int hashFunction(const void *key) {
    int hashKey = *(int *)key;
    unsigned long hash = (unsigned long)hashKey * 31 + HASH_TABLE_SIZE / 2;
    return (hash & (HASH_TABLE_SIZE - 1));
}

void insertRecord(struct HashTable *table, Record record) {
    pthread_mutex_lock(&table->mutex);
    unsigned int index = hashFunction((const void*)&record.key);
    struct HashTableNode* currentNode = table->table[index];
    struct HashTableNode* newNode = malloc(sizeof(struct HashTableNode));

    if (!newNode) {
        pthread_mutex_unlock(&table->mutex);
        return;
    }

    newNode->record = record;
    newNode->next = currentNode;

    if (currentNode)
        table->table[index] = newNode;
    else
        table->table[index] = newNode;

    pthread_mutex_unlock(&table->mutex);
}

Record* findRecord(struct HashTable *table, int key) {
    Record* foundRecord = NULL;
    unsigned int index = hashFunction((const void*)&key);
    struct HashTableNode* currentNode = table->table[index];

    while (currentNode != NULL) {
        if (currentNode->record.key == key) {
            foundRecord = &currentNode->record;
            break;
        }
        currentNode = currentNode->next;
    }

    return foundRecord;
}

void freeHashTable(struct HashTable *table) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        struct HashTableNode* currentNode = table->table[i];
        while (currentNode != NULL) {
            struct HashTableNode* temp = currentNode;
            currentNode = currentNode->next;
            free(temp);
        }
    }
    free(table->table);
    free(table);
}
