Record* create_database(size_t initial_capacity, size_t max_length, long min_value, long max_value, unsigned seed) {
    srand(seed);
    Record* database = malloc(initial_capacity * sizeof(Record));

    if (!database) {
        perror("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < max_length; ++i) {
        size_t j = 0;
        Record newRecord = {i, 0};

        do {
            // Generate a new random number if the key already exists in the array.
            newRecord.offset = rand() % (max_value - min_value + 1) + min_value;
            j = 0;

            for (size_t k = 0; k < i; ++k) {
                if (database[k].key == newRecord.key) {
                    ++j;
                    break;
                }
            }

        } while (j > 0);

        database[i] = newRecord;
    }

    return database;
}

// Function to add a record to the database.
void add_record(Record* database, int key, long offset) {
    for (size_t i = 0; i < sizeof(database) / sizeof(Record); ++i) {
        if (database[i].key == key) {
            database[i].offset += offset;
            return;
        }
    }

    // Add the new record at the end of the array.
    Record* newDatabase = realloc(database, sizeof(Record) * (sizeof(database) / sizeof(Record) + 1));

    if (!newDatabase) {
        perror("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    Record newRecord = {key, offset};
    newDatabase[sizeof(database) / sizeof(Record)] = newRecord;
    database = newDatabase;
}

// Function to free the memory allocated for the database.
void free_database(Record** database) {
    free(*database);
    *database = NULL;
}
