Record* create_record(FZHashMap* hash_table, gsl_rng* rng, long min_key, long max_key, long min_offset, long max_offset) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        // Handle out-of-memory error
        return NULL;
    }

    record->key = malloc((max_key - min_key + 1) * sizeof(int));
    if (!record->key) {
        free(record);
        return NULL;
    }

    for (long i = min_key; i <= max_key; ++i) {
        record->key[i - min_key] = i;
    }

    // Generate unique key within the specified range and find an empty slot in the key array.
    long key = gsl_rng_integer(rng, max_key - min_key + 1) + min_key;

    while (FZHashMap_lookup(hash_table, record->key[key])) {
        // If the key is already used, find another one.
        key = gsl_rng_integer(rng, max_key - min_key + 1) + min_key;
    }

    record->offset = gsl_rng_uniform(rng, max_offset);

    // Generate data for the new record within the specified range.
    record->data = malloc(sizeof(int));
    if (!record->data) {
        free(record->key);
        free(record);
        return NULL;
    }

    *(int*)record->data = gsl_rng_integer(rng, max_offset - min_offset + 1) + min_offset;

    return record;
}

