        thread_args[i].hash_table = hash_table;
        thread_args[i].rng = rng;
        thread_args[i].min_key = min_key;
        thread_args[i].max_key = max_key;
        thread_args[i].min_offset = min_offset;
        thread_args[i].max_offset = max_offset;

        pthread_t tid;
        pthread_create(&tid, NULL, worker, &thread_args[i]);
    }

    // Periodically resize the hash table based on the number of entries.
    // ...

    // Wait for all threads to finish.
    for (long i = 0; i < num_threads; ++i) {
        pthread_join(tid, NULL);
    }

    // Cleanup resources.
