#include "third_party_random.h" // Third-party random number generation library
#include "bloomfilter.h" // Third-party bloom filter implementation
#include "queue.h" // Third-party queue implementation

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct DataSet {
    size_t capacity;
    size_t size;
    Record* records;
    BloomFilter* bf; // Bloom filter for fast membership checks
    Queue* backgroundTasks;
    pthread_mutex_t lock;
} DataSet;

DataSet* createDataSet(size_t initialCapacity, size_t maxRecords, int minKey, int maxKey) {
    DataSet* ds = (DataSet*)malloc(sizeof(DataSet));
    if (!ds) return NULL;

    ds->capacity = initialCapacity;
    ds->size = 0;
    ds->records = (Record*)calloc(initialCapacity, sizeof(Record));
    if (!ds->records) {
        free(ds);
        return NULL;
    }

    ds->bf = createBloomFilter(maxRecords);
    ds->backgroundTasks = createQueue();
    pthread_mutex_init(&ds->lock, NULL);

    generateInitialData(ds, maxRecords, minKey, maxKey);

    return ds;
}

void generateInitialData(DataSet* ds, size_t numRecords, int minKey, int maxKey) {
    for (size_t i = 0; i < numRecords && ds->size < ds->capacity; ++i) {
        int key = generateRandomNumber(minKey, maxKey);
        int exists = bloomFilterContains(ds->bf, key);
        while (exists) {
            key = generateRandomNumber(minKey, maxKey);
            exists = bloomFilterContains(ds->bf, key);
        }

        ds->records[ds->size].key = key;
        ds->records[ds->size].offset = generateRandomNumber(0, LLONG_MAX);
        ++ds->size;
    }
}

int insertRecord(DataSet* ds, int key, long offset) {
    if (ds->size >= ds->capacity) resizeDataSet(ds);

    int exists = bloomFilterContains(ds->bf, key);
    while (exists) {
        key = generateRandomNumber(1, INT_MAX); // Use a different range for re-generation to ensure uniqueness
        exists = bloomFilterContains(ds->bf, key);
    }

    ds->records[ds->size].key = key;
    ds->records[ds->size].offset = offset;
    ++ds->size;
    bloomFilterAdd(ds->bf, key);

    enqueueBackgroundTask(ds->backgroundTasks, resizeBloomFilterIfNeeded, ds);

    return 0;
}

void resizeDataSet(DataSet* ds) {
    size_t newCapacity = ds->capacity * 2;
    Record* newRecords = (Record*)realloc(ds->records, newCapacity * sizeof(Record));
    if (!newRecords) return;

    ds->capacity = newCapacity;
    ds->records = newRecords;
}

void resizeBloomFilterIfNeeded(void* userdata) {
    DataSet* ds = (DataSet*)userdata;
    bloomFilterResizeIfNeeded(ds->bf, ds);
}

// Additional functions for resource management, performance optimization, and thread safety as needed
```

