```cpp
#include <boost/interprocess/managed_shared_memory.hpp>
#include <boost/interprocess/containers/vector.hpp>
#include <boost/interprocess/sync/mutex.hpp>
#include <boost/interprocess/sync/semaphore.hpp>
#include <boost/interprocess/sync/scoped_allocate.hpp>
#include <boost/asio/steady_timer.hpp>

namespace shm = boost::interprocess;
using semaphore_vector_t = boost::interprocess::managed_shared_memory::vector<boost::interprocess::semaphore>;
using mutex_t = boost::interprocess::recursive_mutex;

class SemaphoreManager {
public:
    SemaphoreManager() {
        shm_segment_.reset(new shm::managed_shared_memory(shm::create_only, "SemaphoreManager", 1024 * 1024));
        semaphore_vector_.construct<semaphore_vector_t>(shm_segment_.get(), 0);
        semaphores_.construct<mutex_t*>(shm_segment_.get(), &mutex_);
    }

    ~SemaphoreManager() {
        semaphores_->lock();
        for (auto& semaphore : semaphore_vector_) {
            if (semaphore.use_count() > 1)
                semaphore.release();
            else
                semaphore.destroy();
        }
        semaphores_->unlock();
    }

    boost::interprocess::semaphore* createSemaphore(int initialValue) {
        auto semaphore = semaphore_vector_.emplace_back(initialValue);
        (*semaphores_)->lock();
        ++referenceCount_[&semaphore];
        (*semaphores_)->unlock();
        return &semaphore;
    }

    void deleteSemaphore(boost::interprocess::semaphore* semaphore) {
        std::scoped_lock<mutex_t> lock(*semaphores_);
        if (--referenceCount_[semaphore] == 0) {
            semaphore->destroy();
            semaphore_vector_.erase(semaphore);
        }
    }

    void incSemaphore(boost::interprocess::semaphore* semaphore) const {
        semaphore->wait();
        ++(*semaphore);
        semaphore->post();
    }

    void decSemaphore(boost::interprocess::semaphore* semaphore) const {
        semaphore->wait();
        if (*semaphore > 0)
            --(*semaphore);
        semaphore->post();
    }

private:
    shm::scoped_allocate<shm_segment_t> shm_segment_;
    mutable boost::interprocess::managed_shared_memory* semaphores_;
    mutex_t* mutex_;
    std::unordered_map<boost::interprocess::semaphore*, int> referenceCount_;
};
```

This solution uses managed shared memory and semaphores from the Boost library for concurrency. The SemaphoreManager class creates a managed shared memory segment, manages a vector of semaphores, and provides methods for creating, deleting, incrementing, and decrementing semaphores atomically. References to semaphores are counted using a simple reference counting mechanism to ensure proper cleanup. This solution does not include the periodic pruning of stale references or any error handling, which would require a more complex implementation tailored to your specific needs in a distributed system environment.']

