#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    TX_BUFFER_INFO tx_info;
    PHY_TX_STREAM_T* streams;
    size_t num_streams;
} PHY_TX_TASK_T;

static pthread_mutex_t tasks_mutex = PTHREAD_MUTEX_INITIALIZER;
static PHY_TX_TASK_T** task_array = NULL;
static size_t num_tasks = 0;
static size_t capacity = 0;
static pthread_cond_t tasks_cond = PTHREAD_COND_INITIALIZER;

void phy_tx_task_init(size_t initial_capacity) {
    if (capacity > 0) {
        free(task_array);
    }
    capacity = initial_capacity;
    task_array = malloc(capacity * sizeof(PHY_TX_TASK_T*));
}

PHY_TX_TASK_T* phy_tx_task_create() {
    PHY_TX_TASK_T* new_task = NULL;

    pthread_mutex_lock(&tasks_mutex);
    if (num_tasks < capacity) {
        task_array[num_tasks] = malloc(sizeof(PHY_TX_TASK_T));
        new_task = task_array[num_tasks];
        memset(new_task, 0, sizeof(PHY_TX_TASK_T));
        num_tasks++;
    } else {
        pthread_cond_wait(&tasks_cond, &tasks_mutex);
    }
    pthread_mutex_unlock(&tasks_mutex);

    return new_task;
}

void phy_tx_task_destroy(PHY_TX_TASK_T* task) {
    pthread_mutex_lock(&tasks_mutex);

    if (task >= task_array && task < task_array + num_tasks) {
        free(task->streams);
        free(task);
        memmove(task, task + 1, (num_tasks - 1) * sizeof(PHY_TX_TASK_T*));
        num_tasks--;
    }

    pthread_mutex_unlock(&tasks_mutex);
    pthread_cond_signal(&tasks_cond);
}
```
This is a basic implementation of the task. The code creates and manages an array of `PHY_TX_TASK_T` structures using a mutex to synchronize concurrent access. The functions `phy_tx_task_init()`, `phy_tx_task_create()`, and `phy_tx_task_destroy()` are provided for initialization, task creation, and task destruction respectively.

