    pthread_mutex_init(&head_lock, NULL);
    head = list[0];
    for (size_t i = 1; i < N; ++i) {
        pthread_mutex_lock(&list_lock);
        if (!head) {
            head = list[i];
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = list[i];
        }
        pthread_mutex_unlock(&list_lock);
    }

    return 0;
}

