void get_base_name_and_ext(const char *filename, char *base_name, size_t base_name_size, char *ext, size_t ext_size) {
    size_t len = strlen(filename);
    for (size_t i = len; i > 0 && filename[i] == '.'; --i) {}
    if (i > 0) i++;
    if (len - i >= base_name_size)
        strncpy(base_name, filename + i, base_name_size);
    else {
        size_t j = 0;
        for (size_t k = i; k < len; ++k) {
            if (k >= base_name_size) break;
            base_name[j++] = filename[k];
        }
        base_name[j] = '\0';
    }
    if (i < len) strncpy(ext, filename + i, ext_size);
    else strcpy(ext, "");
}

int create_unique_filename(const char *dir, const char *base_name, char **new_filename) {
    DIR *dp = opendir(dir);
    if (!dp) return -1;

    int count = 0;
