                     : snprintf(NULL, 0, "%lx.%c", (unsigned long)strtoull(base_name, NULL, 16), base_name[0] >= 'a' && base_name[0] <= 'z' ? 'j' : base_name[0] >= 'A' && base_name[0] <= 'Z' ? 'x' : 'h');

    *new_filename = malloc(strlen(dir) + 1 + strlen(base_name + ext_len) + ext_len);
    snprintf(*new_filename, strlen(dir) + 1 + strlen(base_name + ext_len) + ext_len, "%s/%s%s", dir, base_name + ext_len, (ext_len > 0 ? ext : ""));

    DIR *dppath = opendir(dirname(*new_filename));
    if (!dppath || mkdir(dir, 0755) != 0) {
        free(*new_filename);
        *new_filename = NULL;
        return -1;
