#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

// Maximum number of threads for concurrent processing
#define MAX_THREADS 10

typedef struct {
    char *path;
    char *old_substr;
    char *new_substr;
} ReplaceData;

sem_t mutex; // For thread safety

void replace_filename(const char *old_substr, const char *new_substr, const char *path) {
    char new_name[4096];
    strncpy(new_name, path, sizeof(new_name));
    size_t old_len = strlen(old_substr);
    size_t new_len = strlen(new_substr);

    // Replace the substring in the filename
    for (size_t i = 0; i < strlen(new_name); ++i) {
        if (i + old_len >= strlen(new_name)) break;
        if (!strncmp(new_name + i, old_substr, old_len)) {
            strncpy(new_name + i, new_substr, new_len);
            memmove(new_name + i + new_len, new_name + i + old_len, strlen(new_name + i + old_len) + 1);
            break;
        }
    }

    sem_wait(&mutex);
    int ret = rename(path, new_name);
    sem_post(&mutex);

    if (ret != 0 && errno != EEXIST) {
        // Log the error here
    }
}

void* process_file(void *data) {
    ReplaceData *rd = data;
    DIR *d = opendir(rd->path);
    struct dirent *de;

    if (!d) return NULL;

    while ((de = readdir(d))) {
        char filename[4096];
        strncpy(filename, rd->path, sizeof(filename));
        strcat(filename, "/");
        strcat(filename, de->d_name);

        if (strstr(de->d_name, rd->old_substr)) {
            replace_filename(rd->old_substr, rd->new_substr, filename);
        }
    }

    closedir(d);
    free(rd);
    return NULL;
}

void process_directory(const char *path, const char *old_substr, const char *new_substr) {
    sem_init(&mutex, 0, 1);

    ReplaceData *data = malloc(sizeof(ReplaceData));
    data->path = strdup(path);
    data->old_substr = strdup(old_substr);
    data->new_substr = strdup(new_substr);

    pthread_t threads[MAX_THREADS];
    int num_threads = 0;

    DIR *d = opendir(path);
    if (!d) return;

    struct dirent *de;
    while ((de = readdir(d))) {
        char filename[4096];
        strncpy(filename, path, sizeof(filename));
        strcat(filename, "/");
        strcat(filename, de->d_name);

        struct stat st;
        if (stat(filename, &st) == -1 || S_ISDIR(st.st_mode)) continue;

        if (!num_threads < MAX_THREADS) {
            pthread_create(&threads[num_threads], NULL, process_file, data);
            ++num_threads;
            data = malloc(sizeof(ReplaceData));
            data->path = strdup(filename);
            data->old_substr = strdup(old_substr);
            data->new_substr = strdup(new_substr);
        } else {
            process_file(data);
            free(data);
            ++num_threads;
            data = malloc(sizeof(ReplaceData));
            data->path = strdup(filename);
            data->old_substr = strdup(old_substr);
            data->new_substr = strdup(new_substr);
        }
    }

    closedir(d);

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&mutex);
}
