#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    int key;
    int value;
} record;

// Memory management functions
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void safe_free(void* ptr) {
    if (ptr) free(ptr);
}

// Custom quicksort implementation for stability and performance
void qsort_records(record* arr, size_t left, size_t right) {
    if (left < right) {
        size_t pivot = partition(arr, left, right);
        qsort_records(arr, left, pivot - 1);
        qsort_records(arr, pivot + 1, right);
    }
}

size_t partition(record* arr, size_t left, size_t right) {
    record pivot = arr[right];
    size_t i = left;

    for (size_t j = left; j < right; ++j) {
        if (arr[j].key <= pivot.key) {
            swap(&arr[i], &arr[j]);
            ++i;
        }
    }

    swap(&arr[i], &arr[right]);
    return i;
}

void swap(record* a, record* b) {
    record temp = *a;
    *a = *b;
    *b = temp;
}

// Function to initialize and manage arrays
void init_memory(size_t* offsets, int* keys, record** records, size_t capacity, size_t* num_records) {
    *offsets = safe_malloc(capacity * sizeof(size_t));
    *keys = safe_malloc(capacity * sizeof(int));
    *records = safe_malloc(capacity * sizeof(record));

    for (size_t i = 0; i < capacity; ++i) {
        (*offsets)[i] = -1; // Mark as unallocated
        (*keys)[i] = -1; // Mark as unused
    }

    srand(time(NULL));

    for (size_t i = 0, j = 0; i < capacity && j < capacity; ) {
        size_t offset = rand() % capacity;
        if ((*offsets)[offset] == -1) {
            (*offsets)[offset] = *num_records;
            (*keys)[*num_records] = rand() % INT_MAX;
            while (i < *num_records && (*keys)[(*offsets)[i]] <= (*keys)[offset]) ++i;
            (*records)[(*offsets)[i]] = (record){ .key = (*keys)[offset], .value = rand() % 100 };
            ++j;
            ++*num_records;
        }
    }
}

// Merge records into a single sorted list
void merge_sorted(record** sorted, size_t current_capacity, size_t* current_size) {
    if (current_capacity <= 1) return;

    size_t mid = current_capacity / 2;
    record* left_half = safe_malloc(mid * sizeof(record));
    record* right_half = safe_malloc((current_capacity - mid) * sizeof(record));

    for (size_t i = 0; i < mid; ++i) left_half[i] = (*sorted)[i];
    for (size_t i = mid; i < current_capacity; ++i) right_half[i - mid] = (*sorted)[i];

    merge_sorted(left_half, mid, NULL);
    merge_sorted(right_half, current_capacity - mid, NULL);

    size_t i = 0, j = 0;
    for (size_t k = 0; k < current_capacity; ++k) {
        if (i >= mid && j < current_capacity - mid) {
            (*sorted)[k] = left_half[i] < right_half[j] ? left_half[i++] : right_half[j++];
        } else if (i < mid) {
            (*sorted)[k] = left_half[i++];
        } else {
            (*sorted)[k] = right_half[j++];
        }
    }

    safe_free(left_half);
    safe_free(right_half);
}

// Retrieve a record by its key, return NULL if not found
record* get_record_by_key(record* sorted, size_t capacity, int key) {
    for (size_t i = 0; i < capacity; ++i) {
        if (sorted[i].key == key) return &sorted[i];
    }

    return NULL;
}
