public:
    OffsetList() : allocator_(std::nothrow) {}
    ~OffsetList() { clear(); }

    long* allocate(size_t n) {
        void* ptr = allocator_.allocate(n);
        if (!ptr || !allocator_.construct(ptr, n)) {
