    FloatList() : allocator_(std::nothrow) {}
    ~FloatList() { clear(); }

    double* allocate(size_t n) {
        void* ptr = allocator_.allocate(n);
        if (!ptr || !allocator_.construct(ptr, n)) {
            allocator_.deallocate(ptr, n);
            return nullptr;
        }
        return static_cast<double*>(ptr);
    }

    void clear() {
        for (auto i : floats_) {
            if (i) deallocator_(i);
        }
        floats_.clear();
    }

private:
    std::vector<double*, std::default_delete<double[]>> floats_;
    std::scoped_allocator_from_container<std::vector<double>, std::allocator<void>> allocator_;
};

class RecordList {
public:
    RecordList() : keyAllocator_(std::nothrow), recordAllocator_(std::nothrow) {}
    ~RecordList() { clear(); }

    std::unique_ptr<Record> allocate() {
        auto ptr = recordAllocator_.allocate(1);
        if (!ptr || !recordAllocator_.construct(ptr)) {
            recordAllocator_.deallocate(ptr, 1);
            return nullptr;
        }
        return std::unique_ptr<Record>(ptr);
    }

    void clear() {
        for (auto i : records_) {
            if (i) recordAllocator_.destroy(i.get());
        }
        records_.clear();
    }

private:
    std::vector<std::unique_ptr<Record, std::default_delete<Record>>> records_;
    std::scoped_allocator_from_container<std::vector<Record>, std::allocator<void>> recordAllocator_;
    std::scoped_allocator<int> keyAllocator_;
};

// Merge sort function for the RecordList
void mergeSort(RecordList& records, size_t start, size_t end) {
    if (start >= end) return;

    size_t mid = (start + end) / 2;
    mergeSort(records, start, mid);
    mergeSort(records, mid + 1, end);

    merge(records, start, mid, mid + 1, end);
}

// Merge function for the RecordList
void merge(RecordList& records, size_t leftStart, size_t leftEnd,
           size_t rightStart, size_t rightEnd) {
    auto tmp = std::make_unique<Record>(records.size());
    size_t leftIndex = leftStart;
    size_t rightIndex = rightStart;
    size_t tmpIndex = 0;

    while (leftIndex <= leftEnd && rightIndex <= rightEnd) {
        if (records[leftIndex].key < records[rightIndex].key) {
            tmp->at(tmpIndex++) = std::move(records[leftIndex++]);
        } else {
            tmp->at(tmpIndex++) = std::move(records[rightIndex++]);
        }
    }

    while (leftIndex <= leftEnd) {
        tmp->at(tmpIndex++) = std::move(records[leftIndex++]);
    }

    while (rightIndex <= rightEnd) {
        tmp->at(tmpIndex++) = std::move(records[rightIndex++]);
    }

    records.swap(tmp.get());
}

// Function to initialize a record with given key, offset, and random coordinates within specified range
void initRecord(int key, long offset, Record& record) {
    // Generate random coordinates within defined geographical boundary and metadata
    std::uniform_real_distribution<> distX(-10.0, 10.0);
    std::uniform_real_distribution<> distY(-20.0, 20.0);

    Point point;
    point.x = distX(generator_);
    point.y = distY(generator_);
    point.metadata = rand() % METADATA_MAX;

    // Ensure no conflicts with existing offsets and that coordinates remain within a defined geographical boundary
    if (offsetConflicts(offsets_, offset) || !isWithinBoundary(point)) {
        initRecord(key, ++offset, record);
    } else {
        record.key = key;
        record.offset = offset;
        record.point = point;
    }
}

