    struct node* next;
    pthread_mutex_t mutex;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long crc_updates = 0;
unsigned int update_interval = 10000000; // Adjust based on desired periodicity (in nanoseconds)

void generate_random_crc() {
    crc_indication.CRCFLAG = rand() % 2;
}

void init_node(Node** node) {
    *node = malloc(sizeof(Node));
    if (!*node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    (*node)->data.CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
    (*node)->next = NULL;
    pthread_mutex_init(&(*node)->mutex, NULL);
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node;
    init_node(&new_node);
    new_node->data = data;

    pthread_mutex_lock(&list_mutex);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

void periodic_crc_update() {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current != NULL) {
        generate_random_crc(&current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

void log_crc_updates() {
    static unsigned long last_log = 0;
    struct timespec now;

    clock_gettime(CLOCK_MONOTONIC, &now);
    if (now.tv_sec - last_log > 1) {
        printf("CRC updates per second: %.2f\n", crc_updates * 1e9 / (now.tv_sec - last_log));
        last_log = now.tv_sec;
        crc_updates = 0;
    }
}

// Implement a thread function to periodically update CRC flags based on network conditions and signal strength.
void* periodic_update(void *arg) {
    while (1) {
        periodic_crc_update();
        log_crc_updates();
        usleep(update_interval);
    }
    return NULL;
}

