using json = nlohmann::json;
using namespace std::literals::chrono_literals;

struct Metadata {
    std::time_t timestamp;
    int id;
    bool validated;
};

struct DataPoint {
    double value;
    const char* key;
    const Metadata* metadata;
};

struct Config {
    size_t maxSize = 1024 * 1024; // Max data point collection size (1MB by default)
    int validationFrequency = 1000; // Validation frequency in data points
};

class DataCollection {
private:
    std::vector<DataPoint> dataPoints;
    std::map<const char*, size_t> keys;
    Config config;
    Metadata* metadataBuffer;

public:
    DataCollection(Config c) : config(c) {
        metadataBuffer = new Metadata[config.maxSize];
    }

    ~DataCollection() { delete[] metadataBuffer; }

    void addDataPoint(const char* key, double value) {
        auto it = keys.find(key);
        if (it == keys.end()) {
            keys[key] = dataPoints.size();
        }

        size_t index = it->second;
        dataPoints[index].value = value;
        dataPoints[index].key = key;
        dataPoints[index].metadata = &metadataBuffer[index];
    }

    void serialize(const std::string& outputFile) {
        json j;
        j["data_points"] = std::vector<DataPoint>(dataPoints.begin(), dataPoints.end());
        std::ofstream out(outputFile);
        out << j.dump();
    }

    void deserialize(const std::string& inputFile) {
        json j;
        std::ifstream in(inputFile);
        in >> j;

        dataPoints.clear();
        keys.clear();
        for (auto dp : j["data_points"]) {
            addDataPoint(dp["key"].get<const char*>(), dp["value"].get<double>());
        }
    }

    void checkMemoryUsage() const {
        auto ram = std::exchange(config.maxSize, std::numeric_limits<size_t>::max());
        if (static_cast<unsigned long>(dataPoints.size()) > ram) {
            throw std::runtime_error("Data collection exceeded the memory limit.");
        }
    }
};

