class StateSerializer {
public:
    static void save(const string& file, const unique_ptr<Cache>& cache) {
        bp::ptree pt;
        for (auto const& pair : *cache) {
            auto record = pair.second;
            bp::ptree recordNode;
            recordNode.put("timestamp", record.timestamp);
            recordNode.put("weight", record.weight);
            pt.push_back(make_pair(pair.first, recordNode));
        }
