// Define the structures
typedef struct NeighborCellInfo {
    int cellId;
    float latency;
    float packetLoss;
} NeighborCellInfo;

typedef struct NetworkInterfaceConfig {
    int interfaceId;
    NeighborCellInfo* neighbors;
    size_t numNeighbors;
    float linkQuality;
    pthread_mutex_t mutex; // For thread-safe access to the struct
} NetworkInterfaceConfig;

// Function to retrieve neighbor data from an external source asynchronously
void getNeighborData(NetworkInterfaceConfig* netIntConfig, int interfaceId);

// Function to calculate link quality based on latency and packet loss
float calculateLinkQuality(const NeighborCellInfo* neighbor);

// Function to initialize network interfaces with appropriate parameters
void initNetworkInterfaces(NetworkInterfaceConfig** netInts, size_t numInterfaces) {
    *netInts = malloc(numInterfaces * sizeof(NetworkInterfaceConfig));
    if (!*netInts) {
        perror("Memory allocation failed");
        exit(1);
    }

    for (size_t i = 0; i < numInterfaces; ++i) {
        NetworkInterfaceConfig* currentNetInt = &(*netInts)[i];

        // Validate interfaceId is within acceptable range
        if (i >= (1 << 32)) {
            fprintf(stderr, "Invalid interfaceId %lu\n", i);
            continue;
        }

        currentNetInt->interfaceId = i;
        currentNetInt->numNeighbors = 0;
        currentNetInt->linkQuality = NAN;
        currentNetInt->neighbors = NULL;
        pthread_mutex_init(&currentNetInt->mutex, NULL);

        // Launch asynchronous neighbor data retrieval for each network interface
        getNeighborData(currentNetInt, i);
    }
}

// Function to handle memory deallocation upon function exit
void freeNetworkInterfaces(NetworkInterfaceConfig** netInts, size_t numInterfaces) {
    for (size_t i = 0; i < numInterfaces; ++i) {
        if ((*netInts)[i].neighbors) {
            free((*netInts)[i].neighbors);
        }
        pthread_mutex_destroy(&(*netInts)[i].mutex);
    }
    free(*netInts);
}
