#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
    pthread_mutex_t mutex;
} ListNode;

ListNode* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random(NFAPI_CRC_INDICATION_PDU_T *data) {
    data->RX_UE_INFORMATION_TAG = rand();
    data->RNTI = rand() % 65536; // Valid RNTI range is 0-65535
    data->CRC_INDICATION_REL8_TAG = rand();
    data->CRCFLAG = (rand() & 1) == 0 ? 0 : 1;
}

int check_valid(NFAPI_CRC_INDICATION_PDU_T *data) {
    return data->CRCFLAG != 255 && data->RNTI != head->next ? 1 : 0;
}

void insert_node(ListNode* node) {
    pthread_mutex_lock(&list_mutex);
    ListNode* current = head;
    while (current->next && current->next->RNTI == node->data.RNTI)
        current = current->next;

    if (!head || current->RNTI != node->data.RNTI) {
        node->next = head;
        head = node;
    } else {
        node->next = current->next;
        current->next = node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void* list_manager(void *arg) {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T data;
        generate_random(&data);

        ListNode* new_node = malloc(sizeof(ListNode));
        if (!new_node) continue; // Handle out-of-memory errors

        new_node->data = data;
        new_node->next = NULL;
        pthread_mutex_init(&new_node->mutex, NULL);

        pthread_mutex_lock(&list_mutex);
        if (!check_valid(&new_node->data)) {
            free(new_node);
            pthread_mutex_unlock(&list_mutex);
            continue; // Invalid CRC or duplicate RNTI, discard this data structure.
        }
        insert_node(new_node);
        pthread_mutex_unlock(&list_mutex);
    }
}
