        randomGenerator.seed(seed);
    }

    NFAPI_CRC_INDICATION_PDU_T generatePDU() {
        std::unique_lock<std::mutex> lock(ueInfoMutex);

#ifdef EXTERNAL_DATA_SOURCE
        if (ueInfoQueue.empty()) {
            auto fetchTask = std::async([&](){
                ueInfoQueue = dataSource.fetchUEInformation();
            });

            if (!fetchTask.wait_for(std::chrono::seconds(5))){
                std::cerr << "Failed to retrieve UE information from the data source." << std::endl;
            }
        }
#endif

        auto ueInfoIt = ueInfoQueue.front();
        ueInfoQueue.pop_front();

        NFAPI_CRC_INDICATION_PDU_T pdu{};
        pdu.rx_ue_information_tag = ueInfoIt;
        pdu.rnti = ueInfoIt.rnti;
        pdu.crc_indication_rel8_tag.crcflag = (randomGenerator() & 0x1);

        return pdu;
    }
};

