['1. C Code for Dynamic Memory Allocation (using doubly-linked list):

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    float timestamp;
    struct Record *next, *prev;
} Record;

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->offset = 0;
    record->key = -1; // unused until initialized
    record->timestamp = 0.0;
    record->next = NULL;
    record->prev = NULL;
    return record;
}

Record* dynamic_list() {
    Record *head, *tail, *new_node;
    head = tail = NULL;
    int capacity = 16; // initial capacity
    size_t num_elements = 0;

    void** data = malloc(capacity * sizeof(void*));
    if (!data) return NULL;

    while (num_elements < capacity) {
        data[num_elements] = create_record();
        if (!data[num_elements]) {
            free(data);
            return NULL;
        }
        if (!head) head = tail = data[num_elements];
        else {
            tail->next = data[num_elements];
            data[num_elements]->prev = tail;
            tail = data[num_elements];
        }
        num_elements++;
    }

    return (Record*)data;
}
```

