public class TransactionalEmailSender {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final Map<String, EmailConfig> emailConfigs = new HashMap<>();
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final EmailMonitor monitor = new TestEmailMonitor(); // Change to real EmailMonitor instance when ready
    private static final String monitoringApiKey = "your_monitoring_api_key";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            JSONObject jsonObject = new JSONObject(line);
            EmailConfig emailConfig = objectMapper.readValue(jsonObject.toString(), EmailConfig.class);
            emailConfigs.put(emailConfig.getId(), emailConfig);
        }

        for (EmailConfig config : emailConfigs.values()) {
            executor.submit(() -> sendEmail(config));
        }

        scanner.close();
    }

    private static void sendEmail(EmailConfig config) {
        try {
            Session session = createSession(config);
            MimeMessage message = createMimeMessage(session, config);

            Transport transport = findAvailableTransport(config, message);
            int deliveryAttempts = 0;
            while (!transport.isConnected() && deliveryAttempts < config.getMaxRetries()) {
                if (deliveryAttempts > 0) {
                    Thread.sleep(Math.pow(2, deliveryAttempts) * config.getBackoffMultiplier());
                }
                transport = findAvailableTransport(config, message);
                deliveryAttempts++;
            }

            if (transport != null && transport.isConnected()) {
                transport.sendMessage(message, message.getAllRecipients());
                monitor.monitorEmailDelivery(config, true);
            } else {
                monitor.monitorEmailDelivery(config, false);
            }
        } catch (Exception e) {
            monitor.monitorEmailDelivery(config, false);
            System.out.println("Error sending email: " + e.getMessage());
        }
    }

    private static Session createSession(EmailConfig config) throws MessagingException {
