void init_data_source(uint16_t size) {
    if (data_source != NULL) {
        free(data_source->ue_ids);
    }

    data_source = mmap(NULL, sizeof(struct data_source), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    data_source->semaphore = sem_init( Semaphore_Uninitialized, 1, 0 );
    data_source->ue_ids = calloc(size, sizeof(uint16_t));
}

void destroy_data_source() {
    if (data_source != NULL) {
        free(data_source->ue_ids);
        munmap((void*) data_source, sizeof(struct data_source));
        sem_destroy(data_source->semaphore);
        data_source = NULL;
    }
}

