    if (size <= 0) {
        return NULL;
    }

    LTE_PHY_CHANNEL_STATUS_T* array = calloc(size, sizeof(LTE_PHY_CHANNEL_STATUS_T));
    if (!array) {
        perror("Calloc failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&config_mutex);
    init_data_source(size);
    pthread_mutex_unlock(&config_mutex);

    return array;
}

void configure_channel_status(LTE_PHY_CHANNEL_STATUS_T* array, size_t size) {
    if (!array || size <= 0) {
        return;
    }

    pthread_mutex_lock(&config_mutex);

    uint16_t ue_id = 0;
    for (size_t i = 0; i < size; ++i) {
        while (ue_id >= data_source->ue_ids[0]) {
            sem_wait(&data_source->semaphore);
            ue_id = data_source->ue_ids[0];
            if (++ue_id == UINT16_MAX) {
                ue_id = 0;
            }
        }

        array[i].phich_flags = 0b1111_0000; // Example PHICH flags
        array[i].harrq_pid = i % 8;          // HARQ process ID example
        array[i].ue_id = ue_id;             // UE identifier from the data source
    }

    pthread_mutex_unlock(&config_mutex);
}
