#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct entry {
    char *key;
    int value;
    time_t timestamp;
    size_t key_len;
} Entry;

void reset_memory_pool(Entry** pool, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        if (pool[i]) {
            free(pool[i]->key);
            free(pool[i]);
        }
    }
    *pool = realloc(*pool, sizeof(Entry) * capacity);
}

Entry* initialize_memory_pool(size_t capacity) {
    Entry* pool = malloc(sizeof(Entry) * capacity);
    for (size_t i = 0; i < capacity; ++i) {
        pool[i] = malloc(sizeof(struct entry));
        pool[i]->key = NULL;
        pool[i]->value = 0;
        pool[i]->timestamp = time(NULL);
        pool[i]->key_len = 0;
    }
    return pool;
}

void add_entry(Entry** pool, size_t* num_entries, const char *key, int value) {
    if (*num_entries >= 100) {
        fprintf(stderr, "Warning: Array capacity exceeded.\n");
        return;
    }

    size_t key_len = strlen(key);
    if (key_len > 256) {
        fprintf(stderr, "Warning: Key length exceeds maximum allowed (256 chars). Truncating key.\n");
        key_len = 256;
        key[key_len] = '\0';
    }

    pool[*num_entries]->key = strdup(key);
    pool[*num_entries]->value = value;
    pool[*num_entries]->timestamp = time(NULL);
    pool[*num_entries]->key_len = key_len;
    ++(*num_entries);
}

void cleanup_memory_pool(Entry** pool, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) {
        free(pool[i]->key);
        free(pool[i]);
    }
    free(*pool);
}
