// Resource unit structure
struct resource_unit {
    int id;
    long current_bw, peak_bw;
    std::int64_t last_update;
    bool active;
};

class NetworkManager {
private:
    std::unordered_map<int, resource_unit> connections; // Thread-safe unordered_map with a mutex
    std::mutex mtx;
    std::atomic<long> total_bw{ 0 };
    std::atomic<long> peak_bw{ 0 };

    void log(const resource_unit& r) {
        // Implement your logging system here...
    }

public:
    void addConnection(resource_unit ru) {
        if (connections.size() >= MAX_CONNECTIONS) {
            std::cerr << "Error: Maximum capacity reached!" << std::endl;
            return;
        }

        if (ru.id < 0) {
            std::cerr << "Error: Invalid connection ID!" << std::endl;
            return;
        }

        // Lock the mutex to ensure thread-safety
        std::unique_lock<std::mutex> lock(mtx);

        connections[ru.id] = ru;
        total_bw += ru.current_bw;
        peak_bw = std::max(peak_bw, ru.peak_bw + ru.current_bw);
        log(ru);
    }

    void updateConnection(int id, resource_unit ru) {
        if (auto it = connections.find(id); it != connections.end()) {
            std::unique_lock<std::mutex> lock(mtx);

            it->second.current_bw += ru.current_bw;
            total_bw += ru.current_bw;
            peak_bw = std::max(peak_bw, it->second.peak_bw + ru.current_bw + it->second.peak_bw);
            it->second = ru;
            log(it->second);
        } else {
            std::cerr << "Error: Connection not found!" << std::endl;
        }
    }

    resource_unit getConnection(int id) const {
        if (auto it = connections.find(id); it != connections.end())
            return it->second;

        std::cerr << "Error: Connection not found!" << std::endl;
        return {};
    }

    long getTotalBW() const {
        return total_bw;
    }

    long getPeakBW() const {
        return peak_bw;
    }

    // Implement serialization and deserialization methods here...
};
```

