                        fieldsList.splice(i, 1);
                    } else {
                        i++;
                    }
                }
            }

            for (let fieldName of fieldNames) {
                dataCache[fieldName] = newData[fieldName];
            }

            // Update the fields list with freshly received data
            while (fieldsList.length < fieldNames.length) {
                insertAfter(fieldsList, fieldNames[fieldsList.length], dataCache[fieldNames[fieldsList.length]]);
            }
        }

        function notifyParent() {
            let messages = [];
            for (let field of fieldsList) {
                messages.push({ resourceId: resourceId, fieldName: field, fieldData: dataCache[field] });
            }
            // Assuming you have a parent controller that listens to this service and receives messages
            // The actual implementation may vary depending on your application structure
