        }

        // Make an initial API call and update the cache with fresh data
        apiCall(currentUrl).then((data) => {
            updateCache(data);
            notifyParent();
        });

        // Watch for URL changes and adapt accordingly
        $scope.$watch(() => currentUrl, (newUrl) => {
            if (newUrl !== currentUrl) {
