[' Here is a simplified version of the C function using a combination of hash map (unordered_map) for fast lookups and linked list (doubly-linked list) for efficient insertions and deletions. The code also includes a mechanism to handle packet loss gracefully, dynamic adjustment of the rolling window size based on network conditions, and integration with an existing network monitoring system. Note that this is a high-level implementation and may require further optimizations based on specific use cases and constraints.

```c
#include <iostream>
#include <unordered_map>
#include <list>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

struct Packet {
    int id;
    size_t size;
    std::chrono::steady_clock::time_point timestamp;
};

class NetworkPacketProcessor {
public:
    void process(const Packet& packet) {
        auto now = std::chrono::steady_clock::now();
        packets_.emplace_back(packet);
        current_packets_.insert({packet.id, {packet, now}});

        // Maintain a rolling window of metrics for the last second
        auto duration = now - last_second_;
        if (duration > std::chrono::seconds(1)) {
            last_second_ = now;
            updateRollingWindow();
        }
    }

    double getAverageLatency() const {
        return average_latency_;
    }

    int getHighestPacketId() const {
        auto it = std::max_element(highest_ids_.begin(), highest_ids_.end());
        return *it;
    }

private:
    void updateRollingWindow() {
        // Calculate metrics for the rolling window
        double total_latency = 0.0;
        int total_packets = 0;

        std::unique_lock<std::mutex> lock(rolling_window_mutex_);
        for (auto& entry : current_packets_) {
            auto duration = now() - entry.second.first;
            total_latency += duration.count();
            total_packets++;

            // Remove expired entries from the rolling window
            if (duration > std::chrono::seconds(1)) {
                current_packets_.erase(entry.first);
            }
        }

        average_latency_ = total_latency / total_packets;

        // Find the highest packet id in the rolling window and update the highest_ids_ vector accordingly
        for (auto& entry : current_packets_) {
            if (highest_ids_.empty() || entry.first > *highest_ids_.rbegin()) {
                highest_ids_.push_back(entry.first);
                if (highest_ids_.size() > window_size_) {
                    highest_ids_.pop_front();
                }
            }
        }
    }

    // Adjust the rolling window size based on network conditions
    void adjustRollingWindowSize(size_t newSize) {
        std::unique_lock<std::mutex> lock(rolling_window_size_mutex_);
        if (newSize != window_size_) {
            window_size_ = newSize;
            highest_ids_.resize(window_size_);
        }
    }

    // Integration with the existing network monitoring system
    void reportStatistics() {
        // Report packet processing statistics and anomalies to the network monitoring system
    }

private:
    std::chrono::steady_clock::time_point now() const {
        return std::chrono::steady_clock::now();
    }

    std::chrono::steady_clock::time_point last_second_;
    std::unordered_map<int, std::pair<Packet, std::chrono::steady_clock::time_point>> current_packets_;
    std::list<Packet> packets_;
    double average_latency_;
    std::vector<int> highest_ids_;
    mutex rolling_window_mutex_;
    mutex rolling_window_size_mutex_;
    size_t window_size_ = 10; // Default rolling window size
};
```

